    // Save worlds + player data every autosave.online_interval_seconds (default 180) while
    // anyone is online, or every autosave.empty_interval_seconds (default 600) when empty.
    private void tickAdaptiveAutosave() {
        long now = System.currentTimeMillis();
        boolean online = !Bukkit.getOnlinePlayers().isEmpty();
        long intervalMs = 1000L * (long)(online
                ? Math.max(60, this.settings.getInt("autosave.online_interval_seconds", 180))
                : Math.max(60, this.settings.getInt("autosave.empty_interval_seconds", 600)));
        if (now - this.lastAdaptiveSaveMs < intervalMs) {
            return;
        }
        this.lastAdaptiveSaveMs = now;
        try {
            for (org.bukkit.World w : Bukkit.getWorlds()) {
                w.save();
            }
            Bukkit.savePlayers();
        } catch (Throwable t) {
            this.getLogger().warning("Adaptive autosave failed: " + t.getMessage());
        }
    }
