    public void onEnable() {
        this.foliaRuntime = this.isFoliaRuntime();
        this.saveDefaultConfig();
        this.uiActionKey = new NamespacedKey((Plugin)this, "ui_action");
        this.sellWorthMarkerKey = new NamespacedKey((Plugin)this, "sell_worth_marker");
        this.amethystKindKey = new NamespacedKey((Plugin)this, "amethyst_kind");
        this.amethystExpireKey = new NamespacedKey((Plugin)this, "amethyst_expire_at");
        this.settings = this.getConfig();
        this.loadBranding();       // resolve active brand profile before any UI renders
        this.ensureDataSource();   // warm the DB connection pool before any query runs
        this.loadShopConfig();
        this.loadSellConfig();
        this.loadWorthConfig();
        if (!this.settings.isSet("hud.force_ascii_icons")) {
            this.settings.set("hud.force_ascii_icons", (Object)this.settings.getBoolean("use_ascii_icons", false));
            this.saveConfig();
        }
        this.routerDebug = this.settings.getBoolean("router.debug_log", false);
        this.combatDebug = this.settings.getBoolean("combat.debug_log", false);
        this.chatBridgeDebug = this.settings.getBoolean("chat_debug.log_bridge_payloads", false);
        this.getLogger().info("[hud] icon mode=" + (this.isAsciiHudIconsEnabled() ? "ascii-fallback" : "glyph-preferred") + " shards=" + this.hudGlyph("\u25c6", "[S]") + " kills=" + this.hudGlyph("\u2020", "[K]") + " deaths=" + this.hudGlyph("\u2620", "[D]") + " playtime=" + this.hudGlyph("\u231b", "[T]"));
        this.setupEconomy();
        this.setupChat();
        this.runAsyncTask(this::ensureUiSchema);
        // Cross-server sync and limbo maintenance (Alpha). Off by default: a single standalone
        // server does not need the network transfer layer, and the economy runs from the database
        // configured above without it. Set sync.enabled true to run a multi-backend network.
        boolean syncEnabled = this.settings.getBoolean("sync.enabled", false);
        if (syncEnabled) {
            this.playerSyncManager = new PlayerSyncManager(this);
            this.playerSyncManager.start();
            if (!this.isFoliaRuntime()) {
                this.maintenanceQueueManager = new MaintenanceQueueManager(this, this.detectServerName());
                this.maintenanceQueueManager.start();
            } else {
                this.maintenanceQueueManager = null;
            }
        } else {
            this.playerSyncManager = null;
            this.maintenanceQueueManager = null;
        }
        this.startDbHealthCheck();
        Bukkit.getScheduler().runTaskTimerAsynchronously((Plugin)this, this::flushPendingLongStats, 600L, 600L);
        Bukkit.getPluginManager().registerEvents((Listener)this, (Plugin)this);
        this.registerCommand("guide", this);
        this.registerCommand("settings", this);
        this.registerCommand("stats", this);
        this.registerCommand("shop", this);
        this.registerCommand("navigator", this);
        this.registerCommand("spawn", this);
        this.registerCommand("warp", this);
        this.registerCommand("rtp", this);
        this.registerCommand("msg", this);
        this.registerCommand("tell", this);
        this.registerCommand("w", this);
        this.registerCommand("reply", this);
        this.registerCommand("r", this);
        this.registerCommand("team", this);
        this.registerCommand("friend", this);
        this.registerCommand("follow", this);
        this.registerCommand("unfollow", this);
        this.registerCommand("sell", this);
        this.registerCommand("ah", this);
        this.registerCommand("orders", this);
        this.registerCommand("afk", this);
        this.registerCommand("discord", this);
        this.registerCommand("gtp", this);
        this.registerCommand("pizzadebug", this);
        this.registerCommand("homes", this);
        this.registerCommand("home", this);
        this.registerCommand("bal", this);
        this.registerCommand("baltop", this);
        this.registerCommand("leaderboard", this);
        this.registerCommand("leaderboards", this);
        this.registerCommand("bounty", this);
        this.registerCommand("queuetest", this);
        this.registerCommand("vdthrottle", this);
        this.registerCommand("nv", this);   // /nv + /nightvision: same state as the /settings Night Vision toggle
        this.registerCommand("tpauto", this);   // auto-accept incoming TPA requests (same state as /settings)
        this.registerCommand("kill", this);
        this.registerCommand("worth", this);
        this.registerCommand("sellmulti", this);
        this.registerCommand("sethome", this);
        this.registerCommand("delhome", this);
        this.registerCommand("admin", this);
        this.registerCommand("manage", this);   // backend management tier (perm pizzasmp.manage)
        this.registerCommand("maintenancemotd", this);
        this.registerCommand("limbomaint", this);
        this.registerCommand("branding", this);
        this.loadWorldAccess();
        this.getServer().getMessenger().registerOutgoingPluginChannel((Plugin)this, "BungeeCord");
        this.getServer().getMessenger().registerOutgoingPluginChannel((Plugin)this, BRIDGE_CHANNEL);
        this.refreshNetworkPlayerNameCacheAsync();
        this.notificationPollTask = this.runAsyncRepeatingTask(this::pollPendingPlayerNotifications, 20L, 20L);
        this.startPlaytimeAndAfkTask();
        // One-shot (marker-file guarded): convert every team home into a personal named home
        // for ALL team members, then clear team homes. Part of the teams -> friends transition.
        this.runAsyncTask(this::migrateTeamHomesToPersonal);
        // Amethyst tool expiry: sweep every 60s on the main thread (touches player inventories).
        Bukkit.getScheduler().runTaskTimer((Plugin)this, this::runAmethystExpirySweep, 1200L, 1200L);
        // TPS-reactive view distance throttle: check every 30s (600 ticks)
        Bukkit.getScheduler().runTaskTimer((Plugin)this, this::tickVdThrottle, 600L, 600L);
        // Queue admit timer: admit 1 queued player every N ticks (default 60 = 3s)
        Bukkit.getScheduler().runTaskTimer((Plugin)this, () -> { if (this.isQueueEnabled() && !this.joinQueue.isEmpty()) this.admitNextPlayer(); }, 100L, 60L);
        // Adaptive autosave: every 3 min while players are online, every 10 min when empty
        // (bukkit.yml autosave is the 10-min incremental safety net; this adds the fast path).
        Bukkit.getScheduler().runTaskTimer((Plugin)this, this::tickAdaptiveAutosave, 1200L, 600L);
        Bukkit.getScheduler().runTaskTimer((Plugin)this, this::tickVoidRescue, 20L, 20L);   // overworld void = silent RTP to safety
        if (Bukkit.getPluginManager().getPlugin("PlaceholderAPI") != null) {
            try { new PizzaPlaceholders(this).register(); this.getLogger().info("Registered PlaceholderAPI expansion 'pizzasmp' (balance)."); }
            catch (Throwable t) { this.getLogger().warning("PAPI expansion register failed: " + t.getMessage()); }
        }
        if (Bukkit.getPluginManager().getPlugin("ProtocolLib") != null) {
            this.registerPvpOptimizationListener();
            this.registerWorthDisplayListener();
        }
    }

    public void onDisable() {
        this.flushPendingLongStats();
        this.shuttingDown = true;
        // Limbo sync safety net: on ANY shutdown (plain stop, crash-stop, /admin restart — not just the
        // /limbomaint flow), snapshot every online player's location + inventory + ender chest so the
        // limbo can hold them faithfully when Velocity falls them back. Synchronous on purpose: the DB
        // pool is still open here and players are still online. Region copy is intentionally skipped
        // (too heavy for shutdown); the limbo teleports them to the right coords with the right items.
        for (Player op : Bukkit.getOnlinePlayers()) {
            try {
                op.saveData();
                this.captureLimboSnapshot(op);
            } catch (Throwable t) {
                this.getLogger().warning("[LimboSync] shutdown snapshot failed for " + op.getName() + ": " + t.getMessage());
            }
        }
        for (PendingTeleport pendingTeleport : this.pendingTeleports.values()) {
            if (pendingTeleport.task == null) continue;
            pendingTeleport.task.cancel();
        }
        this.pendingTeleports.clear();
        for (PendingRtpTeleport pendingRtpTeleport : this.pendingRtpTeleports.values()) {
            if (pendingRtpTeleport.task == null) continue;
            pendingRtpTeleport.task.cancel();
        }
        this.pendingRtpTeleports.clear();
        for (PendingHomeTeleport pendingHomeTeleport : this.pendingHomeTeleports.values()) {
            if (pendingHomeTeleport.task == null) continue;
            pendingHomeTeleport.task.cancel();
        }
        this.pendingHomeTeleports.clear();
        if (this.playerSyncManager != null) {
            this.playerSyncManager.shutdown();
        }
        if (this.dataSource != null) {
            try { this.dataSource.close(); } catch (Throwable ignored) {}
            this.dataSource = null;
        }
        if (this.maintenanceQueueManager != null) {
            this.maintenanceQueueManager.shutdown();
        }
        this.localReplyTargets.clear();
        this.teamChatModeCache.clear();
        this.muteCacheExpiry.clear();
        this.muteCacheValue.clear();
        this.pendingHomeDeleteSlot.clear();
        this.playerSettingsCache.clear();
        this.shopSelectionState.clear();
        this.ordersViewState.clear();
        this.orderBuilderState.clear();
        this.ahViewState.clear();
        this.pendingTextInputs.clear();
        this.ahSellState.clear();
        for (TaskHandle taskHandle : this.sidebarTasks.values()) {
            if (taskHandle == null) continue;
            taskHandle.cancel();
        }
        if (this.notificationPollTask != null) {
            this.notificationPollTask.cancel();
            this.notificationPollTask = null;
        }
        this.sidebarTasks.clear();
        this.lastActivityTime.clear();
        this.lastPlaytimeFlush.clear();
    }

    private void setupEconomy() {
        try {
            RegisteredServiceProvider rsp = Bukkit.getServicesManager().getRegistration(Economy.class);
            if (rsp != null) {
                this.economy = (Economy)rsp.getProvider();
            }
        }
        catch (NoClassDefFoundError ignored) {
            this.economy = null;
        }
    }

    private void setupChat() {
        try {
            RegisteredServiceProvider rsp = Bukkit.getServicesManager().getRegistration(Chat.class);
            if (rsp != null) {
                this.chatProvider = (Chat)rsp.getProvider();
            }
        }
        catch (NoClassDefFoundError ignored) {
            this.chatProvider = null;
        }
    }

    private boolean isFoliaRuntime() {
        return Bukkit.getName().toLowerCase().contains("folia");
    }

    private void loadShopConfig() {
        File file;
        File root;
        File absData1 = this.getDataFolder().getAbsoluteFile();
        File file2 = root = absData1.getParentFile() != null ? absData1.getParentFile().getParentFile() : null;
        if (root != null) {
            File externalDir = new File(root, "configs/shop");
            File categoriesFile = new File(externalDir, "categories.yml");
            File itemsDir = new File(externalDir, "items");
            if (categoriesFile.exists() && itemsDir.isDirectory()) {
                this.shopConfig = this.loadShopConfigFromExternal(categoriesFile, itemsDir);
                return;
            }
        }
        if (!this.getDataFolder().exists()) {
            this.getDataFolder().mkdirs();
        }
        if (!(file = new File(this.getDataFolder(), "shop.yml")).exists()) {
            this.saveResource("shop.yml", false);
        }
        this.shopConfig = YamlConfiguration.loadConfiguration((File)file);
    }

    private void loadSellConfig() {
        File absData = this.getDataFolder().getAbsoluteFile();
        File root = absData.getParentFile() != null ? absData.getParentFile().getParentFile() : null;
        if (root != null) {
            File externalFile = new File(root, "configs/sell/prices.yml");
            if (externalFile.exists()) {
                this.sellConfig = YamlConfiguration.loadConfiguration(externalFile);
                ConfigurationSection prices = this.sellConfig.getConfigurationSection("prices");
                int count = prices != null ? prices.getKeys(false).size() : 0;
                this.getLogger().info("[sell] Loaded " + count + " prices from " + externalFile.getAbsolutePath());
                return;
            }
            this.getLogger().warning("[sell] prices.yml not found at: " + new File(root, "configs/sell/prices.yml").getAbsolutePath());
        }
        this.sellConfig = new YamlConfiguration();
        this.sellConfig.set("prices", new HashMap());
    }

    private void loadWorthConfig() {
        File externalFile;
        File root;
        File absData2 = this.getDataFolder().getAbsoluteFile();
        File file = root = absData2.getParentFile() != null ? absData2.getParentFile().getParentFile() : null;
        if (root != null && (externalFile = new File(root, "configs/reused/Essentials/worth.yml")).exists()) {
            this.worthConfig = YamlConfiguration.loadConfiguration((File)externalFile);
            return;
        }
        File serverWorth = new File(this.getDataFolder().getParentFile(), "Essentials/worth.yml");
        if (serverWorth.exists()) {
            this.worthConfig = YamlConfiguration.loadConfiguration((File)serverWorth);
            return;
        }
        this.worthConfig = new YamlConfiguration();
    }

    private FileConfiguration loadShopConfigFromExternal(File categoriesFile, File itemsDir) {
        YamlConfiguration out = new YamlConfiguration();
        YamlConfiguration categories = YamlConfiguration.loadConfiguration((File)categoriesFile);
        ConfigurationSection section = categories.getConfigurationSection("categories");
        if (section == null) {
            return out;
        }
        for (String key : section.getKeys(false)) {
            String base = "shop.categories." + key;
            out.set(base + ".slot", (Object)section.getInt(key + ".slot", 0));
            out.set(base + ".icon", (Object)section.getString(key + ".icon", "CHEST"));
            out.set(base + ".name", (Object)section.getString(key + ".name", this.capitalize(key)));
            out.set(base + ".title", (Object)section.getString(key + ".title", "Shop \u00a78\u00bb \u00a7f" + this.capitalize(key)));
            File itemsFile = new File(itemsDir, key + ".yml");
            if (!itemsFile.exists()) continue;
            YamlConfiguration items = YamlConfiguration.loadConfiguration((File)itemsFile);
            ArrayList<Map> mapList = new ArrayList<Map>();
            for (Map row : items.getMapList("items")) {
                mapList.add(row);
            }
            out.set(base + ".items", mapList);
        }
        return out;
    }

    private void registerCommand(String label, CommandExecutor exec) {
        PluginCommand cmd = this.getCommand(label);
        if (cmd != null) {
            cmd.setExecutor(exec);
            if (exec instanceof TabCompleter) {
                TabCompleter completer = (TabCompleter)exec;
                cmd.setTabCompleter(completer);
            }
        }
    }

    // Background DB health probe. Drives the join gate below — if the database is unreachable,
    // we deny new logins rather than let players join into a broken/data-losing state.
    private void startDbHealthCheck() {
        this.runAsyncRepeatingTask(() -> {
            boolean ok;
            try (Connection c = this.openSyncConnection();
                 Statement s = c.createStatement();
                 ResultSet r = s.executeQuery("SELECT 1")) {
                ok = r.next();
            } catch (Throwable t) {
                ok = false;
            }
            if (ok != this.dbHealthy) {
                this.getLogger().warning("[DB] health changed -> " + (ok ? "RECOVERED (joins allowed)" : "UNREACHABLE (blocking new joins)"));
            }
            this.dbHealthy = ok;
        }, 100L, 300L); // first check ~5s after enable, then every 15s
    }

    // DB-down join gate: if the database is unreachable, deny logins with a friendly message
    // (configurable). Runs LOWEST so it decides before the staff-priority/full-server logic.
    @EventHandler(priority=EventPriority.LOWEST)
    public void onLoginDbGate(PlayerLoginEvent e) {
        if (this.dbHealthy) {
            return;
        }
        String msg = this.settings.getString("db.unavailable_kick_message",
            "&c&l{brand} is temporarily unavailable\n\n&cWe're having trouble reaching our database.\n&cPlease try again in a few minutes.");
        e.disallow(PlayerLoginEvent.Result.KICK_OTHER, this.legacyColorize(msg));
    }

    // Limbo return signal: stamp limbo_control.smp_ready_at = NOW() the moment the SMP has
    // FULLY booted (ServerLoadEvent fires right at "Done"). The limbo polls this and returns
    // held players the instant the SMP is actually ready, instead of waiting a blanket TCP-up
    // grace. Only the STARTUP load matters (RELOAD also fires this event).
    @EventHandler
    public void onServerLoad(org.bukkit.event.server.ServerLoadEvent e) {
        if (e.getType() != org.bukkit.event.server.ServerLoadEvent.LoadType.STARTUP) return;
        this.runAsyncTask(() -> {
            try (Connection c = this.openSyncConnection();
                 PreparedStatement ps = c.prepareStatement(
                    "INSERT INTO limbo_control (id, smp_ready_at) VALUES (1, NOW()) ON DUPLICATE KEY UPDATE smp_ready_at=NOW()")) {
                ps.executeUpdate();
                this.getLogger().info("[LimboMaint] SMP ready signal written (limbo will return held players).");
            } catch (Exception ex) {
                this.getLogger().warning("[LimboMaint] ready signal failed: " + ex.getMessage());
            }
        });
    }

    // Staff priority join: let staff bypass the server-full cap (D19).
    // Higher-priority ranks always get in even at max-players.
    @EventHandler(priority=EventPriority.HIGHEST)
    public void onLoginStaffPriority(PlayerLoginEvent e) {
        if (e.getResult() != PlayerLoginEvent.Result.KICK_FULL) return;
        Player p = e.getPlayer();
        // priority 1-7 = staff (dev..mod). pizza++ (8) / pizza+ (9) do NOT bypass full.
        if (this.getQueuePriority(p) <= 7 || p.hasPermission("pizzasmp.joinfull")) {
            e.allow();
        }
    }

    @EventHandler
    public void onJoin(PlayerJoinEvent e) {
        e.joinMessage(null);
        this.guardVoidOnJoin(e.getPlayer());   // don't let a void-kicked player load back into the void
        this.refreshSkinOnJoin(e.getPlayer()); // re-fetch skin from Mojang so skin changes take effect
        long now = System.currentTimeMillis();
        this.lastActivityTime.put(e.getPlayer().getUniqueId(), now);
        this.lastPlaytimeFlush.put(e.getPlayer().getUniqueId(), now);
        if (this.playerSyncManager != null) {
            this.playerSyncManager.handleJoin(e.getPlayer());
        }
        this.clearUnexpectedJoinInvisibility(e.getPlayer());
        // Follow broadcast: followers see this player join.
        this.notifyFollowers(e.getPlayer().getUniqueId(), e.getPlayer().getName(), "joined.", false);
        this.refreshTabName(e.getPlayer());
        this.syncVaultOnJoin(e.getPlayer());
        this.loadSettingsIntoCache(e.getPlayer());
        this.scheduleMutualRefresh(e.getPlayer().getUniqueId());   // locator-bar friends-only cache
        this.runAsyncTask(() -> this.notifyPendingOrderDeliveries(e.getPlayer().getUniqueId()));
        this.refreshNetworkPlayerNameCacheAsync();
        this.runOnPlayerThread(e.getPlayer(), this::refreshVisibilityForAll);
        if (this.maintenanceQueueManager != null) {
            this.maintenanceQueueManager.handleJoin(e.getPlayer());
        }
        // Bedrock players (Floodgate UUID prefix) are exempt from GrimAC anticheat
        if (e.getPlayer().getUniqueId().toString().startsWith("00000000-0000-0000-")) {
            e.getPlayer().addAttachment(this, "grim.exempt", true);
        }
        // Queue gate: if capacity threshold exceeded, hold player in queue
        if (this.shouldQueue(e.getPlayer())) {
            Player qp = e.getPlayer();
            this.runPlayerTaskLater(qp, () -> this.enqueuePlayer(qp), 5L);
            return;
        }
        // Combat logout death screen on next join
        if (this.combatLoggedPending.remove(e.getPlayer().getUniqueId())) {
            Player p = e.getPlayer();
            this.runPlayerTaskLater(p, () -> {
                if (!p.isOnline()) return;
                p.showTitle(net.kyori.adventure.title.Title.title(
                    Component.text("You Died").color(net.kyori.adventure.text.format.NamedTextColor.GRAY),
                    Component.text("You logged out of combat").color(net.kyori.adventure.text.format.NamedTextColor.GRAY),
                    net.kyori.adventure.title.Title.Times.times(java.time.Duration.ofMillis(500), java.time.Duration.ofSeconds(5), java.time.Duration.ofMillis(500))
                ));
            }, 10L);
        }
    }

    private void clearUnexpectedJoinInvisibility(Player player) {
        this.runOnPlayerThread(player, () -> {
            if (!player.isOnline() || !player.hasPotionEffect(PotionEffectType.INVISIBILITY)) {
                return;
            }
            player.removePotionEffect(PotionEffectType.INVISIBILITY);
            this.refreshVisibilityForAll();
        });
    }

    @EventHandler
    public void onQuit(PlayerQuitEvent e) {
        this.runAsyncTask(() -> this.flushPendingLongStatsFor(e.getPlayer().getUniqueId()));
        long elapsed;
        e.quitMessage(null);
        UUID uuid = e.getPlayer().getUniqueId();
        // Follow broadcast: followers see this player leave.
        this.notifyFollowers(uuid, e.getPlayer().getName(), "left.", false);
        Long flushAt = this.lastPlaytimeFlush.remove(uuid);
        this.lastActivityTime.remove(uuid);
        if (flushAt != null && (elapsed = (System.currentTimeMillis() - flushAt) / 1000L) > 0L) {
            long secs = elapsed;
            this.runAsyncTask(() -> this.updatePlaytimeSeconds(uuid, secs));
        }
        if (this.isCombatTagged(e.getPlayer()) && this.settings.getBoolean("combat.quit_death", true)) {
            this.applyCombatLogoutPenalty(e.getPlayer());
        }
        this.cancelPendingTeleport(e.getPlayer(), false);
        this.cancelPendingRtp(uuid);
        this.mutualFriendsCache.remove(uuid);   // locator-bar friends-only cache
        this.rtpCooldowns.remove(uuid);
        this.clearCombatTag(uuid);
        this.localReplyTargets.remove(uuid);
        this.teamChatModeCache.remove(uuid);
        this.muteCacheExpiry.remove(uuid);
        this.muteCacheValue.remove(uuid);
        this.pendingHomeDeleteSlot.remove(uuid);
        this.cancelPendingHomeTeleport(uuid);
        this.playerSettingsCache.remove(uuid);
        this.shopSelectionState.remove(uuid);
        this.ordersViewState.remove(uuid);
        this.orderBuilderState.remove(uuid);
        this.ahViewState.remove(uuid);
        this.pendingTextInputs.remove(uuid);
        this.ahSellState.remove(uuid);
        this.activeRtpSearches.remove(uuid);
        this.queuedPlayers.remove(uuid);
        this.joinQueue.removeIf(q -> q.uuid.equals(uuid));
        this.queueReturnLocations.remove(uuid);
        this.queueReturnGamemodes.remove(uuid);
        this.lastThrottledCommandTime.remove(uuid);
        this.cancelSidebarTask(uuid);
        e.getPlayer().setScoreboard(Bukkit.getScoreboardManager().getMainScoreboard());
        this.refreshNetworkPlayerNameCacheAsync();
        this.refreshVisibilityForAll();
        if (this.playerSyncManager != null) {
            this.playerSyncManager.handleQuit(e.getPlayer());
        }
    }

