    @EventHandler(ignoreCancelled=true)
    public void onGameModeChange(PlayerGameModeChangeEvent e) {
        if (this.playerSyncManager != null) {
            this.playerSyncManager.handleGameModeChange(e.getPlayer(), e.getNewGameMode());
        }
        // Vanilla clients render spectators in grey italic in the tab list. Re-assert a
        // plain non-italic list name once the new gamemode has actually applied.
        Player gp = e.getPlayer();
        this.runPlayerTaskLater(gp, () -> { if (gp.isOnline()) this.refreshTabName(gp); }, 1L);
    }

    // Force a plain, non-italic tab-list name so spectator-mode players aren't shown
    // greyed/italicized, and pin a constant list order so the vanilla client no
    // longer demotes spectators (incl. admins) to the bottom of the tab list.
    private void refreshTabName(Player p) {
        if (p == null || !p.isOnline()) return;
        p.playerListName(Component.text(p.getName())
            .color(net.kyori.adventure.text.format.NamedTextColor.WHITE)
            .decoration(net.kyori.adventure.text.format.TextDecoration.ITALIC, false));
        try { p.setPlayerListOrder(1); } catch (Throwable ignored) {}
    }

