    @EventHandler(priority=EventPriority.HIGHEST, ignoreCancelled=false)
    public void onRespawnAnchorInteract(PlayerInteractEvent event) {
        if (event.getHand() != EquipmentSlot.HAND || event.getAction() != org.bukkit.event.block.Action.RIGHT_CLICK_BLOCK) {
            return;
        }
        Block block = event.getClickedBlock();
        if (block == null || block.getType() != Material.RESPAWN_ANCHOR) {
            return;
        }
        if (block.getWorld().getEnvironment() == World.Environment.NETHER) {
            return;
        }
        if (!(block.getBlockData() instanceof RespawnAnchor anchorData) || anchorData.getCharges() <= 0) {
            return;
        }
        ItemStack heldItem = event.getItem();
        if (heldItem != null && heldItem.getType() == Material.GLOWSTONE && anchorData.getCharges() < 4) {
            return;
        }
        event.setUseInteractedBlock(Event.Result.DENY);
        event.setUseItemInHand(Event.Result.DENY);
        event.setCancelled(true);
        Location center = block.getLocation().add(0.5, 0.5, 0.5);
        block.setType(Material.AIR, false);
        block.getWorld().createExplosion(center, 5.0f, true, true);
    }

    // EnderchestExpander opens a DETACHED 54-slot inventory titled "§7Enderchest" (both via /ec and by
    // right-clicking the block), so the vanilla ender-chest open sound + lid animation never fire.
    // Hook EE's inventory directly (by title) so the FX works for BOTH open paths.
    private static final String EE_TITLE = "§7Enderchest";
    @EventHandler(priority=EventPriority.MONITOR)
    public void onEnderChestOpenFx(org.bukkit.event.inventory.InventoryOpenEvent event) {
        if (!(event.getPlayer() instanceof Player p)) return;
        if (!EE_TITLE.equals(event.getView().getTitle())) return;
        p.playSound(p.getLocation(), Sound.BLOCK_ENDER_CHEST_OPEN, 0.6f, 1.0f);
        // If they opened it by looking at an ender chest block, raise that block's lid.
        Block tb = p.getTargetBlockExact(6);
        if (tb != null && tb.getType() == Material.ENDER_CHEST) {
            this.openEnderChestBlocks.put(p.getUniqueId(), tb.getLocation());
            this.sendChestLid(tb.getLocation(), true);
        }
    }

    @EventHandler(priority=EventPriority.MONITOR)
    public void onEnderChestCloseFx(org.bukkit.event.inventory.InventoryCloseEvent event) {
        if (!(event.getPlayer() instanceof Player p)) return;
        if (!EE_TITLE.equals(event.getView().getTitle())) return;
        p.playSound(p.getLocation(), Sound.BLOCK_ENDER_CHEST_CLOSE, 0.6f, 1.0f);
        Location loc = this.openEnderChestBlocks.remove(p.getUniqueId());
        if (loc != null && loc.getWorld() != null && loc.getBlock().getType() == Material.ENDER_CHEST) {
            this.sendChestLid(loc, false);
        }
    }

    // Raise/lower an ender chest lid for nearby players via the Block Action packet (best-effort).
    private void sendChestLid(Location loc, boolean open) {
        try {
            PacketContainer pkt = ProtocolLibrary.getProtocolManager().createPacket(PacketType.Play.Server.BLOCK_ACTION);
            pkt.getBlockPositionModifier().write(0, new com.comphenix.protocol.wrappers.BlockPosition(loc.getBlockX(), loc.getBlockY(), loc.getBlockZ()));
            pkt.getIntegers().write(0, 1);                 // action id: 1 = chest open/close
            pkt.getIntegers().write(1, open ? 1 : 0);      // param: viewer count (>=1 raises the lid)
            pkt.getBlocks().write(0, Material.ENDER_CHEST);
            for (Player viewer : loc.getWorld().getPlayers()) {
                if (viewer.getLocation().distanceSquared(loc) <= 4096.0) {  // within 64 blocks
                    ProtocolLibrary.getProtocolManager().sendServerPacket(viewer, pkt);
                }
            }
        } catch (Throwable ignored) { /* animation is best-effort; sound already played */ }
    }

    @EventHandler(ignoreCancelled=true)
    public void onNetworkTabComplete(TabCompleteEvent event) {
        CommandSender commandSender = event.getSender();
        if (!(commandSender instanceof Player)) {
            return;
        }
        Player player = (Player)commandSender;
        ParsedTabRequest request = this.parseTabRequest(event.getBuffer());
        if (request == null) {
            return;
        }
        if ("punish".equals(request.label()) && request.argumentIndex() == 2) {
            event.setCompletions(this.mergeCompletions(event.getCompletions(), request.currentToken(), List.of()));
            return;
        }
        if (!this.supportsNetworkPlayerCompletion(request.label(), request.argumentIndex())) {
            return;
        }
        List<String> suggestions = this.completeNetworkPlayerNames(request.currentToken(), player.getUniqueId());
        if (!suggestions.isEmpty()) {
            event.setCompletions(this.mergeCompletions(event.getCompletions(), request.currentToken(), suggestions));
        }
    }

    @EventHandler(ignoreCancelled=true)
    public void onAsyncNetworkTabComplete(AsyncTabCompleteEvent event) {
        CommandSender commandSender;
        if (!event.isCommand() || !((commandSender = event.getSender()) instanceof Player)) {
            return;
        }
        Player player = (Player)commandSender;
        ParsedTabRequest request = this.parseTabRequest(event.getBuffer());
        if (request == null) {
            return;
        }
        ArrayList<String> completions = new ArrayList<String>(event.getCompletions());
        if ("punish".equals(request.label()) && request.argumentIndex() == 2) {
            event.setCompletions(this.mergeCompletions(completions, request.currentToken(), List.of()));
            event.setHandled(true);
            return;
        }
        if (!this.supportsNetworkPlayerCompletion(request.label(), request.argumentIndex())) {
            return;
        }
        List<String> suggestions = this.queryNetworkPlayerNames(request.currentToken(), player.getUniqueId(), 100);
        if (suggestions.isEmpty()) {
            return;
        }
        event.setCompletions(this.mergeCompletions(completions, request.currentToken(), suggestions));
        event.setHandled(true);
    }

    @EventHandler(ignoreCancelled=true)
    public void onCombatTag(EntityDamageByEntityEvent e) {
        Entity entity = e.getEntity();
        if (!(entity instanceof Player)) {
            return;
        }
        Player victim = (Player)entity;
        Player attacker = this.resolveDamageSourcePlayer(e.getDamager());
        if (attacker == null || attacker.getUniqueId().equals(victim.getUniqueId())) {
            return;
        }
        long expireAt = System.currentTimeMillis() + (long)this.getCombatTagSeconds() * 1000L;
        this.applyCombatTag(victim, expireAt);
        this.applyCombatTag(attacker, expireAt);
    }

    // Resolves the responsible player behind any damage source: direct hits, projectiles,
    // end-crystal / bed / anchor explosions (via tracked igniter), TNT, and area-effect clouds.
    private Player resolveDamageSourcePlayer(Entity damager) {
        if (damager == null) return null;
        if (damager instanceof Player p) return p;
        if (damager instanceof Projectile proj) {
            Object shooter = proj.getShooter();
            if (shooter instanceof Player p) return p;
            return null;
        }
        if (damager instanceof org.bukkit.entity.TNTPrimed tnt) {
            Entity src = tnt.getSource();
            if (src instanceof Player p) return p;
            return null;
        }
        if (damager instanceof org.bukkit.entity.AreaEffectCloud cloud) {
            org.bukkit.projectiles.ProjectileSource src = cloud.getSource();
            if (src instanceof Player p) return p;
            return null;
        }
        // End crystals / beds / anchors: look up who last ignited them (tracked below).
        UUID igniter = this.explosionIgniters.get(damager.getUniqueId());
        if (igniter != null) {
            Player p = Bukkit.getPlayer(igniter);
            if (p != null) return p;
        }
        return null;
    }

    // Track who ignites end crystals (so their explosion damage tags combat).
    @EventHandler(priority=EventPriority.MONITOR, ignoreCancelled=true)
    public void onCrystalIgnite(EntityDamageByEntityEvent e) {
        if (!(e.getEntity() instanceof org.bukkit.entity.EnderCrystal)) return;
        Player p = this.resolveDamageSourcePlayer(e.getDamager());
        if (p != null) {
            this.explosionIgniters.put(e.getEntity().getUniqueId(), p.getUniqueId());
        }
    }

    @EventHandler(priority=EventPriority.HIGH)
    public void onDeathClearCombatTag(PlayerDeathEvent e) {
        e.deathMessage(null);
        Player victim = e.getPlayer();
        this.clearCombatTag(victim.getUniqueId());
        this.runAsyncTask(() -> this.incrementLongStat(victim.getUniqueId(), "deaths", 1L));
        this.refreshSidebarSoon(victim);
        // Follow broadcast: people who follow the victim see their death.
        this.notifyFollowers(victim.getUniqueId(), victim.getName(), "died.", false);
        Player killer = victim.getKiller();
        if (killer != null && !killer.getUniqueId().equals(victim.getUniqueId())) {
            this.clearCombatTag(killer.getUniqueId());
            this.refreshSidebarSoon(killer);
            // Follow broadcast: people who follow the killer see their kill.
            this.notifyFollowers(killer.getUniqueId(), killer.getName(), "killed §f" + victim.getName() + "§7.", false);
            UUID killerUuid = killer.getUniqueId();
            final long killShards = this.isPizzaPlusPlus(killer) ? 20L : 10L; // pizza++ earns double
            this.runAsyncTask(() -> {
                this.incrementLongStat(killerUuid, "kills", 1L);
                this.depositShards(killerUuid, killShards);
            });
            killer.sendActionBar((Component)Component.text("§c+1"));
            this.claimBountiesOnKill(killer, victim);
        } else {
            // No killer (self-kill / environment death) — victim claims their own bounty
            this.claimBountiesOnKill(victim, victim);
        }
    }

    @EventHandler(priority=EventPriority.MONITOR)
    public void onDeathProtectDrops(PlayerDeathEvent e) {
        List<ItemStack> drops = new java.util.ArrayList<>(e.getDrops());
        if (drops.isEmpty()) return;
        e.getDrops().clear();
        Location loc = e.getPlayer().getLocation();
        World dropWorld = loc.getWorld();
        if (dropWorld == null) return;
        for (ItemStack drop : drops) {
            if (drop == null || drop.getType() == Material.AIR) continue;
            org.bukkit.entity.Item item = dropWorld.dropItemNaturally(loc, drop);
            this.protectedDeathDrops.add(item.getUniqueId());
        }
    }

    @EventHandler
    public void onDeathDropDespawn(org.bukkit.event.entity.ItemDespawnEvent e) {
        if (!this.protectedDeathDrops.contains(e.getEntity().getUniqueId())) return;
        // Allow despawn after 10 minutes (12000 ticks) so truly abandoned drops eventually clear
        if (e.getEntity().getTicksLived() >= 12000) {
            this.protectedDeathDrops.remove(e.getEntity().getUniqueId());
            return;
        }
        e.setCancelled(true);
    }

    @EventHandler
    public void onDeathDropPickup(org.bukkit.event.entity.EntityPickupItemEvent e) {
        this.protectedDeathDrops.remove(e.getItem().getUniqueId());
    }
    // (Removed the worth-lore inventory resync hack — unit-worth lore is amount-independent,
    // so client stacking prediction stays consistent without forced WINDOW_ITEMS resends.)

    @EventHandler(priority=EventPriority.LOWEST)
    public void onPlayerRespawn(PlayerRespawnEvent e) {
        Player player = e.getPlayer();
        // Re-apply settings-based night vision (effects clear on death)
        this.runPlayerTaskLater(player, () -> this.applyNightVisionPreference(player), 5L);
        if (this.isSettingEnabledCached(player.getUniqueId(), "chainmail_on_respawn")) {
            // Delay 5 ticks: armor slots can be re-cleared by the client/other plugins right
            // after respawn, so set them a touch later and force an inventory update.
            this.runPlayerTaskLater(player, () -> {
                if (!player.isOnline()) return;
                org.bukkit.inventory.PlayerInventory inv = player.getInventory();
                // Kit into the hotbar in order: Sword, Helmet, Chest, Legs, Boots, Steak.
                inv.setItem(0, new ItemStack(Material.IRON_SWORD));
                inv.setItem(1, new ItemStack(Material.CHAINMAIL_HELMET));
                inv.setItem(2, new ItemStack(Material.CHAINMAIL_CHESTPLATE));
                inv.setItem(3, new ItemStack(Material.CHAINMAIL_LEGGINGS));
                inv.setItem(4, new ItemStack(Material.CHAINMAIL_BOOTS));
                inv.setItem(5, new ItemStack(Material.COOKED_BEEF, 16));
                player.updateInventory();
            }, 5L);
        }
        // Random respawn: teleport player to a random location 2 ticks after respawn
        // (can't use setRespawnLocation with async chunk search, so post-respawn TP)
        if (e.isBedSpawn() || e.isAnchorSpawn()) return;
        this.runPlayerTaskLater(player, () -> {
            if (!player.isOnline()) return;
            World w = Bukkit.getWorld("world");
            if (w == null && !Bukkit.getWorlds().isEmpty()) w = Bukkit.getWorlds().getFirst();
            if (w == null) return;
            if (!this.activeRtpSearches.add(player.getUniqueId())) return;
            double borderRadius = 3000.0;
            double centerX = 0.0;
            double centerZ = 0.0;
            if (w.getWorldBorder() != null) {
                centerX = w.getWorldBorder().getCenter().getX();
                centerZ = w.getWorldBorder().getCenter().getZ();
                borderRadius = Math.max(256.0, w.getWorldBorder().getSize() / 2.0 - (double)this.getRtpBorderPadding());
            }
            RtpSearchPlan plan = new RtpSearchPlan(w.getName(), centerX, centerZ, Math.max(0.0, this.settings.getDouble("rtp.min-radius", 500.0)), borderRadius, Math.max(8, this.settings.getInt("rtp.search-attempts", 96)), player.getLocation().getYaw());
            this.searchRtpLocation(player.getUniqueId(), plan, 0);
        }, 2L);
    }

    @EventHandler(ignoreCancelled=true)
    public void onPortalCombatBlock(PlayerPortalEvent e) {
        Player player = e.getPlayer();
        if (player == null) {
            return;
        }
        if (this.isCombatTagged(player)) {
            e.setCancelled(true);
            player.sendActionBar((Component)Component.text((String)"\u00a7cYou are in combat! Cannot use portals."));
            this.logCombatBlocked(player, "portal");
            return;
        }
        // The End is closed (see endRtpClosed) \u2014 block stronghold/gateway portal entry too.
        if (this.endRtpClosed && e.getTo() != null && e.getTo().getWorld() != null
                && e.getTo().getWorld().getEnvironment() == org.bukkit.World.Environment.THE_END) {
            e.setCancelled(true);
            player.sendActionBar(this.worldLockComponent());
        }
    }

