    // ---- Advanced search spell-check ----------------------------------------------------------
    // Corrects typos in AH/orders searches. Only fires when the query matches NOTHING (no item name
    // contains it) — exact, substring and abbreviation matches are never overridden. The distance
    // is a weighted Damerau-Levenshtein tuned for how typos actually happen on a keyboard:
    //   - substituting an ADJACENT QWERTY key costs 0.45 (miss-click: "seord" -> "sword")
    //   - transposing two neighbouring letters costs 0.70 ("sowrd" -> "sword")
    //   - doubling/dropping a repeated letter costs 0.55 ("swoord"/"diamnd" runs), other ins/del 0.80
    //   - any other substitution costs 1.00
    // Candidates are full item names AND their words ("sword" from "diamond_sword") so a corrected
    // word still substring-matches every matching item; multi-word queries correct per word
    // ("dimond sord" -> "diamond_sword").

    private static volatile java.util.List<String> ITEM_QUERY_DICT = null;

    private java.util.List<String> itemQueryDict() {
        java.util.List<String> dict = ITEM_QUERY_DICT;
        if (dict == null) {
            java.util.LinkedHashSet<String> set = new java.util.LinkedHashSet<>();
            for (Material m : Material.values()) {
                if (!m.isItem()) continue;
                String name = m.name().toLowerCase(Locale.ROOT);
                set.add(name);
                for (String tok : name.split("_")) if (tok.length() >= 3) set.add(tok);
            }
            dict = new java.util.ArrayList<>(set);
            ITEM_QUERY_DICT = dict;
        }
        return dict;
    }

    // Key-adjacency across the commonly used physical layouts: a substitution counts as a
    // "miss-click" if the two keys are neighbours on ANY of QWERTY, AZERTY or QWERTZ (union map,
    // precomputed once — covers same-row neighbours plus the stagger diagonals of adjacent rows).
    private static final java.util.Map<Character, java.util.Set<Character>> KEY_NEIGHBORS = buildKeyNeighbors();

    private static java.util.Map<Character, java.util.Set<Character>> buildKeyNeighbors() {
        String[][] layouts = {
            {"1234567890", "qwertyuiop", "asdfghjkl", "zxcvbnm"},    // QWERTY
            {"1234567890", "azertyuiop", "qsdfghjklm", "wxcvbn"},    // AZERTY
            {"1234567890", "qwertzuiop", "asdfghjkl", "yxcvbnm"}     // QWERTZ
        };
        java.util.Map<Character, java.util.Set<Character>> map = new java.util.HashMap<>();
        for (String[] rows : layouts) {
            for (int r = 0; r < rows.length; r++) {
                for (int c = 0; c < rows[r].length(); c++) {
                    java.util.Set<Character> set = map.computeIfAbsent(rows[r].charAt(c), k -> new java.util.HashSet<>());
                    if (c > 0) set.add(rows[r].charAt(c - 1));
                    if (c + 1 < rows[r].length()) set.add(rows[r].charAt(c + 1));
                    for (int dr = -1; dr <= 1; dr += 2) {
                        int rr = r + dr;
                        if (rr < 0 || rr >= rows.length) continue;
                        for (int dc = -1; dc <= 1; dc++) {
                            int cc = c + dc;
                            if (cc >= 0 && cc < rows[rr].length()) set.add(rows[rr].charAt(cc));
                        }
                    }
                }
            }
        }
        return map;
    }

    private static boolean keysAdjacent(char a, char b) {
        java.util.Set<Character> s = KEY_NEIGHBORS.get(a);
        return s != null && s.contains(b);
    }

    // Cheaper to drop/insert next to the same letter ("swoord" -> "sword", "diamnd" -> "diamond").
    private static double insDelCost(String s, int idx1based) {
        return (idx1based >= 2 && s.charAt(idx1based - 1) == s.charAt(idx1based - 2)) ? 0.55 : 0.80;
    }

    // Weighted Damerau-Levenshtein with early abandon; Double.MAX_VALUE when over budget.
    private double weightedEditDistance(String a, String b, double max) {
        int n = a.length(), m = b.length();
        if (Math.abs(n - m) * 0.55 > max) return Double.MAX_VALUE;
        double[] prev2 = null, prev = new double[m + 1], cur = new double[m + 1];
        for (int j = 0; j <= m; j++) prev[j] = j * 0.80;
        for (int i = 1; i <= n; i++) {
            cur[0] = i * 0.80;
            double rowMin = cur[0];
            for (int j = 1; j <= m; j++) {
                char ca = a.charAt(i - 1), cb = b.charAt(j - 1);
                double sub = ca == cb ? 0.0 : (keysAdjacent(ca, cb) ? 0.45 : 1.00);
                double best = Math.min(Math.min(cur[j - 1] + insDelCost(b, j), prev[j] + insDelCost(a, i)), prev[j - 1] + sub);
                if (prev2 != null && i > 1 && j > 1 && ca == b.charAt(j - 2) && a.charAt(i - 2) == cb) {
                    best = Math.min(best, prev2[j - 2] + 0.70);   // transposition
                }
                cur[j] = best;
                rowMin = Math.min(rowMin, best);
            }
            if (rowMin > max) return Double.MAX_VALUE;
            double[] t = prev2 == null ? new double[m + 1] : prev2;
            prev2 = prev; prev = cur; cur = t;
        }
        return prev[m] <= max ? prev[m] : Double.MAX_VALUE;
    }

    private String spellCorrectItemQuery(String raw) {
        if (raw == null || raw.isBlank()) return raw;
        String norm = raw.trim().toLowerCase(Locale.ROOT);
        String joined = norm.replace(' ', '_');
        for (Material m : Material.values()) {
            if (m.isItem() && m.name().toLowerCase(Locale.ROOT).contains(joined)) return raw;   // real hit
        }
        String[] words = norm.split("[ _]+");
        StringBuilder out = new StringBuilder();
        boolean changed = false;
        for (String w : words) {
            String c = this.spellCorrectWord(w);
            if (!w.equals(c)) changed = true;
            if (out.length() > 0) out.append('_');
            out.append(c);
        }
        return changed ? out.toString() : raw;
    }

    // ---- Command spell-check -------------------------------------------------------------------
    // //rtp (extra slashes) is auto-corrected and RUN. An unknown command with a close match either
    // auto-runs (single miss-click confidence) or gets a clickable "Did you mean /rtp?" message.
    // Staff-only commands are never suggested to players who lack them.
    private static final java.util.Set<String> CMD_SUGGEST_STAFF_PREFIXES = java.util.Set.of(
        "admin", "punish", "offend", "unoffend", "sus", "suspicious", "moderation", "freeze", "unfreeze",
        "stash", "spawnstash", "pizzaplus", "maintenance", "maintenancemotd", "limbomaint", "limbo",
        "branding", "vdthrottle", "sfmode", "staffmode", "gmcbypass", "atrack", "servermaint",
        "invsee", "vanish", "sudo", "eco", "lp", "luckperms", "gtp", "admindelhome", "queuetest");

    private boolean knownCommand(String label) {
        return Bukkit.getCommandMap().getKnownCommands().containsKey(label.toLowerCase(Locale.ROOT));
    }

    /** Can this player be shown/offered {@code cand} as a correction? (never leak staff commands) */
    private boolean cmdSuggestable(Player pl, boolean staff, String cand, org.bukkit.command.Command cmd) {
        if (cand.length() < 2 || cand.indexOf(':') >= 0) return false;
        if (staff) return true;
        return !CMD_SUGGEST_STAFF_PREFIXES.contains(cand) && (cmd == null || cmd.testPermissionSilent(pl));
    }

    // Full command-correction pipeline, applied to EVERY failed command in order of confidence:
    //   1) junk normalization — extra slashes, space after slash, stray prefix chars, trailing
    //      punctuation ("//rtp", "/ rtp", "/.rtp", "/rtp.", "/RTP,") -> run silently corrected
    //   2) concatenation split — "/rtpnether" -> "/rtp nether", "/homelootdrop" -> "/home lootdrop"
    //   3) keyboard-aware typo match — auto-runs at miss-click confidence, else clickable suggestion
    @EventHandler(priority = org.bukkit.event.EventPriority.LOWEST, ignoreCancelled = true)
    public void onCommandSpellCheck(PlayerCommandPreprocessEvent e) {
        String msg = e.getMessage();
        if (msg.length() < 2 || !msg.startsWith("/")) return;
        Player pl = e.getPlayer();

        // Normalize: drop leading slash, then any leading junk (more slashes, backslashes, dots,
        // spaces), split label/args, strip trailing punctuation typos from the label.
        String body = msg.substring(1).replaceFirst("^[/\\\\. ]+", "");
        int sp = body.indexOf(' ');
        String label = (sp < 0 ? body : body.substring(0, sp)).toLowerCase(Locale.ROOT);
        String args = sp < 0 ? "" : body.substring(sp);
        String cleanLabel = label.replaceAll("[^a-z0-9_\\-:]+$", "");
        if (cleanLabel.isEmpty() || cleanLabel.contains(":")) return;   // namespaced = intentional

        // 1) Junk-only fixes -> the command exists once cleaned: correct in place and let it run.
        if (this.knownCommand(cleanLabel)) {
            String fixed = "/" + cleanLabel + args;
            if (!msg.equals(fixed)) {
                e.setMessage(fixed);
                pl.sendActionBar(this.legacyColorize("&7Corrected to &#00BFFF/" + cleanLabel));
            }
            return;
        }
        if (!this.isSettingEnabledCached(pl.getUniqueId(), "search_spell_check")) return;
        boolean staff = pl.hasPermission("pizzasmp.pluginadmin");
        java.util.Map<String, org.bukkit.command.Command> known = Bukkit.getCommandMap().getKnownCommands();

        // 2) Concatenated command + argument: longest suggestable command that prefixes the label.
        String segBase = null;
        for (java.util.Map.Entry<String, org.bukkit.command.Command> en : known.entrySet()) {
            String cand = en.getKey();
            if (cand.length() < 3 || cleanLabel.length() <= cand.length() || !cleanLabel.startsWith(cand)) continue;
            if (!this.cmdSuggestable(pl, staff, cand, en.getValue())) continue;
            if (segBase == null || cand.length() > segBase.length()) segBase = cand;
        }
        if (segBase != null) {
            final String run = segBase + " " + cleanLabel.substring(segBase.length()) + args;
            e.setCancelled(true);
            pl.sendActionBar(this.legacyColorize("&7Corrected to &#00BFFF/" + run));
            this.runOnPlayerThread(pl, () -> Bukkit.dispatchCommand(pl, run));
            return;
        }

        // 3) Keyboard-aware typo correction against every command this player may see.
        String best = null;
        double bestD = cleanLabel.length() <= 4 ? 1.00 : 1.60;
        for (java.util.Map.Entry<String, org.bukkit.command.Command> en : known.entrySet()) {
            String cand = en.getKey();
            if (!this.cmdSuggestable(pl, staff, cand, en.getValue())) continue;
            if (Math.abs(cand.length() - cleanLabel.length()) > 2) continue;
            double d = this.weightedEditDistance(cleanLabel, cand, bestD);
            if (d < bestD - 1e-9) {
                bestD = d;
                best = cand;
                if (bestD <= 0.451) break;
            }
        }
        if (best == null) return;
        e.setCancelled(true);
        if (bestD <= 0.71) {
            // Single miss-click / transposition: confident enough to just run it.
            pl.sendActionBar(this.legacyColorize("&7Corrected to &#00BFFF/" + best));
            final String run = best + args;
            this.runOnPlayerThread(pl, () -> Bukkit.dispatchCommand(pl, run));
        } else {
            final String run = "/" + best + args;
            pl.sendMessage(Component.text("Unknown command. Did you mean ", net.kyori.adventure.text.format.NamedTextColor.GRAY)
                .append(Component.text(run, DIALOG_BRAND)
                    .clickEvent(net.kyori.adventure.text.event.ClickEvent.runCommand(run))
                    .hoverEvent(net.kyori.adventure.text.event.HoverEvent.showText(Component.text("Click to run " + run))))
                .append(Component.text("?", net.kyori.adventure.text.format.NamedTextColor.GRAY)));
        }
    }

    // Wrong prefix character typed in CHAT (".rtp", "\\rtp", ";home lootdrop"): the message never
    // reaches the command system, so catch it here — if the first token after the stray prefix is
    // exactly a known command, cancel the chat line (don't broadcast the typo) and run it.
    @EventHandler(priority = org.bukkit.event.EventPriority.LOWEST, ignoreCancelled = true)
    public void onChatCommandPrefixTypo(AsyncChatEvent e) {
        String plain = net.kyori.adventure.text.serializer.plain.PlainTextComponentSerializer.plainText().serialize(e.message());
        if (plain.length() < 2) return;
        char c0 = plain.charAt(0);
        if (c0 != '.' && c0 != '\\' && c0 != ';') return;
        String body = plain.substring(1).trim();
        if (body.isEmpty()) return;
        int sp = body.indexOf(' ');
        String label = (sp < 0 ? body : body.substring(0, sp)).toLowerCase(Locale.ROOT);
        if (label.contains(":") || !this.knownCommand(label)) return;   // not command-intent -> normal chat
        Player pl = e.getPlayer();
        if (!this.isSettingEnabledCached(pl.getUniqueId(), "search_spell_check")) return;
        e.setCancelled(true);
        final String run = body;
        this.runOnPlayerThread(pl, () -> {
            pl.sendActionBar(this.legacyColorize("&7Corrected to &#00BFFF/" + label));
            Bukkit.dispatchCommand(pl, run);
        });
    }

    // Fuzzy ONLINE player lookup for player-argument commands (/tpa, /msg, /pay, /follow, ...):
    // exact match, then unique-prefix, then keyboard-aware typo match ("folksypiza" -> FolksyPizza).
    // The typo stage respects the requester's Search Spell Check toggle.
    private Player fuzzyOnlinePlayer(Player requester, String name) {
        if (name == null || name.isBlank()) return null;
        Player exact = Bukkit.getPlayerExact(name);
        if (exact != null) return exact;
        String q = name.toLowerCase(Locale.ROOT);
        Player prefixMatch = null;
        int prefixCount = 0;
        for (Player p : Bukkit.getOnlinePlayers()) {
            if (p.getName().toLowerCase(Locale.ROOT).startsWith(q)) { prefixMatch = p; prefixCount++; }
        }
        if (prefixCount == 1) return prefixMatch;
        if (requester != null && !this.isSettingEnabledCached(requester.getUniqueId(), "search_spell_check")) return null;
        Player best = null;
        double bestD = q.length() <= 4 ? 1.00 : q.length() <= 8 ? 1.60 : 2.20;
        for (Player p : Bukkit.getOnlinePlayers()) {
            String n = p.getName().toLowerCase(Locale.ROOT);
            if (Math.abs(n.length() - q.length()) > 3) continue;
            double d = this.weightedEditDistance(q, n, bestD);
            if (d < bestD - 1e-9) { bestD = d; best = p; }
        }
        if (best != null && requester != null) {
            requester.sendActionBar(this.legacyColorize("&7Matched &#00BFFF" + best.getName()));
        }
        return best;
    }

    private String spellCorrectWord(String q) {
        if (q.length() < 3) return q;
        // Edit budget scales with word length: short words tolerate ~1 edit, long ones ~2+.
        double budget = q.length() <= 4 ? 1.00 : q.length() <= 7 ? 1.60 : 2.20;
        String best = null;
        double bestD = budget;
        for (String cand : this.itemQueryDict()) {
            if (Math.abs(cand.length() - q.length()) > 3) continue;
            double d = this.weightedEditDistance(q, cand, bestD);   // shrinking budget prunes hard
            if (d < bestD - 1e-9
                || (d <= bestD + 1e-9 && best != null
                    && Math.abs(cand.length() - q.length()) < Math.abs(best.length() - q.length()))) {
                bestD = d;
                best = cand;
                if (bestD <= 0.451) break;   // single adjacent miss-click: cannot do better
            }
        }
        return best != null ? best : q;
    }

    private void handleShopClick(Player p, ItemStack current, ClickType clickType) {
        if (current == null || current.getType() == Material.AIR || !current.hasItemMeta()) {
            return;
        }
        String id = this.uiActionId(current);
        if ((id == null || id.isBlank()) && TITLE_SHOP.equals(p.getOpenInventory().getTitle())) {
            Material type = current.getType();
            if (type == Material.END_STONE) {
                id = "shop_main_open:end";
            } else if (type == Material.NETHERRACK) {
                id = "shop_main_open:nether";
            } else if (type == Material.TOTEM_OF_UNDYING) {
                id = "shop_main_open:gear";
            } else if (type == Material.COOKED_BEEF) {
                id = "shop_main_open:food";
            } else if (type == Material.AMETHYST_SHARD) {
                id = "shop_main_open:shards";
            }
        }
        if (id == null || id.isBlank()) {
            return;
        }
        if ("shop_close".equals(id) || "shop_back_close".equals(id)) {
            p.closeInventory();
            return;
        }
        if ("shop_back_main".equals(id)) {
            this.openShopMain(p);
            return;
        }
        if (id.startsWith("shop_main_open:")) {
            String key = id.substring("shop_main_open:".length()).toLowerCase();
            if ("shards".equals(key)) {
                this.openShardShopMenu(p);
                return;
            }
            this.openShopCategoryMenu(p, key);
            return;
        }
        if (id.startsWith("shop_select:")) {
            String[] parts = id.split(":", 3);
            if (parts.length != 3) return;
            String categoryKey = parts[1].toLowerCase();
            String itemKey = parts[2].toLowerCase();
            this.openShopConfirmMenu(p, categoryKey, itemKey);
            return;
        }
        if (id.startsWith("shop_qty_add:")) {
            this.adjustShopQuantity(p, this.parseIntSafe(id.substring("shop_qty_add:".length()), 0));
            return;
        }
        if (id.startsWith("shop_qty_sub:")) {
            this.adjustShopQuantity(p, -this.parseIntSafe(id.substring("shop_qty_sub:".length()), 0));
            return;
        }
        if ("shop_confirm".equals(id)) {
            this.confirmShopPurchase(p);
            return;
        }
        if (id.equals("shop_cancel") || id.startsWith("shop_cancel:")) {
            // The category is encoded in the action id (shop_cancel:<cat>), so rapid back-clicking always
            // returns to the SAME category the player was in — never the End shop or the main page.
            int ci = id.indexOf(':');
            String cat = ci >= 0 ? id.substring(ci + 1) : null;
            if (cat == null || cat.isBlank()) {
                ShopSelectionState st = this.shopSelectionState.get(p.getUniqueId());
                cat = st != null ? st.categoryKey : null;
            }
            this.shopSelectionState.remove(p.getUniqueId());
            if (cat != null && !cat.isBlank()) this.openShopCategoryMenu(p, cat);
            else this.openShopMain(p);
            return;
        }
        if ("shop_open_main".equals(id)) {
            this.openShopMain(p);
            return;
        }
        if ("shop_open_shards".equals(id)) {
            this.openShardShopMenu(p);
            return;
        }
        if (id.startsWith("shard_open_crate:")) {
            String crateKey = id.substring("shard_open_crate:".length()).toLowerCase();
            if (crateKey.equals("amethyst")) return; // amethyst crate removed
            this.openShardCrateDetails(p, crateKey);
            return;
        }
        if (id.startsWith("shard_buy_crate:")) {
            this.openShardConfirm(p, "crate", id.substring("shard_buy_crate:".length()).toLowerCase());
            return;
        }
        if (id.startsWith("shard_buy_item:")) {
            this.openShardConfirm(p, "item", id.substring("shard_buy_item:".length()).toLowerCase());
            return;
        }
        if (id.startsWith("shard_do_crate:")) {
            this.purchaseCrate(p, id.substring("shard_do_crate:".length()).toLowerCase());
            return;
        }
        if (id.startsWith("shard_do_item:")) {
            this.purchaseShardItem(p, id.substring("shard_do_item:".length()).toLowerCase());
            return;
        }
        if (id.startsWith("shard_cancel_crate:")) {
            this.openShardCrateDetails(p, id.substring("shard_cancel_crate:".length()).toLowerCase());
            return;
        }
        if ("shard_cancel_item".equals(id)) {
            this.openShardShopMenu(p);
            return;
        }
        if ("shard_daily_claim".equals(id)) {
            this.claimDailyCrate(p);
            return;
        }
        if ("shard_daily_locked".equals(id)) {
            p.sendActionBar(Component.text("§cYour daily crate is not ready yet."));
            return;
        }
        if ("shard_back".equals(id)) {
            this.openShardShopMenu(p);
        }
    }

    private String fmtMoney(double value) {
        return this.formatCompactNumber(value);
    }

    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        String cmdNameLower = command.getName().toLowerCase(Locale.ROOT);
        if ("pizzasusflag".equals(cmdNameLower)) {
            this.handlePizzaSusFlagCommand(sender, args);
            return true;
        }
        // Console-capable (and admin players): switch the active brand profile.
        if ("branding".equals(cmdNameLower)) {
            if (sender instanceof Player pp && !pp.hasPermission(PERM_ADMIN_CONSOLE)) {
                pp.sendMessage("§cThis command does not exist.");
                return true;
            }
            this.handleBrandingCommand(sender, args);
            return true;
        }
        // Console-capable (and admin players): limbo full-stop maintenance. Used by scripts/maintenance_limbo.sh.
        if ("limbomaint".equals(cmdNameLower)) {
            if (sender instanceof Player pp && !pp.hasPermission(PERM_ADMIN_CONSOLE)) {
                pp.sendMessage("§cThis command does not exist.");
                return true;
            }
            this.handleLimboMaintCommand(sender, args);
            return true;
        }
        // Console-capable: shards give <player> <amount> (used by PizzaAdminTools for Pizza+/++ stipends).
        if ("shards".equals(cmdNameLower) && !(sender instanceof Player)) {
            if (args.length >= 3 && "give".equalsIgnoreCase(args[0])) {
                this.handleShardsGiveFromConsole(sender, args[1], args[2]);
            } else {
                sender.sendMessage("Usage: /shards give <player> <amount>");
            }
            return true;
        }
        if (!(sender instanceof Player)) {
            sender.sendMessage("Player-only command.");
            return true;
        }
        Player p = (Player)sender;
        switch (command.getName().toLowerCase()) {
            case "guide": {
                this.openGuide(p);
                break;
            }
            case "settings": {
                if (!p.hasPermission("pizzasmp.use.settings")) {
                    return true;
                }
                this.openSettings(p);
                break;
            }
            case "stats": {
                if (!p.hasPermission("pizzasmp.use.stats")) {
                    return true;
                }
                if (args.length >= 1) {
                    this.openStatsMenuFor(p, args[0]);
                } else {
                    this.openStatsMenu(p);
                }
                break;
            }
            case "shop": {
                if (!p.hasPermission("pizzasmp.use.shop")) {
                    return true;
                }
                this.openShopMain(p);
                break;
            }
            case "navigator": {
                this.openNavigator(p);
                break;
            }
            case "spawn": {
                this.routeWarpLikeCommand(p, "spawn");
                break;
            }
            case "warp": {
                if (args.length < 1) {
                    p.sendMessage("\u00a7cUsage: /warp <spawn|duels|pvp|survival|main|afk>");
                    return true;
                }
                this.routeWarpLikeCommand(p, args[0].toLowerCase());
                break;
            }
            case "rtp": {
                this.handleRtpCommand(p, args);
                break;
            }
            case "nv":
            case "nightvision": {
                this.handleNvCommand(p, args);
                break;
            }
            case "tpauto": {
                this.handleTpAutoCommand(p);
                break;
            }
            case "msg": 
            case "tell": 
            case "w": {
                this.handleMsgCommand(p, args);
                break;
            }
            case "reply": 
            case "r": {
                this.handleReplyCommand(p, args);
                break;
            }
            case "team":
            case "teams": {
                this.handleTeamCommand(p, args);
                break;
            }
            case "follow": {
                this.runAsyncTask(() -> this.handleFollowCommand(p, args));
                break;
            }
            case "unfollow": {
                this.runAsyncTask(() -> this.handleUnfollowCommand(p, args));
                break;
            }
            case "friend":
            case "friends": {
                this.handleFriendCommand(p, args);
                break;
            }
            case "sell": {
                this.handleSellCommand(p, args);
                break;
            }
            case "ah": {
                if (!p.hasPermission("pizzasmp.use.ah")) {
                    return true;
                }
                if (args.length >= 2 && "sell".equalsIgnoreCase(args[0])) {
                    this.handleAhSellInHandCommand(p, args[1]);
                    return true;
                }
                // Bare /ah always opens the clean homepage: default filter/sort, no search.
                AhViewState vs;
                if (args.length == 0) {
                    vs = new AhViewState();
                    this.ahViewState.put(p.getUniqueId(), vs);
                } else {
                    vs = this.ahViewState.computeIfAbsent(p.getUniqueId(), id -> new AhViewState());
                }
                if (args.length >= 1 && !"sell".equalsIgnoreCase(args[0])) {
                    String search = this.expandItemAbbrev(p.getUniqueId(), String.join(" ", args)).toLowerCase(Locale.ROOT);
                    UUID playerUuid = this.playerUuidByName(search);
                    if (playerUuid != null) {
                        vs.sellerFilter = playerUuid.toString();
                        vs.search = "";
                    } else {
                        vs.sellerFilter = null;
                        Material mat = Material.matchMaterial(search.toUpperCase(Locale.ROOT));
                        if (mat != null) {
                            vs.search = this.humanName(mat);
                        } else {
                            vs.search = search;
                        }
                    }
                }
                vs.page = 1;
                this.openAuctionHouseMenu(p);
                break;
            }
            case "orders": {
                if (!p.hasPermission("pizzasmp.use.orders")) {
                    p.sendMessage("\u00a7cYou do not have permission to use /orders.");
                    return true;
                }
                // Bare /orders always opens the clean homepage (same as /ah).
                OrdersViewState vs;
                if (args.length == 0) {
                    vs = new OrdersViewState();
                    this.ordersViewState.put(p.getUniqueId(), vs);
                } else {
                    vs = this.ordersViewState.computeIfAbsent(p.getUniqueId(), id -> new OrdersViewState());
                }
                if (args.length >= 1) {
                    String search = String.join(" ", args).toLowerCase(Locale.ROOT);
                    UUID playerUuid = this.playerUuidByName(search);
                    if (playerUuid != null) {
                        vs.creatorFilter = playerUuid.toString();
                        vs.search = "";
                    } else {
                        vs.creatorFilter = null;
                        vs.search = search;
                    }
                }
                vs.page = 1;
                this.openOrdersMenu(p);
                break;
            }
            case "afk": {
                if (!p.hasPermission("pizzasmp.use.afk")) {
                    return true;
                }
                this.routeWarpLikeCommand(p, "afk");
                break;
            }
            case "discord": {
                this.handleDiscordCommand(p);
                break;
            }
            case "gtp": {
                this.handleGtpCommand(p, args);
                break;
            }
            case "pizzadebug": {
                if (!p.isOp() && !p.hasPermission("pizzasmp.admin.debug")) {
                    return true;
                }
                if (args.length >= 1 && "hud".equalsIgnoreCase(args[0])) {
                    this.runAsyncTask(() -> {
                        StatsSnapshot stats = this.loadStatsSnapshot(p.getUniqueId());
                        String team = this.loadTeamName(p.getUniqueId());
                        this.runOnPlayerThread(p, () -> {
                            StatsSnapshot liveStats = this.mergeLiveHudStats(p, stats);
                            p.sendMessage("\u00a79[HUD DEBUG] \u00a7fMoney=" + this.formatMillions(liveStats.money) + " \u00a7fShards=" + this.formatCompactNumber(liveStats.shards) + " \u00a7fKills=" + this.formatCompactNumber(liveStats.kills) + " \u00a7fDeaths=" + this.formatCompactNumber(liveStats.deaths) + " \u00a7fPlaytime=" + this.formatPlaytimeDaysHours(liveStats.playtimeSeconds) + " \u00a7fTeam=" + team + " \u00a7fPing=" + Math.max(0, p.getPing()) + "ms");
                        });
                    });
                    return true;
                }
                if (args.length >= 2 && "sell".equalsIgnoreCase(args[0])) {
                    String matName = args[1].toUpperCase(java.util.Locale.ROOT);
                    Material mat = Material.matchMaterial(matName);
                    double price = mat != null ? this.sellUnitPrice(mat) : -1.0;
                    ConfigurationSection dbgPrices = this.sellConfig != null ? this.sellConfig.getConfigurationSection("prices") : null;
                    int dbgCount = dbgPrices != null ? dbgPrices.getKeys(false).size() : 0;
                    p.sendMessage("\u00a79[SELL DEBUG] \u00a7fmaterial=" + matName + " mat=" + mat + " price=$" + price + " prices_loaded=" + dbgCount);
                    return true;
                }
                p.sendMessage("\u00a77Usage: \u00a7f/pizzadebug hud\u00a77 | \u00a7f/pizzadebug sell <material>");
                break;
            }
            case "homes": {
                this.openHomesFromAnyServer(p);
                break;
            }
            case "home": {
                // Absorbed from SetHomeGUI: no args opens the 9×4 homes GUI; a name teleports.
                if (args.length == 0) {
                    this.openHomesFromAnyServer(p);
                } else {
                    String homeKey = args[0].toLowerCase(Locale.ROOT);
                    this.runAsyncTask(() -> {
                        HomeRecord home = this.loadHomeRecord(p.getUniqueId(), homeKey);
                        this.runOnPlayerThread(p, () -> {
                            if (home != null) {
                                this.startHomeTeleportCountdown(p, home);
                            } else {
                                p.sendActionBar(Component.text("§cNo home named '" + homeKey + "'."));
                                this.openHomesFromAnyServer(p);
                            }
                        });
                    });
                }
                break;
            }
            case "bal":
            case "balance": 
            case "money": {
                this.handleBalanceCommand(p, args);
                break;
            }
            case "baltop": {
                this.openBaltopGui(p);
                break;
            }
            case "leaderboard":
            case "leaderboards": {
                if (args.length >= 1) {
                    LbCategory cat = this.findLbCategory(args[0]);
                    if (cat != null) {
                        this.openLeaderboardCategory(p, cat);
                        break;
                    }
                }
                this.openLeaderboardPicker(p);
                break;
            }
            case "bounty": {
                this.handleBountyCommand(p, args);
                break;
            }
            case "queuetest": {
                if (!p.hasPermission("pizzasmp.admin.queuetest") && !p.isOp()) {
                    p.sendActionBar(Component.text("§cNo permission."));
                    return true;
                }
                // Force-enqueue yourself to demonstrate the queue, held for ~18s.
                this.queueTestHoldUntil.put(p.getUniqueId(), System.currentTimeMillis() + 18000L);
                this.enqueuePlayer(p);
                break;
            }
            case "vdthrottle": {
                if (!p.hasPermission("pizzasmp.admin.vdthrottle") && !p.isOp()) {
                    p.sendActionBar(Component.text("§cNo permission."));
                    return true;
                }
                this.handleVdThrottleCommand(p, args);
                break;
            }
            case "kill": {
                this.openKillConfirmMenu(p);
                break;
            }
            case "admin": {
                if (!p.hasPermission(PERM_ADMIN_CONSOLE)) {
                    p.sendMessage("§cThis command does not exist.");
                    return true;
                }
                if (this.useDialogUi(p)) {
                    this.openAdminConsole(p);
                } else {
                    this.openAdminLegacy(p);
                }
                break;
            }
            case "manage": {
                if (!p.hasPermission("pizzasmp.manage")) {
                    p.sendMessage("§cThis command does not exist.");
                    return true;
                }
                this.openManageConsole(p);   // backend management (dialog; dev + granted admins)
                break;
            }
            case "maintenancemotd": {
                if (!p.hasPermission(PERM_ADMIN_CONSOLE)) {
                    p.sendMessage("§cThis command does not exist.");
                    return true;
                }
                if (args.length == 0) {
                    p.sendMessage(this.legacyColorize("&#00BFFFCurrent maintenance MOTD:"));
                    p.sendMessage("§7" + this.getMaintenanceMotd());
                    p.sendMessage(this.legacyColorize("&7Usage: &#00BFFF/maintenancemotd <text>&7 (supports & and &#RRGGBB colors)"));
                    return true;
                }
                this.setMaintenanceMotd(p, String.join(" ", args));
                return true;
            }
            case "worth": {
                if (args.length == 0) {
                    this.openWorthGui(p);
                } else {
                    this.handleWorthCommand(p, args[0]);
                }
                break;
            }
            case "sellmulti": {
                this.openSellMultiMainGui(p);
                break;
            }
            case "sethome":
            case "delhome": {
                p.performCommand("home");
                break;
            }
            case "tpa": {
                if (args.length < 1) {
                    p.sendActionBar(Component.text("§cUsage: /tpa <player>"));
                    return true;
                }
                this.handleTpaCommand(p, args[0], "tpa");
                return true;
            }
            case "tpahere": {
                if (args.length < 1) {
                    p.sendActionBar(Component.text("§cUsage: /tpahere <player>"));
                    return true;
                }
                this.handleTpaCommand(p, args[0], "tpahere");
                return true;
            }
            case "tpacancel": {
                this.handleTpaCancelCommand(p);
                return true;
            }
            case "tpaaccept": {
                String requesterName = args.length > 0 ? args[0] : null;
                this.handleTpaAcceptCommand(p, requesterName);
                return true;
            }
            case "tpadeny": {
                String requesterName = args.length > 0 ? args[0] : null;
                this.handleTpaDenyCommand(p, requesterName);
                return true;
            }
            case "sus": {
                if (!p.hasPermission("pizzasmp.admin.commands")) {
                    p.sendMessage("§cYou do not have permission to use /sus.");
                    return true;
                }
                this.openSuspiciousPlayersGui(p);
                return true;
            }
            case "ping": {
                int ping = p.getPing();
                p.sendActionBar(this.legacyColorize("§fYour ping is &#00BFFF" + ping + "§fms"));
                return true;
            }
            case "viewdistance": {
                if (!p.hasPermission("pizzasmp.admin.viewdistance")) {
                    p.sendMessage("§cYou do not have permission.");
                    return true;
                }
                if (args.length < 1) {
                    p.sendActionBar(Component.text("§cUsage: /viewdistance <distance>"));
                    return true;
                }
                try {
                    int distance = Integer.parseInt(args[0]);
                    if (distance < 2 || distance > 32) {
                        p.sendMessage("§cView distance must be between 2 and 32.");
                        return true;
                    }
                    this.runAsyncTask(() -> {
                        try {
                            Bukkit.spigot().getConfig().set("settings.view-distance", distance);
                            this.runOnPlayerThread(p, () -> {
                                p.getWorld().setViewDistance(distance);
                                p.sendMessage("§aView distance set to " + distance + ".");
                            });
                        } catch (Exception ex) {
                            this.runOnPlayerThread(p, () -> p.sendMessage("§cFailed: " + ex.getMessage()));
                        }
                    });
                } catch (NumberFormatException ex) {
                    p.sendMessage("§cInvalid distance: " + args[0]);
                }
                return true;
            }
            case "diagnostics": {
                if (!p.hasPermission("pizzasmp.admin.diagnostics")) {
                    p.sendMessage("§cYou do not have permission.");
                    return true;
                }
                Runtime rt = Runtime.getRuntime();
                long usedMemory = (rt.totalMemory() - rt.freeMemory()) / 1024 / 1024;
                long maxMemory = rt.maxMemory() / 1024 / 1024;
                int playerCount = Bukkit.getOnlinePlayers().size();
                int maxPlayers = Bukkit.getMaxPlayers();
                double tps = Bukkit.getTPS()[0];
                long uptime = ManagementFactory.getRuntimeMXBean().getUptime() / 1000;
                int hours = (int)(uptime / 3600);
                int minutes = (int)((uptime % 3600) / 60);
                p.sendMessage("§6=== Server Diagnostics ===");
                p.sendMessage("§fMemory: §a" + usedMemory + "MB / " + maxMemory + "MB");
                p.sendMessage("§fPlayers: §a" + playerCount + " / " + maxPlayers);
                p.sendMessage("§fTPS (1m avg): §a" + String.format("%.2f", tps));
                p.sendMessage("§fUptime: §a" + hours + "h " + minutes + "m");
                return true;
            }
            case "shards": {
                if (!p.hasPermission("pizzasmp.admin.shards")) {
                    p.sendMessage("§cYou do not have permission.");
                    return true;
                }
                if (args.length < 3 || !"give".equalsIgnoreCase(args[0])) {
                    p.sendActionBar(Component.text("§cUsage: /shards give <player> <amount>"));
                    return true;
                }
                this.handleShardsGiveCommand(p, args[1], args[2]);
                return true;
            }
            case "reset": {
                if (!p.hasPermission("pizzasmp.admin.reset")) {
                    p.sendMessage("§cYou do not have permission.");
                    return true;
                }
                if (args.length < 2) {
                    p.sendActionBar(Component.text("§cUsage: /reset <deaths|kills|playtime|money> <player>"));
                    return true;
                }
                this.handleResetCommand(p, args[0], args[1]);
                return true;
            }
            case "txlog": {
                if (!p.hasPermission("pizzasmp.admin.commands")) {
                    p.sendMessage("§cYou do not have permission.");
                    return true;
                }
                String targetName = args.length >= 1 ? args[0] : p.getName();
                int txPage = args.length >= 2 ? Math.max(1, Integer.parseInt(args[1])) : 1;
                this.openPlayerHistoryGui(p, targetName, txPage);
                return true;
            }
            default: {
                return false;
            }
        }
        return true;
    }

    private boolean handleCrossServerRoutePreprocess(Player player, String label, String[] split, String rawMessage) {
        switch (label) {
            case "ah":
            case "auction": 
            case "orders": 
            case "order": {
                return false;
            }
            case "sethome": 
            case "delhome": {
                if (this.normalizeServerTarget("survival").equalsIgnoreCase(this.detectServerName())) {
                    return false;
                }
                this.routeCommandToServer(player, "survival", rawMessage.substring(1), "homes");
                return true;
            }
            case "afk": {
                if (this.normalizeServerTarget("lobby").equalsIgnoreCase(this.detectServerName())) {
                    this.dispatchTeleportCommand(player, "warp afk");
                    return true;
                }
                this.routeCommandToServer(player, "lobby", "warp afk", "afk");
                return true;
            }
            case "tpa": 
            case "tpahere": {
                return false;
            }
            case "team": {
                if (split.length < 2 || !"gui".equalsIgnoreCase(split[1])) break;
                if (this.normalizeServerTarget("lobby").equalsIgnoreCase(this.detectServerName())) {
                    return false;
                }
                this.routeCommandToServer(player, "lobby", "team gui", "teams");
                return true;
            }
            default: {
                return false;
            }
        }
        return false;
    }

    private boolean handleCrossServerTeleportRequestCommand(Player player, String label, String[] split) {
        String requiredSetting;
        String normalized;
        String string = normalized = label == null ? "" : label.toLowerCase(Locale.ROOT);
        if ("tpaccept".equals(normalized) || "tpacept".equals(normalized)) {
            return this.handleRemoteTeleportAccept(player, split.length >= 2 ? split[1] : null);
        }
        if ("tpdeny".equals(normalized)) {
            return this.handleRemoteTeleportDeny(player, split.length >= 2 ? split[1] : null);
        }
        if (!"tpa".equals(normalized) && !"tpahere".equals(normalized)) {
            return false;
        }
        if (split.length < 2 || split[1].isBlank()) {
            return false;
        }
        Player localTarget = Bukkit.getPlayerExact((String)split[1]);
        if (localTarget != null && localTarget.isOnline()) {
            String requiredSetting2;
            String string2 = requiredSetting2 = "tpahere".equals(normalized) ? "tpahere_requests" : "tpa_requests";
            if (!this.privacyAllows(localTarget.getUniqueId(), requiredSetting2, player.getUniqueId())) {
                player.sendMessage("\u00a7cThat player is not accepting this type of teleport request.");
                return true;
            }
            return false;
        }
        OnlinePlayerSession target = this.lookupOnlinePlayerSession(split[1]);
        if (target == null || target.serverName() == null || target.serverName().isBlank()) {
            return false;
        }
        if (this.normalizeServerTarget(target.serverName()).equalsIgnoreCase(this.detectServerName())) {
            return false;
        }
        if (this.isCombatTagged(player)) {
            player.sendActionBar((Component)Component.text((String)"\u00a7cYou are in combat! Cannot teleport."));
            this.logCombatBlocked(player, normalized);
            return true;
        }
        String string3 = requiredSetting = "tpahere".equals(normalized) ? "tpahere_requests" : "tpa_requests";
        if (!this.isRemoteSettingEnabled(target.uuid(), requiredSetting, true)) {
            player.sendMessage("\u00a7cThat player is not accepting this type of teleport request.");
            return true;
        }
        this.createRemoteTeleportRequest(player, target, "tpahere".equals(normalized) ? "TPAHERE" : "TPA");
        return true;
    }

    private void createRemoteTeleportRequest(Player requester, OnlinePlayerSession target, String requestType) {
        if (requester == null || target == null || requestType == null) {
            return;
        }
        this.runAsyncTask(() -> {
            String sql = "INSERT INTO network_teleport_requests (requester_uuid,requester_name,target_uuid,target_name,request_type,requester_server,target_server,status,expires_at) VALUES (?,?,?,?,?,?,?,'PENDING', DATE_ADD(NOW(), INTERVAL 60 SECOND))";
            try (Connection conn = this.openSyncConnection();
                 PreparedStatement ps = conn.prepareStatement(sql);){
                ps.setString(1, requester.getUniqueId().toString());
                ps.setString(2, requester.getName());
                ps.setString(3, target.uuid().toString());
                ps.setString(4, target.username());
                ps.setString(5, requestType);
                ps.setString(6, this.detectServerName());
                ps.setString(7, this.normalizeServerTarget(target.serverName()));
                ps.executeUpdate();
                String targetMessage = "TPAHERE".equals(requestType) ? "\u00a7e" + requester.getName() + " \u00a77wants you to teleport to them. Use \u00a7f/tpaccept " + requester.getName() + " \u00a77or \u00a7f/tpdeny " + requester.getName() + "\u00a77." : "\u00a7e" + requester.getName() + " \u00a77wants to teleport to you. Use \u00a7f/tpaccept " + requester.getName() + " \u00a77or \u00a7f/tpdeny " + requester.getName() + "\u00a77.";
                this.queuePlayerNotification(target.uuid(), targetMessage, "", 70);
                this.runOnPlayerThread(requester, () -> requester.sendMessage("\u00a7aTeleport request sent to \u00a7f" + target.username() + "\u00a7a."));
            }
            catch (Exception ex) {
                this.runOnPlayerThread(requester, () -> requester.sendMessage("\u00a7cFailed to send teleport request."));
                this.getLogger().warning("Failed creating remote teleport request: " + ex.getMessage());
            }
        });
    }

    private boolean handleRemoteTeleportAccept(Player accepter, String requesterFilter) {
        if (accepter == null) {
            return false;
        }
        if (this.isCombatTagged(accepter)) {
            accepter.sendActionBar((Component)Component.text((String)"\u00a7cYou are in combat! Cannot teleport."));
            this.logCombatBlocked(accepter, "tpaccept");
            return true;
        }
        TeleportRequestEntry request = this.findPendingRemoteTeleportRequest(accepter.getUniqueId(), requesterFilter);
        if (request == null) {
            return false;
        }
        this.runAsyncTask(() -> {
            if (!this.markTeleportRequestStatus(request.id(), "ACCEPTED")) {
                this.runOnPlayerThread(accepter, () -> accepter.sendMessage("\u00a7cThat teleport request is no longer available."));
                return;
            }
            if ("TPAHERE".equalsIgnoreCase(request.requestType())) {
                if (this.playerSyncManager != null) {
                    this.playerSyncManager.queueOneTimeAction(accepter.getUniqueId(), "RUN_CMD:tp " + request.requesterName(), 45);
                }
                this.runOnPlayerThread(accepter, () -> {
                    accepter.sendMessage("\u00a7aTeleport request accepted.");
                    this.connectToServer(accepter, this.normalizeServerTarget(request.requesterServer()));
                });
                this.queuePlayerNotification(UUID.fromString(request.requesterUuid()), "\u00a7a" + accepter.getName() + " accepted your teleport request.", "", 30);
                return;
            }
            if (this.playerSyncManager != null) {
                this.playerSyncManager.queueOneTimeAction(UUID.fromString(request.requesterUuid()), "RUN_CMD:tp " + accepter.getName(), 45);
            }
            this.queuePlayerNotification(UUID.fromString(request.requesterUuid()), "\u00a7a" + accepter.getName() + " accepted your teleport request.", "CONNECT:" + this.detectServerName(), 30);
            this.runOnPlayerThread(accepter, () -> accepter.sendMessage("\u00a7aTeleport request accepted."));
        });
        return true;
    }

    private boolean handleRemoteTeleportDeny(Player denier, String requesterFilter) {
        if (denier == null) {
            return false;
        }
        TeleportRequestEntry request = this.findPendingRemoteTeleportRequest(denier.getUniqueId(), requesterFilter);
        if (request == null) {
            return false;
        }
        this.runAsyncTask(() -> {
            if (!this.markTeleportRequestStatus(request.id(), "DENIED")) {
                this.runOnPlayerThread(denier, () -> denier.sendMessage("\u00a7cThat teleport request is no longer available."));
                return;
            }
            this.queuePlayerNotification(UUID.fromString(request.requesterUuid()), "\u00a7c" + denier.getName() + " denied your teleport request.", "", 30);
            this.runOnPlayerThread(denier, () -> denier.sendMessage("\u00a77Teleport request denied."));
        });
        return true;
    }

