    private TeleportRequestEntry findPendingRemoteTeleportRequest(UUID targetUuid, String requesterFilter) {
        if (targetUuid == null) {
            return null;
        }
        String sql = "SELECT id,requester_uuid,requester_name,target_uuid,target_name,request_type,requester_server,target_server FROM network_teleport_requests WHERE target_uuid=? AND status='PENDING' AND expires_at > CURRENT_TIMESTAMP " + (requesterFilter == null || requesterFilter.isBlank() ? "" : "AND LOWER(requester_name)=LOWER(?) ") + "ORDER BY id DESC LIMIT 1";
        try (Connection conn = this.openSyncConnection();
             PreparedStatement ps = conn.prepareStatement(sql);){
            ps.setString(1, targetUuid.toString());
            if (requesterFilter != null && !requesterFilter.isBlank()) {
                ps.setString(2, requesterFilter);
            }
            try (ResultSet rs = ps.executeQuery();){
                if (!rs.next()) return null;
                TeleportRequestEntry teleportRequestEntry = new TeleportRequestEntry(rs.getLong(1), rs.getString(2), rs.getString(3), rs.getString(4), rs.getString(5), rs.getString(6), rs.getString(7), rs.getString(8));
                return teleportRequestEntry;
            }
        }
        catch (Exception ex) {
            this.getLogger().warning("Failed loading pending teleport request: " + ex.getMessage());
        }
        return null;
    }

