    /*
     * Enabled aggressive block sorting
     * Enabled unnecessary exception pruning
     * Enabled aggressive exception aggregation
     */
    private OnlinePlayerSession lookupOnlinePlayerSession(String playerName) {
        if (playerName == null) return null;
        if (playerName.isBlank()) {
            return null;
        }
        Player local = Bukkit.getPlayerExact((String)playerName);
        if (local != null && local.isOnline()) {
            return new OnlinePlayerSession(local.getUniqueId(), local.getName(), this.detectServerName());
        }
        String sql = "SELECT p.uuid,p.username,sl.server_name FROM players p JOIN session_leases sl ON sl.uuid=p.uuid AND sl.expires_at > CURRENT_TIMESTAMP WHERE LOWER(p.username)=LOWER(?) LIMIT 1";
        try (Connection conn = this.openSyncConnection();
             PreparedStatement ps = conn.prepareStatement(sql);){
            ps.setString(1, playerName);
            try (ResultSet rs = ps.executeQuery();){
                if (!rs.next()) return null;
                String uuid = rs.getString(1);
                String username = rs.getString(2);
                String serverName = rs.getString(3);
                if (uuid == null) return null;
                if (username == null) return null;
                if (serverName == null) return null;
                OnlinePlayerSession onlinePlayerSession = new OnlinePlayerSession(UUID.fromString(uuid), username, serverName);
                return onlinePlayerSession;
            }
        }
        catch (Exception ex) {
            this.getLogger().warning("Failed looking up online player session for " + playerName + ": " + ex.getMessage());
        }
        return null;
    }

    /*
     * Enabled aggressive block sorting
     * Enabled unnecessary exception pruning
     * Enabled aggressive exception aggregation
     */
    private boolean isRemoteSettingEnabled(UUID uuid, String key, boolean defaultValue) {
        if (uuid == null) return defaultValue;
        if (key == null) return defaultValue;
        if (key.isBlank()) {
            return defaultValue;
        }
        if (this.playerSettingsCache.containsKey(uuid)) {
            return this.playerSettingsCache.getOrDefault(uuid, Map.of()).getOrDefault(key, defaultValue);
        }
        String sql = "SELECT settings_blob FROM player_settings WHERE uuid=? LIMIT 1";
        try (Connection conn = this.openSyncConnection();
             PreparedStatement ps = conn.prepareStatement(sql);){
            ps.setString(1, uuid.toString());
            try (ResultSet rs = ps.executeQuery();){
                if (!rs.next()) return defaultValue;
                boolean bl = this.parseSettingsBlob(rs.getString(1)).getOrDefault(key, defaultValue);
                return bl;
            }
        }
        catch (Exception ex) {
            this.getLogger().warning("Failed loading remote player settings for " + String.valueOf(uuid) + ": " + ex.getMessage());
        }
        return defaultValue;
    }

