    private void changeTeamRole(Player p, String targetName, String fromRole, String toRole, String actionMsg) {
        try (Connection conn = this.openSyncConnection()) {
            long teamId = this.getTeamIdLong(conn, p.getUniqueId());
            if (teamId < 0) { this.runOnPlayerThread(p, () -> p.sendActionBar(Component.text("§cYou are not in a team."))); return; }
            if (!"OWNER".equalsIgnoreCase(this.getTeamRole(conn, p.getUniqueId(), teamId))) {
                this.runOnPlayerThread(p, () -> p.sendMessage("§cOnly the owner can promote/demote members.")); return;
            }
            UUID targetUuid = null;
            try (PreparedStatement ps = conn.prepareStatement("SELECT member_uuid, role FROM team_members WHERE team_id=?")) {
                ps.setLong(1, teamId);
                try (ResultSet rs = ps.executeQuery()) {
                    while (rs.next()) {
                        UUID u = UUID.fromString(rs.getString("member_uuid"));
                        OfflinePlayer op = Bukkit.getOfflinePlayer(u);
                        if (targetName.equalsIgnoreCase(op.getName()) && fromRole.equalsIgnoreCase(rs.getString("role"))) {
                            targetUuid = u; break;
                        }
                    }
                }
            }
            if (targetUuid == null) {
                this.runOnPlayerThread(p, () -> p.sendMessage("§c" + targetName + " is not a " + fromRole + " in your team."));
                return;
            }
            final UUID finalUuid = targetUuid;
            try (PreparedStatement ps = conn.prepareStatement("UPDATE team_members SET role=? WHERE team_id=? AND member_uuid=?")) {
                ps.setString(1, toRole);
                ps.setLong(2, teamId);
                ps.setString(3, finalUuid.toString());
                ps.executeUpdate();
            }
            Player targetOnline = Bukkit.getPlayer(finalUuid);
            this.runOnPlayerThread(p, () -> p.sendMessage(this.legacyColorize("&#00BFFF" + targetName + " §f" + actionMsg + ".")));
            if (targetOnline != null) this.runOnPlayerThread(targetOnline, () -> targetOnline.sendMessage(this.legacyColorize("&#00BFFFYou have been " + actionMsg + " by §f" + p.getName() + "§7.")));
        } catch (Exception ex) {
            this.getLogger().warning("changeTeamRole failed: " + ex.getMessage());
            this.runOnPlayerThread(p, () -> p.sendMessage("§cFailed. Try again."));
        }
    }

    private void handleTeamTransfer(Player p, String[] args) {
        if (args.length < 2) {
            this.runOnPlayerThread(p, () -> p.sendActionBar(Component.text("§cUsage: /team transfer <player>")));
            return;
        }
        String targetName = args[1];
        try (Connection conn = this.openSyncConnection()) {
            long teamId = this.getTeamIdLong(conn, p.getUniqueId());
            if (teamId < 0) { this.runOnPlayerThread(p, () -> p.sendActionBar(Component.text("§cYou are not in a team."))); return; }
            if (!"OWNER".equalsIgnoreCase(this.getTeamRole(conn, p.getUniqueId(), teamId))) {
                this.runOnPlayerThread(p, () -> p.sendMessage("§cOnly the owner can transfer ownership.")); return;
            }
            UUID targetUuid = null;
            try (PreparedStatement ps = conn.prepareStatement("SELECT member_uuid FROM team_members WHERE team_id=? AND member_uuid != ?")) {
                ps.setLong(1, teamId);
                ps.setString(2, p.getUniqueId().toString());
                try (ResultSet rs = ps.executeQuery()) {
                    while (rs.next()) {
                        UUID u = UUID.fromString(rs.getString("member_uuid"));
                        OfflinePlayer op = Bukkit.getOfflinePlayer(u);
                        if (targetName.equalsIgnoreCase(op.getName())) { targetUuid = u; break; }
                    }
                }
            }
            if (targetUuid == null) {
                this.runOnPlayerThread(p, () -> p.sendMessage("§c" + targetName + " is not in your team."));
                return;
            }
            final UUID finalUuid = targetUuid;
            conn.setAutoCommit(false);
            try (PreparedStatement ps = conn.prepareStatement("UPDATE team_members SET role='OFFICER' WHERE team_id=? AND member_uuid=?")) {
                ps.setLong(1, teamId); ps.setString(2, p.getUniqueId().toString()); ps.executeUpdate();
            }
            try (PreparedStatement ps = conn.prepareStatement("UPDATE team_members SET role='OWNER' WHERE team_id=? AND member_uuid=?")) {
                ps.setLong(1, teamId); ps.setString(2, finalUuid.toString()); ps.executeUpdate();
            }
            try (PreparedStatement ps = conn.prepareStatement("UPDATE teams SET owner_uuid=? WHERE id=?")) {
                ps.setString(1, finalUuid.toString()); ps.setLong(2, teamId); ps.executeUpdate();
            }
            conn.commit(); conn.setAutoCommit(true);
            Player targetOnline = Bukkit.getPlayer(finalUuid);
            this.runOnPlayerThread(p, () -> p.sendMessage(this.legacyColorize("&#00BFFFOwnership transferred to §f" + targetName + "§7.")));
            if (targetOnline != null) this.runOnPlayerThread(targetOnline, () -> targetOnline.sendMessage(this.legacyColorize("&#00BFFFYou are now the owner of the team!")));
        } catch (Exception ex) {
            this.getLogger().warning("handleTeamTransfer failed: " + ex.getMessage());
            this.runOnPlayerThread(p, () -> p.sendMessage("§cFailed. Try again."));
        }
    }

    private void handleTeamDisband(Player p, String[] args) {
        try (Connection conn = this.openSyncConnection()) {
            long teamId = this.getTeamIdLong(conn, p.getUniqueId());
            if (teamId < 0) { this.runOnPlayerThread(p, () -> p.sendActionBar(Component.text("§cYou are not in a team."))); return; }
            if (!"OWNER".equalsIgnoreCase(this.getTeamRole(conn, p.getUniqueId(), teamId))) {
                this.runOnPlayerThread(p, () -> p.sendMessage("§cOnly the owner can disband the team.")); return;
            }
            List<UUID> members = this.getTeamMemberUuids(conn, teamId);
            conn.setAutoCommit(false);
            try (PreparedStatement ps = conn.prepareStatement("DELETE FROM team_invites WHERE team_id=?")) { ps.setLong(1, teamId); ps.executeUpdate(); }
            try (PreparedStatement ps = conn.prepareStatement("DELETE FROM team_members WHERE team_id=?")) { ps.setLong(1, teamId); ps.executeUpdate(); }
            try (PreparedStatement ps = conn.prepareStatement("DELETE FROM teams WHERE id=?")) { ps.setLong(1, teamId); ps.executeUpdate(); }
            conn.commit(); conn.setAutoCommit(true);
            String disbandMsg = "§cThe team has been disbanded by §f" + p.getName() + "§c.";
            for (UUID mu : members) {
                Player mp = Bukkit.getPlayer(mu);
                if (mp != null) this.runOnPlayerThread(mp, () -> mp.sendMessage(disbandMsg));
            }
        } catch (Exception ex) {
            this.getLogger().warning("handleTeamDisband failed: " + ex.getMessage());
            this.runOnPlayerThread(p, () -> p.sendMessage("§cFailed. Try again."));
        }
    }

    // Team homes are retired (teams -> friends transition). Existing team homes were converted
    // into personal named homes for every member by migrateTeamHomesToPersonal().
    private void sendTeamHomesRetired(Player p) {
        p.sendMessage("§cTeam homes have been retired — your team's home was saved as a personal home (§e/home teamhome§c).");
    }

    /**
     * One-shot migration: for every team with a home set, write that location into each
     * member's SetHome data file as a personal named home ("teamhome", suffixed 2,3... on
     * collision), then clear the team's home columns. Added as a BONUS home (bypasses the
     * tier limit — the limit only gates setting NEW homes). Guarded by a marker file so it
     * never runs twice.
     */
    private void migrateTeamHomesToPersonal() {
        File marker = new File(this.getDataFolder(), "teamhomes-migrated.flag");
        if (marker.exists()) {
            return;
        }
        File setHomeData = new File(this.getDataFolder().getParentFile(), "SetHome/data");
        if (!setHomeData.isDirectory()) {
            File alt = new File(this.getDataFolder().getParentFile(), "sethome/data");
            if (alt.isDirectory()) setHomeData = alt; else setHomeData.mkdirs();
        }
        int teamsMigrated = 0;
        int homesWritten = 0;
        StringBuilder summary = new StringBuilder();
        try (Connection conn = this.openSyncConnection()) {
            List<Object[]> teamHomes = new ArrayList<>(); // [teamId, teamName, world, x, y, z, yaw, pitch]
            try (PreparedStatement ps = conn.prepareStatement(
                    "SELECT id, team_name, home_world, home_x, home_y, home_z, home_yaw, home_pitch FROM teams WHERE home_world IS NOT NULL");
                 ResultSet rs = ps.executeQuery()) {
                while (rs.next()) {
                    teamHomes.add(new Object[]{rs.getLong(1), rs.getString(2), rs.getString(3),
                            rs.getDouble(4), rs.getDouble(5), rs.getDouble(6), rs.getFloat(7), rs.getFloat(8)});
                }
            }
            for (Object[] th : teamHomes) {
                long teamId = (Long) th[0];
                String teamName = (String) th[1];
                List<UUID> members = new ArrayList<>();
                try (PreparedStatement ps = conn.prepareStatement("SELECT member_uuid FROM team_members WHERE team_id=?")) {
                    ps.setLong(1, teamId);
                    try (ResultSet rs = ps.executeQuery()) {
                        while (rs.next()) {
                            try { members.add(UUID.fromString(rs.getString(1))); } catch (IllegalArgumentException ignored) {}
                        }
                    }
                }
                for (UUID member : members) {
                    try {
                        String homeName = this.writeSetHomeBonusHome(setHomeData, member,
                                (String) th[2], (Double) th[3], (Double) th[4], (Double) th[5], (Float) th[6], (Float) th[7]);
                        homesWritten++;
                        summary.append(teamName).append(" -> ").append(member).append(" as ").append(homeName).append('\n');
                        String msg = "§eTeam homes were retired — your team's home was saved as your personal home §f/home " + homeName + "§e.";
                        Player online = Bukkit.getPlayer(member);
                        if (online != null && online.isOnline()) {
                            this.runOnPlayerThread(online, () -> online.sendMessage(msg));
                        } else {
                            this.queuePlayerNotification(member, msg, "", 60 * 60 * 24 * 7);
                        }
                    } catch (Exception ex) {
                        this.getLogger().warning("Team-home migration failed for " + member + " (team " + teamName + "): " + ex.getMessage());
                    }
                }
                try (PreparedStatement ps = conn.prepareStatement(
                        "UPDATE teams SET home_world=NULL, home_x=NULL, home_y=NULL, home_z=NULL, home_yaw=NULL, home_pitch=NULL WHERE id=?")) {
                    ps.setLong(1, teamId);
                    ps.executeUpdate();
                }
                teamsMigrated++;
            }
        } catch (Exception ex) {
            this.getLogger().warning("migrateTeamHomesToPersonal failed: " + ex.getMessage());
            return; // no marker written — retried next boot
        }
        try {
            String body = "migrated_at: " + new java.util.Date() + "\nteams: " + teamsMigrated
                    + "\nhomes_written: " + homesWritten + "\n" + summary;
            java.nio.file.Files.writeString(marker.toPath(), body);
        } catch (Exception ex) {
            this.getLogger().warning("Could not write teamhomes-migrated.flag: " + ex.getMessage());
        }
        if (teamsMigrated > 0 || homesWritten > 0) {
            this.getLogger().info("Team-home migration: " + teamsMigrated + " team home(s) converted into " + homesWritten + " personal home(s).");
        } else {
            this.getLogger().info("Team-home migration: nothing to migrate.");
        }
    }

    /** Writes a named home directly into the SetHome yaml (bonus — no tier-limit check). Returns the name used. */
    private String writeSetHomeBonusHome(File setHomeData, UUID uuid, String world, double x, double y, double z, float yaw, float pitch) throws Exception {
        File file = new File(setHomeData, uuid + ".yml");
        org.bukkit.configuration.file.YamlConfiguration yml = org.bukkit.configuration.file.YamlConfiguration.loadConfiguration(file);
        List<String> homes = new ArrayList<>(yml.getStringList("homes"));
        String name = "teamhome";
        int suffix = 2;
        java.util.Set<String> taken = new java.util.HashSet<>();
        for (String h : homes) taken.add(h.toLowerCase());
        while (taken.contains(name)) { name = "teamhome" + suffix; suffix++; }
        homes.add(name);
        yml.set("homes", homes);
        yml.set(name + ".world", world);
        yml.set(name + ".x", x);
        yml.set(name + ".y", y);
        yml.set(name + ".z", z);
        yml.set(name + ".yaw", yaw);
        yml.set(name + ".pitch", pitch);
        yml.save(file);
        return name;
    }

    private void handleTeamInfo(Player p, String[] args) {
        try (Connection conn = this.openSyncConnection()) {
            long teamId = this.getTeamIdLong(conn, p.getUniqueId());
            if (teamId < 0) { this.runOnPlayerThread(p, () -> p.sendActionBar(Component.text("§cYou are not in a team."))); return; }
            String teamName = this.getTeamName(conn, teamId);
            List<String[]> memberInfos = new ArrayList<>();
            try (PreparedStatement ps = conn.prepareStatement("SELECT member_uuid, role FROM team_members WHERE team_id=? ORDER BY FIELD(role,'OWNER','OFFICER','MEMBER')")) {
                ps.setLong(1, teamId);
                try (ResultSet rs = ps.executeQuery()) {
                    while (rs.next()) {
                        String uuid = rs.getString("member_uuid");
                        String role = rs.getString("role");
                        OfflinePlayer op = Bukkit.getOfflinePlayer(UUID.fromString(uuid));
                        String name = op.getName() != null ? op.getName() : uuid.substring(0, 8);
                        memberInfos.add(new String[]{name, role});
                    }
                }
            }
            TeamHomeRecord teamHome = this.loadTeamHome(conn, p.getUniqueId());
            boolean hasHome = teamHome != null;
            this.runOnPlayerThread(p, () -> {
                p.sendMessage(this.legacyColorize("&#00BFFF=== Team: §f" + teamName + " &#00BFFF==="));
                p.sendMessage("§7Members (" + memberInfos.size() + "):");
                for (String[] info : memberInfos) {
                    String roleTag = "OWNER".equalsIgnoreCase(info[1]) ? "§6[OWNER]" : "OFFICER".equalsIgnoreCase(info[1]) ? "§e[OFFICER]" : "§7[MEMBER]";
                    p.sendMessage("  " + roleTag + " §f" + info[0]);
                }
                p.sendMessage("§7Team Home: " + (hasHome ? "§aSET" : "§cNOT SET"));
            });
        } catch (Exception ex) {
            this.getLogger().warning("handleTeamInfo failed: " + ex.getMessage());
            this.runOnPlayerThread(p, () -> p.sendMessage("§cFailed to load team info."));
        }
    }

    private void openTeamSettingsGui(Player p) {
        try (Connection conn = this.openSyncConnection()) {
            long teamId = this.getTeamIdLong(conn, p.getUniqueId());
            if (teamId < 0) { this.runOnPlayerThread(p, () -> p.sendActionBar(Component.text("§cYou are not in a team."))); return; }
            String role = this.getTeamRole(conn, p.getUniqueId(), teamId);
            boolean isManager = "OWNER".equalsIgnoreCase(role) || "OFFICER".equalsIgnoreCase(role);
            String teamName = this.getTeamName(conn, teamId);
            boolean pvpEnabled;
            try (PreparedStatement ps = conn.prepareStatement("SELECT pvp_enabled FROM teams WHERE id=? LIMIT 1")) {
                ps.setLong(1, teamId);
                try (ResultSet rs = ps.executeQuery()) {
                    pvpEnabled = rs.next() && rs.getBoolean("pvp_enabled");
                }
            }
            boolean finalPvp = pvpEnabled;
            this.runOnPlayerThread(p, () -> {
                Inventory inv = Bukkit.createInventory(null, 27, "§bTeam Settings#00BFFFTeam Settings");
                ItemStack pvpItem = this.namedWithLore(
                    finalPvp ? Material.DIAMOND_SWORD : Material.WOODEN_SWORD,
                    "§fFriendly Fire",
                    "team_settings_pvp",
                    List.of(finalPvp ? "§aENABLED - Click to disable" : "§cDISABLED - Click to enable",
                            isManager ? "§7Click to toggle" : "§cManagers only")
                );
                ItemStack infoItem = this.namedWithLore(Material.PLAYER_HEAD, "§fTeam: §e" + teamName, "team_settings_info", List.of("§7Role: §f" + role));
                ItemStack chatItem = this.namedWithLore(Material.BELL, "§fTeam Chat Toggle", "team_settings_chat", List.of("§7/team chat toggle", "§7Routes all chat to team chat"));
                inv.setItem(11, pvpItem);
                inv.setItem(13, infoItem);
                inv.setItem(15, chatItem);
                inv.setItem(22, this.namedWithLore(Material.ARROW, "§fTeam Members", "team_settings_members", List.of("§7View team members")));
                p.openInventory(inv);
            });
        } catch (Exception ex) {
            this.getLogger().warning("openTeamSettingsGui failed: " + ex.getMessage());
            this.runOnPlayerThread(p, () -> p.sendMessage("§cFailed to open team settings."));
        }
    }

    private long getTeamIdLong(Connection conn, UUID uuid) throws SQLException {
        try (PreparedStatement ps = conn.prepareStatement("SELECT team_id FROM team_members WHERE member_uuid=? LIMIT 1")) {
            ps.setString(1, uuid.toString());
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) return rs.getLong("team_id");
            }
        }
        return -1L;
    }

    private String getTeamRole(Connection conn, UUID uuid, long teamId) throws SQLException {
        try (PreparedStatement ps = conn.prepareStatement("SELECT role FROM team_members WHERE team_id=? AND member_uuid=? LIMIT 1")) {
            ps.setLong(1, teamId);
            ps.setString(2, uuid.toString());
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) return rs.getString("role");
            }
        }
        return null;
    }

    private String getTeamName(Connection conn, long teamId) throws SQLException {
        try (PreparedStatement ps = conn.prepareStatement("SELECT team_name FROM teams WHERE id=? LIMIT 1")) {
            ps.setLong(1, teamId);
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) return rs.getString("team_name");
            }
        }
        return "Unknown";
    }

    private List<UUID> getTeamMemberUuids(Connection conn, long teamId) throws SQLException {
        List<UUID> result = new ArrayList<>();
        try (PreparedStatement ps = conn.prepareStatement("SELECT member_uuid FROM team_members WHERE team_id=?")) {
            ps.setLong(1, teamId);
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next()) result.add(UUID.fromString(rs.getString("member_uuid")));
            }
        }
        return result;
    }

    private void sendBridgeChat(Player sender, String prefix, String message) {
        if (this.chatBridgeDebug) {
            this.getLogger().info("[chat-bridge-debug] type=CHAT uuid=" + String.valueOf(sender.getUniqueId()) + " server=" + this.detectServerName() + " msg=" + message);
        }
        this.sendBridgePayload(sender, out -> {
            out.writeUTF("CHAT");
            out.writeUTF(sender.getUniqueId().toString());
            out.writeUTF(sender.getName());
            out.writeUTF(this.detectServerName());
            out.writeUTF(prefix == null ? "" : prefix);
            out.writeUTF(message);
        });
    }

    private void sendBridgeDirectMessage(Player sender, String target, String message, boolean reply) {
        if (this.chatBridgeDebug) {
            this.getLogger().info("[chat-bridge-debug] type=" + (reply ? "REPLY" : "MSG") + " uuid=" + String.valueOf(sender.getUniqueId()) + " target=" + target + " msg=" + message);
        }
        this.sendBridgePayload(sender, out -> {
            out.writeUTF(reply ? "REPLY" : "MSG");
            out.writeUTF(sender.getUniqueId().toString());
            out.writeUTF(sender.getName());
            out.writeUTF(target == null ? "" : target);
            out.writeUTF(message);
        });
    }

    private void sendBridgeTeamChat(Player sender, String message) {
        List<UUID> members = this.getTeamMembers(sender.getUniqueId());
        if (members.isEmpty()) {
            sender.sendMessage("\u00a7cYou are not in a team.");
            return;
        }
        String prefix = "";
        if (this.chatProvider != null) {
            String raw = this.chatProvider.getPlayerPrefix(sender);
            prefix = raw == null ? "" : this.normalizeLegacyColors(raw);
        }
        String finalPrefix = prefix;
        String recipientsCsv = members.stream().map(UUID::toString).collect(Collectors.joining(","));
        if (this.chatBridgeDebug) {
            this.getLogger().info("[chat-bridge-debug] type=TEAM uuid=" + String.valueOf(sender.getUniqueId()) + " recipients=" + members.size() + " msg=" + message);
        }
        Component formatted = this.legacyColorize("&#00BFFF[TEAM] " + finalPrefix + sender.getName() + "\u00a77: \u00a7f" + message);
        for (UUID memberUuid : members) {
            Player mp = Bukkit.getPlayer(memberUuid);
            if (mp != null && mp.isOnline()) {
                mp.sendMessage(formatted);
            }
        }
        this.sendBridgePayload(sender, out -> {
            out.writeUTF("TEAM");
            out.writeUTF(sender.getUniqueId().toString());
            out.writeUTF(sender.getName());
            out.writeUTF(this.detectServerName());
            out.writeUTF(finalPrefix);
            out.writeUTF(message);
            out.writeUTF(recipientsCsv);
        });
    }

    private void sendBridgePayload(Player sender, BridgeWriter writer) {
        try (ByteArrayOutputStream bytes = new ByteArrayOutputStream();
             DataOutputStream out = new DataOutputStream(bytes);){
            writer.write(out);
            sender.sendPluginMessage((Plugin)this, BRIDGE_CHANNEL, bytes.toByteArray());
        }
        catch (IOException ex) {
            sender.sendMessage("\u00a7cMessage routing failed. Please try again.");
            this.getLogger().warning("Bridge payload write failed: " + ex.getMessage());
        }
    }

    private String plainMessage(Component component) {
        String value = PlainTextComponentSerializer.plainText().serialize(component);
        return value == null ? "" : value;
    }

    // ---- Branding -----------------------------------------------------------
    // Loads branding.yml (saved from resources on first run) and resolves the active
    // profile into the brand* fields. Same plugins/DB/command-names; display + colours only.
    private void loadBranding() {
        try { this.saveResource("branding.yml", false); } catch (Exception ignored) {}
        File f = new File(this.getDataFolder(), "branding.yml");
        this.brandingConfig = org.bukkit.configuration.file.YamlConfiguration.loadConfiguration(f);
        String active = this.brandingConfig.getString("active", "example");
        String base = "profiles." + active + ".";
        if (!this.brandingConfig.isConfigurationSection("profiles." + active)) {
            this.getLogger().warning("[brand] profile '" + active + "' not found in branding.yml; using pizzasmp defaults.");
            active = "pizzasmp"; base = "profiles.pizzasmp.";
        }
        this.brandActive = active;
        this.brandDisplay = this.brandingConfig.getString(base + "display", "ExampleSMP");
        this.brandShort = this.brandingConfig.getString(base + "short", "Pizza");
        this.brandRegion = this.brandingConfig.getString(base + "region", "NA-East");
        this.brandTagline = this.brandingConfig.getString(base + "tagline", "Survival");
        this.brandDiscord = this.brandingConfig.getString(base + "discord", "discord.gg/example");
        this.brandTierPlus = this.brandingConfig.getString(base + "tiers.plus", "Pizza+");
        this.brandTierPlusPlus = this.brandingConfig.getString(base + "tiers.plusplus", "Pizza++");
        this.brandColors.clear();
        this.brandColors.put("primary", this.brandingConfig.getString(base + "colors.primary", "00BFFF"));
        this.brandColors.put("info",    this.brandingConfig.getString(base + "colors.info",    "00BFFF"));
        this.brandColors.put("success", this.brandingConfig.getString(base + "colors.success", "55FF55"));
        this.brandColors.put("warning", this.brandingConfig.getString(base + "colors.warning", "FFAA00"));
        this.brandColors.put("danger",  this.brandingConfig.getString(base + "colors.danger",  "FF5555"));
        this.brandColors.put("muted",   this.brandingConfig.getString(base + "colors.muted",   "AAAAAA"));
        this.brandColors.put("text",    this.brandingConfig.getString(base + "colors.text",     "FFFFFF"));
        // Dialog accent colour follows the brand primary.
        try { DIALOG_BRAND = TextColor.color(Integer.parseInt(this.brandColorHex("primary"), 16)); } catch (Exception ignored) {}
        this.getLogger().info("[brand] active=" + this.brandActive + " display='" + this.brandDisplay + "' primary=#" + this.brandColors.get("primary"));
    }

    private String brandColorHex(String role) {
        String h = this.brandColors.get(role);
        return (h == null || h.length() != 6) ? "00BFFF" : h.toUpperCase(Locale.ROOT);
    }

    // Section-sign hex form (\u00a7x\u00a7R\u00a7R...) of a role colour, for strings that are NOT
    // run through legacyColorize (e.g. scoreboard title, inventory titles).
    private String brandSectionHex(String role) {
        String hex = this.brandColorHex(role);
        StringBuilder sb = new StringBuilder("\u00a7x");
        for (int i = 0; i < 6; i++) sb.append('\u00a7').append(hex.charAt(i));
        return sb.toString();
    }

    // Rewrite brand tokens in a message before colour processing. The literal &#00BFFF acts as the
    // "primary colour" marker, so existing code re-themes automatically; {tokens} cover name/region/etc.
    private String applyBrandTokens(String value) {
        if (value == null || value.isEmpty()) return value;
        if (value.indexOf("&#00BFFF") >= 0 && !"00BFFF".equals(this.brandColorHex("primary"))) {
            value = value.replace("&#00BFFF", "&#" + this.brandColorHex("primary"));
        }
        if (value.indexOf('{') < 0) return value;
        value = value.replace("{brand}", this.brandDisplay)
                     .replace("{brand_short}", this.brandShort)
                     .replace("{region}", this.brandRegion)
                     .replace("{tagline}", this.brandTagline)
                     .replace("{discord}", this.brandDiscord)
                     .replace("{plus}", this.brandTierPlus)
                     .replace("{plusplus}", this.brandTierPlusPlus)
                     .replace("{primary}", "&#" + this.brandColorHex("primary"))
                     .replace("{info}", "&#" + this.brandColorHex("info"))
                     .replace("{success}", "&#" + this.brandColorHex("success"))
                     .replace("{warning}", "&#" + this.brandColorHex("warning"))
                     .replace("{danger}", "&#" + this.brandColorHex("danger"))
                     .replace("{muted}", "&#" + this.brandColorHex("muted"))
                     .replace("{text}", "&#" + this.brandColorHex("text"));
        return value;
    }

    private Component legacyColorize(String msg) {
        if (msg == null) {
            return Component.empty();
        }
        String normalized = this.normalizeLegacyColors(this.applyBrandTokens(msg)).replace('&', '\u00a7');
        return LegacyComponentSerializer.legacySection().deserialize(normalized);
    }

    private String normalizeLegacyColors(String value) {
        if (value == null || value.isBlank()) {
            return "";
        }
        Matcher matcher = HEX_COLOR_PATTERN.matcher(value);
        StringBuilder out = new StringBuilder();
        while (matcher.find()) {
            String hex = matcher.group(1).toUpperCase(Locale.ROOT);
            StringBuilder expanded = new StringBuilder("&x");
            for (int i = 0; i < hex.length(); ++i) {
                expanded.append('&').append(hex.charAt(i));
            }
            matcher.appendReplacement(out, Matcher.quoteReplacement(expanded.toString()));
        }
        matcher.appendTail(out);
        return out.toString();
    }

    private boolean isMuted(UUID uuid) {
        long now = System.currentTimeMillis();
        long expiry = this.muteCacheExpiry.getOrDefault(uuid, 0L);
        if (expiry > now && this.muteCacheValue.containsKey(uuid)) {
            return this.muteCacheValue.getOrDefault(uuid, false);
        }
        boolean muted = this.queryMuteState(uuid);
        this.muteCacheValue.put(uuid, muted);
        this.muteCacheExpiry.put(uuid, now + 2000L);
        return muted;
    }

