    private boolean queryMuteState(UUID uuid) {
        String sql = "SELECT COUNT(*) FROM punishments WHERE target_uuid=? AND type='MUTE' AND active=1 AND (expires_at IS NULL OR expires_at > CURRENT_TIMESTAMP)";
        try (Connection conn = this.openSyncConnection();
             PreparedStatement ps = conn.prepareStatement(sql);){
            ps.setString(1, uuid.toString());
            try (ResultSet rs = ps.executeQuery();){
                if (!rs.next()) return false;
                boolean bl = rs.getInt(1) > 0;
                return bl;
            }
        }
        catch (Exception exception) {
            // empty catch block
        }
        return false;
    }

    private boolean isTeamChatModeEnabled(UUID uuid) {
        if (TEAMS_DISABLED) {
            return false; // teams retired — never route chat to team chat
        }
        if (this.teamChatModeCache.containsKey(uuid)) {
            return this.teamChatModeCache.getOrDefault(uuid, false);
        }
        boolean mode = this.queryTeamChatMode(uuid);
        this.teamChatModeCache.put(uuid, mode);
        return mode;
    }

    private boolean toggleTeamChatMode(UUID uuid) {
        boolean current = this.queryTeamChatMode(uuid);
        return this.setTeamChatMode(uuid, !current);
    }

