    private List<UUID> getTeamMembers(UUID uuid) {
        ArrayList<UUID> members = new ArrayList<UUID>();
        String sql = "SELECT tm2.member_uuid FROM team_members tm1 JOIN team_members tm2 ON tm1.team_id = tm2.team_id WHERE tm1.member_uuid=?";
        try (Connection conn = this.openSyncConnection();
             PreparedStatement ps = conn.prepareStatement(sql);){
            ps.setString(1, uuid.toString());
            try (ResultSet rs = ps.executeQuery();){
                while (rs.next()) {
                    String raw = rs.getString(1);
                    if (raw == null || raw.isBlank()) continue;
                    members.add(UUID.fromString(raw));
                }
            }
        }
        catch (Exception exception) {
            // empty catch block
        }
        return members;
    }

    private String jdbcUrl() {
        String host = this.settings.getString("sync.database.host", "127.0.0.1");
        int port = this.settings.getInt("sync.database.port", 3306);
        String database = this.settings.getString("sync.database.name", "smpcore");
        String parameters = this.settings.getString("sync.database.parameters", "useUnicode=true&characterEncoding=utf8&useSSL=false&allowPublicKeyRetrieval=true");
        return "jdbc:mariadb://" + host + ":" + port + "/" + database + "?" + parameters;
    }

    // Lazily build the shared HikariCP pool (idempotent). Used by both PNC and PlayerSyncManager.
    synchronized com.zaxxer.hikari.HikariDataSource ensureDataSource() {
        if (this.dataSource != null) {
            return this.dataSource;
        }
        try {
            com.zaxxer.hikari.HikariConfig hc = new com.zaxxer.hikari.HikariConfig();
            hc.setPoolName("PizzaNetworkCore");
            hc.setDriverClassName("org.mariadb.jdbc.Driver");
            hc.setJdbcUrl(this.jdbcUrl());
            hc.setUsername(this.settings.getString("sync.database.user", "smpcore"));
            hc.setPassword(this.settings.getString("sync.database.password", "changeme"));
            // Small pool: a remote 1-ECPU DB runs only a few queries truly in parallel; HikariCP guidance
            // is that a small pool beats a large one. Stays far under the server's 200-connection ceiling.
            hc.setMaximumPoolSize(this.settings.getInt("sync.database.pool.max-size", 20));
            hc.setMinimumIdle(this.settings.getInt("sync.database.pool.min-idle", 5));
            hc.setConnectionTimeout(this.settings.getLong("sync.database.pool.connection-timeout-ms", 10000L));
            hc.setKeepaliveTime(300000L);                                                  // ping idle conns every 5m
            hc.setIdleTimeout(600000L);
            hc.setMaxLifetime(this.settings.getLong("sync.database.pool.max-lifetime-ms", 1800000L)); // < MySQL wait_timeout
            hc.setInitializationFailTimeout(-1);  // don't hard-fail enable if the DB is momentarily unreachable
            this.dataSource = new com.zaxxer.hikari.HikariDataSource(hc);
            this.mariadbDriverLoaded = true;
            this.getLogger().info("DB pool ready (max=" + hc.getMaximumPoolSize() + ", min-idle=" + hc.getMinimumIdle() + ") -> " + this.jdbcUrl());
        } catch (Throwable t) {
            this.getLogger().warning("Failed to init DB pool; falling back to per-op connections: " + t.getMessage());
            this.dataSource = null;
        }
        return this.dataSource;
    }

    // Package-private: PlayerSyncManager borrows from the same pool.
    Connection openSyncConnection() throws SQLException {
        com.zaxxer.hikari.HikariDataSource ds = this.dataSource;
        if (ds == null) {
            ds = this.ensureDataSource();
        }
        if (ds != null) {
            return ds.getConnection();
        }
        // Fallback: pool unavailable — per-op connection.
        if (!this.mariadbDriverLoaded) {
            try {
                Class.forName("org.mariadb.jdbc.Driver");
                this.mariadbDriverLoaded = true;
            }
            catch (ClassNotFoundException ignored) {}
        }
        return DriverManager.getConnection(this.jdbcUrl(),
            this.settings.getString("sync.database.user", "smpcore"),
            this.settings.getString("sync.database.password", "changeme"));
    }

    private boolean isTeleportCommand(String label) {
        return switch (label) {
            case "spawn", "warp", "afk", "tp", "teleport", "tphere", "back", "server", "lobby", "survival", "pvp", "duels", "hub" -> true;
            default -> false;
        };
    }

    private void startTeleportCountdown(Player player, String fullCommand) {
        if (this.isCombatTagged(player)) {
            player.sendActionBar((Component)Component.text((String)"\u00a7cYou are in combat! Cannot teleport."));
            this.logCombatBlocked(player, "countdown");
            return;
        }
        UUID uuid = player.getUniqueId();
        this.cancelPendingById(uuid);
        // Instant teleport — no warmup.
        this.executeDelayedTeleportCommand(player, fullCommand);
    }

    private boolean exceedsTeleportMoveTolerance(Location from, Location to) {
        double dx = Math.abs(from.getX() - to.getX());
        double dy = Math.abs(from.getY() - to.getY());
        double dz = Math.abs(from.getZ() - to.getZ());
        return dx > 1.5 || dz > 1.5 || dy > 2.5;
    }

    private void cancelPendingTeleport(Player player, boolean notify) {
        this.cancelPendingById(player.getUniqueId());
        if (notify) {
            // empty if block
        }
    }

    private void cancelPendingById(UUID uuid) {
        PendingTeleport pending = this.pendingTeleports.remove(uuid);
        if (pending != null && pending.task != null) {
            pending.task.cancel();
        }
    }

    private void executeDelayedTeleportCommand(Player player, String fullCommand) {
        String label;
        if (fullCommand == null || fullCommand.length() < 2 || fullCommand.charAt(0) != '/') {
            return;
        }
        String[] split = fullCommand.substring(1).trim().split("\\s+");
        if (split.length == 0 || split[0].isBlank()) {
            return;
        }
        switch (label = split[0].toLowerCase()) {
            case "spawn": {
                this.routeWarpLikeCommand(player, "spawn");
                break;
            }
            case "afk": {
                this.routeWarpLikeCommand(player, "afk");
                break;
            }
            case "duels": 
            case "pvp": 
            case "survival": 
            case "lobby": 
            case "hub": {
                this.routeWarpLikeCommand(player, label);
                break;
            }
            case "warp": {
                if (split.length < 2) {
                    player.sendMessage("\u00a7cUsage: /warp <spawn|duels|survival|afk>");
                    return;
                }
                this.routeWarpLikeCommand(player, split[1].toLowerCase());
                break;
            }
            case "rtp": {
                if (split.length < 2) {
                    this.handleRtpCommand(player, new String[0]);
                    return;
                }
                this.handleRtpCommand(player, new String[]{split[1]});
                break;
            }
            default: {
                this.delayBypassDispatch.add(player.getUniqueId());
                Bukkit.dispatchCommand((CommandSender)player, (String)fullCommand.substring(1));
            }
        }
    }

    private void performLocalRtp(Player player, String dimension) {
        String worldName = switch (dimension) {
            case "nether" -> "world_nether";
            case "end" -> "world_the_end";
            default -> "world";
        };
        World world = Bukkit.getWorld((String)worldName);
        if (world == null && !Bukkit.getWorlds().isEmpty()) {
            world = (World)Bukkit.getWorlds().getFirst();
        }
        if (world == null) {
            player.sendMessage("\u00a7cThe RTP world is unavailable right now.");
            return;
        }
        if (!this.activeRtpSearches.add(player.getUniqueId())) {
            return;
        }
        double borderRadius = 3000.0;
        double centerX = 0.0;
        double centerZ = 0.0;
        if (world.getWorldBorder() != null) {
            centerX = world.getWorldBorder().getCenter().getX();
            centerZ = world.getWorldBorder().getCenter().getZ();
            borderRadius = Math.max(256.0, world.getWorldBorder().getSize() / 2.0 - (double)this.getRtpBorderPadding());
        }
        RtpSearchPlan plan = new RtpSearchPlan(world.getName(), centerX, centerZ, Math.max(0.0, this.settings.getDouble("rtp.min-radius", 500.0)), borderRadius, Math.max(8, this.settings.getInt("rtp.search-attempts", 96)), player.getLocation().getYaw());
        player.sendActionBar(this.legacyColorize("&#00BFFFSearching for a safe location…"));
        this.searchRtpLocation(player.getUniqueId(), plan, 0);
    }

    private void openRtpMenu(Player player) {
        Inventory inv = Bukkit.createInventory(null, (int)27, (String)TITLE_RTP);
        this.fillBlue(inv);
        // Small-caps (unicode) names matching the old RTPGUI style.
        inv.setItem(11, this.namedWithLore(Material.GRASS_BLOCK, "\u00a7a\u1d07\u1d00s\u1d1b", "rtp_dim:overworld", List.of("\u00a7fClick to randomly teleport")));
        inv.setItem(13, this.namedWithLore(Material.NETHERRACK, "\u00a7a\u1d1b\u029c\u1d07 \u0274\u1d07\u1d1b\u029c\u1d07\u0280", "rtp_dim:nether", List.of("\u00a7fClick to randomly teleport")));
        inv.setItem(15, this.namedWithLore(Material.END_STONE, "\u00a7a\u1d1b\u029c\u1d07 \u1d07\u0274\u1d05", "rtp_dim:end", List.of("\u00a7fClick to randomly teleport")));
        player.openInventory(inv);
        player.playSound(player.getLocation(), Sound.UI_BUTTON_CLICK, 0.7f, 1.2f);
    }

    private void handleRtpMenuClick(Player player, ItemStack current) {
        if (current == null || !current.hasItemMeta()) {
            return;
        }
        if (!this.canUseRtp(player)) {
            player.sendMessage("\u00a7cYou do not have permission to use /rtp.");
            player.closeInventory();
            return;
        }
        if (this.isCombatTagged(player)) {
            player.sendActionBar((Component)Component.text((String)"\u00a7cYou are in combat! Cannot use RTP."));
            return;
        }
        String id = this.uiActionId(current);
        if (id == null) {
            return;
        }
        if ("rtp_close".equals(id)) {
            player.closeInventory();
            return;
        }
        if (!id.startsWith("rtp_dim:")) {
            return;
        }
        String dimension = this.normalizeRtpDimension(id.substring("rtp_dim:".length()));
        if (dimension == null) {
            return;
        }
        player.closeInventory();
        this.startRtpWarmup(player, dimension, false);
    }

    private String normalizeRtpDimension(String input) {
        if (input == null) {
            return null;
        }
        return switch (input.toLowerCase()) {
            case "east", "overworld", "world", "ow" -> "overworld";
            case "nether" -> "nether";
            case "end", "the_end" -> "end";
            default -> null;
        };
    }

    private boolean canUseRtp(Player player) {
        return player != null && (player.hasPermission("pizzasmp.use.rtp") || player.hasPermission("pizzasmp.rtp.use"));
    }

    private int getCombatTagSeconds() {
        return Math.max(1, this.settings.getInt("combat.tag_seconds", 20));
    }

    private long getCombatRemainingMillis(Player player) {
        if (player == null) {
            return 0L;
        }
        long until = this.combatTaggedUntil.getOrDefault(player.getUniqueId(), 0L);
        if (until <= System.currentTimeMillis()) {
            this.clearCombatTag(player.getUniqueId());
            return 0L;
        }
        return until - System.currentTimeMillis();
    }

    // Scoreboard tag used to expose combat-tag state to other plugins
    // (e.g. punish-drop reads this to know if a ban happened mid-combat).
    private static final String COMBAT_SCOREBOARD_TAG = "pizza_combat";

    private void applyCombatTag(Player player, long expireAt) {
        if (player == null || !player.isOnline()) {
            return;
        }
        boolean wasInCombat = this.combatTaggedUntil.containsKey(player.getUniqueId());
        this.combatTaggedUntil.put(player.getUniqueId(), expireAt);
        try { player.addScoreboardTag(COMBAT_SCOREBOARD_TAG); } catch (Throwable ignored) {}
        this.scheduleCombatActionbar(player.getUniqueId());
        // Cancel pending teleports when entering combat (damage alone doesn't cancel; combat does)
        if (!wasInCombat) {
            UUID uuid = player.getUniqueId();
            if (this.pendingTeleports.containsKey(uuid) || this.pendingRtpTeleports.containsKey(uuid) || this.pendingHomeTeleports.containsKey(uuid)) {
                this.cancelPendingTeleport(player, true);
                this.cancelPendingHomeTeleport(uuid);
                player.sendActionBar((Component)Component.text("§cTeleport cancelled — you entered combat"));
            }
        }
    }

    private void scheduleCombatActionbar(UUID uuid) {
        if (this.combatActionbarTasks.containsKey(uuid)) {
            return;
        }
        this.tickCombatActionbar(uuid);
    }

    private void tickCombatActionbar(UUID uuid) {
        Player player = Bukkit.getPlayer((UUID)uuid);
        if (player == null || !player.isOnline()) {
            this.clearCombatTag(uuid);
            return;
        }
        long until = this.combatTaggedUntil.getOrDefault(uuid, 0L);
        long remainingMillis = until - System.currentTimeMillis();
        if (remainingMillis <= 0L) {
            this.clearCombatTag(uuid);
            return;
        }
        long remainingSeconds = Math.max(1L, (long)Math.ceil((double)remainingMillis / 1000.0));
        String prefix = this.settings.getString("combat.actionbar_prefix", "\u00a7fCombat: &#00BFFF");
        player.sendActionBar(this.legacyColorize(prefix + remainingSeconds + "s"));
        this.combatActionbarTasks.put(uuid, this.runPlayerTaskLater(player, () -> this.tickCombatActionbar(uuid), 20L));
    }

    private void clearCombatTag(UUID uuid) {
        Player player;
        this.combatTaggedUntil.remove(uuid);
        TaskHandle task = this.combatActionbarTasks.remove(uuid);
        if (task != null) {
            task.cancel();
        }
        Player p = Bukkit.getPlayer(uuid);
        if (p != null) { try { p.removeScoreboardTag(COMBAT_SCOREBOARD_TAG); } catch (Throwable ignored) {} }
        if ((player = Bukkit.getPlayer((UUID)uuid)) != null && player.isOnline()) {
            player.sendActionBar((Component)Component.empty());
        }
    }

    private void applyCombatLogoutPenalty(Player player) {
        if (player == null || this.shuttingDown) {
            return;
        }
        // Flag for the death screen on next join
        this.combatLoggedPending.add(player.getUniqueId());
        this.clearCombatTag(player.getUniqueId());
        int totalExp = Math.max(0, player.getTotalExperience());
        this.dropPlayerInventory(player);
        if (totalExp > 0) {
            ExperienceOrb orb = (ExperienceOrb)player.getWorld().spawn(player.getLocation(), ExperienceOrb.class);
            orb.setExperience(totalExp);
        }
        player.setTotalExperience(0);
        player.setLevel(0);
        player.setExp(0.0f);
        Location respawn = this.resolveCombatLogoutRespawn(player);
        try {
            player.teleport(respawn);
        }
        catch (Exception exception) {
            // empty catch block
        }
        try {
            double maxHealth = 20.0;
            AttributeInstance maxHealthAttribute = player.getAttribute(Attribute.MAX_HEALTH);
            if (maxHealthAttribute != null) {
                maxHealth = maxHealthAttribute.getValue();
            }
            player.setFireTicks(0);
            player.setFallDistance(0.0f);
            player.setHealth(maxHealth);
        }
        catch (Exception exception) {
            // empty catch block
        }
        player.setFoodLevel(20);
        player.setSaturation(20.0f);
        player.setExhaustion(0.0f);
        // Flush the cleared inventory/XP to player.dat now so an abnormal disconnect
        // can't leave the old, pre-penalty snapshot on disk (which would let the
        // player rejoin with their full inventory and effectively skip the penalty).
        try { player.saveData(); } catch (Exception ignored) {}
        this.runAsyncTask(() -> this.incrementLongStat(player.getUniqueId(), "deaths", 1L));
    }

    private Location resolveCombatLogoutRespawn(Player player) {
        Location bedSpawn = player.getBedSpawnLocation();
        if (bedSpawn != null && bedSpawn.getWorld() != null) {
            return bedSpawn.clone().add(0.5, 0.0, 0.5);
        }
        Location worldSpawn = player.getWorld().getSpawnLocation();
        return worldSpawn.clone().add(0.5, 0.0, 0.5);
    }

    private void dropPlayerInventory(Player player) {
        if (player == null) {
            return;
        }
        for (ItemStack stack : player.getInventory().getStorageContents()) {
            this.dropPlayerItem(player, stack);
        }
        for (ItemStack stack : player.getInventory().getArmorContents()) {
            this.dropPlayerItem(player, stack);
        }
        this.dropPlayerItem(player, player.getInventory().getItemInOffHand());
        player.getInventory().clear();
        player.getInventory().setArmorContents(new ItemStack[4]);
        player.getInventory().setItemInOffHand(null);
        player.updateInventory();
    }

    private void dropPlayerItem(Player player, ItemStack stack) {
        if (player == null || stack == null || stack.getType().isAir()) {
            return;
        }
        org.bukkit.entity.Item item = player.getWorld().dropItemNaturally(player.getLocation(), stack.clone());
        this.protectedDeathDrops.add(item.getUniqueId());
    }

    private boolean isCombatTagged(Player player) {
        return this.getCombatRemainingMillis(player) > 0L;
    }

    private void searchRtpLocation(UUID uuid, RtpSearchPlan plan, int attempt) {
        if (!this.activeRtpSearches.contains(uuid)) {
            return;
        }
        Player player = Bukkit.getPlayer((UUID)uuid);
        if (player == null || !player.isOnline()) {
            this.activeRtpSearches.remove(uuid);
            return;
        }
        if (attempt >= plan.maxAttempts) {
            this.activeRtpSearches.remove(uuid);
            this.runOnPlayerThread(player, () -> player.sendActionBar(this.legacyColorize("§cCouldn't find a safe spot — try again.")));
            // Refund the cooldown so they can immediately retry.
            this.rtpCooldowns.remove(uuid);
            return;
        }
        double angle = ThreadLocalRandom.current().nextDouble(0.0, Math.PI * 2);
        double radius = plan.minRadius >= plan.maxRadius ? plan.maxRadius : ThreadLocalRandom.current().nextDouble(plan.minRadius, plan.maxRadius);
        int x = NumberConversions.floor((double)(plan.centerX + Math.cos(angle) * radius));
        int z = NumberConversions.floor((double)(plan.centerZ + Math.sin(angle) * radius));
        this.scheduleRtpCandidateCheck(uuid, plan, attempt, x, z);
    }

    private void scheduleRtpCandidateCheck(UUID uuid, RtpSearchPlan plan, int attempt, int x, int z) {
        World world = Bukkit.getWorld((String)plan.worldName);
        if (world == null) {
            this.activeRtpSearches.remove(uuid);
            Player player = Bukkit.getPlayer((UUID)uuid);
            if (player != null && player.isOnline()) {
                this.runOnPlayerThread(player, () -> player.sendMessage("\u00a7cThe RTP world is unavailable right now."));
            }
            return;
        }
        this.runRegionTask(world, x, z, () -> {
            Location target = this.findSafeRtpLocation(world, x, z, plan.yaw);
            if (target == null) {
                this.runAsyncTask(() -> this.searchRtpLocation(uuid, plan, attempt + 1));
                return;
            }
            this.activeRtpSearches.remove(uuid);
            Player player = Bukkit.getPlayer((UUID)uuid);
            if (player == null || !player.isOnline()) {
                return;
            }
            this.runOnPlayerThread(player, () -> {
                if (player.isOnline()) {
                    player.teleport(target);
                }
            });
        });
    }

    private Location findSafeRtpLocation(World world, int x, int z, float yaw) {
        // The Nether/End have a bedrock ROOF, so getHighestBlockYAt returns the ceiling.
        // For enclosed worlds, scan DOWNWARD from a sensible Y to find a real floor with headroom.
        if (world.getEnvironment() == World.Environment.NETHER) {
            return this.findEnclosedSafeLocation(world, x, z, 120, world.getMinHeight() + 5, yaw);
        }
        // Overworld / End surface: getHighestBlockYAt returns the SURFACE (top solid block) Y.
        int surfaceY = world.getHighestBlockYAt(x, z);
        int minY = world.getMinHeight();
        int maxY = world.getMaxHeight() - 2;
        if (surfaceY < minY + 1 || surfaceY > maxY) {
            return null;
        }
        Block ground = world.getBlockAt(x, surfaceY, z);       // the surface block (must be solid)
        Block feet = world.getBlockAt(x, surfaceY + 1, z);     // where the player stands (must be air)
        Block head = world.getBlockAt(x, surfaceY + 2, z);     // headroom (must be air)
        if (!ground.getType().isSolid()) {
            return null;
        }
        if (this.isUnsafeRtpBlock(ground) || this.isUnsafeRtpBlock(feet) || this.isUnsafeRtpBlock(head)) {
            return null;
        }
        if (!feet.isPassable() || !head.isPassable()) {
            return null;
        }
        return new Location(world, (double)x + 0.5, (double)(surfaceY + 1), (double)z + 0.5, yaw, 0.0f);
    }

    // Scan downward from topY to find: solid ground + 2 air blocks above (a safe standing pocket),
    // staying below the bedrock roof. Used for the Nether.
    private Location findEnclosedSafeLocation(World world, int x, int z, int topY, int bottomY, float yaw) {
        topY = Math.min(topY, world.getMaxHeight() - 3);
        for (int y = topY; y > bottomY; y--) {
            Block ground = world.getBlockAt(x, y, z);
            Block feet = world.getBlockAt(x, y + 1, z);
            Block head = world.getBlockAt(x, y + 2, z);
            if (!ground.getType().isSolid()) continue;
            if (this.isUnsafeRtpBlock(ground) || this.isUnsafeRtpBlock(feet) || this.isUnsafeRtpBlock(head)) continue;
            if (!feet.isPassable() || !head.isPassable()) continue;
            // Reject the bedrock roof itself (ground at the very top is the ceiling).
            if (ground.getType() == Material.BEDROCK && y >= 125) continue;
            return new Location(world, (double)x + 0.5, (double)(y + 1), (double)z + 0.5, yaw, 0.0f);
        }
        return null;
    }

    private boolean isUnsafeRtpBlock(Block block) {
        Waterlogged waterlogged;
        if (block == null) {
            return true;
        }
        Material material = block.getType();
        if (material.isAir()) {
            return false;
        }
        BlockData blockData = block.getBlockData();
        if (blockData instanceof Waterlogged && (waterlogged = (Waterlogged)blockData).isWaterlogged()) {
            return true;
        }
        return this.getUnsafeRtpGroundMaterials().contains(material);
    }

    private Set<Material> getUnsafeRtpGroundMaterials() {
        ConcurrentHashMap.KeySetView out = ConcurrentHashMap.newKeySet();
        for (String entry : this.settings.getStringList("rtp.unsafe-ground-materials")) {
            if (entry == null || entry.isBlank()) continue;
            try {
                out.add(Material.valueOf((String)entry.trim().toUpperCase(Locale.ROOT)));
            }
            catch (IllegalArgumentException illegalArgumentException) {}
        }
        if (out.isEmpty()) {
            out.add(Material.WATER);
            out.add(Material.LAVA);
            out.add(Material.KELP);
            out.add(Material.KELP_PLANT);
        }
        return out;
    }

    private int getRtpBorderPadding() {
        return Math.max(0, this.settings.getInt("rtp.max-radius-border-padding", 64));
    }

    private void runRegionTask(World world, int blockX, int blockZ, Runnable task) {
        if (this.foliaRuntime) {
            Bukkit.getRegionScheduler().execute((Plugin)this, world, blockX, blockZ, task);
            return;
        }
        Bukkit.getScheduler().runTask((Plugin)this, task);
    }

    private void logCombatBlocked(Player player, String path) {
        if (!this.combatDebug || player == null) {
            return;
        }
        this.getLogger().info("[combat-debug] uuid=" + String.valueOf(player.getUniqueId()) + " server=" + this.detectServerName() + " path=" + path + " result=blocked");
    }

    // Pizza++ premium tier (LuckPerms group pizza++, inherits pizza+).
    boolean isPizzaPlusPlus(Player p) {
        return p != null && (p.hasPermission("group.pizza++") || p.hasPermission("pizzasmp.rank.pizzaplusplus"));
    }

    private boolean isPizzaPlus(Player p) {
        return p != null && (p.hasPermission("group.pizza+") || p.hasPermission("group.pizzaplus")
                || p.hasPermission("pizzasmp.rank.pizzaplus"));
    }

    // Concurrent AH listings / open orders cap: default 18, pizza+ 27, pizza++ & staff 36.
    private int marketSlotCap(Player p) {
        // Pizza++/staff get ALL 45 grid slots; Pizza+ gets 27; default 18.
        if (p == null) return 18;
        if (p.isOp() || p.hasPermission("pizzasmp.staff") || this.isPizzaPlusPlus(p)) return 45;
        if (this.isPizzaPlus(p)) return 27;
        return 18;
    }

    private long getRtpCooldownMillis(Player player) {
        // owner/dev/sradmin: 5s | staff (mod/srmod/admin/co-owner): 10s | pizza++: 8s | pizza+: 15s | default: 25s
        if (player.hasPermission("group.dev") || player.hasPermission("group.owner")
                || player.hasPermission("group.sradmin")) {
            return 5000L;
        }
        if (player.hasPermission("group.mod") || player.hasPermission("group.srmod")
                || player.hasPermission("group.admin") || player.hasPermission("group.co-owner")
                || player.hasPermission("group.staff")) {
            return 10000L;
        }
        if (this.isPizzaPlusPlus(player)) {
            return 8000L;
        }
        if (player.hasPermission("group.pizza+") || player.hasPermission("group.pizzaplus")
                || player.hasPermission("group.donutplus")) {
            return 15000L;
        }
        return 25000L;
    }

    private boolean canUseRtpNow(Player player) {
        long last = this.rtpCooldowns.getOrDefault(player.getUniqueId(), 0L);
        return System.currentTimeMillis() - last >= this.getRtpCooldownMillis(player);
    }

    private long getRtpCooldownRemainingMillis(Player player) {
        long last = this.rtpCooldowns.getOrDefault(player.getUniqueId(), 0L);
        long cooldown = this.getRtpCooldownMillis(player);
        long elapsed = System.currentTimeMillis() - last;
        return Math.max(0L, cooldown - elapsed);
    }

    private void markRtpUsed(Player player) {
        this.rtpCooldowns.put(player.getUniqueId(), System.currentTimeMillis());
    }

    private void cancelPendingRtp(UUID uuid) {
        PendingRtpTeleport pending = this.pendingRtpTeleports.remove(uuid);
        if (pending != null && pending.task != null) {
            pending.task.cancel();
        }
    }

    private void tickTeleportCountdown(UUID uuid) {
        PendingTeleport pending = this.pendingTeleports.get(uuid);
        Player player = Bukkit.getPlayer((UUID)uuid);
        if (pending == null || player == null || !player.isOnline()) {
            this.cancelPendingById(uuid);
            return;
        }
        if (pending.seconds <= 0) {
            this.pendingTeleports.remove(uuid);
            if (pending.task != null) {
                pending.task.cancel();
            }
            this.executeDelayedTeleportCommand(player, pending.command);
            return;
        }
        player.sendActionBar(this.legacyColorize("\u00a77Teleporting in &#00BFFF" + pending.seconds + "\u00a77s"));
        if (this.isSettingEnabledCached(uuid, "music_sound_notifications")) {
            player.playSound(player.getLocation(), Sound.BLOCK_NOTE_BLOCK_HAT, 0.5f, 1.8f);
        }
        --pending.seconds;
        pending.task = this.runPlayerTaskLater(player, () -> this.tickTeleportCountdown(uuid), 20L);
    }

    private void tickRtpCountdown(UUID uuid) {
        // Instant RTP: the safe location was already found asynchronously, so teleport immediately.
        PendingRtpTeleport pending = this.pendingRtpTeleports.get(uuid);
        Player player = Bukkit.getPlayer((UUID)uuid);
        if (pending == null || player == null || !player.isOnline()) {
            this.cancelPendingRtp(uuid);
            return;
        }
        this.pendingRtpTeleports.remove(uuid);
        if (pending.task != null) {
            pending.task.cancel();
        }
        // Teleport to the pre-found destination, mark cooldown, play the ender-pearl sound.
        Location dest = pending.destination;
        if (dest != null) {
            this.markRtpUsed(player);
            player.teleportAsync(dest).thenAccept(ok -> this.runOnPlayerThread(player, () -> {
                if (ok) {
                    this.resetFallAfterTeleport(player);
                    player.sendActionBar(Component.text("\u00a77You teleported to a random location."));
                    if (this.isSettingEnabledCached(uuid, "music_sound_notifications")) {
                        player.playSound(player.getLocation(), Sound.ENTITY_ENDERMAN_TELEPORT, 0.8f, 1.2f);
                    }
                }
            }));
        }
    }

    private TaskHandle runPlayerTaskLater(Player player, Runnable task, long delayTicks) {
        if (this.foliaRuntime) {
            ScheduledTask scheduled = player.getScheduler().runDelayed((Plugin)this, st -> task.run(), null, delayTicks);
            return () -> ((ScheduledTask)scheduled).cancel();
        }
        int taskId = Bukkit.getScheduler().scheduleSyncDelayedTask((Plugin)this, task, delayTicks);
        return () -> Bukkit.getScheduler().cancelTask(taskId);
    }

    private void runOnPlayerThread(Player player, Runnable task) {
        if (player == null || !player.isOnline()) {
            return;
        }
        if (this.foliaRuntime) {
            player.getScheduler().run((Plugin)this, st -> task.run(), null);
            return;
        }
        Bukkit.getScheduler().runTask((Plugin)this, task);
    }

    private void runAsyncTask(Runnable task) {
        if (this.foliaRuntime) {
            Bukkit.getAsyncScheduler().runNow((Plugin)this, st -> task.run());
            return;
        }
        Bukkit.getScheduler().runTaskAsynchronously((Plugin)this, task);
    }

    private TaskHandle runAsyncRepeatingTask(Runnable task, long initialDelayTicks, long periodTicks) {
        if (this.foliaRuntime) {
            long initialDelayMs = Math.max(1L, initialDelayTicks * 50L);
            long periodMs = Math.max(1L, periodTicks * 50L);
            ScheduledTask scheduled = Bukkit.getAsyncScheduler().runAtFixedRate((Plugin)this, st -> task.run(), initialDelayMs, periodMs, TimeUnit.MILLISECONDS);
            return () -> ((ScheduledTask)scheduled).cancel();
        }
        int taskId = Bukkit.getScheduler().runTaskTimerAsynchronously((Plugin)this, task, initialDelayTicks, periodTicks).getTaskId();
        return () -> Bukkit.getScheduler().cancelTask(taskId);
    }

    private void pollPendingPlayerNotifications() {
        for (Player player : Bukkit.getOnlinePlayers()) {
            List<PlayerNotificationEntry> notifications;
            if (player == null || !player.isOnline() || (notifications = this.consumePendingPlayerNotifications(player.getUniqueId())).isEmpty()) continue;
            this.runOnPlayerThread(player, () -> {
                if (!player.isOnline()) {
                    return;
                }
                for (PlayerNotificationEntry notification : notifications) {
                    String target;
                    if (notification.message() != null && !notification.message().isBlank()) {
                        player.sendMessage(notification.message());
                    }
                    if (notification.action() == null || notification.action().isBlank() || !notification.action().startsWith("CONNECT:") || (target = this.normalizeServerTarget(notification.action().substring("CONNECT:".length()))).isBlank() || target.equalsIgnoreCase(this.detectServerName())) continue;
                    this.connectToServer(player, target);
                }
            });
        }
    }

    private List<PlayerNotificationEntry> consumePendingPlayerNotifications(UUID recipientUuid) {
        ArrayList<PlayerNotificationEntry> out;
        block32: {
            if (recipientUuid == null) {
                return List.of();
            }
            out = new ArrayList<PlayerNotificationEntry>();
            ArrayList<Long> ids = new ArrayList<Long>();
            String selectSql = "SELECT id,message,action FROM network_player_notifications WHERE recipient_uuid=? AND expires_at > CURRENT_TIMESTAMP ORDER BY id ASC LIMIT 10";
            try (Connection conn = this.openSyncConnection();
                 PreparedStatement ps = conn.prepareStatement(selectSql);){
                ps.setString(1, recipientUuid.toString());
                try (ResultSet rs = ps.executeQuery();){
                    while (rs.next()) {
                        long id = rs.getLong(1);
                        ids.add(id);
                        out.add(new PlayerNotificationEntry(id, rs.getString(2), rs.getString(3)));
                    }
                }
                if (ids.isEmpty()) break block32;
                StringBuilder deleteSql = new StringBuilder("DELETE FROM network_player_notifications WHERE recipient_uuid=? AND id IN (");
                for (int i = 0; i < ids.size(); ++i) {
                    if (i > 0) {
                        deleteSql.append(',');
                    }
                    deleteSql.append('?');
                }
                deleteSql.append(')');
                try (PreparedStatement delete = conn.prepareStatement(deleteSql.toString());){
                    delete.setString(1, recipientUuid.toString());
                    for (int i = 0; i < ids.size(); ++i) {
                        delete.setLong(i + 2, (Long)ids.get(i));
                    }
                    delete.executeUpdate();
                }
            }
            catch (Exception ex) {
                if (!this.routerDebug) break block32;
                this.getLogger().warning("Failed polling player notifications for " + String.valueOf(recipientUuid) + ": " + ex.getMessage());
            }
        }
        return out;
    }

    private void queuePlayerNotification(UUID recipientUuid, String message, String action, int ttlSeconds) {
        if (recipientUuid == null) {
            return;
        }
        String sql = "INSERT INTO network_player_notifications (recipient_uuid,message,action,expires_at) VALUES (?,?,?, DATE_ADD(NOW(), INTERVAL ? SECOND))";
        try (Connection conn = this.openSyncConnection();
             PreparedStatement ps = conn.prepareStatement(sql);){
            ps.setString(1, recipientUuid.toString());
            ps.setString(2, message == null ? "" : message);
            ps.setString(3, action == null ? "" : action);
            ps.setInt(4, Math.max(5, ttlSeconds));
            ps.executeUpdate();
        }
        catch (Exception ex) {
            this.getLogger().warning("Failed queueing player notification for " + String.valueOf(recipientUuid) + ": " + ex.getMessage());
        }
    }

    private boolean isServer(String logicalName) {
        int port = Bukkit.getPort();
        return switch (logicalName.toLowerCase()) {
            case "lobby" -> {
                if (port == 25566) {
                    yield true;
                }
                yield false;
            }
            case "survival", "main" -> {
                // Single-server deployment runs survival on the default 25565.
                if (port == 25567 || port == 25565) {
                    yield true;
                }
                yield false;
            }
            case "pvp" -> {
                if (port == 25568) {
                    yield true;
                }
                yield false;
            }
            case "maintenance" -> {
                if (port == 25569) {
                    yield true;
                }
                yield false;
            }
            default -> false;
        };
    }

    private String normalizeServerTarget(String target) {
        if (target == null) {
            return "";
        }
        String normalized = target.toLowerCase();
        if ("main".equals(normalized)) {
            return "survival";
        }
        if ("hub".equals(normalized) || "server".equals(normalized)) {
            return "lobby";
        }
        if ("duels".equals(normalized)) {
            return "pvp";
        }
        return normalized;
    }

    private String detectServerName() {
        int port = Bukkit.getPort();
        if (port == 25566) {
            return "lobby";
        }
        if (port == 25567 || port == 25565) {
            return "survival";
        }
        if (port == 25568) {
            return "pvp";
        }
        if (port == 25569) {
            return "maintenance";
        }
        return "unknown-" + port;
    }

    private void connectToServer(Player player, String serverName) {
        if (this.routerDebug) {
            this.getLogger().info("[router-debug] uuid=" + String.valueOf(player.getUniqueId()) + " server=" + this.detectServerName() + " target=" + serverName + " result=proxy_connect_send");
        }
        try (ByteArrayOutputStream bytes = new ByteArrayOutputStream();
             DataOutputStream out = new DataOutputStream(bytes);){
            out.writeUTF("Connect");
            out.writeUTF(serverName);
            player.sendPluginMessage((Plugin)this, "BungeeCord", bytes.toByteArray());
        }
        catch (IOException e) {
            player.sendMessage("\u00a7cTransfer failed. Please try again.");
            this.getLogger().warning("Failed connecting " + player.getName() + " to " + serverName + ": " + e.getMessage());
        }
    }

