    private ParsedTabRequest parseTabRequest(String buffer) {
        if (buffer == null || !buffer.startsWith("/")) {
            return null;
        }
        String withoutSlash = buffer.substring(1);
        boolean trailingSpace = withoutSlash.endsWith(" ");
        String trimmed = withoutSlash.trim();
        if (trimmed.isEmpty()) {
            return null;
        }
        String[] parts = trimmed.split("\\s+");
        if (parts.length == 0 || parts[0].isBlank()) {
            return null;
        }
        int argumentIndex = trailingSpace ? parts.length : parts.length - 1;
        String currentToken = trailingSpace ? "" : parts[parts.length - 1];
        return new ParsedTabRequest(parts[0].toLowerCase(Locale.ROOT), argumentIndex, currentToken);
    }

    private boolean supportsNetworkPlayerCompletion(String label, int argumentIndex) {
        if (argumentIndex != 1) {
            return false;
        }
        return switch (label) {
            case "msg", "tell", "w", "pm", "message", "tpa", "tpahere", "gtp", "punish", "bancheck", "forgive", "unpunish" -> true;
            default -> false;
        };
    }

    private List<String> completeNetworkPlayerNames(String prefix, UUID viewerUuid) {
        this.refreshNetworkPlayerNameCacheIfNeeded();
        String normalizedPrefix = prefix == null ? "" : prefix.toLowerCase(Locale.ROOT);
        ArrayList<String> out = new ArrayList<String>();
        for (Player player : Bukkit.getOnlinePlayers()) {
            String name;
            if (viewerUuid != null && viewerUuid.equals(player.getUniqueId()) || (name = player.getName()) == null || !name.toLowerCase(Locale.ROOT).startsWith(normalizedPrefix)) continue;
            this.addCompletionIfMissing(out, name);
        }
        for (String name : this.cachedNetworkPlayerNames) {
            if (name == null || name.isBlank() || !name.toLowerCase(Locale.ROOT).startsWith(normalizedPrefix)) continue;
            this.addCompletionIfMissing(out, name);
        }
        return out;
    }

    private List<String> completeKnownPlayerNames(String prefix, UUID viewerUuid) {
        List<String> out;
        block21: {
            out = this.completeNetworkPlayerNames(prefix, viewerUuid);
            String normalizedPrefix = prefix == null ? "" : prefix.toLowerCase(Locale.ROOT);
            String sql = "SELECT uuid, username FROM players WHERE LOWER(username) LIKE ? ORDER BY LOWER(username) ASC LIMIT 20";
            try (Connection conn = this.openSyncConnection();
                 PreparedStatement ps = conn.prepareStatement(sql);){
                ps.setString(1, normalizedPrefix + "%");
                try (ResultSet rs = ps.executeQuery();){
                    while (rs.next()) {
                        String uuidRaw = rs.getString(1);
                        String username = rs.getString(2);
                        if (username == null || username.isBlank() || viewerUuid != null && uuidRaw != null && viewerUuid.toString().equalsIgnoreCase(uuidRaw)) continue;
                        this.addCompletionIfMissing(out, username);
                    }
                }
            }
            catch (Exception ex) {
                if (!this.routerDebug) break block21;
                this.getLogger().warning("Failed querying known player names: " + ex.getMessage());
            }
        }
        return out;
    }

    private List<String> queryNetworkPlayerNames(String prefix, UUID viewerUuid, int limit) {
        ArrayList<String> out;
        block21: {
            out = new ArrayList<String>();
            String normalizedPrefix = prefix == null ? "" : prefix.toLowerCase(Locale.ROOT);
            String sql = "SELECT p.uuid,p.username FROM players p JOIN session_leases sl ON sl.uuid=p.uuid AND sl.expires_at > CURRENT_TIMESTAMP WHERE LOWER(p.username) LIKE ? ORDER BY LOWER(p.username) ASC LIMIT ?";
            try (Connection conn = this.openSyncConnection();
                 PreparedStatement ps = conn.prepareStatement(sql);){
                ps.setString(1, normalizedPrefix + "%");
                ps.setInt(2, Math.max(1, limit));
                try (ResultSet rs = ps.executeQuery();){
                    while (rs.next()) {
                        String uuidRaw = rs.getString(1);
                        String username = rs.getString(2);
                        if (username == null || username.isBlank() || viewerUuid != null && uuidRaw != null && viewerUuid.toString().equalsIgnoreCase(uuidRaw)) continue;
                        this.addCompletionIfMissing(out, username);
                    }
                }
            }
            catch (Exception ex) {
                if (!this.routerDebug) break block21;
                this.getLogger().warning("Failed querying network player names: " + ex.getMessage());
            }
        }
        return out;
    }

    private void refreshNetworkPlayerNameCacheIfNeeded() {
        if (System.currentTimeMillis() - this.cachedNetworkPlayerNamesLoadedAt <= 2500L) {
            return;
        }
        this.refreshNetworkPlayerNameCacheAsync();
    }

    private void refreshNetworkPlayerNameCacheAsync() {
        if (!this.networkPlayerNameRefreshQueued.compareAndSet(false, true)) {
            return;
        }
        this.runAsyncTask(() -> {
            ArrayList<String> refreshed = new ArrayList<String>();
            String sql = "SELECT p.username FROM players p JOIN session_leases sl ON sl.uuid=p.uuid AND sl.expires_at > CURRENT_TIMESTAMP ORDER BY LOWER(p.username) ASC LIMIT 500";
            try (Connection conn = this.openSyncConnection();
                 PreparedStatement ps = conn.prepareStatement(sql);
                 ResultSet rs = ps.executeQuery();){
                while (rs.next()) {
                    String name = rs.getString(1);
                    if (name == null || name.isBlank()) continue;
                    this.addCompletionIfMissing(refreshed, name);
                }
            }
            catch (Exception ex) {
                if (this.routerDebug) {
                    this.getLogger().warning("Failed refreshing network player cache: " + ex.getMessage());
                }
            }
            finally {
                this.cachedNetworkPlayerNames = List.copyOf(refreshed);
                this.cachedNetworkPlayerNamesLoadedAt = System.currentTimeMillis();
                this.networkPlayerNameRefreshQueued.set(false);
            }
        });
    }

    private List<String> mergeCompletions(List<String> base, String prefix, List<String> extra) {
        ArrayList<String> out = new ArrayList<String>();
        if (base != null) {
            for (String value : base) {
                if (value == null || value.isBlank()) continue;
                this.addCompletionIfMissing(out, value);
            }
        }
        String normalizedPrefix = prefix == null ? "" : prefix.toLowerCase(Locale.ROOT);
        for (String value : extra) {
            if (value == null || value.isBlank() || !value.toLowerCase(Locale.ROOT).startsWith(normalizedPrefix)) continue;
            this.addCompletionIfMissing(out, value);
        }
        return out;
    }

    private void addCompletionIfMissing(List<String> out, String value) {
        for (String existing : out) {
            if (!existing.equalsIgnoreCase(value)) continue;
            return;
        }
        out.add(value);
    }

