    private void openSettings(Player player) {
        if (player == null || !player.isOnline()) {
            return;
        }
        if (this.useDialogUi(player)) {
            this.openSettingsDialog(player, null);
            return;
        }
        UUID uuid = player.getUniqueId();
        this.runAsyncTask(() -> {
            Map<String, Boolean> values = this.loadPlayerSettings(uuid);
            this.playerSettingsCache.put(uuid, values);
            this.settingsPageByPlayer.put(uuid, 1);
            this.runOnPlayerThread(player, () -> this.openSettingsInventory(player, values, 1));
        });
    }

