    // Dialog settings only shown to holders of the given permission (dev-only entries).
    private static final Map<String, String> SETTING_GATE_PERMS = Map.of(
        "staff_mode_bypass", "pizzasmp.manage.grant");

    private void openSettingsDialog(Player player, String openCategory) {
        if (player == null || !player.isOnline()) {
            return;
        }
        UUID uuid = player.getUniqueId();
        this.runAsyncTask(() -> {
            Map<String, Boolean> values = this.loadPlayerSettings(uuid);
            this.playerSettingsCache.put(uuid, values);
            this.runOnPlayerThread(player, () -> this.showSettingsDialog(player, values, openCategory));
        });
    }

    private void showSettingsDialog(Player player, Map<String, Boolean> values, String openCategory) {
        List<ActionButton> buttons = new ArrayList<>();
        for (SettingsCategory cat : SETTINGS_DIALOG_CATEGORIES) {
            boolean open = cat.id().equals(openCategory);
            buttons.add(this.dialogButton(
                Component.text(cat.title(), open ? DIALOG_BRAND : NamedTextColor.WHITE),
                open ? "Click to collapse" : "Click to expand", 250,
                pl -> this.openSettingsDialog(pl, open ? null : cat.id())));
            if (!open) {
                continue;
            }
            for (SettingsEntry entry : cat.entries()) {
                String gate = SETTING_GATE_PERMS.get(entry.key());
                if (gate != null && !player.hasPermission(gate)) continue;   // dev-only entries hidden from others
                if (PRIVACY_TRISTATE.contains(entry.key())) {
                    String mode = this.privacyModeFromValues(values, entry.key());
                    NamedTextColor mc = "off".equals(mode) ? NamedTextColor.RED : "friends".equals(mode) ? NamedTextColor.YELLOW : NamedTextColor.GREEN;
                    Component label = Component.text(entry.label() + ": ", NamedTextColor.WHITE)
                        .append(Component.text(this.privacyModeLabel(mode), mc));
                    buttons.add(this.dialogButton(label, "Cycle: Anyone / Friends & Followers / Off", 250,
                        pl -> this.cyclePrivacySetting(pl, entry.key(), () -> this.openSettingsDialog(pl, cat.id()))));
                    continue;
                }
                boolean raw = values.getOrDefault(entry.key(), this.defaultSettingValue(entry.key()));
                boolean shown = entry.inverted() != raw;
                Component label = Component.text(entry.label() + ": ", NamedTextColor.WHITE)
                    .append(Component.text(shown ? "ON" : "OFF", shown ? NamedTextColor.GREEN : NamedTextColor.RED));
                buttons.add(this.dialogButton(label, "Click to toggle", 250,
                    pl -> this.togglePlayerSetting(pl, entry.key(), () -> this.openSettingsDialog(pl, cat.id()))));
            }
        }
        Dialog dialog = this.buildDialog(Component.text("Settings", DIALOG_BRAND),
            List.of(), List.of(),
            DialogType.multiAction(buttons)
                .columns(1)
                .exitAction(this.dialogButton(Component.text("Close"), null, 250, null))
                .build());
        player.showDialog(dialog);
    }

    private void openSettingsInventory(Player player, Map<String, Boolean> values, int page) {
        // 9x4 (36 slots), single page using each setting's designed slot (spread across all rows).
        // No page 2 — every setting fits and renders on one screen.
        Inventory inv = Bukkit.createInventory(null, 36, TITLE_SETTINGS);
        for (SettingDefinition def : SETTINGS_DEFINITIONS) {
            if (def.slot < 0 || def.slot >= 36) continue;
            boolean enabled = values.getOrDefault(def.key, def.defaultValue);
            inv.setItem(def.slot, this.buildSettingsItem(player, def, enabled));
        }
        this.settingsPageByPlayer.put(player.getUniqueId(), 1);
        player.openInventory(inv);
    }

    private ItemStack buildSettingsItem(Player player, SettingDefinition def, boolean enabled) {
        ItemStack item = this.named(def.icon, "\u00a7a" + def.label, "settings_toggle:" + def.key);
        ItemMeta meta = item.getItemMeta();
        ArrayList<String> lore = new ArrayList<String>();
        for (String line : def.descriptionLines) {
            lore.add("\u00a77" + line);
        }
        if (def.pizzaPlusOnly && (def.requiredPermission == null || !player.hasPermission(def.requiredPermission))) {
            lore.add("\u00a76" + this.brandTierPlus + " Only");
        }
        if (PRIVACY_TRISTATE.contains(def.key)) {
            String mode = this.getPrivacyMode(player.getUniqueId(), def.key);
            String color = "off".equals(mode) ? "\u00a7c" : "friends".equals(mode) ? "\u00a7e" : "\u00a7a";
            lore.add("\u00a77Currently: " + color + this.privacyModeLabel(mode));
            lore.add("\u00a78Click: Anyone / Friends / Off");
        } else {
            lore.add(enabled ? "\u00a77Currently: \u00a7aOn" : "\u00a77Currently: \u00a7cOff");
        }
        meta.setLore(lore);
        item.setItemMeta(meta);
        return item;
    }

    private SettingDefinition findSettingByKey(String key) {
        for (SettingDefinition def : SETTINGS_DEFINITIONS) {
            if (!def.key.equalsIgnoreCase(key)) continue;
            return def;
        }
        return null;
    }

    // ===================== Tri-state privacy settings =====================
    // These keys are tri-state (Anyone / Friends & Followers / Off), encoded as two booleans:
    // <key> (master on/off) + <key>_friends (restrict to follow relationships). The follows-table
    // per-friend toggle (toggleCol) overrides the global setting for people who follow the target.
    private static final java.util.Set<String> PRIVACY_TRISTATE = java.util.Set.of(
        "payments", "tpa_requests", "tpahere_requests", "private_messages");

    private String privacyToggleColumn(String key) {
        return switch (key) {
            case "payments" -> "can_pay";
            case "tpa_requests", "tpahere_requests" -> "can_tpa";
            case "private_messages" -> "can_message";
            default -> null;
        };
    }

    private String privacyModeFromValues(java.util.Map<String, Boolean> values, String key) {
        boolean master = values.getOrDefault(key, this.defaultSettingValue(key));
        if (!master) return "off";
        return values.getOrDefault(key + "_friends", false) ? "friends" : "anyone";
    }

    private String getPrivacyMode(UUID uuid, String key) {
        java.util.Map<String, Boolean> values = this.playerSettingsCache.get(uuid);
        if (values == null) {
            // Not cached (offline target): master from definition default, modifier off → "anyone"/"off".
            return this.isSettingEnabledCached(uuid, key) ? "anyone" : "off";
        }
        return this.privacyModeFromValues(values, key);
    }

    private String privacyModeLabel(String mode) {
        return switch (mode) {
            case "off" -> "Off";
            case "friends" -> "Friends & Followers";
            default -> "Anyone";
        };
    }

    /** True if {@code sender} may perform the {@code key}-gated action toward {@code target}. */
    private boolean privacyAllows(UUID target, String key, UUID sender) {
        if (target == null || sender == null || target.equals(sender)) return true;
        String col = this.privacyToggleColumn(key);
        try (Connection conn = this.openSyncConnection()) {
            // Per-friend override: if the target follows the sender, that relationship's toggle decides.
            if (col != null) {
                try (PreparedStatement ps = conn.prepareStatement(
                        "SELECT " + col + " FROM follows WHERE follower_uuid=? AND target_uuid=? LIMIT 1")) {
                    ps.setString(1, target.toString());
                    ps.setString(2, sender.toString());
                    try (ResultSet rs = ps.executeQuery()) {
                        if (rs.next()) return rs.getBoolean(1);
                    }
                }
            }
            String mode = this.getPrivacyMode(target, key);
            if ("off".equals(mode)) return false;
            if ("anyone".equals(mode)) return true;
            // Friends & Followers = any follow relationship in either direction.
            return this.isFollowing(conn, target, sender) || this.isFollowing(conn, sender, target);
        } catch (Exception ex) {
            this.getLogger().warning("privacyAllows failed: " + ex.getMessage());
            return true; // fail open
        }
    }

    /** Cycle a tri-state privacy setting: Anyone -> Friends & Followers -> Off -> Anyone. */
    private void cyclePrivacySetting(Player player, String key, Runnable reopen) {
        if (player == null || !player.isOnline() || key == null) return;
        UUID uuid = player.getUniqueId();
        this.runAsyncTask(() -> {
            java.util.Map<String, Boolean> values = this.loadPlayerSettings(uuid);
            boolean master = values.getOrDefault(key, this.defaultSettingValue(key));
            boolean friends = values.getOrDefault(key + "_friends", false);
            if (!master) { master = true; friends = false; }        // off -> anyone
            else if (!friends) { friends = true; }                  // anyone -> friends
            else { master = false; friends = false; }               // friends -> off
            values.put(key, master);
            values.put(key + "_friends", friends);
            this.savePlayerSettings(uuid, values);
            this.playerSettingsCache.put(uuid, values);
            boolean fMaster = master;
            this.runOnPlayerThread(player, () -> {
                this.applySettingSideEffects(player, key, fMaster);
                player.playSound(player.getLocation(), Sound.UI_BUTTON_CLICK, 0.5f, 1.1f);
                if (reopen != null) reopen.run();
                else this.openSettingsInventory(player, values, this.settingsPageByPlayer.getOrDefault(uuid, 1));
            });
        });
    }

    private void togglePlayerSetting(Player player, String key) {
        this.togglePlayerSetting(player, key, null);
    }

    /** Toggles a setting; {@code reopen} overrides the default legacy-inventory refresh (used by the dialog UI). */
    private void togglePlayerSetting(Player player, String key, Runnable reopen) {
        if (player == null || !player.isOnline() || key == null || key.isBlank()) {
            return;
        }
        UUID uuid = player.getUniqueId();
        this.runAsyncTask(() -> {
            Map<String, Boolean> values = this.loadPlayerSettings(uuid);
            boolean next = values.getOrDefault(key, this.defaultSettingValue(key)) == false;
            values.put(key, next);
            this.savePlayerSettings(uuid, values);
            this.playerSettingsCache.put(uuid, values);
            this.runOnPlayerThread(player, () -> {
                this.applySettingSideEffects(player, key, next);
                player.playSound(player.getLocation(), Sound.UI_BUTTON_CLICK, 0.5f, next ? 1.3f : 0.8f);
                if (reopen != null) {
                    reopen.run();
                } else {
                    this.openSettingsInventory(player, values, this.settingsPageByPlayer.getOrDefault(uuid, 1));
                }
            });
        });
    }

    private void loadSettingsIntoCache(Player player) {
        if (player == null) {
            return;
        }
        UUID uuid = player.getUniqueId();
        String username = player.getName();
        this.runAsyncTask(() -> {
            this.ensurePlayerRow(uuid, username);
            Map<String, Boolean> values = this.loadPlayerSettings(uuid);
            this.playerSettingsCache.put(uuid, values);
            this.runOnPlayerThread(player, () -> this.applyInitialSettingSideEffects(player));
        });
    }

    private void ensurePlayerRow(UUID uuid, String username) {
        String sql = "INSERT IGNORE INTO players (uuid, username) VALUES (?, ?)";
        try (Connection conn = this.openSyncConnection();
             PreparedStatement ps = conn.prepareStatement(sql);){
            ps.setString(1, uuid.toString());
            ps.setString(2, username != null ? username : "unknown");
            ps.executeUpdate();
        }
        catch (Exception ex) {
            this.getLogger().warning("Failed ensuring player row: " + ex.getMessage());
        }
    }

    private void applyInitialSettingSideEffects(Player player) {
        if (player == null || !player.isOnline()) {
            return;
        }
        this.applyVisibilityPreference(player);
        this.applyScoreboardPreference(player);
        this.applyMobSpawnPreference(player);
        this.applyNightVisionPreference(player);
    }

    // /nv [player] — flips the SAME "night_vision" setting the /settings GUI uses (one shared state:
    // toggling either place changes both). PAT's old separate NV list was retired for this.
    private void handleNvCommand(Player sender, String[] args) {
        if (!sender.hasPermission("pizzasmp.nv")) {
            sender.sendActionBar(this.legacyColorize("&cYou do not have permission to use /nv."));
            return;
        }
        Player target = sender;
        if (args.length > 0) {
            if (!sender.hasPermission("pizzasmp.nv.others")) {
                sender.sendActionBar(this.legacyColorize("&cYou do not have permission to toggle night vision for others."));
                return;
            }
            target = Bukkit.getPlayerExact(args[0]);
            if (target == null) {
                sender.sendActionBar(this.legacyColorize("&cPlayer not found: " + args[0]));
                return;
            }
        }
        final Player ft = target;
        this.togglePlayerSetting(ft, "night_vision", () -> {
            boolean on = this.isSettingEnabledCached(ft.getUniqueId(), "night_vision");
            ft.sendActionBar(this.legacyColorize(on ? "&7Night vision &#00BFFFenabled" : "&7Night vision &fdisabled"));
            if (!ft.equals(sender)) {
                sender.sendActionBar(this.legacyColorize("&7Night vision for &f" + ft.getName() + " &7is now " + (on ? "&#00BFFFon" : "&foff")));
            }
        });
    }

    /** Applies/removes the infinite night-vision effect per the "night_vision" setting (/settings alternative to /nv). */
    private void applyNightVisionPreference(Player player) {
        if (player == null || !player.isOnline()) {
            return;
        }
        if (this.isSettingEnabledCached(player.getUniqueId(), "night_vision")) {
            player.addPotionEffect(new org.bukkit.potion.PotionEffect(PotionEffectType.NIGHT_VISION, org.bukkit.potion.PotionEffect.INFINITE_DURATION, 0, false, false));
        } else {
            player.removePotionEffect(PotionEffectType.NIGHT_VISION);
        }
    }

    // Settings night vision is persistent: re-apply after milk (clears effects) and totem pops.
    @EventHandler(ignoreCancelled = true)
    public void onMilkNightVision(org.bukkit.event.player.PlayerItemConsumeEvent e) {
        if (e.getItem() != null && e.getItem().getType() == Material.MILK_BUCKET) {
            Player p = e.getPlayer();
            this.runPlayerTaskLater(p, () -> this.applyNightVisionPreference(p), 2L);
        }
    }

    @EventHandler(ignoreCancelled = true)
    public void onTotemNightVision(org.bukkit.event.entity.EntityResurrectEvent e) {
        if (e.getEntity() instanceof Player p) {
            this.runPlayerTaskLater(p, () -> this.applyNightVisionPreference(p), 2L);
        }
    }

    private void applySettingSideEffects(Player player, String key, boolean enabled) {
        if (player == null || !player.isOnline()) {
            return;
        }
        switch (key) {
            case "player_visibility": {
                this.applyVisibilityPreference(player);
                break;
            }
            case "scoreboard_toggle": {
                this.applyScoreboardPreference(player);
                break;
            }
            case "disable_mob_spawns": {
                this.applyMobSpawnPreference(player);
                break;
            }
            case "night_vision": {
                this.applyNightVisionPreference(player);
                break;
            }
            case "team_chat": {
                if (enabled) break;
                this.setTeamChatMode(player.getUniqueId(), false);
                break;
            }
            case "staff_mode_bypass": {
                // Drives the LuckPerms node PizzaAdminTools reads: ON = dev exempt from /sfmode hider,
                // OFF = dev is subject to opt-in staff mode like everyone (fair-play self-test).
                final String cmd = "lp user " + player.getName() + " permission set pizzasmp.sfmode.bypass " + enabled;
                Bukkit.getScheduler().runTask((Plugin)this, () -> Bukkit.dispatchCommand(Bukkit.getConsoleSender(), cmd));
                player.sendActionBar(this.legacyColorize(enabled
                    ? "&7Staff mode bypass &#00BFFFON&7 — your staff functions are always available."
                    : "&7Staff mode bypass &fOFF&7 — you're now subject to /sfmode. Relog to apply fully."));
                break;
            }
        }
    }

    private void applyVisibilityPreference(Player player) {
        if (player == null || !player.isOnline()) {
            return;
        }
        if (!this.isServer("lobby") && !this.isServer("maintenance")) {
            return;
        }
        boolean showPlayers = this.isSettingEnabledCached(player.getUniqueId(), "player_visibility");
        for (Player other : Bukkit.getOnlinePlayers()) {
            boolean staff;
            if (other.getUniqueId().equals(player.getUniqueId())) continue;
            boolean bl = staff = other.hasPermission("pizzasmp.staff.punish") || other.hasPermission("pizzasmp.staff.gtp") || other.isOp();
            if (showPlayers || staff) {
                player.showPlayer((Plugin)this, other);
                continue;
            }
            player.hidePlayer((Plugin)this, other);
        }
    }

    private void refreshVisibilityForAll() {
        if (!this.isServer("lobby") && !this.isServer("maintenance")) {
            return;
        }
        for (Player viewer : Bukkit.getOnlinePlayers()) {
            this.applyVisibilityPreference(viewer);
        }
    }

    private void applyScoreboardPreference(Player player) {
        if (player == null || !player.isOnline()) {
            return;
        }
        UUID uuid = player.getUniqueId();
        if (!this.isSidebarHudEnabled() || !this.isSettingEnabledCached(uuid, "scoreboard_toggle")) {
            this.cancelSidebarTask(uuid);
            player.setScoreboard(Bukkit.getScoreboardManager().getMainScoreboard());
            return;
        }
        this.refreshSidebarSoon(player);
    }

    private void cancelSidebarTask(UUID uuid) {
        TaskHandle existing = this.sidebarTasks.remove(uuid);
        if (existing != null) {
            existing.cancel();
        }
    }

    private void refreshSidebar(Player player) {
        if (player == null || !player.isOnline()) {
            return;
        }
        if (!this.isSidebarHudEnabled()) {
            this.cancelSidebarTask(player.getUniqueId());
            player.setScoreboard(Bukkit.getScoreboardManager().getMainScoreboard());
            return;
        }
        UUID uuid = player.getUniqueId();
        this.cancelSidebarTask(uuid);
        this.runAsyncTask(() -> {
            StatsSnapshot stats = this.loadStatsSnapshot(uuid);
            String team = this.loadTeamName(uuid);
            String server = this.serverHudLabel();
            this.runOnPlayerThread(player, () -> {
                if (!player.isOnline() || !this.isSettingEnabledCached(uuid, "scoreboard_toggle")) {
                    player.setScoreboard(Bukkit.getScoreboardManager().getMainScoreboard());
                    this.cancelSidebarTask(uuid);
                    return;
                }
                this.renderSidebar(player, new HudSnapshot(this.mergeLiveHudStats(player, stats), team, server));
                this.sidebarTasks.put(uuid, this.runPlayerTaskLater(player, () -> this.refreshSidebar(player), 20L));
            });
        });
    }

    private void renderSidebar(Player player, HudSnapshot hud) {
        if (player == null || hud == null) {
            return;
        }
        Scoreboard board = Bukkit.getScoreboardManager().getNewScoreboard();
        Objective objective = board.registerNewObjective("pizzahud", "dummy", this.hudTitleText());
        objective.setDisplaySlot(DisplaySlot.SIDEBAR);
        // Hide the score numbers on the right side of every line
        objective.numberFormat(io.papermc.paper.scoreboard.numbers.NumberFormat.blank());
        int score = 15;
        UUID hudUuid = player.getUniqueId();
        objective.getScore(this.blankLineToken(1)).setScore(score--);
        if (this.isSettingEnabledCached(hudUuid, "show_money")) {
            objective.getScore("\u00a7a\u00a7l$ \u00a7fMoney \u00a7a" + this.formatMillions(hud.stats.money)).setScore(score--);
        }
        if (this.isSettingEnabledCached(hudUuid, "show_shards")) {
            objective.getScore("\u00a75" + this.hudGlyph("\u25c6", "[S]") + " \u00a7fShards \u00a75" + this.formatCompactNumber(hud.stats.shards)).setScore(score--);
        }
        if (this.isSettingEnabledCached(hudUuid, "show_kills")) {
            objective.getScore("\u00a7c" + this.hudGlyph("\u2694", "[K]") + " \u00a7fKills \u00a7c" + this.formatCompactNumber(hud.stats.kills)).setScore(score--);
        }
        if (this.isSettingEnabledCached(hudUuid, "show_deaths")) {
            objective.getScore("\u00a76" + this.hudGlyph("\u2620", "[D]") + " \u00a7fDeaths \u00a76" + this.formatCompactNumber(hud.stats.deaths)).setScore(score--);
        }
        if (this.isSettingEnabledCached(hudUuid, "show_playtime")) {
            objective.getScore("\u00a7e" + this.hudGlyph("\u231a", "[T]") + " \u00a7fPlaytime \u00a7e" + this.formatPlaytimeDaysHours(hud.stats.playtimeSeconds)).setScore(score--);
        }
        if (!TEAMS_DISABLED && !"NONE".equalsIgnoreCase(hud.teamName)) {
            objective.getScore("\u00a7x\u00a70\u00a70\u00a7B\u00a7F\u00a7F\u00a7F" + this.hudGlyph("\u2692", "[AXE]") + " \u00a7x\u00a70\u00a70\u00a7B\u00a7F\u00a7F\u00a7F(" + hud.teamName + ")").setScore(score--);
        }
        objective.getScore(this.blankLineToken(2)).setScore(score--);
        this.setSidebarSplitLine(board, objective, "hudregion", "\u00a71\u00a7r", score, "\u00a77NA East ", "\u00a77(" + this.brandSectionHex("primary") + Math.max(0, player.getPing()) + "ms\u00a77)");
        player.setScoreboard(board);
    }

    private void setSidebarSplitLine(Scoreboard board, Objective objective, String teamName, String entry, int score, String prefix, String suffix) {
        Team team = board.getTeam(teamName);
        if (team == null) {
            team = board.registerNewTeam(teamName);
        }
        team.setPrefix(prefix);
        team.setSuffix(suffix);
        if (!team.hasEntry(entry)) {
            team.addEntry(entry);
        }
        objective.getScore(entry).setScore(score);
    }

    private String hudTitleText() {
        // Scoreboard sidebar title: the brand display name, bold, each glyph in the primary colour.
        String prefix = this.brandSectionHex("primary") + "\u00a7l";
        StringBuilder sb = new StringBuilder();
        for (char c : this.brandDisplay.toCharArray()) {
            if (c == ' ') { sb.append(' '); continue; }
            sb.append(prefix).append(c);
        }
        return sb.toString();
    }

    private String blankLineToken(int idx) {
        // Each blank line needs a unique entry (scoreboard collapses duplicates).
        // Use a single color code per line \u2014 invisible, takes one scoreboard row, no extra width.
        char[] codes = "0123456789abcdef".toCharArray();
        return "\u00a7" + codes[idx % codes.length];
    }

    private String hudGlyph(String preferred, String fallback) {
        if (this.isAsciiHudIconsEnabled()) {
            return fallback;
        }
        if (preferred == null || preferred.isBlank()) {
            return fallback;
        }
        int cp = preferred.codePointAt(0);
        if (!Character.isDefined(cp) || Character.isISOControl(cp)) {
            return fallback;
        }
        return preferred;
    }

    private boolean isAsciiHudIconsEnabled() {
        return this.settings.getBoolean("hud.force_ascii_icons", false) || this.settings.getBoolean("use_ascii_icons", false);
    }

    private boolean isSidebarHudEnabled() {
        return this.settings.getBoolean("hud.sidebar_enabled", false);
    }

    private boolean isChatInterceptionEnabled() {
        return this.settings.getBoolean("chat.intercept_async_chat", false) && this.settings.getBoolean("chat.global_chat_enabled", false);
    }

    /*
     * Enabled aggressive block sorting
     * Enabled unnecessary exception pruning
     * Enabled aggressive exception aggregation
     */
    private String loadTeamName(UUID uuid) {
        if (uuid == null) {
            return "NONE";
        }
        String sql = "SELECT t.team_name FROM team_members tm JOIN teams t ON tm.team_id=t.id WHERE tm.member_uuid=? LIMIT 1";
        try (Connection conn = this.openSyncConnection();
             PreparedStatement ps = conn.prepareStatement(sql);){
            ps.setString(1, uuid.toString());
            try (ResultSet rs = ps.executeQuery();){
                if (!rs.next()) return "NONE";
                String name = rs.getString(1);
                if (name == null) return "NONE";
                if (name.isBlank()) return "NONE";
                String string = name;
                return string;
            }
        }
        catch (Exception exception) {
            // empty catch block
        }
        return "NONE";
    }

    private String serverHudLabel() {
        return switch (this.detectServerName().toLowerCase(Locale.ROOT)) {
            case "lobby" -> "LOBBY";
            case "survival", "main" -> "SURVIVAL";
            case "pvp", "duels" -> "DUELS";
            case "maintenance" -> "MAINTENANCE";
            default -> this.detectServerName().toUpperCase(Locale.ROOT);
        };
    }

    private void applyMobSpawnPreference(Player player) {
        // no-op: mob spawn suppression is handled per-spawn in onCreatureSpawn
    }

    private void openShopMain(Player player) {
        if (player == null || !player.isOnline()) {
            return;
        }
        this.runOnPlayerThread(player, () -> {
            if (!player.isOnline()) {
                return;
            }
            // 9x3: middle row has 5 category icons centered, no glass fillers
            Inventory inv = Bukkit.createInventory(null, 27, TITLE_SHOP);
            inv.setItem(11, this.buildMainShopCategoryItem(Material.END_STONE,       "End",    "shop_main_open:end"));
            inv.setItem(12, this.buildMainShopCategoryItem(Material.NETHERRACK,      "Nether", "shop_main_open:nether"));
            inv.setItem(13, this.buildMainShopCategoryItem(Material.TOTEM_OF_UNDYING,"Gear",   "shop_main_open:gear"));
            inv.setItem(14, this.buildMainShopCategoryItem(Material.COOKED_BEEF,     "Food",   "shop_main_open:food"));
            inv.setItem(15, this.buildMainShopCategoryItem(Material.AMETHYST_SHARD,  "Shards", "shop_main_open:shards"));
            player.openInventory(inv);
        });
    }

    private ItemStack buildMainShopCategoryItem(Material icon, String label, String id) {
        return this.namedWithLore(icon, "\u00a7a" + label, id, List.of("\u00a77Click to browse"));
    }

    // Category menu: Row0=glass, Row1=9 items (click→confirm), Row2=back+glass
    private void openShopCategoryMenu(Player player, String categoryKey) {
        List<ShopEntry> entries = this.shopEntries(categoryKey);
        if (entries.isEmpty()) {
            this.openShopMain(player);
            return;
        }
        Inventory inv = Bukkit.createInventory(null, 27, this.categoryTitle(categoryKey));
        for (int i = 0; i < entries.size() && i < 9; ++i) {
            inv.setItem(9 + i, this.buildCategorySelectItem(categoryKey, entries.get(i)));
        }
        String backAction = "gear2".equals(categoryKey) ? "shop_main_open:gear" : "shop_open_main";
        inv.setItem(18, this.namedWithLore(Material.RED_STAINED_GLASS_PANE, "\u00a7c\u00a7l\u00ab Back", backAction, List.of()));
        if ("gear".equals(categoryKey)) {
            inv.setItem(26, this.namedWithLore(Material.ARROW, "\u00a7a\u00a7lPage 2 \u00bb", "shop_main_open:gear2", List.of("\u00a77Tools, fireworks & amethyst")));
        }
        this.runOnPlayerThread(player, () -> player.openInventory(inv));
    }

    private ItemStack buildCategorySelectItem(String categoryKey, ShopEntry entry) {
        Material displayMaterial = entry.material;
        String displayName = "\u00a7f" + entry.label;
        if (entry.key.startsWith("amethyst_")) {
            displayMaterial = switch(entry.key) {
                case "amethyst_drill" -> Material.NETHERITE_PICKAXE;
                case "amethyst_multitool" -> Material.NETHERITE_SHOVEL;
                case "amethyst_sellaxe", "amethyst_treechopper" -> Material.NETHERITE_AXE;
                default -> entry.material;
            };
            displayName = "\u00a7d" + entry.label;
        }
        ItemStack item = new ItemStack(displayMaterial);
        if (entry.material == Material.TIPPED_ARROW) {
            ItemMeta m2 = item.getItemMeta();
            if (m2 instanceof PotionMeta pm) {
                pm.setBasePotionType(PotionType.SLOW_FALLING);
                item.setItemMeta(m2);
            }
        }
        ItemMeta meta = item.getItemMeta();
        meta.setDisplayName(displayName);
        ArrayList<String> lore = new ArrayList<>();
        if (entry.unitAmount > 1) {
            lore.add("\u00a7a$" + this.fmtMoney(entry.priceMoney) + " \u00a78\u00d7" + entry.unitAmount);
        } else {
            lore.add("\u00a7a$" + this.fmtMoney(entry.priceMoney));
        }
        if (entry.key.startsWith("amethyst_")) {
            lore.add("");
            lore.addAll(this.getAmethystToolLore(entry.key));
        } else if (entry.key.endsWith("_sword") || entry.key.endsWith("_pickaxe") || entry.key.endsWith("_axe")) {
            lore.add("");
            lore.addAll(this.getToolEnchantmentsLore(entry.key));
        }
        if (this.uiActionKey != null) {
            meta.getPersistentDataContainer().set(this.uiActionKey, PersistentDataType.STRING, "shop_select:" + categoryKey + ":" + entry.key);
        }
        meta.setLore(lore);
        item.setItemMeta(meta);
        return item;
    }

    private ArrayList<String> getAmethystToolLore(String toolKey) {
        ArrayList<String> lore = new ArrayList<>();
        lore.add("§7Enchantments:");
        switch (toolKey) {
            case "amethyst_drill":
                lore.add("§7• Silk Touch");
                lore.add("§7• Efficiency V");
                lore.add("§7• Unbreaking III");
                lore.add("§7• Mending");
                lore.add("§7Breaks 9 Blocks at Once");
                break;
            case "amethyst_multitool":
                lore.add("§7• Efficiency V");
                lore.add("§7• Unbreaking III");
                lore.add("§7• Mending");
                break;
            case "amethyst_sellaxe":
                lore.add("§7• Efficiency V");
                lore.add("§7• Unbreaking III");
                lore.add("§7• Mending");
                lore.add("§7Instantly Sells All Items in A Chest");
                break;
            case "amethyst_treechopper":
                lore.add("§7• Efficiency V");
                lore.add("§7• Unbreaking III");
                lore.add("§7• Mending");
                lore.add("§7Break Trees Instantly");
                break;
        }
        lore.add("");
        lore.add("§cTimer: §f3 days");
        lore.add("§7Timer starts when you first equip it");
        return lore;
    }

    // ---- TPS-reactive view distance throttle ----
    private void tickVdThrottle() {
        double[] tps = Bukkit.getTPS();
        double tps1m = tps.length > 0 ? tps[0] : 20.0;
        long now = System.currentTimeMillis();
        int oldVd = this.currentThrottledVd;

        if (tps1m < TPS_DROP_THRESHOLD && this.currentThrottledVd > VD_MIN) {
            this.currentThrottledVd--;
            this.lastVdRecoveryCheck = 0L;
            this.applyServerVd(this.currentThrottledVd);
            for (Player p : Bukkit.getOnlinePlayers()) {
                p.sendActionBar(Component.text("§7View distance temporarily throttled to §f" + this.currentThrottledVd + " §7chunks"));
            }
            this.getLogger().info("[VDThrottle] TPS=" + String.format("%.1f", tps1m) + " → VD reduced to " + this.currentThrottledVd);
        } else if (tps1m >= TPS_RECOVER_THRESHOLD && this.currentThrottledVd < VD_MAX) {
            if (this.lastVdRecoveryCheck == 0L) {
                this.lastVdRecoveryCheck = now;
            } else if (now - this.lastVdRecoveryCheck >= VD_RECOVER_DELAY_MS) {
                this.currentThrottledVd++;
                this.lastVdRecoveryCheck = 0L;
                this.applyServerVd(this.currentThrottledVd);
                if (this.currentThrottledVd < VD_MAX) {
                    for (Player p : Bukkit.getOnlinePlayers()) {
                        p.sendActionBar(Component.text("§7View distance recovering — §f" + this.currentThrottledVd + " §7chunks"));
                    }
                }
                this.getLogger().info("[VDThrottle] TPS=" + String.format("%.1f", tps1m) + " → VD increased to " + this.currentThrottledVd);
            }
        } else {
            this.lastVdRecoveryCheck = 0L;
        }
        this.applyPerPlayerVdSweep();
        // Crystal igniter entries are only needed for the tick the crystal explodes; clear stale ones.
        if (this.explosionIgniters.size() > 200) {
            this.explosionIgniters.clear();
        }
    }

    // /vdthrottle — admin view/control of the view-distance throttle.
    private void handleVdThrottleCommand(Player admin, String[] args) {
        double[] tps = Bukkit.getTPS();
        double tps1m = tps.length > 0 ? tps[0] : 20.0;
        int online = Bukkit.getOnlinePlayers().size();
        if (args.length == 0) {
            // Status overview
            admin.sendMessage("§e§l⚙ VD Throttle Status");
            admin.sendMessage("§7TPS (1m): §f" + String.format("%.1f", tps1m));
            admin.sendMessage("§7Players online: §f" + online);
            admin.sendMessage("§7Server VD (throttled): §f" + this.currentThrottledVd + " §7(range " + VD_MIN + "-" + VD_MAX + ")");
            admin.sendMessage("§7Per-player VD: §f" + (PER_PLAYER_VD_ENABLED ? "§aenabled" : "§cdisabled"));
            admin.sendMessage("§7Your VD: §f" + admin.getViewDistance());
            admin.sendMessage("§7Usage: §f/vdthrottle <player|set|reset>");
            return;
        }
        String sub = args[0].toLowerCase(Locale.ROOT);
        switch (sub) {
            case "set" -> {
                // /vdthrottle set <n> [player]
                if (args.length < 2) { admin.sendMessage("§cUsage: /vdthrottle set <2-32> [player]"); return; }
                int vd;
                try { vd = Math.max(2, Math.min(32, Integer.parseInt(args[1]))); }
                catch (NumberFormatException e) { admin.sendMessage("§cInvalid number."); return; }
                if (args.length >= 3) {
                    Player target = Bukkit.getPlayerExact(args[2]);
                    if (target == null) { admin.sendMessage("§cPlayer not found: " + args[2]); return; }
                    target.setViewDistance(vd);
                    this.vdThrottleOverrides.put(target.getUniqueId(), vd);
                    admin.sendMessage("§aSet §f" + target.getName() + "§a's view distance to §f" + vd + "§a (override).");
                } else {
                    this.currentThrottledVd = Math.max(VD_MIN, Math.min(VD_MAX, vd));
                    this.applyServerVd(vd);
                    admin.sendMessage("§aServer view distance forced to §f" + vd + "§a.");
                }
            }
            case "reset" -> {
                // /vdthrottle reset [player]
                if (args.length >= 2) {
                    Player target = Bukkit.getPlayerExact(args[1]);
                    if (target == null) { admin.sendMessage("§cPlayer not found: " + args[1]); return; }
                    this.vdThrottleOverrides.remove(target.getUniqueId());
                    target.setViewDistance(this.calcPerPlayerVd(target, tps1m, online));
                    admin.sendMessage("§aReset §f" + target.getName() + "§a's view distance to auto.");
                } else {
                    this.currentThrottledVd = VD_MAX;
                    this.applyServerVd(VD_MAX);
                    admin.sendMessage("§aView distance reset to §f" + VD_MAX + "§a; auto-throttle resumes.");
                }
            }
            default -> {
                // Treat as a player name — show that player's current VD.
                Player target = Bukkit.getPlayerExact(args[0]);
                if (target == null) { admin.sendMessage("§cPlayer not found: " + args[0]); return; }
                int calc = this.calcPerPlayerVd(target, tps1m, online);
                boolean overridden = this.vdThrottleOverrides.containsKey(target.getUniqueId());
                admin.sendMessage("§e" + target.getName() + "§7's view distance: §f" + target.getViewDistance()
                    + " §7(calculated: §f" + calc + "§7, priority §f" + this.getQueuePriority(target) + "§7"
                    + (overridden ? "§7, §coverridden" : "") + "§7)");
            }
        }
    }

    private void applyServerVd(int vd) {
        for (org.bukkit.World w : Bukkit.getWorlds()) {
            w.setViewDistance(vd);
        }
    }

    // ---- Queue system ----
    // Players joining above capacity threshold enter spectator in void, frozen, no commands, no chat.
    // Released FIFO-by-priority with staggered delay (1 player per 3-5s) to smooth load.
    // Controlled by config: queue.enabled (default false), queue.capacity_threshold (default 45),
    // queue.admit_interval_ticks (default 60 = 3s)

    private final java.util.concurrent.ConcurrentLinkedDeque<QueuedPlayer> joinQueue = new java.util.concurrent.ConcurrentLinkedDeque<>();
    private final Set<UUID> queuedPlayers = ConcurrentHashMap.newKeySet();
    private final Map<UUID, Location> queueReturnLocations = new ConcurrentHashMap<>();
    private final Map<UUID, GameMode> queueReturnGamemodes = new ConcurrentHashMap<>();
    private static final Location VOID_LOCATION = new Location(null, 0, -64, 0);

    private static final class QueuedPlayer implements Comparable<QueuedPlayer> {
        final UUID uuid;
        final int priority;
        final long joinedAt;
        QueuedPlayer(UUID uuid, int priority) { this.uuid = uuid; this.priority = priority; this.joinedAt = System.currentTimeMillis(); }
        @Override public int compareTo(QueuedPlayer o) { int c = Integer.compare(this.priority, o.priority); return c != 0 ? c : Long.compare(this.joinedAt, o.joinedAt); }
    }

    private boolean isQueueEnabled() {
        return this.settings.getBoolean("queue.enabled", true);
    }

    private int getQueueCapacityThreshold() {
        return this.settings.getInt("queue.capacity_threshold", 45);
    }

    private int getQueueAdmitIntervalTicks() {
        return this.settings.getInt("queue.admit_interval_ticks", 60);
    }

    int getQueuePriority(Player p) {
        if (p.hasPermission("group.dev")) return 1;
        if (p.hasPermission("group.owner")) return 2;
        if (p.hasPermission("group.sradmin")) return 3;
        if (p.hasPermission("group.co-owner")) return 4;
        if (p.hasPermission("group.admin")) return 5;
        if (p.hasPermission("group.srmod")) return 6;
        if (p.hasPermission("group.mod")) return 7;
        if (this.isPizzaPlusPlus(p)) return 8;
        if (p.hasPermission("group.pizza+") || p.hasPermission("group.pizzaplus")) return 9;
        return 10;
    }

    private boolean shouldQueue(Player p) {
        if (!this.isQueueEnabled()) return false;
        int online = (int) Bukkit.getOnlinePlayers().stream().filter(pl -> !this.queuedPlayers.contains(pl.getUniqueId())).count();
        return online >= this.getQueueCapacityThreshold();
    }

    void enqueuePlayer(Player p) {
        UUID uuid = p.getUniqueId();
        this.queueReturnLocations.put(uuid, p.getLocation().clone());
        this.queueReturnGamemodes.put(uuid, p.getGameMode());
        this.queuedPlayers.add(uuid);
        QueuedPlayer qp = new QueuedPlayer(uuid, this.getQueuePriority(p));
        this.joinQueue.add(qp);
        this.resortQueue();
        p.setGameMode(GameMode.SPECTATOR);
        org.bukkit.World endWorld = Bukkit.getWorld("world_the_end");
        if (endWorld == null) endWorld = Bukkit.getWorlds().getFirst();
        p.teleport(new Location(endWorld, 0, 320, 0));
        p.setAllowFlight(true);
        p.setFlying(true);
        this.tickQueueDisplay(uuid);
    }

    private void resortQueue() {
        java.util.List<QueuedPlayer> sorted = new java.util.ArrayList<>(this.joinQueue);
        java.util.Collections.sort(sorted);
        this.joinQueue.clear();
        this.joinQueue.addAll(sorted);
    }

    private void admitNextPlayer() {
        if (this.joinQueue.isEmpty()) return;
        QueuedPlayer next = this.joinQueue.peek();
        if (next == null) return;
        // Test-hold: /queuetest keeps the player in the queue for a fixed window.
        Long holdUntil = this.queueTestHoldUntil.get(next.uuid);
        if (holdUntil != null && System.currentTimeMillis() < holdUntil) return;
        double[] tps = Bukkit.getTPS();
        double tps1m = tps.length > 0 ? tps[0] : 20.0;
        // Hold if TPS is struggling — wait for a better moment
        if (tps1m < 17.0) return;
        // Slower admission under moderate load
        int activeCount = (int) Bukkit.getOnlinePlayers().stream().filter(pl -> !this.queuedPlayers.contains(pl.getUniqueId())).count();
        if (tps1m < 19.0 && activeCount >= this.getQueueCapacityThreshold()) return;
        this.joinQueue.poll();
        Player p = Bukkit.getPlayer(next.uuid);
        this.queuedPlayers.remove(next.uuid);
        this.queueTestHoldUntil.remove(next.uuid);
        if (p == null || !p.isOnline()) return;
        Location returnLoc = this.queueReturnLocations.remove(next.uuid);
        GameMode returnGm = this.queueReturnGamemodes.remove(next.uuid);
        if (returnLoc != null) p.teleport(returnLoc);
        p.setGameMode(returnGm != null ? returnGm : GameMode.SURVIVAL);
        // No "admitted" hotbar message — clear any lingering title and just let them in.
        p.resetTitle();
        this.resortQueue();
    }

    private void tickQueueDisplay(UUID uuid) {
        if (!this.queuedPlayers.contains(uuid)) return;
        Player p = Bukkit.getPlayer(uuid);
        if (p == null || !p.isOnline()) {
            this.queuedPlayers.remove(uuid);
            this.joinQueue.removeIf(q -> q.uuid.equals(uuid));
            this.queueReturnLocations.remove(uuid);
            this.queueReturnGamemodes.remove(uuid);
            return;
        }
        int pos = 1;
        for (QueuedPlayer qp : this.joinQueue) {
            if (qp.uuid.equals(uuid)) break;
            pos++;
        }
        int admitInterval = Math.max(1, this.getQueueAdmitIntervalTicks()) * 50;
        int etaSeconds = (pos * admitInterval) / 1000;
        String etaStr = etaSeconds >= 60 ? (etaSeconds / 60) + "m " + (etaSeconds % 60) + "s" : etaSeconds + "s";
        p.sendTitle("§7Position in queue §f#" + pos, "§7ETA: §f" + etaStr, 0, 40, 10);
        // Keep player frozen in end void
        org.bukkit.World endWorld = Bukkit.getWorld("world_the_end");
        if (endWorld == null) endWorld = Bukkit.getWorlds().getFirst();
        if (p.getLocation().getY() < 310 || !p.getWorld().equals(endWorld)) p.teleport(new Location(endWorld, 0, 320, 0));
        this.runPlayerTaskLater(p, () -> this.tickQueueDisplay(uuid), 20L);
    }

    @EventHandler(priority=EventPriority.LOWEST)
    public void onQueuedPlayerChat(AsyncChatEvent e) {
        if (this.queuedPlayers.contains(e.getPlayer().getUniqueId())) {
            e.setCancelled(true);
        }
    }

    @EventHandler(priority=EventPriority.LOWEST)
    public void onQueuedPlayerMove(PlayerMoveEvent e) {
        if (this.queuedPlayers.contains(e.getPlayer().getUniqueId())) {
            if (e.getTo() != null && (e.getFrom().getX() != e.getTo().getX() || e.getFrom().getZ() != e.getTo().getZ())) {
                e.setTo(e.getFrom());
            }
        }
    }

    // ---- Per-player VD throttle (beta, not applied yet) ----
    // Calculates ideal VD per player based on: player count, TPS, priority.
    // Higher-priority players (staff/pizza+) get +1-2 VD over default players.
    // When enabled, calls Player#setViewDistance(int) per-player.
    private static final boolean PER_PLAYER_VD_ENABLED = true;

    int calcPerPlayerVd(Player p, double tps, int onlineCount) {
        int baseVd;
        if (onlineCount <= 10) baseVd = 12; // low pop: full server view distance (no fog wall)
        else if (onlineCount <= 15) baseVd = 10;
        else if (onlineCount <= 25) baseVd = 9;
        else if (onlineCount <= 35) baseVd = 8;
        else if (onlineCount <= 45) baseVd = 7;
        else baseVd = 6;
        if (tps < 18.0) baseVd = Math.max(VD_MIN, baseVd - 1);
        int priority = this.getQueuePriority(p);
        int bonus = priority <= 3 ? 2 : priority <= 7 ? 1 : 0;
        return Math.min(VD_MAX, Math.max(VD_MIN, baseVd + bonus));
    }

    // ---- Command throttle under high load ----
    // When TPS < 17, expensive GUI commands (shop, orders, ah, worth, baltop, bounty list, stats)
    // are rate-limited: 1 per player per 5s. Cheap commands (pay, sell, ping, home) always allowed.
    // Commands throttled under heavy load (TPS < 16). /shop has priority — only throttled under extreme load (TPS < 14).
    private static final Set<String> THROTTLED_HEAVY = Set.of("ah", "orders", "worth", "baltop", "bounty", "stats", "sellmulti");
    private static final Set<String> THROTTLED_EXTREME = Set.of("shop");
    private final Map<UUID, Long> lastThrottledCommandTime = new ConcurrentHashMap<>();

    boolean isCommandThrottled(Player p, String cmd) {
        double[] tps = Bukkit.getTPS();
        double tps1m = tps.length > 0 ? tps[0] : 20.0;
        String base = cmd.toLowerCase(Locale.ROOT).split("\\s+")[0].replace("/", "");
        boolean isHeavy = THROTTLED_HEAVY.contains(base);
        boolean isExtreme = THROTTLED_EXTREME.contains(base);
        if (!isHeavy && !isExtreme) return false;
        // /shop only throttled under extreme load
        if (isExtreme && tps1m >= 14.0) return false;
        if (isHeavy && tps1m >= 17.0) return false;
        long now = System.currentTimeMillis();
        Long last = this.lastThrottledCommandTime.get(p.getUniqueId());
        if (last != null && now - last < 5000L) {
            long remaining = (5000L - (now - last)) / 1000L + 1;
            p.sendActionBar(Component.text("§7Commands temporarily throttled — try again in §f" + remaining + "s"));
            return true;
        }
        this.lastThrottledCommandTime.put(p.getUniqueId(), now);
        return false;
    }

    private void applyPerPlayerVdSweep() {
        if (!PER_PLAYER_VD_ENABLED) return;
        double[] tps = Bukkit.getTPS();
        double tps1m = tps.length > 0 ? tps[0] : 20.0;
        int online = Bukkit.getOnlinePlayers().size();
        for (Player p : Bukkit.getOnlinePlayers()) {
            if (this.queuedPlayers.contains(p.getUniqueId())) continue;
            if (this.vdThrottleOverrides.containsKey(p.getUniqueId())) continue; // admin override
            int vd = this.calcPerPlayerVd(p, tps1m, online);
            p.setViewDistance(vd);
        }
    }

    private static String amethystDisplayName(String kind) {
        return switch (kind) {
            case "drill" -> "Amethyst Pickaxe";
            case "multitool" -> "Amethyst Shovel";
            case "sellaxe" -> "Amethyst Sell-Axe";
            case "treechopper" -> "Amethyst Axe";
            default -> "Amethyst Tool";
        };
    }

    private String formatRemainingMs(long ms) {
        if (ms <= 0) return "expired";
        long s = ms / 1000;
        long d = s / 86400; s %= 86400;
        long h = s / 3600;  s %= 3600;
        long m = s / 60;
        if (d > 0) return d + "d " + h + "h " + m + "m";
        if (h > 0) return h + "h " + m + "m";
        return m + "m";
    }

    private void applyAmethystLore(ItemStack stack, String kind, long expireAt) {
        if (stack == null || !stack.hasItemMeta()) return;
        ItemMeta meta = stack.getItemMeta();
        if (meta == null) return;
        ArrayList<String> lore = meta.hasLore() ? new ArrayList<>(meta.getLore()) : new ArrayList<>();
        // Strip prior timer lines (we always rewrite).
        lore.removeIf(s -> s != null && (s.contains("Timer:") || s.contains("disappear")
                                       || s.contains("Expires in:") || s.contains("Not yet armed")));
        if (expireAt <= 0L) {
            lore.add("§cTimer: §fnot armed");
            lore.add("§7Equip to start the 3-day timer");
        } else {
            long remaining = expireAt - System.currentTimeMillis();
            lore.add("§cExpires in: §f" + formatRemainingMs(remaining));
        }
        meta.setLore(lore);
        stack.setItemMeta(meta);
    }

    private boolean isAmethystToolStack(ItemStack stack) {
        if (stack == null || !stack.hasItemMeta()) return false;
        ItemMeta meta = stack.getItemMeta();
        if (meta == null) return false;
        return meta.getPersistentDataContainer().has(this.amethystKindKey, PersistentDataType.STRING);
    }

    @EventHandler
    public void onAmethystHeld(org.bukkit.event.player.PlayerItemHeldEvent e) {
        Player p = e.getPlayer();
        ItemStack stack = p.getInventory().getItem(e.getNewSlot());
        if (!isAmethystToolStack(stack)) return;
        ItemMeta meta = stack.getItemMeta();
        org.bukkit.persistence.PersistentDataContainer pdc = meta.getPersistentDataContainer();
        String kind = pdc.get(this.amethystKindKey, PersistentDataType.STRING);
        Long expire = pdc.get(this.amethystExpireKey, PersistentDataType.LONG);
        if (expire == null || expire <= 0L) {
            // First equip: arm the 3-day timer.
            long expireAt = System.currentTimeMillis() + AMETHYST_LIFETIME_MS;
            pdc.set(this.amethystExpireKey, PersistentDataType.LONG, expireAt);
            stack.setItemMeta(meta);
            applyAmethystLore(stack, kind, expireAt);
            p.sendActionBar((Component)Component.text("§dAmethyst " + amethystDisplayName(kind) + " armed (3 days)"));
        } else {
            // Refresh hover countdown text.
            applyAmethystLore(stack, kind, expire);
        }
    }

    private void runAmethystExpirySweep() {
        long now = System.currentTimeMillis();
        for (Player p : Bukkit.getOnlinePlayers()) {
            org.bukkit.inventory.PlayerInventory inv = p.getInventory();
            for (int i = 0; i < inv.getSize(); ++i) {
                ItemStack stack = inv.getItem(i);
                if (!isAmethystToolStack(stack)) continue;
                ItemMeta meta = stack.getItemMeta();
                org.bukkit.persistence.PersistentDataContainer pdc = meta.getPersistentDataContainer();
                Long expire = pdc.get(this.amethystExpireKey, PersistentDataType.LONG);
                if (expire == null || expire <= 0L) continue;
                if (now >= expire) {
                    String kind = pdc.get(this.amethystKindKey, PersistentDataType.STRING);
                    inv.setItem(i, null);
                    p.sendActionBar((Component)Component.text("§cYour " + amethystDisplayName(kind != null ? kind : "tool") + " has expired"));
                    p.playSound(p.getLocation(), Sound.ENTITY_ITEM_BREAK, 0.8f, 0.7f);
                }
            }
        }
    }

    private ArrayList<String> getToolEnchantmentsLore(String toolKey) {
        ArrayList<String> lore = new ArrayList<>();
        lore.add("§7Enchantments:");
        switch (toolKey) {
            case "diamond_sword":
            case "netherite_sword":
                lore.add("§7• Fire Aspect II");
                lore.add("§7• Unbreaking III");
                lore.add("§7• Mending");
                break;
            case "diamond_pickaxe":
            case "netherite_pickaxe":
                lore.add("§7• Efficiency V");
                lore.add("§7• Unbreaking III");
                lore.add("§7• Mending");
                break;
            case "diamond_axe":
            case "netherite_axe":
                lore.add("§7• Efficiency V");
                lore.add("§7• Unbreaking III");
                lore.add("§7• Mending");
                break;
        }
        return lore;
    }

    // Confirm menu: Row0=glass, Row1=qty-buttons|item|qty-buttons, Row2=cancel|cost|confirm
    private void openShopConfirmMenu(Player player, String categoryKey, String itemKey) {
        ShopEntry entry = this.findShopEntry(categoryKey, itemKey);
        if (entry == null) {
            this.openShopCategoryMenu(player, categoryKey);
            return;
        }
        ShopSelectionState state = this.shopSelectionState.computeIfAbsent(player.getUniqueId(), id -> new ShopSelectionState(categoryKey, itemKey, 1));
        if (!categoryKey.equals(state.categoryKey) || !itemKey.equals(state.itemKey)) {
            state.categoryKey = categoryKey;
            state.itemKey = itemKey;
            state.quantity = 1;
        }
        int maxQty = this.shopMaxQty(entry);
        state.quantity = Math.max(1, Math.min(maxQty, state.quantity));

        Inventory inv = Bukkit.createInventory(null, 27, TITLE_SHOP_CONFIRM);
        // qty buttons only for stackable items
        if (maxQty > 1) {
            int maxStack = entry.material.getMaxStackSize();
            // Subtract buttons \u2014 hidden once at the minimum (qty 1), mirroring the add buttons at max.
            if (state.quantity > 1) {
                ItemStack sub1 = this.namedWithLore(Material.RED_STAINED_GLASS_PANE, "\u00a7c-1", "shop_qty_sub:1", List.of());
                sub1.setAmount(1);
                inv.setItem(11, sub1);
            }

            if (maxQty >= 10 && state.quantity > 1) {   // stays visible until min; -10 clamps to 1
                ItemStack sub10 = this.namedWithLore(Material.RED_STAINED_GLASS_PANE, "\u00a7c-10", "shop_qty_sub:10", List.of());
                sub10.setAmount(10);
                inv.setItem(10, sub10);
            }

            if (maxStack >= 16 && state.quantity > 1) {
                ItemStack subMax = this.namedWithLore(Material.RED_STAINED_GLASS_PANE, "\u00a7c-" + maxStack, "shop_qty_sub:" + maxStack, List.of());
                subMax.setAmount(Math.min(maxStack, 64));
                inv.setItem(9, subMax);
            }

            // Add buttons (only show if not at max)
            int totalItems = entry.unitAmount * state.quantity;
            if (totalItems < entry.material.getMaxStackSize()) {
                ItemStack add1 = this.namedWithLore(Material.LIME_STAINED_GLASS_PANE, "\u00a7a+1", "shop_qty_add:1", List.of());
                add1.setAmount(1);
                inv.setItem(15, add1);
            }

            if (maxQty >= 10 && totalItems < entry.material.getMaxStackSize()) {   // stays visible until max; +10 clamps to max
                ItemStack add10 = this.namedWithLore(Material.LIME_STAINED_GLASS_PANE, "\u00a7a+10", "shop_qty_add:10", List.of());
                add10.setAmount(10);
                inv.setItem(16, add10);
            }

            if (totalItems < entry.material.getMaxStackSize()) {
                ItemStack addMax = this.namedWithLore(Material.LIME_STAINED_GLASS_PANE, "\u00a7a+" + maxStack, "shop_qty_add:" + maxStack, List.of());
                addMax.setAmount(Math.min(maxStack, 64));
                inv.setItem(17, addMax);
            }
        }
        inv.setItem(13, this.buildConfirmItemDisplay(entry, state.quantity));
        inv.setItem(21, this.namedWithLore(Material.RED_STAINED_GLASS_PANE,   "\u00a7cBack",  "shop_cancel:" + categoryKey,  List.of()));
        int totalItems = entry.unitAmount * state.quantity;
        inv.setItem(23, this.namedWithLore(Material.GREEN_STAINED_GLASS_PANE,  "\u00a7aConfirm", "shop_confirm", List.of(
            "\u00a7aTotal: \u00a7f$" + this.fmtMoney(entry.priceMoney * state.quantity),
            "\u00a7aItems: \u00a7f" + totalItems
        )));
        this.runOnPlayerThread(player, () -> player.openInventory(inv));
    }

    private int shopMaxQty(ShopEntry entry) {
        if (entry == null) return 1;
        // Amethyst tools are unique one-off items (icon material is AMETHYST_SHARD which stacks to 64,
        // which previously let you "buy a stack"). Always cap them at 1.
        if (entry.key != null && entry.key.startsWith("amethyst_")) return 1;
        int maxStack = entry.material.getMaxStackSize();
        if (maxStack <= 1 || entry.unitAmount <= 0) return 1;
        return Math.max(1, maxStack / entry.unitAmount);
    }

    private ItemStack buildConfirmItemDisplay(ShopEntry entry, int qty) {
        Material displayMaterial = entry.material;
        String displayName = "\u00a7f" + entry.label;
        if (entry.key.startsWith("amethyst_")) {
            displayMaterial = switch(entry.key) {
                case "amethyst_drill" -> Material.NETHERITE_PICKAXE;
                case "amethyst_multitool" -> Material.NETHERITE_SHOVEL;
                case "amethyst_sellaxe", "amethyst_treechopper" -> Material.NETHERITE_AXE;
                default -> entry.material;
            };
            displayName = "\u00a7d" + entry.label;
        }
        int totalAmount = entry.unitAmount * qty;
        int displayAmt = Math.max(1, Math.min(totalAmount, displayMaterial.getMaxStackSize()));
        ItemStack item = new ItemStack(displayMaterial, displayAmt);
        if (entry.material == Material.TIPPED_ARROW) {
            ItemMeta m2 = item.getItemMeta();
            if (m2 instanceof PotionMeta pm) {
                pm.setBasePotionType(PotionType.SLOW_FALLING);
                item.setItemMeta(m2);
            }
        }
        ItemMeta meta = item.getItemMeta();
        meta.setDisplayName(displayName);
        ArrayList<String> lore = new ArrayList<>();
        if (entry.unitAmount > 1) {
            lore.add("\u00a7aPrice: \u00a7f$" + this.fmtMoney(entry.priceMoney) + " \u00a78\u00d7" + entry.unitAmount);
        } else {
            lore.add("\u00a7aPrice: \u00a7f$" + this.fmtMoney(entry.priceMoney));
        }
        if (qty > 1) {
            lore.add("\u00a7aQty: \u00a7f" + qty);
            lore.add("\u00a7aTotal: \u00a7f$" + this.fmtMoney(entry.priceMoney * qty));
        }
        if (entry.key.startsWith("amethyst_")) {
            lore.add("");
            lore.addAll(this.getAmethystToolLore(entry.key));
        } else if (entry.key.endsWith("_sword") || entry.key.endsWith("_pickaxe") || entry.key.endsWith("_axe")) {
            lore.add("");
            lore.addAll(this.getToolEnchantmentsLore(entry.key));
        }
        meta.setLore(lore);
        item.setItemMeta(meta);
        return item;
    }

    private void adjustShopQuantity(Player player, int delta) {
        if (delta == 0) return;
        ShopSelectionState state = this.shopSelectionState.get(player.getUniqueId());
        if (state == null || state.itemKey == null) return;
        ShopEntry entry = this.findShopEntry(state.categoryKey, state.itemKey);
        if (entry == null) return;
        int maxQty = this.shopMaxQty(entry);
        state.quantity = Math.max(1, Math.min(maxQty, state.quantity + delta));
        this.openShopConfirmMenu(player, state.categoryKey, state.itemKey);
    }

    private void confirmShopPurchase(Player player) {
        ShopSelectionState state = this.shopSelectionState.get(player.getUniqueId());
        if (state == null || state.itemKey == null || state.quantity <= 0) return;
        ShopEntry entry = this.findShopEntry(state.categoryKey, state.itemKey);
        if (entry == null) return;
        // Special handling: amethyst tools dispatch /tools give command
        if (state.itemKey.startsWith("amethyst_")) {
            double cost = entry.priceMoney;
            if (!this.hasMoney(player, cost)) {
                player.sendActionBar(this.legacyColorize("§cNot enough money."));
                return;
            }
            String toolName = switch (state.itemKey) {
                case "amethyst_drill"       -> "drill";
                case "amethyst_multitool"   -> "multitool";
                case "amethyst_sellaxe"     -> "sellaxe";
                case "amethyst_treechopper" -> "treechopper";
                default -> null;
            };
            if (toolName == null) return;
            // Inventory-full guard: never take money if there's no room for the tool (the "scam" bug).
            if (player.getInventory().firstEmpty() == -1) {
                player.sendActionBar(this.legacyColorize("§cYour inventory is full. Make room before buying."));
                return;
            }
            if (!this.withdrawMoney(player, cost)) return;
            final String ft = toolName;
            final String entryLabel = entry.label;
            final double fCost = cost;
            this.runOnPlayerThread(player, () -> {
                Bukkit.dispatchCommand(Bukkit.getConsoleSender(), "tools give " + player.getName() + " " + ft);
                // Tag the newly-given amethyst tool so PNC tracks expiry. Timer starts on first equip,
                // not at purchase. Also push aAmethyst's self_destruct_time far into the future so it
                // doesn't expire the tool ahead of our system.
                final String kind = ft;
                this.scheduleTask(() -> {
                    org.bukkit.NamespacedKey aamethystKey = new org.bukkit.NamespacedKey("aamethyst", "self_destruct_time");
                    long farFuture = System.currentTimeMillis() + 365L * 24L * 60L * 60L * 1000L;
                    for (org.bukkit.inventory.ItemStack stack : player.getInventory().getContents()) {
                        if (stack == null || !stack.hasItemMeta()) continue;
                        org.bukkit.inventory.meta.ItemMeta meta = stack.getItemMeta();
                        if (meta == null) continue;
                        org.bukkit.persistence.PersistentDataContainer pdc = meta.getPersistentDataContainer();
                        // Only target untagged amethyst tools — skip tools the player already owned/equipped.
                        boolean isFresh = pdc.has(aamethystKey, org.bukkit.persistence.PersistentDataType.LONG)
                                          && !pdc.has(amethystExpireKey, org.bukkit.persistence.PersistentDataType.LONG)
                                          && !pdc.has(amethystKindKey, org.bukkit.persistence.PersistentDataType.STRING);
                        if (!isFresh) continue;
                        pdc.set(aamethystKey, org.bukkit.persistence.PersistentDataType.LONG, farFuture);
                        pdc.set(amethystKindKey, org.bukkit.persistence.PersistentDataType.STRING, kind);
                        // Arm the 3-day self-destruct timer AT PURCHASE (so every bought tool is armed,
                        // not just ones the player equips in the hotbar).
                        long armAt = System.currentTimeMillis() + AMETHYST_LIFETIME_MS;
                        pdc.set(amethystExpireKey, org.bukkit.persistence.PersistentDataType.LONG, armAt);
                        stack.setItemMeta(meta);
                        applyAmethystLore(stack, kind, armAt);
                    }
                }, 1, TimeUnit.SECONDS);
                player.sendActionBar(Component.text("§aYou purchased an Amethyst " + entryLabel + " for §f$" + this.fmtMoney(fCost) + "§a."));
                player.playSound(player.getLocation(), Sound.ENTITY_EXPERIENCE_ORB_PICKUP, 0.55f, 1.2f);
            });
            return;
        }
        double totalCost = entry.priceMoney * (double)state.quantity;
        int giveAmount = entry.unitAmount * state.quantity;
        if (totalCost <= 0.0 || giveAmount <= 0) return;
        if (!this.hasMoney(player, totalCost)) {
            player.sendActionBar(this.legacyColorize("\u00a7cNot enough money."));
            return;
        }
        if (!this.withdrawMoney(player, totalCost)) return;
        this.runAsyncTask(() -> this.incrementMoneyStat(player.getUniqueId(), "shop_spent", totalCost));
        int remaining = giveAmount;
        int given = 0;
        boolean inventoryFull = false;
        while (remaining > 0) {
            int stackAmount = Math.min(Math.max(1, entry.material.getMaxStackSize()), remaining);
            ItemStack offer = this.createSingleShopStack(entry, stackAmount);
            HashMap leftovers = player.getInventory().addItem(new ItemStack[]{offer});
            int accepted = stackAmount;
            for (Object extra : leftovers.values()) accepted -= ((ItemStack)extra).getAmount();
            if (accepted <= 0) { inventoryFull = true; break; }
            given += accepted;
            remaining -= accepted;
            if (!leftovers.isEmpty()) { inventoryFull = true; break; }
        }
        if (given <= 0) {
            this.depositMoney(player, totalCost);
            player.sendActionBar(this.legacyColorize("\u00a7cInventory full."));
            player.playSound(player.getLocation(), Sound.ENTITY_VILLAGER_NO, 0.85f, 0.9f);
            this.openShopConfirmMenu(player, state.categoryKey, state.itemKey);
            return;
        }
        if (inventoryFull) {
            player.sendActionBar(this.legacyColorize("\u00a7cInventory full."));
            player.playSound(player.getLocation(), Sound.ENTITY_VILLAGER_NO, 0.85f, 0.9f);
        }
        if (given < giveAmount) {
            double charged = entry.priceMoney * (double)given / (double)Math.max(1, entry.unitAmount);
            this.depositMoney(player, totalCost - charged);
        }
        player.playSound(player.getLocation(), Sound.ENTITY_EXPERIENCE_ORB_PICKUP, 0.55f, 1.2f);
        this.logTransactionAudit(player.getUniqueId().toString(), player.getName(), "SHOP_BUY", entry.material.name(), given, entry.priceMoney, totalCost, "item=" + entry.key);
        // Stay on confirm menu so player can buy more
        this.openShopConfirmMenu(player, state.categoryKey, state.itemKey);
    }

    private ItemStack createSingleShopStack(ShopEntry entry, int amount) {
        ItemStack stack = new ItemStack(entry.material, amount);
        if (entry.material == Material.TIPPED_ARROW) {
            ItemMeta meta = stack.getItemMeta();
            if (meta instanceof PotionMeta pm) {
                pm.setBasePotionType(PotionType.SLOW_FALLING);
                stack.setItemMeta(meta);
            }
        } else if (entry.material == Material.FIREWORK_ROCKET) {
            ItemMeta meta = stack.getItemMeta();
            if (meta instanceof FireworkMeta fm) {
                fm.setPower(3);
                stack.setItemMeta(meta);
            }
        } else if (entry.key.endsWith("_sword")) {
            stack.addUnsafeEnchantment(Enchantment.FIRE_ASPECT, 2);
            stack.addUnsafeEnchantment(Enchantment.UNBREAKING, 3);
            stack.addUnsafeEnchantment(Enchantment.MENDING, 1);
        } else if (entry.key.endsWith("_pickaxe")) {
            stack.addUnsafeEnchantment(Enchantment.EFFICIENCY, 5);
            stack.addUnsafeEnchantment(Enchantment.UNBREAKING, 3);
            stack.addUnsafeEnchantment(Enchantment.MENDING, 1);
        } else if (entry.key.endsWith("_axe")) {
            stack.addUnsafeEnchantment(Enchantment.EFFICIENCY, 5);
            stack.addUnsafeEnchantment(Enchantment.UNBREAKING, 3);
            stack.addUnsafeEnchantment(Enchantment.MENDING, 1);
        }
        return stack;
    }
    private void giveItemStack(Player player, ItemStack stack) {
        if (stack == null || stack.getType() == Material.AIR) {
            return;
        }
        HashMap leftovers = player.getInventory().addItem(new ItemStack[]{stack});
        if (!leftovers.isEmpty()) {
            for (Object leftover : leftovers.values()) {
                this.dropItemLikePlayer(player, (ItemStack)leftover);
            }
        }
    }

    private void dropItemLikePlayer(Player player, ItemStack stack) {
        if (stack == null || stack.getType() == Material.AIR || player == null) return;
        org.bukkit.entity.Item dropped = player.getWorld().dropItem(player.getEyeLocation(), stack);
        dropped.setVelocity(player.getLocation().getDirection().multiply(0.3));
    }

    private String categoryTitle(String categoryKey) {
        return switch (categoryKey.toLowerCase()) {
            case "end"       -> TITLE_SHOP_END;
            case "nether"    -> TITLE_SHOP_NETHER;
            case "gear"      -> TITLE_SHOP_GEAR;
            case "gear2"     -> TITLE_SHOP_GEAR_2;
            case "food"      -> TITLE_SHOP_FOOD;
            default          -> TITLE_SHOP;
        };
    }

    private List<ShopEntry> shopEntries(String categoryKey) {
        return switch (categoryKey.toLowerCase()) {
            case "end"      -> END_CATEGORY_ITEMS;
            case "nether"   -> NETHER_CATEGORY_ITEMS;
            case "gear"     -> GEAR_CATEGORY_ITEMS;
            case "gear2"    -> GEAR_CATEGORY_ITEMS_P2;
            case "food"     -> FOOD_CATEGORY_ITEMS;
            default         -> List.of();
        };
    }

    private ShopEntry findShopEntry(String categoryKey, String itemKey) {
        for (ShopEntry entry : this.shopEntries(categoryKey)) {
            if (!entry.key.equalsIgnoreCase(itemKey)) continue;
            return entry;
        }
        return null;
    }

    private void openShardShopMenu(Player player) {
        if (player == null || !player.isOnline()) {
            return;
        }
        this.runAsyncTask(() -> {
            long shards = this.getShardBalance(player.getUniqueId());
            long dailyRem = this.getDailyClaimRemainingMs(player.getUniqueId());
            this.runOnPlayerThread(player, () -> {
                if (!player.isOnline()) {
                    return;
                }
                Inventory inv = Bukkit.createInventory(null, 54, TITLE_SHARD_SHOP);
                ItemStack filler = this.namedWithLore(Material.GRAY_STAINED_GLASS_PANE, " ", null, List.of());
                for (int i = 0; i < 54; i++) inv.setItem(i, filler);
                inv.setItem(4, this.namedWithLore(Material.AMETHYST_SHARD, "\u00a7fShard Balance", "shard_balance", List.of("\u00a77Shards: \u00a7b" + shards)));
                // Daily crate (free, 24h)
                boolean ready = dailyRem <= 0L;
                List<String> dailyLore = ready
                    ? List.of("\u00a77A free crate, once every 24h", "\u00a7aReady! Click to claim")
                    : List.of("\u00a77A free crate, once every 24h", "\u00a7cReady in " + (dailyRem / 3600000L) + "h " + ((dailyRem % 3600000L) / 60000L) + "m");
                inv.setItem(13, this.namedWithLore(ready ? Material.ENDER_CHEST : Material.CHEST, (ready ? "\u00a7a" : "\u00a77") + "Daily Crate",
                    ready ? "shard_daily_claim" : "shard_daily_locked", dailyLore));
                // Crates (prices unchanged)
                inv.setItem(20, this.namedWithLore(Material.CHEST, "\u00a7fCommon Crate", "shard_open_crate:common", List.of("\u00a77Diamond gear loadout", "\u00a77Price: \u00a7b200 shards", "\u00a77Click to open")));
                inv.setItem(22, this.namedWithLore(Material.CHEST, "\u00a7fCrimson Crate", "shard_open_crate:crimson", List.of("\u00a77Netherite + redstone trims", "\u00a77Price: \u00a7b2500 shards", "\u00a77Click to open")));
                inv.setItem(24, this.namedWithLore(Material.CHEST, "\u00a7fPrime Crate", "shard_open_crate:prime", List.of("\u00a77Netherite, Mace + diamond trims", "\u00a77Price: \u00a7b2000 shards", "\u00a77Click to open")));
                // Direct-buy items
                this.putShardItem(inv, 29, Material.TOTEM_OF_UNDYING, "Totem of Undying", "totem");
                this.putShardItem(inv, 30, Material.ENCHANTED_BOOK, "Mending Book", "mending");
                this.putShardItem(inv, 31, Material.ENCHANTED_GOLDEN_APPLE, "Enchanted Golden Apple", "godapple");
                this.putShardItem(inv, 32, Material.ELYTRA, "Elytra", "elytra");
                this.putShardItem(inv, 33, Material.SHULKER_BOX, "Shulker Box", "shulker");
                this.putShardItem(inv, 38, Material.NETHERITE_INGOT, "Netherite Ingot", "netherite_ingot");
                this.putShardItem(inv, 39, Material.EXPERIENCE_BOTTLE, "16x XP Bottles", "xp_bottles");
                this.putShardItem(inv, 40, Material.TRIDENT, "Trident", "trident");
                this.putShardItem(inv, 41, Material.NAME_TAG, "Name Tag", "name_tag");
                inv.setItem(49, this.namedWithLore(Material.RED_STAINED_GLASS_PANE, "\u00a7cBack", "shop_open_main", List.of()));
                player.openInventory(inv);
            });
        });
    }

    private void putShardItem(Inventory inv, int slot, Material mat, String name, String key) {
        Integer price = SHARD_ITEM_PRICES.get(key);
        inv.setItem(slot, this.namedWithLore(mat, "\u00a7f" + name, "shard_buy_item:" + key,
            List.of("\u00a77Price: \u00a7b" + price + " shards", "\u00a77Click to buy")));
    }

    private ItemStack enchantedBook(Enchantment ench, int level) {
        ItemStack book = new ItemStack(Material.ENCHANTED_BOOK);
        org.bukkit.inventory.meta.EnchantmentStorageMeta meta = (org.bukkit.inventory.meta.EnchantmentStorageMeta) book.getItemMeta();
        meta.addStoredEnchant(ench, level, true);
        book.setItemMeta(meta);
        return book;
    }

    private ItemStack buildShardItem(String key) {
        return switch (key) {
            case "totem" -> new ItemStack(Material.TOTEM_OF_UNDYING);
            case "mending" -> this.enchantedBook(Enchantment.MENDING, 1);
            case "godapple" -> new ItemStack(Material.ENCHANTED_GOLDEN_APPLE);
            case "elytra" -> new ItemStack(Material.ELYTRA);
            case "shulker" -> new ItemStack(Material.SHULKER_BOX);
            case "netherite_ingot" -> new ItemStack(Material.NETHERITE_INGOT);
            case "xp_bottles" -> new ItemStack(Material.EXPERIENCE_BOTTLE, 16);
            case "trident" -> new ItemStack(Material.TRIDENT);
            case "name_tag" -> new ItemStack(Material.NAME_TAG);
            default -> null;
        };
    }

    private void purchaseShardItem(Player player, String key) {
        Integer cost = SHARD_ITEM_PRICES.get(key);
        if (cost == null) return;
        UUID uuid = player.getUniqueId();
        this.runAsyncTask(() -> {
            if (!this.withdrawShards(uuid, cost.intValue())) {
                this.runOnPlayerThread(player, () -> player.sendActionBar(Component.text("\u00a7cNot enough shards (need " + cost + ").")));
                return;
            }
            ItemStack item = this.buildShardItem(key);
            this.runOnPlayerThread(player, () -> {
                if (!player.isOnline()) return;
                if (item != null) this.giveItemStack(player, item);
                player.playSound(player.getLocation(), Sound.ENTITY_EXPERIENCE_ORB_PICKUP, 0.7f, 1.0f);
                player.sendActionBar(Component.text("\u00a77Purchased for \u00a7b" + cost + " shards\u00a77."));
                this.openShardShopMenu(player);
            });
        });
    }

    // ----- Daily crate -----
    private long getDailyClaimRemainingMs(UUID uuid) {
        String sql = "SELECT TIMESTAMPDIFF(SECOND, last_claim, NOW()) FROM shard_daily_claims WHERE uuid=?";
        try (Connection conn = this.openSyncConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setString(1, uuid.toString());
            try (ResultSet rs = ps.executeQuery()) {
                if (!rs.next()) return 0L;
                long elapsed = rs.getLong(1);
                long remaining = 86400L - elapsed;
                return remaining > 0L ? remaining * 1000L : 0L;
            }
        } catch (Exception ex) {
            this.getLogger().warning("Failed reading daily claim: " + ex.getMessage());
            return 0L;
        }
    }

    private void recordDailyClaim(UUID uuid) {
        String sql = "INSERT INTO shard_daily_claims (uuid, last_claim) VALUES (?, NOW()) ON DUPLICATE KEY UPDATE last_claim=NOW()";
        try (Connection conn = this.openSyncConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setString(1, uuid.toString());
            ps.executeUpdate();
        } catch (Exception ex) {
            this.getLogger().warning("Failed recording daily claim: " + ex.getMessage());
        }
    }

    private java.util.List<ItemStack> buildDailyCrateRewards() {
        java.util.List<ItemStack> out = new java.util.ArrayList<>();
        int roll = this.ecoRandom.nextInt(100);
        if (roll < 60) {
            out.add(new ItemStack(Material.DIAMOND, 8));
            out.add(new ItemStack(Material.GOLD_INGOT, 8));
            out.add(new ItemStack(Material.IRON_INGOT, 16));
        } else if (roll < 85) {
            out.add(new ItemStack(Material.DIAMOND, 16));
            out.add(this.enchantedBook(Enchantment.MENDING, 1));
            out.add(new ItemStack(Material.EXPERIENCE_BOTTLE, 16));
        } else if (roll < 97) {
            out.add(new ItemStack(Material.DIAMOND, 32));
            out.add(new ItemStack(Material.ENCHANTED_GOLDEN_APPLE, 1));
            out.add(new ItemStack(Material.NETHERITE_SCRAP, 2));
        } else {
            out.add(new ItemStack(Material.NETHERITE_INGOT, 2));
            out.add(new ItemStack(Material.ENCHANTED_GOLDEN_APPLE, 3));
            out.add(new ItemStack(Material.TOTEM_OF_UNDYING, 1));
        }
        return out;
    }

    private void claimDailyCrate(Player player) {
        UUID uuid = player.getUniqueId();
        this.runAsyncTask(() -> {
            long rem = this.getDailyClaimRemainingMs(uuid);
            if (rem > 0L) {
                long hrs = rem / 3600000L;
                long mins = (rem % 3600000L) / 60000L;
                this.runOnPlayerThread(player, () -> player.sendActionBar(Component.text("\u00a7cDaily crate ready in " + hrs + "h " + mins + "m.")));
                return;
            }
            this.recordDailyClaim(uuid);
            java.util.List<ItemStack> rewards = this.buildDailyCrateRewards();
            long bonus = 50L + this.ecoRandom.nextInt(101);
            this.depositShards(uuid, bonus);
            this.runOnPlayerThread(player, () -> {
                if (!player.isOnline()) return;
                for (ItemStack r : rewards) this.giveItemStack(player, r);
                player.playSound(player.getLocation(), Sound.UI_TOAST_CHALLENGE_COMPLETE, 0.7f, 1.0f);
                player.sendMessage("\u00a77Daily crate claimed: \u00a7b+" + bonus + " shards \u00a77and items.");
                this.openShardShopMenu(player);
            });
        });
    }

    private void openShardCrateDetails(Player player, String crateKey) {
        Integer price = SHARD_CRATE_PRICES.get(crateKey);
        String title = this.crateTitle(crateKey);
        if (title == null || price == null) {
            return;
        }
        Inventory inv = Bukkit.createInventory(null, 54, title);
        ItemStack filler = this.namedWithLore(Material.GRAY_STAINED_GLASS_PANE, " ", null, List.of());
        for (int i = 0; i < 54; i++) inv.setItem(i, filler);
        inv.setItem(4, this.namedWithLore(Material.CHEST, "\u00a7f" + title, null,
            List.of("\u00a77Possible rewards shown below", "\u00a77Price: \u00a7b" + price + " shards")));
        // Rewards centered in rows 2-3.
        int[] rewardSlots = {19, 20, 21, 22, 23, 24, 25, 28, 29, 30, 31, 32, 33, 34};
        List<ItemStack> previews = this.buildCrateRewards(crateKey);
        for (int i = 0; i < previews.size() && i < rewardSlots.length; i++) {
            inv.setItem(rewardSlots[i], previews.get(i));
        }
        inv.setItem(48, this.namedWithLore(Material.LIME_STAINED_GLASS_PANE, "\u00a7aBuy for " + price + " shards", "shard_buy_crate:" + crateKey, List.of("\u00a77Click to review and confirm")));
        inv.setItem(50, this.namedWithLore(Material.RED_STAINED_GLASS_PANE, "\u00a7cBack", "shard_back", List.of()));
        player.openInventory(inv);
    }

    private ItemStack shardItemIcon(String key, int price) {
        ItemStack item = this.buildShardItem(key);
        if (item == null) item = new ItemStack(Material.BARRIER);
        ItemMeta meta = item.getItemMeta();
        meta.setLore(List.of("\u00a77Price: \u00a7b" + price + " shards"));
        item.setItemMeta(meta);
        return item;
    }

    private void openShardConfirm(Player player, String type, String key) {
        boolean crate = "crate".equals(type);
        Integer price = crate ? SHARD_CRATE_PRICES.get(key) : SHARD_ITEM_PRICES.get(key);
        if (price == null) { this.openShardShopMenu(player); return; }
        Inventory inv = Bukkit.createInventory(null, 27, TITLE_SHARD_CONFIRM);
        ItemStack filler = this.namedWithLore(Material.GRAY_STAINED_GLASS_PANE, " ", null, List.of());
        for (int i = 0; i < 27; i++) inv.setItem(i, filler);
        ItemStack icon = crate
            ? this.namedWithLore(Material.CHEST, "\u00a7f" + this.crateTitle(key), null, List.of("\u00a77Price: \u00a7b" + price + " shards"))
            : this.shardItemIcon(key, price);
        inv.setItem(13, icon);
        inv.setItem(11, this.namedWithLore(Material.LIME_WOOL, "\u00a7aConfirm",
            crate ? ("shard_do_crate:" + key) : ("shard_do_item:" + key), List.of("\u00a77Spend \u00a7b" + price + " shards")));
        inv.setItem(15, this.namedWithLore(Material.RED_WOOL, "\u00a7cCancel",
            crate ? ("shard_cancel_crate:" + key) : "shard_cancel_item", List.of("\u00a77Keep your shards")));
        player.openInventory(inv);
    }

    private String crateTitle(String crateKey) {
        return switch (crateKey.toLowerCase()) {
            case "common" -> TITLE_CRATE_COMMON;
            case "crimson" -> TITLE_CRATE_CRIMSON;
            case "amethyst" -> TITLE_CRATE_AMETHYST;
            case "prime" -> TITLE_CRATE_PRIME;
            default -> null;
        };
    }

    private void purchaseCrate(Player player, String crateKey) {
        Integer cost = SHARD_CRATE_PRICES.get(crateKey);
        if (cost == null) {
            return;
        }
        UUID uuid = player.getUniqueId();
        this.runAsyncTask(() -> {
            if (!this.withdrawShards(uuid, cost.intValue())) {
                return;
            }
            List<ItemStack> rewards = this.buildCrateRewards(crateKey);
            this.logCrateReward(uuid, player.getName(), crateKey, cost, rewards.size());
            this.runOnPlayerThread(player, () -> {
                if (!player.isOnline()) {
                    return;
                }
                for (ItemStack reward : rewards) {
                    this.giveItemStack(player, reward);
                }
                player.playSound(player.getLocation(), Sound.UI_TOAST_CHALLENGE_COMPLETE, 0.65f, 1.0f);
                this.openShardCrateDetails(player, crateKey);
            });
        });
    }

    private List<ItemStack> buildCrateRewards(String crateKey) {
        ArrayList<ItemStack> out = new ArrayList<ItemStack>();
        switch (crateKey.toLowerCase()) {
            case "common": {
                out.add(this.createEnchanted(Material.DIAMOND_HELMET, false, Map.of(Enchantment.PROTECTION, 3, Enchantment.UNBREAKING, 2)));
                out.add(this.createEnchanted(Material.DIAMOND_CHESTPLATE, false, Map.of(Enchantment.PROTECTION, 3, Enchantment.UNBREAKING, 2)));
                out.add(this.createEnchanted(Material.DIAMOND_LEGGINGS, false, Map.of(Enchantment.BLAST_PROTECTION, 3, Enchantment.UNBREAKING, 2)));
                out.add(this.createEnchanted(Material.DIAMOND_BOOTS, false, Map.of(Enchantment.BLAST_PROTECTION, 3, Enchantment.UNBREAKING, 2)));
                out.add(this.createEnchanted(Material.DIAMOND_SWORD, false, Map.of(Enchantment.SHARPNESS, 4, Enchantment.UNBREAKING, 2)));
                out.add(this.createEnchanted(Material.DIAMOND_PICKAXE, false, Map.of(Enchantment.EFFICIENCY, 4, Enchantment.UNBREAKING, 2)));
                break;
            }
            case "crimson": {
                out.add(this.applyTrim(this.createEnchanted(Material.NETHERITE_HELMET, true, Map.of(Enchantment.PROTECTION, 4, Enchantment.UNBREAKING, 3)), TrimMaterial.REDSTONE, TrimPattern.SENTRY));
                out.add(this.applyTrim(this.createEnchanted(Material.NETHERITE_CHESTPLATE, true, Map.of(Enchantment.PROTECTION, 4, Enchantment.UNBREAKING, 3)), TrimMaterial.REDSTONE, TrimPattern.SENTRY));
                out.add(this.applyTrim(this.createEnchanted(Material.NETHERITE_LEGGINGS, true, Map.of(Enchantment.BLAST_PROTECTION, 4, Enchantment.UNBREAKING, 3)), TrimMaterial.REDSTONE, TrimPattern.SENTRY));
                out.add(this.applyTrim(this.createEnchanted(Material.NETHERITE_BOOTS, true, Map.of(Enchantment.BLAST_PROTECTION, 4, Enchantment.UNBREAKING, 3, Enchantment.DEPTH_STRIDER, 3)), TrimMaterial.REDSTONE, TrimPattern.SENTRY));
                out.add(this.createEnchanted(Material.NETHERITE_SWORD, true, Map.of(Enchantment.SHARPNESS, 5, Enchantment.FIRE_ASPECT, 2, Enchantment.UNBREAKING, 3)));
                out.add(this.createEnchanted(Material.NETHERITE_AXE, true, Map.of(Enchantment.SHARPNESS, 5, Enchantment.UNBREAKING, 3)));
                out.add(this.createEnchanted(Material.NETHERITE_PICKAXE, true, Map.of(Enchantment.EFFICIENCY, 5, Enchantment.UNBREAKING, 3)));
                break;
            }
            case "amethyst": {
                out.add(this.createNamedEnchanted(Material.NETHERITE_HELMET, "\u00a7dAMETHYST HELMET", true, Map.of(Enchantment.PROTECTION, 4, Enchantment.UNBREAKING, 3)));
                out.add(this.createNamedEnchanted(Material.NETHERITE_CHESTPLATE, "\u00a7dAMETHYST CHESTPLATE", true, Map.of(Enchantment.PROTECTION, 4, Enchantment.UNBREAKING, 3)));
                out.add(this.createNamedEnchanted(Material.NETHERITE_LEGGINGS, "\u00a7dAMETHYST LEGGINGS", true, Map.of(Enchantment.BLAST_PROTECTION, 4, Enchantment.UNBREAKING, 3)));
                out.add(this.createNamedEnchanted(Material.NETHERITE_BOOTS, "\u00a7dAMETHYST BOOTS", true, Map.of(Enchantment.BLAST_PROTECTION, 4, Enchantment.UNBREAKING, 3, Enchantment.DEPTH_STRIDER, 3)));
                out.add(this.createNamedEnchanted(Material.NETHERITE_SWORD, "\u00a7dAMETHYST SWORD", true, Map.of(Enchantment.SHARPNESS, 5, Enchantment.UNBREAKING, 3)));
                out.add(this.createNamedEnchanted(Material.NETHERITE_AXE, "\u00a7dAMETHYST AXE", true, Map.of(Enchantment.SHARPNESS, 5, Enchantment.UNBREAKING, 3)));
                out.add(this.createNamedEnchanted(Material.NETHERITE_PICKAXE, "\u00a7dAMETHYST PICKAXE", true, Map.of(Enchantment.EFFICIENCY, 5, Enchantment.UNBREAKING, 3)));
                break;
            }
            case "prime": {
                out.add(this.applyTrim(this.createEnchanted(Material.NETHERITE_HELMET, true, Map.of(Enchantment.PROTECTION, 4, Enchantment.UNBREAKING, 3)), TrimMaterial.DIAMOND, TrimPattern.SPIRE));
                out.add(this.applyTrim(this.createEnchanted(Material.NETHERITE_CHESTPLATE, true, Map.of(Enchantment.PROTECTION, 4, Enchantment.UNBREAKING, 3)), TrimMaterial.DIAMOND, TrimPattern.SPIRE));
                out.add(this.applyTrim(this.createEnchanted(Material.NETHERITE_LEGGINGS, true, Map.of(Enchantment.BLAST_PROTECTION, 4, Enchantment.UNBREAKING, 3)), TrimMaterial.DIAMOND, TrimPattern.SPIRE));
                out.add(this.applyTrim(this.createEnchanted(Material.NETHERITE_BOOTS, true, Map.of(Enchantment.BLAST_PROTECTION, 4, Enchantment.UNBREAKING, 3, Enchantment.FEATHER_FALLING, 4)), TrimMaterial.DIAMOND, TrimPattern.SPIRE));
                out.add(this.createEnchanted(Material.NETHERITE_SWORD, true, Map.of(Enchantment.SHARPNESS, 5, Enchantment.FIRE_ASPECT, 2, Enchantment.UNBREAKING, 3)));
                out.add(this.createEnchanted(Material.CROSSBOW, true, Map.of(Enchantment.QUICK_CHARGE, 3, Enchantment.MULTISHOT, 1, Enchantment.PIERCING, 4, Enchantment.UNBREAKING, 3)));
                out.add(this.createEnchanted(Material.MACE, true, Map.of(Enchantment.BREACH, 4, Enchantment.UNBREAKING, 3)));
                break;
            }
        }
        return out;
    }

    private ItemStack createEnchanted(Material material, boolean mending, Map<Enchantment, Integer> enchants) {
        ItemStack item = new ItemStack(material);
        ItemMeta meta = item.getItemMeta();
        for (Map.Entry<Enchantment, Integer> enchant : enchants.entrySet()) {
            meta.addEnchant(enchant.getKey(), enchant.getValue().intValue(), true);
        }
        if (mending) {
            meta.addEnchant(Enchantment.MENDING, 1, true);
        }
        item.setItemMeta(meta);
        return item;
    }

    private ItemStack createNamedEnchanted(Material material, String displayName, boolean mending, Map<Enchantment, Integer> enchants) {
        ItemStack item = this.createEnchanted(material, mending, enchants);
        ItemMeta meta = item.getItemMeta();
        meta.setDisplayName(displayName);
        item.setItemMeta(meta);
        return item;
    }

    private ItemStack applyTrim(ItemStack source, TrimMaterial material, TrimPattern pattern) {
        ItemMeta meta = source.getItemMeta();
        if (meta instanceof ArmorMeta) {
            ArmorMeta armorMeta = (ArmorMeta)meta;
            armorMeta.setTrim(new ArmorTrim(material, pattern));
            source.setItemMeta((ItemMeta)armorMeta);
        }
        return source;
    }

    private List<String> prefixedLore(List<String> input) {
        if (input == null || input.isEmpty()) {
            return List.of();
        }
        ArrayList<String> out = new ArrayList<String>();
        for (String line : input) {
            out.add("\u00a77" + line);
        }
        return out;
    }

    private void logCrateReward(UUID uuid, String username, String crateKey, int shardsCost, int rewardCount) {
        String sql = "INSERT INTO crate_reward_log (uuid, username, crate_key, shards_cost, reward_count, server_name) VALUES (?, ?, ?, ?, ?, ?)";
        try (Connection conn = this.openSyncConnection();
             PreparedStatement ps = conn.prepareStatement(sql);){
            ps.setString(1, uuid.toString());
            ps.setString(2, username);
            ps.setString(3, crateKey);
            ps.setInt(4, shardsCost);
            ps.setInt(5, rewardCount);
            ps.setString(6, this.detectServerName());
            ps.executeUpdate();
        }
        catch (Exception ex) {
            this.getLogger().warning("Failed logging crate reward: " + ex.getMessage());
        }
    }

    private void logChatMessage(UUID uuid, String username, String serverName, String channel, String message) {
        if (message == null || message.isBlank()) {
            return;
        }
        String sql = "INSERT INTO network_chat_log (player_uuid, player_name, server_name, channel, message, source_plugin) VALUES (?, ?, ?, ?, ?, 'PizzaNetworkCore')";
        try (Connection conn = this.openSyncConnection();
             PreparedStatement ps = conn.prepareStatement(sql);){
            ps.setString(1, uuid.toString());
            ps.setString(2, username);
            ps.setString(3, serverName);
            ps.setString(4, channel == null || channel.isBlank() ? "global" : channel);
            ps.setString(5, message);
            ps.executeUpdate();
        }
        catch (Exception ex) {
            this.getLogger().warning("Failed logging chat message: " + ex.getMessage());
        }
    }

    /*
     * Enabled aggressive block sorting
     * Enabled unnecessary exception pruning
     * Enabled aggressive exception aggregation
     */
    private long getShardBalance(UUID uuid) {
        String sql = "SELECT shards FROM balances WHERE uuid=?";
        try (Connection conn = this.openSyncConnection();
             PreparedStatement ps = conn.prepareStatement(sql);){
            ps.setString(1, uuid.toString());
            try (ResultSet rs = ps.executeQuery();){
                if (!rs.next()) return 0L;
                long l = rs.getLong(1);
                return l;
            }
        }
        catch (Exception ex) {
            this.getLogger().warning("Failed reading shard balance: " + ex.getMessage());
        }
        return 0L;
    }

    /*
     * Enabled aggressive exception aggregation
     */
    private boolean withdrawShards(UUID uuid, long amount) {
        String sql = "UPDATE balances SET shards=shards-? WHERE uuid=? AND shards>=?";
        try (Connection conn = this.openSyncConnection();){
            boolean bl;
            block14: {
                PreparedStatement ps = conn.prepareStatement(sql);
                try {
                    ps.setLong(1, amount);
                    ps.setString(2, uuid.toString());
                    ps.setLong(3, amount);
                    boolean bl2 = bl = ps.executeUpdate() > 0;
                    if (ps == null) break block14;
                }
                catch (Throwable throwable) {
                    if (ps != null) {
                        try {
                            ps.close();
                        }
                        catch (Throwable throwable2) {
                            throwable.addSuppressed(throwable2);
                        }
                    }
                    throw throwable;
                }
                ps.close();
            }
            return bl;
        }
        catch (Exception ex) {
            this.getLogger().warning("Failed withdrawing shards: " + ex.getMessage());
            return false;
        }
    }

    private void depositShards(UUID uuid, long amount) {
        if (uuid == null || amount <= 0L) {
            return;
        }
        String sql = "INSERT INTO balances (uuid, shards) VALUES (?, ?) ON DUPLICATE KEY UPDATE shards = shards + VALUES(shards)";
        try (Connection conn = this.openSyncConnection();
             PreparedStatement ps = conn.prepareStatement(sql);){
            ps.setString(1, uuid.toString());
            ps.setLong(2, amount);
            ps.executeUpdate();
        }
        catch (Exception ex) {
            this.getLogger().warning("Failed depositing shards: " + ex.getMessage());
        }
    }

    private void updatePlaytimeSeconds(UUID uuid, long seconds) {
        if (uuid == null || seconds <= 0L) {
            return;
        }
        String sql = "UPDATE players SET playtime_seconds = playtime_seconds + ? WHERE uuid = ?";
        try (Connection conn = this.openSyncConnection();
             PreparedStatement ps = conn.prepareStatement(sql);){
            ps.setLong(1, seconds);
            ps.setString(2, uuid.toString());
            ps.executeUpdate();
        }
        catch (Exception ex) {
            this.getLogger().warning("Failed updating playtime: " + ex.getMessage());
        }
    }

    private void startPlaytimeAndAfkTask() {
        Runnable tick = () -> {
            long now = System.currentTimeMillis();
            for (Player player : Bukkit.getOnlinePlayers()) {
                long elapsed;
                UUID uuid = player.getUniqueId();
                Long flushAt = this.lastPlaytimeFlush.put(uuid, now);
                if (flushAt != null && (elapsed = (now - flushAt) / 1000L) > 0L) {
                    long secs = elapsed;
                    this.updatePlaytimeSeconds(uuid, secs);
                }
                // Passive shards: everyone earns 1/min online (active or AFK); pizza++ earns 2/min.
                this.depositShards(uuid, this.isPizzaPlusPlus(player) ? 2L : 1L);
                // Every 10 minutes online: a +20 shard "thanks for playing" bonus with a chat notice.
                int mins = this.shardBonusMinutes.merge(uuid, 1, Integer::sum);
                if (mins >= 10) {
                    this.shardBonusMinutes.put(uuid, 0);
                    this.depositShards(uuid, PLAYTIME_SHARD_BONUS);
                    this.runOnPlayerThread(player, () -> player.sendMessage(this.legacyColorize(
                        "&7You earned &d&l" + PLAYTIME_SHARD_BONUS + " shards&r&7 for playing the server")));
                }
            }
        };
        if (this.foliaRuntime) {
            Bukkit.getAsyncScheduler().runAtFixedRate((Plugin)this, st -> tick.run(), 60L, 60L, TimeUnit.SECONDS);
        } else {
            Bukkit.getScheduler().runTaskTimerAsynchronously((Plugin)this, tick, 1200L, 1200L);
        }
    }

    // Best-effort, idempotent schema statement. MySQL rejects some MariaDB-only syntax (e.g.
    // ADD COLUMN IF NOT EXISTS), so run each independently — one failure must not abort the rest.
    private void execSchema(Statement st, String sql) {
        try {
            st.execute(sql);
        } catch (SQLException e) {
            this.getLogger().fine("[schema] skipped: " + e.getMessage());
        }
    }

    // MySQL-safe "ADD COLUMN IF NOT EXISTS": MySQL/OCI does NOT support the MariaDB IF NOT EXISTS
    // clause on ALTER TABLE ADD COLUMN (it throws 1064 every boot). Check information_schema first and
    // only ALTER when the column is actually absent. {@code definition} is everything after the column
    // name, e.g. "TIMESTAMP NULL DEFAULT NULL AFTER created_at".
    private void addColumnIfMissing(Connection conn, Statement st, String table, String column, String definition) {
        try {
            boolean exists;
            try (PreparedStatement ps = conn.prepareStatement(
                    "SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = ? AND COLUMN_NAME = ? LIMIT 1")) {
                ps.setString(1, table);
                ps.setString(2, column);
                try (ResultSet rs = ps.executeQuery()) { exists = rs.next(); }
            }
            if (!exists) {
                st.execute("ALTER TABLE " + table + " ADD COLUMN " + column + " " + definition);
            }
        } catch (SQLException e) {
            this.getLogger().fine("[schema] addColumnIfMissing " + table + "." + column + " skipped: " + e.getMessage());
        }
    }

    private void ensureUiSchema() {
        String chatLogSql = "CREATE TABLE IF NOT EXISTS network_chat_log (id BIGINT AUTO_INCREMENT PRIMARY KEY,logged_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,player_uuid CHAR(36) NOT NULL,player_name VARCHAR(16) NOT NULL,server_name VARCHAR(32) NOT NULL,channel VARCHAR(16) NOT NULL DEFAULT 'global',message TEXT NOT NULL,source_plugin VARCHAR(32) NOT NULL DEFAULT 'PizzaNetworkCore',INDEX idx_chat_uuid (player_uuid),INDEX idx_chat_server (server_name),INDEX idx_chat_channel (channel),INDEX idx_chat_logged_at (logged_at))";
        String crateLogSql = "CREATE TABLE IF NOT EXISTS crate_reward_log (id BIGINT AUTO_INCREMENT PRIMARY KEY,uuid CHAR(36) NOT NULL,username VARCHAR(16) NOT NULL,crate_key VARCHAR(32) NOT NULL,shards_cost INT NOT NULL,reward_count INT NOT NULL,server_name VARCHAR(32) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_crate_uuid (uuid),INDEX idx_crate_created (created_at))";
        String dailyClaimSql = "CREATE TABLE IF NOT EXISTS shard_daily_claims (uuid CHAR(36) PRIMARY KEY, last_claim TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP)";
        String teleportRequestsSql = "CREATE TABLE IF NOT EXISTS network_teleport_requests (id BIGINT AUTO_INCREMENT PRIMARY KEY,requester_uuid CHAR(36) NOT NULL,requester_name VARCHAR(16) NOT NULL,target_uuid CHAR(36) NOT NULL,target_name VARCHAR(16) NOT NULL,request_type VARCHAR(16) NOT NULL,requester_server VARCHAR(32) NOT NULL,target_server VARCHAR(32) NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'PENDING',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,expires_at TIMESTAMP NOT NULL,responded_at TIMESTAMP NULL DEFAULT NULL,INDEX idx_tp_target_pending (target_uuid, status, expires_at),INDEX idx_tp_requester_pending (requester_uuid, status, expires_at))";
        String notificationSql = "CREATE TABLE IF NOT EXISTS network_player_notifications (id BIGINT AUTO_INCREMENT PRIMARY KEY,recipient_uuid CHAR(36) NOT NULL,message TEXT NOT NULL,action VARCHAR(96) NOT NULL DEFAULT '',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,expires_at TIMESTAMP NOT NULL,INDEX idx_notify_recipient (recipient_uuid, expires_at))";
        String auctionListingsSql = "CREATE TABLE IF NOT EXISTS auction_listings (id BIGINT AUTO_INCREMENT PRIMARY KEY,seller_uuid CHAR(36) NOT NULL,buyer_uuid CHAR(36) NULL,item_blob LONGBLOB NOT NULL,item_key VARCHAR(96) NOT NULL,price DOUBLE NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',expires_at TIMESTAMP NULL DEFAULT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_auction_status_created (status, created_at),INDEX idx_auction_seller_status (seller_uuid, status))";
        String auctionPayoutsSql = "CREATE TABLE IF NOT EXISTS auction_payouts (id BIGINT AUTO_INCREMENT PRIMARY KEY,recipient_uuid CHAR(36) NOT NULL,listing_id BIGINT NOT NULL,amount DOUBLE NOT NULL,claimed TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_auction_payout_recipient (recipient_uuid, claimed))";
        String orderListingsSql = "CREATE TABLE IF NOT EXISTS order_listings (id BIGINT AUTO_INCREMENT PRIMARY KEY,creator_uuid CHAR(36) NOT NULL,item_key VARCHAR(96) NOT NULL,amount_total INT NOT NULL,amount_filled INT NOT NULL DEFAULT 0,unit_price DOUBLE NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,expires_at TIMESTAMP NULL DEFAULT NULL,INDEX idx_order_status_created (status, created_at),INDEX idx_order_creator_status (creator_uuid, status))";
        String orderDeliveriesSql = "CREATE TABLE IF NOT EXISTS order_deliveries (id BIGINT AUTO_INCREMENT PRIMARY KEY,order_id BIGINT NOT NULL,fulfiller_uuid CHAR(36) NOT NULL,amount INT NOT NULL,payout DOUBLE NOT NULL,item_blob LONGBLOB NULL,claimed TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,claimed_at TIMESTAMP NULL DEFAULT NULL,INDEX idx_order_delivery_order (order_id),INDEX idx_order_delivery_claimed (claimed))";
        try (Connection conn = this.openSyncConnection();
             Statement st = conn.createStatement();){
            this.addColumnIfMissing(conn, st, "player_settings", "settings_blob", "LONGTEXT NULL");
            this.addColumnIfMissing(conn, st, "balances", "pending_vault_credit", "DECIMAL(18,4) NOT NULL DEFAULT 0");
            this.addColumnIfMissing(conn, st, "player_stats", "blocks_placed", "BIGINT NOT NULL DEFAULT 0");
            this.addColumnIfMissing(conn, st, "player_stats", "blocks_broken", "BIGINT NOT NULL DEFAULT 0");
            this.addColumnIfMissing(conn, st, "player_stats", "mobs_killed", "BIGINT NOT NULL DEFAULT 0");
            this.addColumnIfMissing(conn, st, "player_stats", "shop_spent", "DECIMAL(18,2) NOT NULL DEFAULT 0");
            this.addColumnIfMissing(conn, st, "player_stats", "sell_earned", "DECIMAL(18,2) NOT NULL DEFAULT 0");
            this.execSchema(st, chatLogSql);
            this.execSchema(st, crateLogSql);
            this.execSchema(st, dailyClaimSql);
            this.execSchema(st, teleportRequestsSql);
            this.execSchema(st, notificationSql);
            this.execSchema(st, auctionListingsSql);
            this.execSchema(st, auctionPayoutsSql);
            this.execSchema(st, orderListingsSql);
            this.execSchema(st, orderDeliveriesSql);
            // Limbo maintenance: per-player snapshot the limbo reads to render them "frozen in place".
            this.execSchema(st, "CREATE TABLE IF NOT EXISTS limbo_snapshots (uuid CHAR(36) PRIMARY KEY,world VARCHAR(64) NOT NULL,x DOUBLE NOT NULL,y DOUBLE NOT NULL,z DOUBLE NOT NULL,yaw FLOAT NOT NULL,pitch FLOAT NOT NULL,inv_blob LONGBLOB NULL,ender_blob LONGBLOB NULL,blocks_blob LONGBLOB NULL,captured_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP)");
            // Single-row control channel: /limbomaint stop sets return_all_at; the limbo polls it to force-return stuck players.
            // smp_ready_at is bumped to NOW() once the SMP has fully booted (ServerLoadEvent) so the limbo can return
            // players the instant the SMP is actually ready, instead of waiting a blanket TCP-up grace period.
            this.execSchema(st, "CREATE TABLE IF NOT EXISTS limbo_control (id TINYINT PRIMARY KEY, return_all_at TIMESTAMP NULL DEFAULT NULL, smp_ready_at TIMESTAMP NULL DEFAULT NULL)");
            this.addColumnIfMissing(conn, st, "limbo_control", "smp_ready_at", "TIMESTAMP NULL DEFAULT NULL");
            this.addColumnIfMissing(conn, st, "limbo_control", "branding_reload_at", "TIMESTAMP NULL DEFAULT NULL");
            this.addColumnIfMissing(conn, st, "limbo_control", "closed_worlds", "VARCHAR(255) NOT NULL DEFAULT ''");
            this.addColumnIfMissing(conn, st, "order_listings", "updated_at", "TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP AFTER created_at");
            this.addColumnIfMissing(conn, st, "order_listings", "expires_at", "TIMESTAMP NULL DEFAULT NULL AFTER updated_at");
            // Order-matching engine: enchantment requirement for this order.
            //   '*'         = wildcard, accepts any/no enchants
            //   ''  (empty) = plain only, accepts only UNENCHANTED items
            //   'ench:lvl,…'= accepts items that CONTAIN at least those enchants at >= those levels
            this.addColumnIfMissing(conn, st, "order_listings", "enchant_spec", "VARCHAR(255) NOT NULL DEFAULT '*'");
            this.addColumnIfMissing(conn, st, "order_deliveries", "item_blob", "LONGBLOB NULL AFTER payout");
            this.addColumnIfMissing(conn, st, "order_deliveries", "claimed_at", "TIMESTAMP NULL DEFAULT NULL AFTER created_at");
            String sellmultiSql = "CREATE TABLE IF NOT EXISTS sell_multiplier_progress (id BIGINT AUTO_INCREMENT PRIMARY KEY,player_uuid CHAR(36) NOT NULL,category VARCHAR(32) NOT NULL,level INT NOT NULL DEFAULT 0,earned DECIMAL(18,2) NOT NULL DEFAULT 0,claimed_up_to INT NOT NULL DEFAULT 0,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uk_sellmulti (player_uuid, category))";
            this.execSchema(st, sellmultiSql);
            String teamsTableSql = "CREATE TABLE IF NOT EXISTS teams (id BIGINT AUTO_INCREMENT PRIMARY KEY,team_name VARCHAR(32) NOT NULL,owner_uuid CHAR(36) NOT NULL,pvp_enabled TINYINT(1) NOT NULL DEFAULT 0,home_world VARCHAR(64) NULL,home_x DOUBLE NULL,home_y DOUBLE NULL,home_z DOUBLE NULL,home_yaw FLOAT NULL,home_pitch FLOAT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uk_team_name (team_name),INDEX idx_teams_owner (owner_uuid))";
            String teamMembersTableSql = "CREATE TABLE IF NOT EXISTS team_members (id BIGINT AUTO_INCREMENT PRIMARY KEY,team_id BIGINT NOT NULL,member_uuid CHAR(36) NOT NULL,role VARCHAR(16) NOT NULL DEFAULT 'member',team_chat_mode TINYINT(1) NOT NULL DEFAULT 0,joined_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uk_team_member (team_id,member_uuid),INDEX idx_team_member_uuid (member_uuid))";
            String teamInvitesSql = "CREATE TABLE IF NOT EXISTS team_invites (id BIGINT AUTO_INCREMENT PRIMARY KEY,team_id BIGINT NOT NULL,invitee_uuid CHAR(36) NOT NULL,invited_by_uuid CHAR(36) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,expires_at TIMESTAMP NOT NULL,UNIQUE KEY uk_invite (team_id,invitee_uuid),INDEX idx_invite_invitee (invitee_uuid))";
            this.execSchema(st, teamsTableSql);
            this.execSchema(st, teamMembersTableSql);
            this.execSchema(st, teamInvitesSql);
            this.addColumnIfMissing(conn, st, "teams", "pvp_enabled", "TINYINT(1) NOT NULL DEFAULT 0 AFTER owner_uuid");
            String anticheatViolationsSql = "CREATE TABLE IF NOT EXISTS anticheat_violations (id BIGINT AUTO_INCREMENT PRIMARY KEY,player_uuid CHAR(36) NOT NULL,player_name VARCHAR(16) NOT NULL,violation_type VARCHAR(64) NOT NULL,severity VARCHAR(16) NOT NULL DEFAULT 'MEDIUM',description TEXT NULL,check_name VARCHAR(96) NULL,vl_points DOUBLE NOT NULL DEFAULT 0,plugin_name VARCHAR(32) NOT NULL DEFAULT 'GrimAC',server_name VARCHAR(32) NOT NULL,reported_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,reviewed TINYINT(1) NOT NULL DEFAULT 0,reviewed_by CHAR(36) NULL,reviewed_at TIMESTAMP NULL,action_taken VARCHAR(32) NULL,action_details TEXT NULL,INDEX idx_violation_player (player_uuid, reported_at),INDEX idx_violation_reviewed (reviewed, reported_at),INDEX idx_violation_severity (severity, reported_at))";
            this.execSchema(st, anticheatViolationsSql);
            String transactionAuditSql = "CREATE TABLE IF NOT EXISTS transaction_audit_log (id BIGINT AUTO_INCREMENT PRIMARY KEY,player_uuid CHAR(36) NOT NULL,player_name VARCHAR(16) NOT NULL,event_type VARCHAR(32) NOT NULL,item_key VARCHAR(96) NOT NULL,amount INT NOT NULL DEFAULT 1,unit_price DOUBLE NOT NULL DEFAULT 0,total_price DOUBLE NOT NULL DEFAULT 0,extra_info VARCHAR(255) NULL,server_name VARCHAR(32) NOT NULL,logged_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_audit_player (player_uuid, logged_at),INDEX idx_audit_event (event_type, logged_at))";
            this.execSchema(st, transactionAuditSql);
            String deathChestsSql = "CREATE TABLE IF NOT EXISTS death_chests (id BIGINT AUTO_INCREMENT PRIMARY KEY,player_uuid CHAR(36) NOT NULL,player_name VARCHAR(16) NOT NULL,world_name VARCHAR(64) NOT NULL,x DOUBLE NOT NULL,y DOUBLE NOT NULL,z DOUBLE NOT NULL,items_blob LONGBLOB NOT NULL,xp_levels INT NOT NULL DEFAULT 0,xp_points FLOAT NOT NULL DEFAULT 0,claimed TINYINT(1) NOT NULL DEFAULT 0,killed_by_name VARCHAR(16) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,claimed_at TIMESTAMP NULL,INDEX idx_death_chest_unclaimed (player_uuid, claimed))";
            this.execSchema(st, deathChestsSql);
            String bountiesSql = "CREATE TABLE IF NOT EXISTS bounties (id BIGINT AUTO_INCREMENT PRIMARY KEY,placer_uuid CHAR(36) NOT NULL,target_uuid CHAR(36) NOT NULL,amount DOUBLE NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',claimer_uuid CHAR(36) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,claimed_at TIMESTAMP NULL,INDEX idx_bounty_target (target_uuid, status),INDEX idx_bounty_placer (placer_uuid, status))";
            this.execSchema(st, bountiesSql);
            String commandLogSql = "CREATE TABLE IF NOT EXISTS command_log (id BIGINT AUTO_INCREMENT PRIMARY KEY,player_uuid CHAR(36) NOT NULL,player_name VARCHAR(16) NOT NULL,command TEXT NOT NULL,server_name VARCHAR(32) NOT NULL,logged_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_cmd_player (player_uuid, logged_at),INDEX idx_cmd_logged (logged_at))";
            this.execSchema(st, commandLogSql);
            // Friends system (replaces teams): one row per relationship; PENDING rows are
            // requests from requester->target, ACCEPTED rows are mutual (queried both directions).
            String friendsSql = "CREATE TABLE IF NOT EXISTS friends (id BIGINT AUTO_INCREMENT PRIMARY KEY,requester_uuid CHAR(36) NOT NULL,target_uuid CHAR(36) NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'PENDING',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,responded_at TIMESTAMP NULL DEFAULT NULL,UNIQUE KEY uk_friend_pair (requester_uuid,target_uuid),INDEX idx_friend_target_status (target_uuid,status),INDEX idx_friend_requester_status (requester_uuid,status))";
            this.execSchema(st, friendsSql);
        }
        catch (Exception ex) {
            this.getLogger().warning("Failed applying UI schema migration: " + ex.getMessage());
        }
        // Follow model: created in its OWN block so an earlier failure can't skip it. One-directional
        // follow; mutual follow = friends. Per-relationship toggles live on the follower's row.
        this.ensureFollowsSchema();
    }

    private void ensureFollowsSchema() {
        String followsSql = "CREATE TABLE IF NOT EXISTS follows (" +
            "follower_uuid CHAR(36) NOT NULL," +
            "target_uuid CHAR(36) NOT NULL," +
            "created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP," +
            "see_activity TINYINT(1) NOT NULL DEFAULT 1," +
            "see_transactions TINYINT(1) NOT NULL DEFAULT 1," +
            "can_message TINYINT(1) NOT NULL DEFAULT 1," +
            "can_tpa TINYINT(1) NOT NULL DEFAULT 1," +
            "auto_accept_tpa TINYINT(1) NOT NULL DEFAULT 1," +
            "can_pay TINYINT(1) NOT NULL DEFAULT 1," +
            "PRIMARY KEY (follower_uuid, target_uuid)," +
            "INDEX idx_follow_target (target_uuid))";
        try (Connection conn = this.openSyncConnection();
             Statement st = conn.createStatement()) {
            this.execSchema(st, followsSql);
            // One-shot migration (flag-guarded so it never re-adds an unfollowed pair).
            java.io.File followFlag = new java.io.File(this.getDataFolder(), "follows-migrated.flag");
            if (!followFlag.exists()) {
                this.execSchema(st, "INSERT IGNORE INTO follows (follower_uuid, target_uuid) " +
                    "SELECT requester_uuid, target_uuid FROM friends WHERE status='ACCEPTED'");
                this.execSchema(st, "INSERT IGNORE INTO follows (follower_uuid, target_uuid) " +
                    "SELECT target_uuid, requester_uuid FROM friends WHERE status='ACCEPTED'");
                try { this.getDataFolder().mkdirs(); followFlag.createNewFile(); } catch (Exception ignored) {}
            }
        } catch (Exception ex) {
            this.getLogger().warning("Failed creating follows schema: " + ex.getMessage());
        }
    }

