    private Map<String, Boolean> loadPlayerSettings(UUID uuid) {
        Map<String, Boolean> values = this.defaultSettings();
        String select = "SELECT settings_blob FROM player_settings WHERE uuid=?";
        String insert = "INSERT INTO player_settings (uuid, settings_blob) VALUES (?, ?) ON DUPLICATE KEY UPDATE settings_blob=VALUES(settings_blob)";
        try (Connection conn = this.openSyncConnection();
             PreparedStatement ps = conn.prepareStatement(select);){
            ps.setString(1, uuid.toString());
            try (ResultSet rs = ps.executeQuery();){
                if (rs.next()) {
                    String blob = rs.getString(1);
                    values.putAll(this.parseSettingsBlob(blob));
                    Map<String, Boolean> map = values;
                    return map;
                }
            }
            try (PreparedStatement create = conn.prepareStatement(insert);){
                create.setString(1, uuid.toString());
                create.setString(2, this.settingsBlob(values));
                create.executeUpdate();
                return values;
            }
        }
        catch (Exception ex) {
            this.getLogger().warning("Failed loading player settings: " + ex.getMessage());
        }
        return values;
    }

    private void savePlayerSettings(UUID uuid, Map<String, Boolean> values) {
        String sql = "INSERT INTO player_settings (uuid, settings_blob) VALUES (?, ?) ON DUPLICATE KEY UPDATE settings_blob=VALUES(settings_blob), updated_at=CURRENT_TIMESTAMP";
        try (Connection conn = this.openSyncConnection();
             PreparedStatement ps = conn.prepareStatement(sql);){
            ps.setString(1, uuid.toString());
            ps.setString(2, this.settingsBlob(values));
            ps.executeUpdate();
        }
        catch (Exception ex) {
            this.getLogger().warning("Failed saving player settings: " + ex.getMessage());
        }
    }

    private String settingsBlob(Map<String, Boolean> values) {
        StringBuilder sb = new StringBuilder();
        for (SettingDefinition def : SETTINGS_DEFINITIONS) {
            boolean enabled = values.getOrDefault(def.key, def.defaultValue);
            sb.append(def.key).append('=').append(enabled ? (char)'1' : '0').append('\n');
        }
        // Tri-state privacy modifiers (<key>_friends) are NOT in SETTINGS_DEFINITIONS, so persist
        // them explicitly — otherwise "Friends & Followers" is dropped on save and can never stick.
        for (String key : PRIVACY_TRISTATE) {
            if (values.getOrDefault(key + "_friends", false)) {
                sb.append(key).append("_friends=1\n");
            }
        }
        return sb.toString();
    }

    private Map<String, Boolean> parseSettingsBlob(String blob) {
        String[] lines;
        if (blob == null || blob.isBlank()) {
            return Collections.emptyMap();
        }
        HashMap<String, Boolean> out = new HashMap<String, Boolean>();
        for (String raw : lines = blob.split("\\R")) {
            if (raw == null || raw.isBlank() || !raw.contains("=")) continue;
            String[] kv = raw.split("=", 2);
            String key = kv[0].trim().toLowerCase();
            String val = kv[1].trim();
            out.put(key, "1".equals(val) || "true".equalsIgnoreCase(val));
        }
        return out;
    }

    private Map<String, Boolean> defaultSettings() {
        LinkedHashMap<String, Boolean> values = new LinkedHashMap<String, Boolean>();
        for (SettingDefinition def : SETTINGS_DEFINITIONS) {
            values.put(def.key, def.defaultValue);
        }
        return values;
    }

    private boolean defaultSettingValue(String key) {
        for (SettingDefinition def : SETTINGS_DEFINITIONS) {
            if (!def.key.equals(key)) continue;
            return def.defaultValue;
        }
        return true;
    }

    private boolean isSettingEnabledCached(UUID uuid, String key) {
        if (uuid == null || key == null) {
            return true;
        }
        Map<String, Boolean> values = this.playerSettingsCache.get(uuid);
        if (values == null) {
            return this.defaultSettingValue(key);
        }
        return values.getOrDefault(key, this.defaultSettingValue(key));
    }

    private boolean isQuietSpawnActive(Player player) {
        if (player == null || !player.isOnline()) {
            return false;
        }
        if (!this.isSettingEnabledCached(player.getUniqueId(), "quiet_spawn")) {
            return false;
        }
        return this.isServer("lobby") || this.isServer("maintenance");
    }

    private boolean showChatServerMessage(Player player) {
        if (this.isQuietSpawnActive(player)) {
            return false;
        }
        return this.isSettingEnabledCached(player.getUniqueId(), "chat_server_messages");
    }

    private boolean showHotbarServerMessage(Player player) {
        if (this.isQuietSpawnActive(player)) {
            return false;
        }
        return this.isSettingEnabledCached(player.getUniqueId(), "hotbar_server_messages");
    }

    private int parseIntSafe(String raw, int fallback) {
        try {
            return Integer.parseInt(raw);
        }
        catch (Exception ignored) {
            return fallback;
        }
    }

    private ParsedAmount parseCompactAmount(String raw) {
        if (raw == null) {
            return null;
        }
        String cleaned = raw.trim().replace(",", "").toUpperCase(Locale.ROOT);
        if (cleaned.isEmpty()) {
            return null;
        }
        double multiplier = 1.0;
        if (cleaned.endsWith("K")) {
            multiplier = 1000.0;
            cleaned = cleaned.substring(0, cleaned.length() - 1);
        } else if (cleaned.endsWith("M")) {
            multiplier = 1000000.0;
            cleaned = cleaned.substring(0, cleaned.length() - 1);
        } else if (cleaned.endsWith("B")) {
            multiplier = 1.0E9;
            cleaned = cleaned.substring(0, cleaned.length() - 1);
        }
        if (cleaned.isEmpty()) {
            return null;
        }
        try {
            String normalized;
            double value = Double.parseDouble(cleaned) * multiplier;
            if (!Double.isFinite(value) || value < 0.0) {
                return null;
            }
            if (Math.abs(value - Math.rint(value)) < 1.0E-7) {
                normalized = Long.toString((long)Math.rint(value));
            } else {
                normalized = String.format(Locale.US, "%.2f", value);
                while (normalized.contains(".") && (normalized.endsWith("0") || normalized.endsWith("."))) {
                    normalized = normalized.substring(0, normalized.length() - 1);
                }
            }
            return new ParsedAmount(value, normalized);
        }
        catch (NumberFormatException ignored) {
            return null;
        }
    }

