    private void openAuctionHouseMenu(Player player) {
        AhViewState state = this.ahViewState.computeIfAbsent(player.getUniqueId(), id -> new AhViewState());
        state.viewerUuid = player.getUniqueId().toString();
        this.runAsyncTask(() -> {
            List<AhListingEntry> listings = this.queryAhListings(state);
            this.runOnPlayerThread(player, () -> this.renderAhMain(player, listings, state));
        });
    }

    private void renderAhMain(Player player, List<AhListingEntry> entries, AhViewState state) {
        if (player == null || !player.isOnline()) {
            return;
        }
        // Cache the rendered listings so a buy can refresh INSTANTLY in-memory (no DB re-query).
        state.cachedListings = new ArrayList<>(entries);
        Inventory inv = Bukkit.createInventory(null, (int)54, (String)TITLE_AH);
        this.renderAhListingEntries(inv, entries, state.page);
        inv.setItem(47, this.namedWithLore(Material.CAULDRON, "\u00a7aSort: \u00a7f" + state.sort, "ah_sort", List.of("\u00a77\u2022 Highest price", "\u00a77\u2022 Lowest price", "\u00a77\u2022 Last listed", "\u00a77\u2022 Recently listed")));
        inv.setItem(48, this.namedWithLore(Material.HOPPER, "\u00a7aFilter: \u00a7f" + state.filter, "ah_filter", List.of("\u00a77\u2022 All", "\u00a77\u2022 Blocks", "\u00a77\u2022 Tools", "\u00a77\u2022 Food", "\u00a77\u2022 Combat", "\u00a77\u2022 Potions", "\u00a77\u2022 Books", "\u00a77\u2022 Ingredients", "\u00a77\u2022 Utilities")));
        inv.setItem(49, this.namedWithLore(Material.PAPER, "\u00a7aAuction House", "ah_refresh", List.of()));
        inv.setItem(50, this.namedWithLore(Material.OAK_SIGN, "\u00a7aSearch", "ah_search", List.of()));
        inv.setItem(51, this.namedWithLore(Material.CHEST, "\u00a7aYour items", "ah_my_items", List.of()));
        inv.setItem(52, this.namedWithLore(Material.EMERALD, "\u00a7aSell item", "ah_sell", List.of("\u00a7fList the item in your hand", "\u00a77Or open the insert menu")));
        if (state.page > 1) {
            inv.setItem(45, this.namedWithLore(Material.ARROW, "\u00a7aBack", "ah_prev", List.of()));
        }
        if (entries.size() > state.page * 45) {
            inv.setItem(53, this.namedWithLore(Material.ARROW, "\u00a7aNext", "ah_next", List.of()));
        }
        player.openInventory(inv);
    }

    private void renderAhListingEntries(Inventory inv, List<AhListingEntry> entries, int page) {
        int start = Math.max(0, (page - 1) * 45);
        int end = Math.min(entries.size(), start + 45);
        int slot = 0;
        for (int i = start; i < end; ++i) {
            AhListingEntry e = entries.get(i);
            ItemStack item = e.item.clone();
            ItemMeta meta = item.getItemMeta();
            ArrayList<String> lore = new ArrayList<String>();
            lore.add("\u00a7fPrice: \u00a7f$" + this.fmtMoney(e.price));
            lore.add("\u00a77Seller: \u00a7f" + e.sellerName);
            lore.add("\u00a77Listed: \u00a7f" + this.shortAge(e.createdAtMs));
            meta.setLore(lore);
            if (this.uiActionKey != null) {
                meta.getPersistentDataContainer().set(this.uiActionKey, PersistentDataType.STRING, "ah_listing:" + e.id);
            }
            item.setItemMeta(meta);
            inv.setItem(slot++, item);
        }
    }

    private void renderAhMyListingEntries(Inventory inv, List<AhListingEntry> entries, int page) {
        int start = Math.max(0, (page - 1) * 45);
        int end = Math.min(entries.size(), start + 45);
        int slot = 0;
        for (int i = start; i < end; ++i) {
            AhListingEntry e = entries.get(i);
            ItemStack item = e.item.clone();
            ItemMeta meta = item.getItemMeta();
            meta.setLore(List.of("\u00a7fPrice: \u00a7f$" + this.fmtMoney(e.price), "\u00a77Listed: \u00a7f" + this.shortAge(e.createdAtMs), "\u00a7cClick to cancel listing"));
            if (this.uiActionKey != null) {
                meta.getPersistentDataContainer().set(this.uiActionKey, PersistentDataType.STRING, "ah_mine_listing:" + e.id);
            }
            item.setItemMeta(meta);
            inv.setItem(slot++, item);
        }
    }

    private void openOrdersMenu(Player player) {
        OrdersViewState state = this.ordersViewState.computeIfAbsent(player.getUniqueId(), id -> new OrdersViewState());
        state.viewerUuid = player.getUniqueId().toString();
        this.runAsyncTask(() -> {
            List<OrderEntry> orders = this.queryOrders(state);
            this.runOnPlayerThread(player, () -> this.renderOrdersMain(player, orders, state));
        });
    }

    // After an order fills or is cancelled, re-render it for every OTHER player browsing orders so the
    // change shows up instantly (the orders browse re-queries the DB, so this just re-opens their view).
    private void refreshOrdersForViewers(UUID exclude) {
        for (Player viewer : Bukkit.getOnlinePlayers()) {
            if (viewer.getUniqueId().equals(exclude)) continue;
            String t = viewer.getOpenInventory().getTitle();
            if (TITLE_ORDERS.equals(t)) {
                this.openOrdersMenu(viewer); // reuses the viewer's existing state (page/filter/sort)
            } else if (TITLE_ORDERS_ITEM.equals(t)) {
                OrdersViewState st = this.ordersViewState.get(viewer.getUniqueId());
                if (st != null && st.itemFilter != null) {
                    final String itemFilter = st.itemFilter;
                    this.runAsyncTask(() -> {
                        List<OrderEntry> orders = this.queryOrdersForItem(itemFilter, st);
                        this.runOnPlayerThread(viewer, () -> this.renderOrdersItemList(viewer, orders, st));
                    });
                }
            }
        }
    }

    private void renderOrdersMain(Player player, List<OrderEntry> orders, OrdersViewState state) {
        if (player == null || !player.isOnline()) {
            return;
        }
        Inventory inv = Bukkit.createInventory(null, (int)54, (String)TITLE_ORDERS);
        int start = Math.max(0, (state.page - 1) * 45);
        int end = Math.min(orders.size(), start + 45);
        for (int i = start; i < end; ++i) {
            OrderEntry o = orders.get(i);
            ItemStack item = new ItemStack(o.material());
            ItemMeta meta = item.getItemMeta();
            meta.setDisplayName("\u00a7b" + this.humanName(o.material()));
            if (this.uiActionKey != null) {
                meta.getPersistentDataContainer().set(this.uiActionKey, PersistentDataType.STRING, "orders_listing:" + o.id());
            }
            ArrayList<String> lore = new ArrayList<String>();
            lore.add("\u00a77Remaining: \u00a7f" + o.remainingAmount() + "/" + o.amountTotal());
            lore.add("\u00a77Price per: \u00a7f$" + this.fmtMoney(o.unitPrice()));
            lore.add("\u00a77Creator: \u00a7f" + o.creatorName());
            lore.add("\u00a77Listed: \u00a7f" + this.shortAge(o.createdAtMs()));
            lore.add("\u00a77Expires in: \u00a7f" + this.timeUntil(o.expiresAtMs()));
            lore.add("\u00a7aClick to deliver");
            meta.setLore(lore);
            item.setItemMeta(meta);
            inv.setItem(i - start, item);
        }
        int total = orders.size();
        int maxPage = Math.max(1, (int)Math.ceil((double)total / 45.0));
        // Green control layout, matching the Auction House (no glass background).
        if (state.page > 1) {
            inv.setItem(45, this.namedWithLore(Material.ARROW, "\u00a7aPrev", "orders_prev", List.of("\u00a77Page " + (state.page - 1))));
        }
        inv.setItem(46, this.namedWithLore(Material.OAK_SIGN, "\u00a7aPage \u00a7f" + state.page + "\u00a7a/\u00a7f" + maxPage, "orders_page", List.of("\u00a77" + total + " active order(s)")));
        inv.setItem(47, this.namedWithLore(Material.CAULDRON, "\u00a7aSort: \u00a7f" + state.sort, "orders_sort", List.of("\u00a77\u2022 Best price", "\u00a77\u2022 Most orders", "\u00a77\u2022 Most remaining", "\u00a77\u2022 Recently listed")));
        inv.setItem(48, this.namedWithLore(Material.HOPPER, "\u00a7aFilter: \u00a7f" + state.filter, "orders_filter", List.of("\u00a77\u2022 All", "\u00a77\u2022 Blocks", "\u00a77\u2022 Tools", "\u00a77\u2022 Food", "\u00a77\u2022 Combat", "\u00a77\u2022 Potions", "\u00a77\u2022 Books", "\u00a77\u2022 Ingredients", "\u00a77\u2022 Utilities")));
        inv.setItem(49, this.namedWithLore(Material.PAPER, "\u00a7aOrders", "orders_refresh", List.of()));
        inv.setItem(50, this.namedWithLore(Material.OAK_SIGN, "\u00a7aSearch", "orders_search", List.of()));
        inv.setItem(51, this.namedWithLore(Material.CHEST, "\u00a7aYour orders", "orders_my", List.of()));
        if (state.page < maxPage) {
            inv.setItem(53, this.namedWithLore(Material.ARROW, "\u00a7aNext", "orders_next", List.of("\u00a77Page " + (state.page + 1))));
        }
        player.openInventory(inv);
    }

    private void openOrdersItemMenu(Player player, String materialName) {
        OrdersViewState state = this.ordersViewState.computeIfAbsent(player.getUniqueId(), id -> new OrdersViewState());
        state.itemFilter = materialName;
        state.itemPage = 1;
        state.viewerUuid = player.getUniqueId().toString();
        this.runAsyncTask(() -> {
            List<OrderEntry> orders = this.queryOrdersForItem(materialName, state);
            this.runOnPlayerThread(player, () -> this.renderOrdersItemList(player, orders, state));
        });
    }

    private void renderOrdersItemList(Player player, List<OrderEntry> orders, OrdersViewState state) {
        if (player == null || !player.isOnline()) return;
        Inventory inv = Bukkit.createInventory(null, (int)54, (String)TITLE_ORDERS_ITEM);
        int start = Math.max(0, (state.itemPage - 1) * 45);
        int end = Math.min(orders.size(), start + 45);
        for (int i = start; i < end; ++i) {
            OrderEntry o = orders.get(i);
            ItemStack item = new ItemStack(o.material());
            ItemMeta meta = item.getItemMeta();
            meta.setDisplayName("\u00a7b" + this.humanName(o.material()));
            if (this.uiActionKey != null) {
                meta.getPersistentDataContainer().set(this.uiActionKey, PersistentDataType.STRING, "orders_listing:" + o.id());
            }
            ArrayList<String> lore = new ArrayList<String>();
            lore.add("\u00a77Remaining: \u00a7f" + o.remainingAmount() + "/" + o.amountTotal());
            lore.add("\u00a77Price per: \u00a7f$" + this.fmtMoney(o.unitPrice()));
            lore.add("\u00a77Creator: \u00a7f" + o.creatorName());
            lore.add("\u00a77Listed: \u00a7f" + this.shortAge(o.createdAtMs()));
            lore.add("\u00a77Expires in: \u00a7f" + this.timeUntil(o.expiresAtMs()));
            lore.add("\u00a7aClick to deliver");
            meta.setLore(lore);
            item.setItemMeta(meta);
            inv.setItem(i - start, item);
        }
        inv.setItem(45, this.namedWithLore(Material.ARROW, "\u00a7aBack to Orders", "orders_item_back", List.of()));
        if (state.itemPage > 1) {
            inv.setItem(46, this.namedWithLore(Material.ARROW, "\u00a7aPrev", "orders_item_prev", List.of("\u00a77Page " + (state.itemPage - 1))));
        }
        int maxPage = (int)Math.ceil((double)orders.size() / 45.0);
        inv.setItem(47, this.namedWithLore(Material.OAK_SIGN, "\u00a7aPage \u00a7f" + state.itemPage + "\u00a7a/\u00a7f" + Math.max(1, maxPage), "orders_item_page", List.of()));
        inv.setItem(51, this.namedWithLore(Material.CHEST, "\u00a7aYour orders", "orders_my", List.of()));
        if (orders.size() > state.itemPage * 45) {
            inv.setItem(53, this.namedWithLore(Material.ARROW, "\u00a7aNext", "orders_item_next", List.of("\u00a77Page " + (state.itemPage + 1))));
        }
        player.openInventory(inv);
    }

    private void openOrdersMyMenu(Player player) {
        OrdersViewState state = this.ordersViewState.computeIfAbsent(player.getUniqueId(), id -> new OrdersViewState());
        this.runAsyncTask(() -> {
            List<OrderEntry> orders = this.queryOrdersForCreator(player.getUniqueId(), state);
            int pendingDeliveries = this.queryPendingOrderDeliveries(player.getUniqueId()).size();
            this.runOnPlayerThread(player, () -> this.renderOrdersMy(player, orders, pendingDeliveries, state));
        });
    }

    private void renderOrdersMy(Player player, List<OrderEntry> orders, int pendingDeliveries, OrdersViewState state) {
        Inventory inv = Bukkit.createInventory(null, (int)54, (String)TITLE_ORDERS_MY);
        // Tiered slot grid: active orders fill from slot 0, then GRAY "empty" slots up to the
        // rank cap (click to create), then RED locked slots (unlock with Pizza+/Pizza++).
        int cap = this.marketSlotCap(player);
        this.renderOwnOrdersEntries(inv, orders, 1);
        int n = Math.min(orders.size(), 45);
        this.fillMarketSlots(inv, n, cap, "orders_new_slot", "\u00a77Empty Order Slot", "\u00a7fClick to create an order");
        if (pendingDeliveries > 0) {
            inv.setItem(47, this.namedWithLore(Material.CHEST, "\u00a7aClaim deliveries \u00a7f(" + pendingDeliveries + ")", "orders_my_claim_all", List.of("\u00a77Items ready to collect")));
        }
        inv.setItem(49, this.namedWithLore(Material.HOPPER, "\u00a7aFilter: \u00a7f" + state.filter, "orders_my_filter", List.of("\u00a77Click to change")));
        inv.setItem(50, this.namedWithLore(Material.ARROW, "\u00a7aBack to Orders", "orders_main", List.of()));
        player.openInventory(inv);
    }

    /** Fills slots [activeCount,45): GRAY click-to-use up to the rank cap, then RED locked beyond it. */
    private void fillMarketSlots(Inventory inv, int activeCount, int cap, String grayAction, String grayLabel, String grayLore) {
        for (int i = activeCount; i < 45; i++) {
            if (i < cap) {
                inv.setItem(i, this.namedWithLore(Material.GRAY_STAINED_GLASS_PANE, grayLabel, grayAction, List.of(grayLore)));
            } else {
                inv.setItem(i, this.namedWithLore(Material.RED_STAINED_GLASS_PANE, "\u00a7cLocked Slot", "market_locked", List.of("\u00a77Unlock more slots with", "\u00a76" + this.brandTierPlus + " \u00a77/ \u00a76" + this.brandTierPlusPlus)));
            }
        }
    }

    private void renderOwnOrdersEntries(Inventory inv, List<OrderEntry> orders, int page) {
        int start = Math.max(0, (page - 1) * 45);
        int end = Math.min(orders.size(), start + 45);
        int slot = 0;
        for (int i = start; i < end; ++i) {
            OrderEntry o = orders.get(i);
            ItemStack item = new ItemStack(o.material());
            ItemMeta meta = item.getItemMeta();
            meta.setDisplayName("\u00a7a" + this.humanName(o.material()));
            if (this.uiActionKey != null) {
                meta.getPersistentDataContainer().set(this.uiActionKey, PersistentDataType.STRING, "orders_listing:" + o.id());
            }
            meta.setLore(List.of("\u00a77Amount requested: \u00a7f" + o.amountTotal(), "\u00a77Price per: \u00a7f$" + this.fmtMoney(o.unitPrice()), "\u00a77Amount delivered: \u00a7f" + o.amountFilled(), "\u00a77Expires in: \u00a7f" + this.timeUntil(o.expiresAtMs()), "\u00a7aClick to manage"));
            item.setItemMeta(meta);
            inv.setItem(slot++, item);
        }
    }

    private void openOrderNewMenu(Player player) {
        OrderBuilderState state = this.orderBuilderState.computeIfAbsent(player.getUniqueId(), id -> new OrderBuilderState());
        Inventory inv = Bukkit.createInventory(null, (int)27, (String)TITLE_ORDERS_NEW);
        inv.setItem(10, this.namedWithLore(Material.RED_STAINED_GLASS_PANE, "\u00a7c\u00a7lCancel", "orders_new_cancel", List.of()));
        Material previewMaterial = state.material == null || !state.material.isItem() ? Material.PAPER : state.material;
        String previewLabel = state.material == null || !state.material.isItem() ? "\u00a7aChoose item" : "\u00a7a" + this.humanName(state.material);
        String previewLore = state.material == null || !state.material.isItem() ? "\u00a7fClick to pick" : "\u00a77Current: \u00a7f" + this.humanName(state.material);
        inv.setItem(12, this.namedWithLore(previewMaterial, previewLabel, "orders_new_item", List.of(previewLore)));
        String amountText = state.amount <= 0L ? "not set" : Long.toString(state.amount);
        inv.setItem(13, this.namedWithLore(Material.CHEST, "\u00a7aAmount", "orders_new_amount", List.of("\u00a7fClick to enter", "\u00a77Supports: 1k, 1m, 1b", "\u00a77Current: \u00a7f" + amountText)));
        String priceText = state.unitPrice <= 0.0 ? "not set" : this.fmtMoney(state.unitPrice);
        inv.setItem(14, this.namedWithLore(Material.EMERALD, "\u00a7aPrice", "orders_new_price", List.of("\u00a7fClick to enter", "\u00a77Supports: 1k, 1m, 1b", "\u00a77Current: \u00a7f$" + priceText)));
        double total = state.amount > 0L && state.unitPrice > 0.0 ? (double)state.amount * state.unitPrice : 0.0;
        inv.setItem(15, this.namedWithLore(Material.GREEN_STAINED_GLASS_PANE, "\u00a7a\u00a7lConfirm", "orders_new_confirm", List.of("\u00a7fTotal cost: \u00a7f$" + this.fmtMoney(total))));
        player.openInventory(inv);
    }

    private void openOrderItemPicker(Player player) {
        OrdersViewState state = this.ordersViewState.computeIfAbsent(player.getUniqueId(), id -> new OrdersViewState());
        Inventory inv = Bukkit.createInventory(null, (int)54, (String)TITLE_ORDERS_PICK);
        List<Material> materials = this.pickerMaterials(state.search);
        int start = Math.max(0, (state.page - 1) * 45);
        int end = Math.min(materials.size(), start + 45);
        int slot = 0;
        for (int i = start; i < end; ++i) {
            Material m = materials.get(i);
            inv.setItem(slot++, this.namedWithLore(m, "\u00a7a" + this.humanName(m), "orders_pick_item:" + m.name(), List.of()));
        }
        inv.setItem(49, this.namedWithLore(Material.OAK_SIGN, "\u00a7aSearch", "orders_pick_search", List.of()));
        if (state.page > 1) {
            inv.setItem(45, this.namedWithLore(Material.ARROW, "\u00a7aBack", "orders_pick_prev", List.of()));
        }
        if (materials.size() > state.page * 45) {
            inv.setItem(53, this.namedWithLore(Material.ARROW, "\u00a7aNext", "orders_pick_next", List.of()));
        }
        player.openInventory(inv);
    }

    // ---- Guided order-creation dialog flow (1.21.6+): Choose Item -> How many -> Price -> Review ----

    /** Routes to the next unset step, or the review screen. Legacy clients get the inventory builder. */
    private void openOrderBuilder(Player player) {
        if (!this.useDialogUi(player)) {
            this.openOrderNewMenu(player);
            return;
        }
        OrderBuilderState s = this.orderBuilderState.computeIfAbsent(player.getUniqueId(), k -> new OrderBuilderState());
        if (s.material == null || !s.material.isItem()) {
            this.openOrderItemPickerDialog(player);
        } else if (s.amount <= 0L) {
            this.requestTextInput(player, TextInputMode.ORDER_AMOUNT, "Type order amount in chat (supports 1k/1m/1b).");
        } else if (s.unitPrice <= 0.0) {
            this.requestTextInput(player, TextInputMode.ORDER_PRICE, "Type unit price in chat (supports 1k/1m/1b).");
        } else {
            this.openOrderReviewDialog(player);
        }
    }

    private void reopenOrderBuilderStep(Player player, TextInputMode retry) {
        if (retry == TextInputMode.ORDER_AMOUNT) {
            this.requestTextInput(player, TextInputMode.ORDER_AMOUNT, "Type order amount in chat (supports 1k/1m/1b).");
        } else if (retry == TextInputMode.ORDER_PRICE) {
            this.requestTextInput(player, TextInputMode.ORDER_PRICE, "Type unit price in chat (supports 1k/1m/1b).");
        } else {
            this.openOrderBuilder(player);
        }
    }

    /** A plane-1 emoji glyph that approximates an item's category (dialog buttons can't show real icons). */
    private String materialGlyph(Material m) {
        String n = m.name();
        if (n.contains("SWORD") || n.contains("BOW") || n.equals("TRIDENT") || n.contains("ARROW") || n.equals("SHIELD") || n.equals("MACE")) return "⚔";        // ⚔
        if (n.contains("PICKAXE") || n.contains("SHOVEL") || n.contains("_HOE") || n.contains("SHEARS") || n.contains("FLINT_AND_STEEL")) return "⛏";          // ⛏
        if (n.contains("HELMET") || n.contains("CHESTPLATE") || n.contains("LEGGINGS") || n.contains("BOOTS") || n.equals("ELYTRA")) return "🛡";          // 🛡
        if (n.equals("TOTEM_OF_UNDYING")) return "✨";                                                                                                          // ✨
        if (n.contains("POTION") || n.equals("EXPERIENCE_BOTTLE") || n.contains("HONEY_BOTTLE")) return "🧪";                                              // 🧪
        if (n.endsWith("_LOG") || n.endsWith("_WOOD") || n.endsWith("_PLANKS") || n.endsWith("_STEM") || n.endsWith("_HYPHAE")) return "🪵";               // 🪵
        if (n.endsWith("_ORE") || n.startsWith("RAW_") || n.equals("ANCIENT_DEBRIS")) return "⛰";                                                              // ⛰
        if (n.equals("DIAMOND") || n.equals("DIAMOND_BLOCK")) return "💎";                                                                                // 💎
        if (n.contains("FLOWER") || n.endsWith("_SAPLING") || n.endsWith("_LEAVES") || n.contains("GRASS") || n.endsWith("_FERN") || n.endsWith("_ROOTS")) return "🌿"; // 🌿
        if (n.endsWith("_DYE")) return "🎨";                                                                                                              // 🎨
        if (n.endsWith("_WOOL") || n.endsWith("_CARPET") || n.endsWith("_BED")) return "🪡";                                                              // 🧶
        if (n.contains("APPLE") || n.contains("BREAD") || n.contains("BEEF") || n.contains("PORK") || n.contains("CHICKEN") || n.contains("MUTTON")
            || n.contains("COD") || n.contains("SALMON") || n.contains("CARROT") || n.contains("POTATO") || n.contains("MELON") || n.contains("BERRIES")
            || n.contains("STEW") || n.contains("SOUP") || n.equals("COOKIE") || n.equals("CAKE")) return "🍖";                                            // 🍖
        if (n.equals("ENDER_PEARL") || n.equals("ENDER_EYE")) return "🔮";                                                                                // 🔮
        if (n.equals("END_CRYSTAL") || n.equals("RESPAWN_ANCHOR") || n.equals("GLOWSTONE")) return "💥";                                                   // 💥
        if (n.contains("SPAWN_EGG") || n.contains("EGG")) return "🥚";                                                                                    // 🥚
        if (n.contains("HEAD") || n.contains("SKULL")) return "💀";                                                                                       // 💀
        return "📦"; // 📦 default crate/box
    }

    /** "Choose Item": search box + paginated item list with a category glyph next to each name. */
    private void openOrderItemPickerDialog(Player player) {
        if (!this.useDialogUi(player)) {
            this.openOrderItemPicker(player);
            return;
        }
        OrdersViewState vs = this.ordersViewState.computeIfAbsent(player.getUniqueId(), k -> new OrdersViewState());
        List<Material> mats = this.pickerMaterials(vs.search);
        int perPage = 21;
        int pages = Math.max(1, (mats.size() + perPage - 1) / perPage);
        if (vs.page < 1) vs.page = 1;
        if (vs.page > pages) vs.page = pages;
        int start = (vs.page - 1) * perPage;
        int end = Math.min(mats.size(), start + perPage);

        var ib = DialogInput.text("search", Component.text("Search", NamedTextColor.GRAY)).width(300).maxLength(32);
        if (vs.search != null && !vs.search.isEmpty()) ib.initial(vs.search);

        List<ActionButton> buttons = new ArrayList<>();
        buttons.add(ActionButton.builder(Component.text("Search", NamedTextColor.WHITE)).width(300)
            .action(DialogAction.customClick((view, aud) -> {
                if (aud instanceof Player pl) {
                    String q = view.getText("search");
                    this.runOnPlayerThread(pl, () -> {
                        OrdersViewState st = this.ordersViewState.computeIfAbsent(pl.getUniqueId(), k -> new OrdersViewState());
                        st.search = q == null ? "" : q.trim();
                        st.page = 1;
                        this.openOrderItemPickerDialog(pl);
                    });
                }
            }, ClickCallback.Options.builder().build())).build());
        for (int i = start; i < end; i++) {
            Material m = mats.get(i);
            buttons.add(this.dialogButton(Component.text(this.materialGlyph(m) + " " + this.humanName(m), NamedTextColor.WHITE),
                null, 300, pl -> this.pickOrderItem(pl, m)));
        }
        if (vs.page > 1) {
            buttons.add(this.dialogButton(Component.text("◀ Prev", DIALOG_BRAND), null, 150, pl -> {
                OrdersViewState st = this.ordersViewState.computeIfAbsent(pl.getUniqueId(), k -> new OrdersViewState());
                st.page = Math.max(1, st.page - 1);
                this.openOrderItemPickerDialog(pl);
            }));
        }
        if (end < mats.size()) {
            buttons.add(this.dialogButton(Component.text("Next ▶", DIALOG_BRAND), null, 150, pl -> {
                OrdersViewState st = this.ordersViewState.computeIfAbsent(pl.getUniqueId(), k -> new OrdersViewState());
                st.page = st.page + 1;
                this.openOrderItemPickerDialog(pl);
            }));
        }
        Dialog dialog = this.buildDialog(Component.text("Choose Item", DIALOG_BRAND), List.of(), List.of(ib.build()),
            DialogType.multiAction(buttons).columns(end - start > 0 && (end - start) > 10 ? 2 : 1)
                .exitAction(this.dialogButton(Component.text("Cancel", NamedTextColor.RED), null, 150,
                    pl -> this.openOrdersMyMenu(pl))).build());
        player.showDialog(dialog);
    }

    private void pickOrderItem(Player player, Material m) {
        OrderBuilderState s = this.orderBuilderState.computeIfAbsent(player.getUniqueId(), k -> new OrderBuilderState());
        s.material = m;
        this.openOrderBuilder(player);
    }

    /** "Review Order": Item/Amount/Price/Total + Change buttons + Create Order. */
    private void openOrderReviewDialog(Player player) {
        OrderBuilderState s = this.orderBuilderState.get(player.getUniqueId());
        if (s == null || s.material == null || s.amount <= 0L || s.unitPrice <= 0.0) {
            this.openOrderBuilder(player);
            return;
        }
        double total = (double) s.amount * s.unitPrice;
        List<DialogBody> body = List.of(
            DialogBody.plainMessage(Component.text("Item: " + this.humanName(s.material), NamedTextColor.WHITE)),
            DialogBody.plainMessage(Component.text("Amount: " + s.amount, NamedTextColor.WHITE)),
            DialogBody.plainMessage(Component.text("Price: $" + this.fmtMoney(s.unitPrice) + " each", NamedTextColor.GREEN)),
            DialogBody.plainMessage(Component.text("Total: $" + this.fmtMoney(total), NamedTextColor.GREEN)));
        List<ActionButton> buttons = new ArrayList<>();
        buttons.add(this.dialogButton(Component.text("Change Item", NamedTextColor.WHITE), null, 150,
            pl -> this.openOrderItemPickerDialog(pl)));
        buttons.add(this.dialogButton(Component.text("Change Amount", NamedTextColor.WHITE), null, 150,
            pl -> this.requestTextInput(pl, TextInputMode.ORDER_AMOUNT, "Type order amount in chat (supports 1k/1m/1b).")));
        buttons.add(this.dialogButton(Component.text("Change Price", NamedTextColor.WHITE), null, 150,
            pl -> this.requestTextInput(pl, TextInputMode.ORDER_PRICE, "Type unit price in chat (supports 1k/1m/1b).")));
        buttons.add(this.dialogButton(Component.text("Create Order", NamedTextColor.GREEN), null, 150,
            pl -> { pl.closeDialog(); this.createOrderFromBuilder(pl); }));
        Dialog dialog = this.buildDialog(Component.text("Review Order", DIALOG_BRAND), body, List.of(),
            DialogType.multiAction(buttons).columns(2)
                .exitAction(this.dialogButton(Component.text("Cancel", NamedTextColor.RED), null, 150,
                    pl -> this.openOrdersMyMenu(pl))).build());
        player.showDialog(dialog);
    }

    private void handleOrdersMainClick(Player player, int slot, ItemStack item, ClickType clickType) {
        if (item == null || !item.hasItemMeta()) {
            return;
        }
        String id = this.uiActionId(item);
        if (id == null) {
            return;
        }
        OrdersViewState state = this.ordersViewState.computeIfAbsent(player.getUniqueId(), k -> new OrdersViewState());
        switch (id) {
            case "orders_refresh": {
                this.openOrdersMenu(player);
                break;
            }
            case "orders_prev": {
                state.page = Math.max(1, state.page - 1);
                this.openOrdersMenu(player);
                break;
            }
            case "orders_next": {
                ++state.page;
                this.openOrdersMenu(player);
                break;
            }
            case "orders_filter": {
                state.nextFilter();
                state.page = 1;
                this.openOrdersMenu(player);
                break;
            }
            case "orders_sort": {
                state.nextSort();
                state.page = 1;
                this.openOrdersMenu(player);
                break;
            }
            case "orders_search": {
                this.requestTextInput(player, TextInputMode.ORDERS_SEARCH, "Type search text in chat.");
                break;
            }
            case "orders_my": {
                state.page = 1;
                this.openOrdersMyMenu(player);
                break;
            }
            default: {
                if (id.startsWith("orders_listing:") && clickType.isLeftClick()) {
                    long orderId = this.parseLongSafe(id.substring("orders_listing:".length()), -1L);
                    if (orderId > 0L) this.fulfillOrder(player, orderId);
                    break;
                }
                if (id.startsWith("orders_item:") && clickType.isLeftClick()) {
                    String matName = id.substring("orders_item:".length());
                    this.openOrdersItemMenu(player, matName);
                }
            }
        }
    }

    private void handleOrdersItemClick(Player player, int slot, ItemStack item, ClickType clickType) {
        if (item == null || !item.hasItemMeta()) return;
        String id = this.uiActionId(item);
        if (id == null) return;
        OrdersViewState state = this.ordersViewState.computeIfAbsent(player.getUniqueId(), k -> new OrdersViewState());
        switch (id) {
            case "orders_item_back": {
                state.itemFilter = null;
                state.page = 1;
                this.openOrdersMenu(player);
                break;
            }
            case "orders_item_prev": {
                state.itemPage = Math.max(1, state.itemPage - 1);
                this.openOrdersItemMenu(player, state.itemFilter);
                break;
            }
            case "orders_item_next": {
                ++state.itemPage;
                this.openOrdersItemMenu(player, state.itemFilter);
                break;
            }
            case "orders_my": {
                state.page = 1;
                this.openOrdersMyMenu(player);
                break;
            }
            default: {
                if (!id.startsWith("orders_listing:") || !clickType.isLeftClick()) break;
                long orderId = this.parseLongSafe(id.substring("orders_listing:".length()), -1L);
                if (orderId <= 0L) break;
                this.fulfillOrder(player, orderId);
            }
        }
    }

    private void handleOrdersMyClick(Player player, int slot, ItemStack item, ClickType clickType) {
        if (item == null || !item.hasItemMeta()) {
            return;
        }
        String id = this.uiActionId(item);
        if (id == null) {
            return;
        }
        OrdersViewState state = this.ordersViewState.computeIfAbsent(player.getUniqueId(), k -> new OrdersViewState());
        switch (id) {
            case "orders_new":
            case "orders_new_slot": {
                // Fresh build: clear the builder so the flow starts at Choose Item.
                OrderBuilderState b = this.orderBuilderState.computeIfAbsent(player.getUniqueId(), k -> new OrderBuilderState());
                b.material = null;
                b.amount = 0L;
                b.unitPrice = 0.0;
                this.openOrderBuilder(player);
                break;
            }
            case "orders_my_filter": {
                state.nextFilter();
                this.openOrdersMyMenu(player);
                break;
            }
            case "market_locked": {
                player.sendActionBar(Component.text("§cUnlock more order slots with §6" + this.brandTierPlus + " §c/ §6" + this.brandTierPlusPlus));
                break;
            }
            case "orders_main": {
                state.page = 1;
                this.openOrdersMenu(player);
                break;
            }
            case "orders_my_prev": {
                state.page = Math.max(1, state.page - 1);
                this.openOrdersMyMenu(player);
                break;
            }
            case "orders_my_next": {
                ++state.page;
                this.openOrdersMyMenu(player);
                break;
            }
            case "orders_my_claim_all": {
                state.selectedOrderId = 0L;
                state.deliveriesPage = 1;
                this.openOrderDeliveriesMenu(player);
                break;
            }
            default: {
                if (!id.startsWith("orders_listing:") || !clickType.isLeftClick()) break;
                long orderId = this.parseLongSafe(id.substring("orders_listing:".length()), -1L);
                if (orderId <= 0L) {
                    break;
                }
                state.selectedOrderId = orderId;
                state.deliveriesPage = 1;
                this.openOrderDetailMenu(player, orderId);
            }
        }
    }

    private void handleOrdersDeliveriesClick(Player player, int slot, ItemStack item, ClickType clickType) {
        if (item == null || !item.hasItemMeta()) {
            return;
        }
        String id = this.uiActionId(item);
        if (id == null) {
            return;
        }
        OrdersViewState state = this.ordersViewState.computeIfAbsent(player.getUniqueId(), k -> new OrdersViewState());
        switch (id) {
            case "orders_claims_prev": {
                state.deliveriesPage = Math.max(1, state.deliveriesPage - 1);
                this.openOrderDeliveriesMenu(player);
                break;
            }
            case "orders_claims_next": {
                ++state.deliveriesPage;
                this.openOrderDeliveriesMenu(player);
                break;
            }
            case "orders_claims_back": {
                this.openOrderDetailMenu(player, state.selectedOrderId);
                break;
            }
            case "orders_claims_refresh": {
                this.openOrderDeliveriesMenu(player);
                break;
            }
            case "orders_claims_drop_page": {
                this.dropVisibleOrderDeliveries(player);
                break;
            }
            case "orders_claims_sell_page": {
                this.openOrderSellConfirm(player);
                break;
            }
            case "orders_claims_claim_all": {
                this.claimAllOrderDeliveries(player);
                break;
            }
            default: {
                long deliveryId;
                if (!id.startsWith("orders_claim_delivery:") || !clickType.isLeftClick() || (deliveryId = this.parseLongSafe(id.substring("orders_claim_delivery:".length()), -1L)) <= 0L) break;
                this.claimOrderDelivery(player, deliveryId);
            }
        }
    }

    private void handleOrderDetailClick(Player player, int slot, ItemStack item) {
        if (item == null || !item.hasItemMeta()) {
            return;
        }
        String id = this.uiActionId(item);
        if (id == null) {
            return;
        }
        OrdersViewState state = this.ordersViewState.computeIfAbsent(player.getUniqueId(), k -> new OrdersViewState());
        switch (id) {
            case "orders_detail_back": {
                this.openOrdersMyMenu(player);
                break;
            }
            case "orders_detail_refresh": {
                this.openOrderDetailMenu(player, state.selectedOrderId);
                break;
            }
            case "orders_detail_cancel": {
                this.openOrderCancelConfirm(player, state.selectedOrderId);
                break;
            }
            case "orders_detail_claims": {
                state.deliveriesPage = 1;
                this.openOrderDeliveriesMenu(player);
                break;
            }
        }
    }

    private void openOrderDetailMenu(Player player, long orderId) {
        if (orderId <= 0L) {
            this.openOrdersMyMenu(player);
            return;
        }
        OrdersViewState state = this.ordersViewState.computeIfAbsent(player.getUniqueId(), id -> new OrdersViewState());
        state.selectedOrderId = orderId;
        this.runAsyncTask(() -> {
            OrderEntry order = this.loadOrderByIdForCreator(orderId, player.getUniqueId());
            int pendingDeliveries = order == null ? 0 : this.queryPendingOrderDeliveries(player.getUniqueId(), order.id()).size();
            this.runOnPlayerThread(player, () -> {
                if (order == null) {
                    player.sendMessage("\u00a7cThat order is no longer active.");
                    this.openOrdersMyMenu(player);
                    return;
                }
                this.renderOrderDetailMenu(player, order, pendingDeliveries);
            });
        });
    }

    private void renderOrderDetailMenu(Player player, OrderEntry order, int pendingDeliveries) {
        if (player == null || !player.isOnline() || order == null) {
            return;
        }
        Inventory inv = Bukkit.createInventory(null, (int)27, (String)TITLE_ORDER_DETAIL);
        ItemStack preview = new ItemStack(order.material());
        ItemMeta meta = preview.getItemMeta();
        meta.setDisplayName("\u00a7a" + this.humanName(order.material()));
        meta.setLore(List.of("\u00a77Amount requested: \u00a7f" + order.amountTotal(), "\u00a77Amount delivered: \u00a7f" + order.amountFilled(), "\u00a77Remaining: \u00a7f" + order.remainingAmount(), "\u00a77Price per: \u00a7f$" + this.fmtMoney(order.unitPrice()), "\u00a77Expires in: \u00a7f" + this.timeUntil(order.expiresAtMs())));
        preview.setItemMeta(meta);
        inv.setItem(10, this.namedWithLore(Material.RED_TERRACOTTA, "\u00a7cCancel order", "orders_detail_cancel", List.of()));
        inv.setItem(13, preview);
        inv.setItem(16, this.namedWithLore(Material.CHEST, "\u00a7aClaim items", "orders_detail_claims", List.of("\u00a77Pending deliveries: \u00a7f" + pendingDeliveries, pendingDeliveries > 0 ? "\u00a7fClick to open claimed items" : "\u00a77No items waiting")));
        inv.setItem(22, this.namedWithLore(Material.ARROW, "\u00a7aBack to Your Orders", "orders_detail_back", List.of()));
        inv.setItem(4, this.namedWithLore(Material.PAPER, "\u00a7aOrder overview", "orders_detail_refresh", List.of()));
        player.openInventory(inv);
    }

    private void openOrderCancelConfirm(Player player, long orderId) {
        if (orderId <= 0L) {
            this.openOrdersMyMenu(player);
            return;
        }
        this.orderConfirmState.put(player.getUniqueId(), new OrderConfirmState(OrderConfirmMode.CANCEL_ORDER, orderId));
        // Load the order so the confirm screen can show exactly what will be refunded.
        this.runAsyncTask(() -> {
            OrderEntry order = this.loadOrderByIdForCreator(orderId, player.getUniqueId());
            this.runOnPlayerThread(player, () -> {
                Inventory inv = Bukkit.createInventory(null, (int)27, (String)TITLE_ORDER_CANCEL_CONFIRM);
                ItemStack fill = this.namedWithLore(Material.GRAY_STAINED_GLASS_PANE, "\u00a7r", null, List.of());
                for (int s = 0; s < 27; ++s) inv.setItem(s, fill);
                ItemStack preview;
                if (order != null) {
                    int remaining = order.remainingAmount();
                    double refund = (double)remaining * order.unitPrice();
                    preview = new ItemStack(order.material());
                    ItemMeta m = preview.getItemMeta();
                    m.setDisplayName("\u00a7c" + this.humanName(order.material()));
                    m.setLore(List.of(
                        "\u00a77Remaining: \u00a7f" + remaining + "/" + order.amountTotal(),
                        "\u00a77Price per: \u00a7f$" + this.fmtMoney(order.unitPrice()),
                        "\u00a77Refund on cancel: \u00a7f$" + this.fmtMoney(refund),
                        "\u00a77Already-delivered items stay claimable."));
                    preview.setItemMeta(m);
                } else {
                    preview = this.namedWithLore(Material.RED_TERRACOTTA, "\u00a7cOrder no longer active", null, List.of("\u00a77Nothing to cancel"));
                }
                inv.setItem(13, preview);
                inv.setItem(11, this.namedWithLore(Material.RED_STAINED_GLASS_PANE, "\u00a7c\u00a7lKeep Order", "orders_cancel_back", List.of("\u00a77Go back, change nothing")));
                inv.setItem(15, this.namedWithLore(Material.GREEN_STAINED_GLASS_PANE, "\u00a7a\u00a7lConfirm Cancel", "orders_cancel_confirm", List.of("\u00a77Cancel the order and refund")));
                player.openInventory(inv);
            });
        });
    }

    private void handleOrderCancelConfirmClick(Player player, int slot, ItemStack item) {
        if (item == null || !item.hasItemMeta()) {
            return;
        }
        String id = this.uiActionId(item);
        if (id == null) {
            return;
        }
        OrderConfirmState state = this.orderConfirmState.get(player.getUniqueId());
        if (state == null || state.mode() != OrderConfirmMode.CANCEL_ORDER) {
            this.openOrdersMyMenu(player);
            return;
        }
        if ("orders_cancel_back".equals(id)) {
            this.orderConfirmState.remove(player.getUniqueId());
            this.openOrderDetailMenu(player, state.orderId());
            return;
        }
        if ("orders_cancel_confirm".equals(id)) {
            this.orderConfirmState.remove(player.getUniqueId());
            this.cancelOwnOrder(player, state.orderId());
        }
    }

