    private void openOrderDeliveryInsert(Player player, OrderEntry order) {
        if (player == null || order == null) {
            return;
        }
        OrderFulfillmentState state = this.orderFulfillmentState.computeIfAbsent(player.getUniqueId(), id -> new OrderFulfillmentState());
        state.orderId = order.id();
        state.material = order.material();
        state.unitPrice = order.unitPrice();
        state.pendingAmount = 0;
        state.pendingItems.clear();
        Inventory inv = Bukkit.createInventory(null, (int)27, (String)TITLE_ORDER_DELIVER);
        player.openInventory(inv);
    }

    private void handleOrderDeliveryInsertClick(Player player, InventoryClickEvent e) {
        OrderFulfillmentState state = this.orderFulfillmentState.get(player.getUniqueId());
        if (state == null || state.material == null) {
            return;
        }
        int raw = e.getRawSlot();
        Inventory top = e.getView().getTopInventory();
        if (raw < 0) {
            return;
        }
        if (raw < top.getSize()) {
            return;
        }
        if (!e.isShiftClick()) {
            return;
        }
        ItemStack moving = e.getCurrentItem();
        if (moving == null || moving.getType() == Material.AIR || moving.getType() != state.material) {
            return;
        }
        int target = this.firstEmptyOrderDeliverySlot(top);
        if (target == -1) {
            e.setCancelled(true);
            return;
        }
        e.setCancelled(true);
        top.setItem(target, moving.clone());
        e.getClickedInventory().setItem(e.getSlot(), null);
    }

    private int firstEmptyOrderDeliverySlot(Inventory inv) {
        for (int slot = 0; slot < 27; ++slot) {
            ItemStack item = inv.getItem(slot);
            if (item != null && item.getType() != Material.AIR) continue;
            return slot;
        }
        return -1;
    }

    private void processOrderDeliveryInsertOnClose(Player player, Inventory inventory) {
        OrderFulfillmentState state = this.orderFulfillmentState.get(player.getUniqueId());
        if (player == null || inventory == null || state == null || state.material == null) {
            return;
        }
        ArrayList<ItemStack> accepted = new ArrayList<ItemStack>();
        int acceptedAmount = 0;
        for (int slot = 0; slot < 27; ++slot) {
            ItemStack stack = inventory.getItem(slot);
            if (stack == null || stack.getType() == Material.AIR) {
                continue;
            }
            inventory.setItem(slot, null);
            if (stack.getType() == state.material) {
                accepted.add(stack.clone());
                acceptedAmount += stack.getAmount();
                continue;
            }
            // Shulker box drilldown: extract matching items from inside, return shulker with leftovers.
            if (stack.getType().name().contains("SHULKER_BOX") && stack.hasItemMeta()
                    && stack.getItemMeta() instanceof BlockStateMeta bsm
                    && bsm.getBlockState() instanceof ShulkerBox box) {
                org.bukkit.inventory.Inventory shulkerInv = box.getInventory();
                boolean anyTaken = false;
                for (int si = 0; si < shulkerInv.getSize(); ++si) {
                    ItemStack inner = shulkerInv.getItem(si);
                    if (inner == null || inner.getType() != state.material) continue;
                    accepted.add(inner.clone());
                    acceptedAmount += inner.getAmount();
                    shulkerInv.setItem(si, null);
                    anyTaken = true;
                }
                if (anyTaken) {
                    bsm.setBlockState(box);
                    stack.setItemMeta(bsm);
                }
            }
            this.giveItemStack(player, stack.clone());
        }
        if (acceptedAmount <= 0) {
            this.orderFulfillmentState.remove(player.getUniqueId());
            return;
        }
        state.pendingItems.clear();
        state.pendingItems.addAll(accepted);
        state.pendingAmount = acceptedAmount;
        this.runPlayerTaskLater(player, () -> this.openOrderDeliveryConfirm(player), 1L);
    }

    private void openOrderDeliveryConfirm(Player player) {
        OrderFulfillmentState state = this.orderFulfillmentState.get(player.getUniqueId());
        if (state == null || state.orderId <= 0L || state.material == null || state.pendingAmount <= 0) {
            return;
        }
        this.runAsyncTask(() -> {
            OrderEntry order = this.loadOrderById(state.orderId);
            this.runOnPlayerThread(player, () -> {
                if (order == null || order.remainingAmount() <= 0) {
                    this.returnPendingOrderFulfillmentItems(player);
                    player.sendMessage("\u00a7cThat order is no longer available.");
                    this.openOrdersMenu(player);
                    return;
                }
                int deliverable = Math.min(state.pendingAmount, order.remainingAmount());
                if (deliverable <= 0) {
                    this.returnPendingOrderFulfillmentItems(player);
                    player.sendMessage("\u00a7cThat order is already filled.");
                    this.openOrdersMenu(player);
                    return;
                }
                Inventory inv = Bukkit.createInventory(null, (int)27, (String)TITLE_ORDER_DELIVER_CONFIRM);
                ItemStack preview = new ItemStack(order.material(), Math.max(1, Math.min(deliverable, order.material().getMaxStackSize())));
                ItemMeta meta = preview.getItemMeta();
                ArrayList<String> lore = new ArrayList<String>();
                lore.add("\u00a77Requested item: \u00a7f" + this.humanName(order.material()));
                lore.add("\u00a77Queued amount: \u00a7f" + state.pendingAmount);
                lore.add("\u00a77Deliver now: \u00a7f" + deliverable);
                if (state.pendingAmount > deliverable) {
                    lore.add("\u00a77Returned to you: \u00a7f" + (state.pendingAmount - deliverable));
                }
                lore.add("\u00a77Payout now: \u00a7f$" + this.fmtMoney((double)deliverable * order.unitPrice()));
                meta.setDisplayName("\u00a7a" + this.humanName(order.material()));
                meta.setLore(lore);
                preview.setItemMeta(meta);
                inv.setItem(11, this.namedWithLore(Material.RED_STAINED_GLASS_PANE, "\u00a7c\u00a7lCancel", "orders_deliver_confirm_cancel", List.of()));
                inv.setItem(13, preview);
                inv.setItem(15, this.namedWithLore(Material.GREEN_STAINED_GLASS_PANE, "\u00a7a\u00a7lConfirm", "orders_deliver_confirm_accept", List.of()));
                player.openInventory(inv);
            });
        });
    }

    private void handleOrderDeliveryConfirmClick(Player player, int slot, ItemStack item) {
        if (item == null || !item.hasItemMeta()) {
            return;
        }
        String id = this.uiActionId(item);
        if (id == null) {
            return;
        }
        if ("orders_deliver_confirm_cancel".equals(id)) {
            this.returnPendingOrderFulfillmentItems(player);
            this.openOrdersMenu(player);
            return;
        }
        if ("orders_deliver_confirm_accept".equals(id)) {
            this.finalizeOrderDelivery(player);
        }
    }

    private void finalizeOrderDelivery(Player player) {
        OrderFulfillmentState state = this.orderFulfillmentState.get(player.getUniqueId());
        if (state == null || state.orderId <= 0L || state.material == null || state.pendingAmount <= 0) {
            this.openOrdersMenu(player);
            return;
        }
        ItemStack preview = state.pendingItems.isEmpty() ? new ItemStack(state.material) : state.pendingItems.get(0).clone();
        int requestedAmount = state.pendingAmount;
        this.runAsyncTask(() -> {
            OrderDeliveryApplyResult result = this.applyOrderDelivery(state.orderId, player.getUniqueId(), state.material, requestedAmount, preview);
            this.runOnPlayerThread(player, () -> {
                if (result == null || result.amount() <= 0) {
                    this.returnPendingOrderFulfillmentItems(player);
                    player.sendMessage("\u00a7cThat order is no longer available.");
                    this.openOrdersMenu(player);
                    return;
                }
                if (requestedAmount > result.amount()) {
                    this.returnPendingOrderItems(player, state, requestedAmount - result.amount());
                }
                long deliveredOrderId = state.orderId;
                Material deliveredMaterial = state.material;
                this.orderFulfillmentState.remove(player.getUniqueId());
                this.depositMoney(player, result.payout());
                String itemLabel = this.humanName(deliveredMaterial);
                player.sendActionBar(this.legacyColorize("&#00BFFFDelivered " + result.amount() + "x " + itemLabel + " for $" + this.fmtMoney(result.payout()) + "."));
                this.logTransactionAudit(player.getUniqueId().toString(), player.getName(), "ORDER_DELIVER", deliveredMaterial.name(), result.amount(), result.payout() / Math.max(1, result.amount()), result.payout(), "order=" + deliveredOrderId);
                if (result.creatorUuid() != null && !SERVER_UUID.equals(result.creatorUuid().toString())) {
                    Player creator = Bukkit.getPlayer(result.creatorUuid());
                    if (creator != null && creator.isOnline() && this.isSettingEnabledCached(result.creatorUuid(), "order_notifications")) {
                        creator.sendActionBar(this.legacyColorize("&#00BFFF" + player.getName() + " delivered " + result.amount() + "x " + itemLabel + " to your order."));
                    } else {
                        this.runAsyncTask(() -> this.queuePlayerNotification(result.creatorUuid(), "\u00a7aOrder delivery: \u00a7f" + player.getName() + " \u00a7adelivered \u00a7f" + result.amount() + "x " + itemLabel + "\u00a7a. Use \u00a7f/orders \u00a7ato claim.", "", 180));
                    }
                }
                this.orderConfirmCloseBypass.add(player.getUniqueId());
                // Order remaining changed: refresh it instantly for everyone else browsing orders.
                this.refreshOrdersForViewers(player.getUniqueId());
                this.fulfillOrder(player, deliveredOrderId);
            });
        });
    }

    private void returnPendingOrderFulfillmentItems(Player player) {
        OrderFulfillmentState state = this.orderFulfillmentState.remove(player.getUniqueId());
        if (state == null || state.material == null || state.pendingAmount <= 0) {
            return;
        }
        this.returnPendingOrderItems(player, state, state.pendingAmount);
    }

    private void returnPendingOrderItems(Player player, OrderFulfillmentState state, int amount) {
        if (player == null || state == null || state.material == null || amount <= 0) {
            return;
        }
        int remaining = amount;
        for (ItemStack stack : state.pendingItems) {
            if (remaining <= 0) {
                break;
            }
            ItemStack give = stack.clone();
            int stackAmount = Math.min(remaining, Math.max(1, give.getAmount()));
            give.setAmount(stackAmount);
            this.giveItemStack(player, give);
            remaining -= stackAmount;
        }
        while (remaining > 0) {
            int giveAmount = Math.min(remaining, Math.max(1, state.material.getMaxStackSize()));
            this.giveItemStack(player, new ItemStack(state.material, giveAmount));
            remaining -= giveAmount;
        }
    }

    private List<Long> visibleOrderDeliveryIds(List<OrderDeliveryEntry> deliveries, int page) {
        ArrayList<Long> ids = new ArrayList<Long>();
        int start = Math.max(0, (page - 1) * 45);
        int end = Math.min(deliveries.size(), start + 45);
        for (int i = start; i < end; ++i) {
            ids.add(deliveries.get(i).id());
        }
        return ids;
    }

    private void dropVisibleOrderDeliveries(Player player) {
        OrdersViewState state = this.ordersViewState.computeIfAbsent(player.getUniqueId(), id -> new OrdersViewState());
        if (state.selectedOrderId <= 0L) {
            this.openOrdersMyMenu(player);
            return;
        }
        this.runAsyncTask(() -> {
            List<OrderDeliveryEntry> deliveries = this.queryPendingOrderDeliveries(player.getUniqueId(), state.selectedOrderId);
            List<Long> ids = this.visibleOrderDeliveryIds(deliveries, state.deliveriesPage);
            if (ids.isEmpty()) {
                this.runOnPlayerThread(player, () -> player.sendMessage("\u00a7cThere are no claimable deliveries on this page."));
                return;
            }
            List<OrderDeliveryEntry> claimed = this.claimOrderDeliveries(player.getUniqueId(), state.selectedOrderId, ids);
            double totalPayoutAmount = 0.0;
            for (OrderDeliveryEntry delivery : claimed) {
                totalPayoutAmount += delivery.payout();
            }
            final double totalPayout = totalPayoutAmount;
            this.runOnPlayerThread(player, () -> {
                if (claimed.isEmpty()) {
                    player.sendMessage("\u00a7cThose deliveries are no longer available.");
                    this.openOrderDeliveriesMenu(player);
                    return;
                }
                for (OrderDeliveryEntry delivery : claimed) {
                    for (ItemStack stack : this.splitOrderDeliveryStacks(delivery)) {
                        this.dropItemLikePlayer(player, stack);
                    }
                }
                if (totalPayout > 0.0) {
                    this.depositMoney(player, totalPayout);
                    player.sendMessage("\u00a7aDropped " + claimed.size() + " delivery " + (claimed.size() == 1 ? "entry" : "entries") + " for $" + this.fmtMoney(totalPayout) + ".");
                } else {
                    player.sendMessage("\u00a7aDropped " + claimed.size() + " delivery " + (claimed.size() == 1 ? "entry" : "entries") + ".");
                }
                this.openOrderDeliveriesMenu(player);
            });
        });
    }

    private void sellVisibleOrderDeliveries(Player player) {
        OrdersViewState state = this.ordersViewState.computeIfAbsent(player.getUniqueId(), id -> new OrdersViewState());
        if (state.selectedOrderId <= 0L) {
            this.openOrdersMyMenu(player);
            return;
        }
        this.runAsyncTask(() -> {
            List<OrderDeliveryEntry> deliveries = this.queryPendingOrderDeliveries(player.getUniqueId(), state.selectedOrderId);
            List<Long> ids = this.visibleOrderDeliveryIds(deliveries, state.deliveriesPage);
            if (ids.isEmpty()) {
                this.runOnPlayerThread(player, () -> player.sendMessage("\u00a7cThere are no claimable deliveries on this page."));
                return;
            }
            List<OrderDeliveryEntry> claimed = this.claimOrderDeliveries(player.getUniqueId(), state.selectedOrderId, ids);
            this.runOnPlayerThread(player, () -> {
                if (claimed.isEmpty()) {
                    player.sendMessage("\u00a7cThose deliveries are no longer available.");
                    this.openOrderDeliveriesMenu(player);
                    return;
                }
                double total = 0.0;
                double payoutTotal = 0.0;
                ArrayList<ItemStack> unsellable = new ArrayList<ItemStack>();
                int soldAmount = 0;
                for (OrderDeliveryEntry delivery : claimed) {
                    payoutTotal += delivery.payout();
                    double worth = this.getItemWorth(delivery.item());
                    if (worth <= 0.0) {
                        unsellable.addAll(this.splitOrderDeliveryStacks(delivery));
                        continue;
                    }
                    soldAmount += delivery.amount();
                    total += worth;
                }
                for (ItemStack stack : unsellable) {
                    this.giveItemStack(player, stack);
                }
                double totalCredited = total + payoutTotal;
                if (totalCredited > 0.0) {
                    this.depositMoney(player, totalCredited);
                    this.runAsyncTask(() -> this.incrementMoneyStat(player.getUniqueId(), "sell_earned", totalCredited));
                    String msg = "\u00a7aSold " + soldAmount + " order items for $" + this.fmtMoney(totalCredited) + ".";
                    if (payoutTotal > 0.0) {
                        msg = "\u00a7aSold " + soldAmount + " order items ($" + this.fmtMoney(total) + ") + payout ($" + this.fmtMoney(payoutTotal) + ") = $" + this.fmtMoney(totalCredited) + ".";
                    }
                    player.sendMessage(msg);
                } else {
                    player.sendMessage("\u00a77No sellable items were found on that page.");
                }
                if (!unsellable.isEmpty()) {
                    player.sendMessage("\u00a77Returned " + unsellable.size() + " unsellable stack" + (unsellable.size() == 1 ? "" : "s") + " to you.");
                }
                this.openOrderDeliveriesMenu(player);
            });
        });
    }

    private List<OrderDeliveryEntry> claimOrderDeliveries(UUID creator, long orderId, List<Long> deliveryIds) {
        ArrayList<OrderDeliveryEntry> claimed = new ArrayList<OrderDeliveryEntry>();
        if (creator == null || deliveryIds == null || deliveryIds.isEmpty()) {
            return claimed;
        }
        ArrayList<Long> ids = new ArrayList<Long>();
        for (Long deliveryId : deliveryIds) {
            if (deliveryId == null || deliveryId.longValue() <= 0L || ids.contains(deliveryId)) continue;
            ids.add(deliveryId);
        }
        if (ids.isEmpty()) {
            return claimed;
        }
        StringBuilder placeholders = new StringBuilder();
        for (int i = 0; i < ids.size(); ++i) {
            if (i > 0) {
                placeholders.append(",");
            }
            placeholders.append("?");
        }
        String selectSql = "SELECT d.id,d.item_blob,d.amount,d.payout,d.fulfiller_uuid,d.created_at,p.username FROM order_deliveries d JOIN order_listings o ON o.id=d.order_id LEFT JOIN players p ON p.uuid=d.fulfiller_uuid WHERE o.creator_uuid=? AND d.claimed=0" + (orderId > 0L ? " AND d.order_id=?" : "") + " AND d.id IN (" + placeholders + ") FOR UPDATE";
        String updateSql = "UPDATE order_deliveries SET claimed=1, claimed_at=CURRENT_TIMESTAMP WHERE claimed=0 AND id IN (" + placeholders + ")";
        try (Connection conn = this.openSyncConnection();){
            conn.setAutoCommit(false);
            try (PreparedStatement sel = conn.prepareStatement(selectSql);
                 PreparedStatement upd = conn.prepareStatement(updateSql);){
                int param = 1;
                sel.setString(param++, creator.toString());
                if (orderId > 0L) {
                    sel.setLong(param++, orderId);
                }
                for (Long id : ids) {
                    sel.setLong(param++, id.longValue());
                }
                try (ResultSet rs = sel.executeQuery();){
                    while (rs.next()) {
                        ItemStack item = this.deserializeItem(rs.getBytes(2));
                        if (item == null) {
                            item = new ItemStack(Material.STONE, Math.max(1, rs.getInt(3)));
                        }
                        claimed.add(new OrderDeliveryEntry(rs.getLong(1), item, rs.getInt(3), rs.getDouble(4), this.safeName(rs.getString(7), rs.getString(5)), rs.getTimestamp(6) == null ? System.currentTimeMillis() : rs.getTimestamp(6).getTime()));
                    }
                }
                if (claimed.isEmpty()) {
                    conn.rollback();
                    return claimed;
                }
                param = 1;
                for (Long id : ids) {
                    upd.setLong(param++, id.longValue());
                }
                upd.executeUpdate();
                conn.commit();
            }
            catch (Exception ex) {
                conn.rollback();
                throw ex;
            }
            finally {
                conn.setAutoCommit(true);
            }
        }
        catch (Exception ex) {
            this.getLogger().warning("Failed claiming order deliveries: " + ex.getMessage());
            claimed.clear();
        }
        return claimed;
    }

    private List<ItemStack> splitOrderDeliveryStacks(OrderDeliveryEntry delivery) {
        ArrayList<ItemStack> stacks = new ArrayList<ItemStack>();
        if (delivery == null || delivery.item() == null || delivery.amount() <= 0) {
            return stacks;
        }
        ItemStack template = delivery.item().clone();
        int remaining = delivery.amount();
        while (remaining > 0) {
            ItemStack stack = template.clone();
            int giveAmount = Math.min(remaining, Math.max(1, stack.getMaxStackSize()));
            stack.setAmount(giveAmount);
            stacks.add(stack);
            remaining -= giveAmount;
        }
        return stacks;
    }

    private void handleOrdersNewClick(Player player, int slot, ItemStack item) {
        if (item == null || !item.hasItemMeta()) {
            return;
        }
        String id = this.uiActionId(item);
        if (id == null) {
            return;
        }
        switch (id) {
            case "orders_new_cancel": {
                this.openOrdersMyMenu(player);
                break;
            }
            case "orders_new_item": {
                OrdersViewState state = this.ordersViewState.computeIfAbsent(player.getUniqueId(), k -> new OrdersViewState());
                state.page = 1;
                this.openOrderItemPicker(player);
                break;
            }
            case "orders_new_amount": {
                this.requestTextInput(player, TextInputMode.ORDER_AMOUNT, "Type order amount in chat (supports 1k/1m/1b).");
                break;
            }
            case "orders_new_price": {
                this.requestTextInput(player, TextInputMode.ORDER_PRICE, "Type unit price in chat (supports 1k/1m/1b).");
                break;
            }
            case "orders_new_confirm": {
                this.createOrderFromBuilder(player);
                break;
            }
        }
    }

    private void handleOrdersPickerClick(Player player, int slot, ItemStack item) {
        if (item == null || !item.hasItemMeta()) {
            return;
        }
        String id = this.uiActionId(item);
        if (id == null) {
            return;
        }
        OrdersViewState state = this.ordersViewState.computeIfAbsent(player.getUniqueId(), k -> new OrdersViewState());
        switch (id) {
            case "orders_pick_search": {
                this.requestTextInput(player, TextInputMode.ORDER_ITEM_SEARCH, "Type item search text in chat.");
                break;
            }
            case "orders_pick_prev": {
                state.page = Math.max(1, state.page - 1);
                this.openOrderItemPicker(player);
                break;
            }
            case "orders_pick_next": {
                ++state.page;
                this.openOrderItemPicker(player);
                break;
            }
            default: {
                Material mat;
                if (!id.startsWith("orders_pick_item:") || (mat = Material.matchMaterial((String)id.substring("orders_pick_item:".length()))) == null || !mat.isItem()) break;
                OrderBuilderState builder = this.orderBuilderState.computeIfAbsent(player.getUniqueId(), k -> new OrderBuilderState());
                builder.material = mat;
                this.openOrderBuilder(player);
            }
        }
    }

    private void handleAhMainClick(Player player, int slot, ItemStack item, ClickType clickType) {
        if (item == null || !item.hasItemMeta()) {
            return;
        }
        String id = this.uiActionId(item);
        if (id == null) {
            return;
        }
        AhViewState state = this.ahViewState.computeIfAbsent(player.getUniqueId(), k -> new AhViewState());
        switch (id) {
            case "ah_refresh": {
                this.openAuctionHouseMenu(player);
                break;
            }
            case "ah_prev": {
                state.page = Math.max(1, state.page - 1);
                this.openAuctionHouseMenu(player);
                break;
            }
            case "ah_next": {
                ++state.page;
                this.openAuctionHouseMenu(player);
                break;
            }
            case "ah_sort": {
                state.nextSort();
                state.page = 1;
                this.openAuctionHouseMenu(player);
                break;
            }
            case "ah_filter": {
                state.nextFilter();
                state.page = 1;
                this.openAuctionHouseMenu(player);
                break;
            }
            case "ah_search": {
                this.requestTextInput(player, TextInputMode.AH_SEARCH, "Type auction search text in chat.");
                break;
            }
            case "ah_my_items": {
                state.page = 1;
                this.openAhMyItems(player);
                break;
            }
            case "ah_sell": {
                this.openAhSellInsert(player);
                break;
            }
            default: {
                long listingId;
                if (!id.startsWith("ah_listing:") || !clickType.isLeftClick() || (listingId = this.parseLongSafe(id.substring("ah_listing:".length()), -1L)) <= 0L) break;
                // Quick Auction Buy: when ON, a plain click buys the item instantly (no confirm).
                // When OFF, the click opens the confirm screen.
                if (this.isSettingEnabledCached(player.getUniqueId(), "quick_auction_buy")) {
                    // Rapid-fire allowed: dedupe is per-listing (inside buyAhListing). Pass the slot so
                    // the bought item is removed in place (no menu reorder that would mis-buy).
                    this.buyAhListing(player, listingId, slot);
                } else {
                    this.openAhBuyConfirm(player, listingId);
                }
            }
        }
    }

