    private void handleAhSellInsertClick(Player player, InventoryClickEvent e) {
        int rawSlot = e.getRawSlot();
        if (rawSlot < 0) {
            return;
        }
        Inventory top = e.getView().getTopInventory();
        int topSize = top.getSize();
        if (rawSlot >= topSize) {
            if (!e.isShiftClick()) {
                return;
            }
            ItemStack moving = e.getCurrentItem();
            if (moving == null || moving.getType() == Material.AIR) {
                return;
            }
            e.setCancelled(true);
            ItemStack existing = top.getItem(4);
            if (existing != null && existing.getType() != Material.AIR) {
                player.sendMessage("\u00a7cRemove the current item first.");
                return;
            }
            top.setItem(4, moving.clone());
            e.getClickedInventory().setItem(e.getSlot(), null);
            return;
        }
        if (rawSlot >= 9) {
            return;
        }
        if (rawSlot != 4) {
            e.setCancelled(true);
        }
        if (rawSlot == 0) {
            this.openAuctionHouseMenu(player);
            return;
        }
        if (rawSlot == 8) {
            ItemStack toSell = top.getItem(4);
            if (toSell == null || toSell.getType() == Material.AIR) {
                player.sendMessage("\u00a7cInsert an item first.");
                return;
            }
            AhSellState state = this.ahSellState.computeIfAbsent(player.getUniqueId(), k -> new AhSellState());
            state.item = toSell.clone();
            top.setItem(4, null);
            this.requestTextInput(player, TextInputMode.AH_SELL_PRICE, "Type listing price in chat (supports 1k/1m/1b).");
        }
    }

    private void handleAhSellConfirmClick(Player player, int slot, ItemStack item) {
        if (item == null || !item.hasItemMeta()) {
            return;
        }
        String id = this.uiActionId(item);
        if (id == null) {
            return;
        }
        if ("ah_sell_confirm_cancel".equals(id)) {
            this.ahSellCloseBypass.add(player.getUniqueId());
            this.openAhSellInsert(player);
            return;
        }
        if ("ah_sell_confirm_accept".equals(id)) {
            this.finalizeAhListing(player);
        }
    }

    private void requestTextInput(Player player, TextInputMode mode, String prompt) {
        if (this.useDialogUi(player)) {
            this.showTextInputDialog(player, mode);
            return;
        }
        this.pendingTextInputs.put(player.getUniqueId(), new PendingTextInput(mode));
        player.closeInventory();
        player.sendMessage("\u00a7f" + prompt);
    }

    /** Dialog-based replacement for the chat text prompt (1.21.6+). Mode-aware body + prefill + minimum. */
    private void showTextInputDialog(Player player, TextInputMode mode) {
        List<DialogBody> body = new ArrayList<>();
        String initial = "";
        switch (mode) {
            case ORDER_AMOUNT: {
                OrderBuilderState s = this.orderBuilderState.get(player.getUniqueId());
                initial = (s != null && s.amount > 0) ? Long.toString(s.amount) : "1";
                break;
            }
            case ORDER_PRICE: {
                OrderBuilderState s = this.orderBuilderState.get(player.getUniqueId());
                double worth = (s != null && s.material != null) ? this.sellUnitPrice(s.material) : 0.0;
                long amt = (s != null) ? s.amount : 0L;
                if (amt > 0) body.add(DialogBody.plainMessage(Component.text("Amount: " + amt, NamedTextColor.GRAY)));
                if (worth > 0) body.add(DialogBody.plainMessage(Component.text("Minimum: $" + this.fmtMoney(worth), NamedTextColor.GREEN)));
                double cur = (s != null) ? s.unitPrice : 0.0;
                initial = this.fmtMoney(cur > 0 ? cur : Math.max(1.0, worth));
                break;
            }
            case AH_SELL_PRICE: {
                AhSellState s = this.ahSellState.get(player.getUniqueId());
                double floor = (s != null && s.item != null) ? this.worthFloorFor(s.item) : 0.0;
                if (floor > 0) body.add(DialogBody.plainMessage(Component.text("Minimum: $" + this.fmtMoney(floor), NamedTextColor.GREEN)));
                double cur = (s != null) ? s.price : 0.0;
                initial = this.fmtMoney(cur > 0 ? cur : Math.max(1.0, floor));
                break;
            }
            default: break;
        }
        var ib = DialogInput.text("value", Component.text(mode.label, NamedTextColor.GRAY))
            .width(300).maxLength(mode.numeric ? 16 : 48);
        if (!initial.isEmpty()) ib.initial(initial);
        List<DialogInput> inputs = List.of(ib.build());
        ActionButton confirm = ActionButton.builder(Component.text(mode.confirmLabel, NamedTextColor.GREEN))
            .width(150)
            .action(DialogAction.customClick((view, audience) -> {
                if (audience instanceof Player pl) {
                    String raw = view.getText("value");
                    this.runOnPlayerThread(pl, () -> {
                        if (raw == null || raw.isBlank()) {
                            this.reopenAfterTextCancel(pl, mode);
                        } else {
                            this.handlePendingTextInput(pl, new PendingTextInput(mode), raw);
                        }
                    });
                }
            }, ClickCallback.Options.builder().build()))
            .build();
        ActionButton cancel = this.dialogButton(Component.text("Cancel", NamedTextColor.RED), null, 150,
            pl -> this.reopenAfterTextCancel(pl, mode));
        Dialog dialog = this.buildDialog(Component.text(mode.title, DIALOG_BRAND), body, inputs,
            DialogType.confirmation(confirm, cancel));
        player.showDialog(dialog);
    }

    /** Cancel/blank from a text-input dialog: return to the menu that opened it. */
    private void reopenAfterTextCancel(Player player, TextInputMode mode) {
        switch (mode) {
            case ORDERS_SEARCH -> this.openOrdersMenu(player);
            case ORDER_ITEM_SEARCH -> this.openOrderItemPicker(player);
            case ORDER_AMOUNT, ORDER_PRICE -> {
                // Cancel exits the flow: go to Review if the order is already complete, else back
                // to Your Orders (do NOT re-open the same input, which used to loop forever).
                OrderBuilderState s = this.orderBuilderState.get(player.getUniqueId());
                if (s != null && s.material != null && s.amount > 0L && s.unitPrice > 0.0) {
                    this.openOrderReviewDialog(player);
                } else {
                    this.openOrdersMyMenu(player);
                }
            }
            case AH_SEARCH -> this.openAuctionHouseMenu(player);
            case AH_SELL_PRICE -> this.openAhSellInsert(player);
            case BOUNTY_SEARCH -> this.openBountyGui(player, 1);
        }
    }

    private void handlePendingTextInput(Player player, PendingTextInput pendingInput, String rawText) {
        String text;
        String string = text = rawText == null ? "" : rawText.trim();
        if (text.isEmpty()) {
            player.sendMessage("\u00a7cInput cannot be empty.");
            return;
        }
        switch (pendingInput.mode.ordinal()) {
            case 0: {
                OrdersViewState state = this.ordersViewState.computeIfAbsent(player.getUniqueId(), k -> new OrdersViewState());
                state.search = text;
                state.page = 1;
                this.openOrdersMenu(player);
                break;
            }
            case 1: {
                OrdersViewState state = this.ordersViewState.computeIfAbsent(player.getUniqueId(), k -> new OrdersViewState());
                state.search = text;
                state.page = 1;
                this.openOrderItemPicker(player);
                break;
            }
            case 2: {
                ParsedAmount parsed = this.parseCompactAmount(text);
                if (parsed == null || parsed.value < 1.0) {
                    player.sendMessage("\u00a7cInvalid amount.");
                    this.reopenOrderBuilderStep(player, TextInputMode.ORDER_AMOUNT);
                    return;
                }
                OrderBuilderState builder = this.orderBuilderState.computeIfAbsent(player.getUniqueId(), k -> new OrderBuilderState());
                builder.amount = (long)Math.floor(parsed.value);
                this.reopenOrderBuilderStep(player, null);
                break;
            }
            case 3: {
                ParsedAmount parsed = this.parseCompactAmount(text);
                if (parsed == null || parsed.value < 1.0) {
                    player.sendMessage("\u00a7cInvalid price.");
                    this.reopenOrderBuilderStep(player, TextInputMode.ORDER_PRICE);
                    return;
                }
                OrderBuilderState builder = this.orderBuilderState.computeIfAbsent(player.getUniqueId(), k -> new OrderBuilderState());
                // "No less than actual worth": floor the unit price at the item's sell worth.
                double worth = builder.material != null ? this.sellUnitPrice(builder.material) : 0.0;
                if (worth > 0 && parsed.value < worth) {
                    player.sendMessage("\u00a7cPrice cannot be below the item's worth ($" + this.fmtMoney(worth) + ").");
                    this.reopenOrderBuilderStep(player, TextInputMode.ORDER_PRICE);
                    return;
                }
                builder.unitPrice = parsed.value;
                this.reopenOrderBuilderStep(player, null);
                break;
            }
            case 4: {
                AhViewState state = this.ahViewState.computeIfAbsent(player.getUniqueId(), k -> new AhViewState());
                state.search = text;
                state.page = 1;
                this.openAuctionHouseMenu(player);
                break;
            }
            case 5: {
                ParsedAmount parsed = this.parseCompactAmount(text);
                if (parsed == null || parsed.value < 1.0) {
                    player.sendMessage("\u00a7cInvalid price.");
                    this.requestTextInput(player, TextInputMode.AH_SELL_PRICE, "Type listing price in chat (supports 1k/1m/1b).");
                    return;
                }
                AhSellState state = this.ahSellState.computeIfAbsent(player.getUniqueId(), k -> new AhSellState());
                double floor = state.item != null ? this.worthFloorFor(state.item) : 0.0;
                if (floor > 0 && parsed.value < floor) {
                    player.sendMessage("\u00a7cListing price cannot be below the worth floor ($" + this.fmtMoney(floor) + ").");
                    this.requestTextInput(player, TextInputMode.AH_SELL_PRICE, "Type listing price in chat (supports 1k/1m/1b).");
                    return;
                }
                state.price = parsed.value;
                // Quick Auction Sell ON -> list immediately (no confirm); OFF -> show the confirm screen with the price.
                if (this.isSettingEnabledCached(player.getUniqueId(), "quick_auction_sell")) {
                    this.finalizeAhListing(player);
                } else {
                    this.openAhSellConfirm(player);
                }
                break;
            }
            case 6: {
                this.bountyGuiSearch.put(player.getUniqueId(), text);
                this.openBountyGui(player, 1);
                break;
            }
        }
    }

    private void createOrderFromBuilder(Player player) {
        OrderBuilderState state = this.orderBuilderState.computeIfAbsent(player.getUniqueId(), k -> new OrderBuilderState());
        if (state.material == null || !state.material.isItem()) {
            player.sendMessage("\u00a7cChoose an item first.");
            return;
        }
        if (state.amount < 1L || state.unitPrice < 1.0) {
            player.sendMessage("\u00a7cSet amount and price first.");
            return;
        }
        double total = (double)state.amount * state.unitPrice;
        if (!this.withdrawMoney(player, total)) {
            player.sendMessage("\u00a7cNot enough money for escrow.");
            return;
        }
        UUID uuid = player.getUniqueId();
        Material material = state.material;
        long amount = state.amount;
        double unitPrice = state.unitPrice;
        final int orderCap = this.marketSlotCap(player);
        this.runAsyncTask(() -> {
            // Tiered concurrent-order cap: default 18, pizza+ 27, pizza++/staff 36.
            int activeOrders = 0;
            try (Connection conn = this.openSyncConnection();
                 PreparedStatement cps = conn.prepareStatement("SELECT COUNT(*) FROM order_listings WHERE creator_uuid=? AND status='ACTIVE'")) {
                cps.setString(1, uuid.toString());
                try (ResultSet rs = cps.executeQuery()) {
                    if (rs.next()) activeOrders = rs.getInt(1);
                }
            } catch (Exception ex) {
                this.getLogger().warning("Failed counting orders: " + ex.getMessage());
            }
            if (activeOrders >= orderCap) {
                this.depositMoney(player, total);
                this.runOnPlayerThread(player, () ->
                    player.sendMessage("§cYou have reached your open order limit (§f" + orderCap + "§c). Escrow refunded."));
                return;
            }
            String sql = "INSERT INTO order_listings (creator_uuid,item_key,amount_total,amount_filled,unit_price,status,expires_at) VALUES (?,?,?,?,?,'ACTIVE',DATE_ADD(NOW(), INTERVAL 80 DAY))";
            try (Connection conn = this.openSyncConnection();
                 PreparedStatement ps = conn.prepareStatement(sql);){
                ps.setString(1, uuid.toString());
                ps.setString(2, material.name());
                ps.setInt(3, (int)Math.min(Integer.MAX_VALUE, amount));
                ps.setInt(4, 0);
                ps.setDouble(5, unitPrice);
                ps.executeUpdate();
            }
            catch (Exception ex) {
                this.depositMoney(player, total);
                this.runOnPlayerThread(player, () -> player.sendMessage("\u00a7cOrder creation failed."));
                return;
            }
            this.logTransactionAudit(uuid.toString(), player.getName(), "ORDER_CREATE", material.name(), (int)Math.min(Integer.MAX_VALUE, amount), unitPrice, total, null);
            this.runOnPlayerThread(player, () -> {
                player.sendMessage("\u00a7aOrder listed.");
                this.openOrdersMyMenu(player);
            });
        });
    }

    private void fulfillOrder(Player player, long orderId) {
        this.runAsyncTask(() -> {
            OrderEntry order = this.loadOrderById(orderId);
            this.runOnPlayerThread(player, () -> {
                if (order == null) {
                    player.sendActionBar(this.legacyColorize("\u00a7cOrder is no longer available."));
                    this.orderFulfillmentState.remove(player.getUniqueId());
                    return;
                }
                // Open delivery insert even if order is full; confirm step will block delivery
                this.openOrderDeliveryInsert(player, order);
            });
        });
    }

    private void cancelOwnOrder(Player player, long orderId) {
        this.runAsyncTask(() -> {
            try (Connection conn = this.openSyncConnection();){
                conn.setAutoCommit(false);
                try (PreparedStatement sel = conn.prepareStatement("SELECT amount_total,amount_filled,unit_price FROM order_listings WHERE id=? AND creator_uuid=? AND status='ACTIVE' AND (expires_at IS NULL OR expires_at > CURRENT_TIMESTAMP) FOR UPDATE");
                     PreparedStatement upd = conn.prepareStatement("UPDATE order_listings SET status='CANCELLED' WHERE id=? AND creator_uuid=? AND status='ACTIVE'");
                     PreparedStatement refund = conn.prepareStatement("INSERT INTO balances (uuid,pending_vault_credit) VALUES (?,?) ON DUPLICATE KEY UPDATE pending_vault_credit=pending_vault_credit+VALUES(pending_vault_credit)");){
                    double unitPrice;
                    int remaining;
                    sel.setLong(1, orderId);
                    sel.setString(2, player.getUniqueId().toString());
                    try (ResultSet rs = sel.executeQuery();){
                        if (!rs.next()) {
                            conn.rollback();
                            this.runOnPlayerThread(player, () -> player.sendMessage("\u00a7cOrder is no longer active."));
                            return;
                        }
                        remaining = Math.max(0, rs.getInt(1) - rs.getInt(2));
                        unitPrice = rs.getDouble(3);
                    }
                    upd.setLong(1, orderId);
                    upd.setString(2, player.getUniqueId().toString());
                    if (upd.executeUpdate() <= 0) {
                        conn.rollback();
                        this.runOnPlayerThread(player, () -> player.sendMessage("\u00a7cCancel failed."));
                        return;
                    }
                    double refundAmount = (double)remaining * unitPrice;
                    if (refundAmount > 0.0) {
                        refund.setString(1, player.getUniqueId().toString());
                        refund.setDouble(2, refundAmount);
                        refund.executeUpdate();
                    }
                    conn.commit();
                    this.runOnPlayerThread(player, () -> {
                        if (refundAmount > 0.0) {
                            this.applyPendingCreditNow(player);
                            player.sendMessage("\u00a7aOrder cancelled. Refunded $" + this.fmtMoney(refundAmount) + ".");
                        } else {
                            player.sendMessage("\u00a7aOrder cancelled.");
                        }
                        this.openOrdersMyMenu(player);
                        // Vanish the cancelled order for everyone else browsing orders.
                        this.refreshOrdersForViewers(player.getUniqueId());
                    });
                    return;
                }
                catch (Exception ex) {
                    conn.rollback();
                    throw ex;
                }
                finally {
                    conn.setAutoCommit(true);
                }
            }
            catch (Exception ex) {
                this.runOnPlayerThread(player, () -> player.sendMessage("\u00a7cCancel failed."));
            }
        });
    }

    private void openOrderDeliveriesMenu(Player player) {
        OrdersViewState state = this.ordersViewState.computeIfAbsent(player.getUniqueId(), id -> new OrdersViewState());
        boolean allDeliveries = state.selectedOrderId <= 0L;
        this.runAsyncTask(() -> {
            OrderEntry order = allDeliveries ? null : this.loadOrderByIdForCreator(state.selectedOrderId, player.getUniqueId());
            List<OrderDeliveryEntry> deliveries = allDeliveries
                ? this.queryPendingOrderDeliveries(player.getUniqueId())
                : (order == null ? List.of() : this.queryPendingOrderDeliveries(player.getUniqueId(), state.selectedOrderId));
            this.runOnPlayerThread(player, () -> {
                if (!allDeliveries && order == null) {
                    player.sendMessage("\u00a7cThat order is no longer active.");
                    this.openOrdersMyMenu(player);
                    return;
                }
                Inventory inv = Bukkit.createInventory(null, (int)54, (String)TITLE_ORDERS_DELIVERIES);
                int startIdx = Math.max(0, (state.deliveriesPage - 1) * 45);
                int endIdx = Math.min(deliveries.size(), startIdx + 45);
                for (int i = startIdx; i < endIdx; i++) {
                    OrderDeliveryEntry delivery = deliveries.get(i);
                    if (delivery.item() == null) continue;
                    ItemStack stack = delivery.item().clone();
                    // One slot per delivery \u2014 display one stack, full amount shown in lore
                    stack.setAmount(Math.max(1, Math.min(delivery.amount(), stack.getMaxStackSize())));
                    ItemMeta meta = stack.getItemMeta();
                    meta.setDisplayName("\u00a7a" + this.humanName(delivery.item().getType()));
                    meta.setLore(List.of(
                        "\u00a77Amount: \u00a7f" + String.format("%,d", delivery.amount()) + "x",
                        "\u00a77Delivered by: \u00a7f" + delivery.fulfillerName(),
                        "\u00a77Paid out: \u00a7f$" + this.fmtMoney(delivery.payout()),
                        "\u00a77Time: \u00a7f" + this.shortAge(delivery.createdAtMs()),
                        "\u00a7aClick to claim"
                    ));
                    if (this.uiActionKey != null) {
                        meta.getPersistentDataContainer().set(this.uiActionKey, PersistentDataType.STRING, "orders_claim_delivery:" + delivery.id());
                    }
                    stack.setItemMeta(meta);
                    inv.setItem(i - startIdx, stack);
                }
                if (state.deliveriesPage > 1) {
                    inv.setItem(45, this.namedWithLore(Material.ARROW, "\u00a7aPrevious", "orders_claims_prev", List.of()));
                }
                if (deliveries.size() > endIdx) {
                    inv.setItem(53, this.namedWithLore(Material.ARROW, "\u00a7aNext", "orders_claims_next", List.of()));
                }
                inv.setItem(48, this.namedWithLore(Material.HOPPER, "\u00a7a\u00a7lClaim Everything", "orders_claims_claim_all", List.of("\u00a77Collect \u00a7fall \u00a77pending deliveries", "\u00a77across every page at once")));
                inv.setItem(49, this.namedWithLore(Material.EMERALD, "\u00a7aSell all on page", "orders_claims_sell_page", List.of()));
                inv.setItem(52, this.namedWithLore(Material.DROPPER, "\u00a7aDrop this page", "orders_claims_drop_page", List.of()));
                player.openInventory(inv);
            });
        });
    }

    private void openAhMyItems(Player player) {
        AhViewState state = this.ahViewState.computeIfAbsent(player.getUniqueId(), k -> new AhViewState());
        this.runAsyncTask(() -> {
            List<AhListingEntry> mine = this.queryAhMyListings(player.getUniqueId(), state.page);
            this.runOnPlayerThread(player, () -> {
                Inventory inv = Bukkit.createInventory(null, (int)54, (String)TITLE_AH_MY);
                // Tiered slot grid: active listings fill from slot 0, then GRAY "empty" slots up to
                // the rank cap (click to sell), then RED locked slots (unlock with Pizza+/Pizza++).
                int cap = this.marketSlotCap(player);
                this.renderAhMyListingEntries(inv, mine, 1);
                int n = Math.min(mine.size(), 45);
                this.fillMarketSlots(inv, n, cap, "ah_new_slot", "\u00a77Empty Listing Slot", "\u00a7fClick to sell an item");
                inv.setItem(49, this.namedWithLore(Material.WRITABLE_BOOK, "\u00a7aPast transactions", "ah_my_tx", List.of()));
                inv.setItem(50, this.namedWithLore(Material.ARROW, "\u00a7aBack to Auction House", "ah_my_back_main", List.of()));
                player.openInventory(inv);
            });
        });
    }

    private void openAhTransactions(Player player) {
        AhViewState state = this.ahViewState.computeIfAbsent(player.getUniqueId(), k -> new AhViewState());
        this.runAsyncTask(() -> {
            List<AhTxEntry> tx = this.queryAhTransactions(player.getUniqueId(), state.page);
            this.runOnPlayerThread(player, () -> {
                Inventory inv = Bukkit.createInventory(null, (int)54, (String)TITLE_AH_TX);
                int slot = 0;
                int start = Math.max(0, (state.page - 1) * 45);
                int end = Math.min(tx.size(), start + 45);
                for (int i = start; i < end; ++i) {
                    AhTxEntry t = (AhTxEntry)tx.get(i);
                    ItemStack item = t.item.clone();
                    ItemMeta meta = item.getItemMeta();
                    meta.setDisplayName("\u00a7a" + this.humanName(item.getType()));
                    meta.setLore(List.of("\u00a77Price: \u00a7f$" + this.fmtMoney(t.price), "\u00a77With: \u00a7f" + t.otherName, "\u00a77Time: \u00a7f" + this.shortAge(t.createdAtMs)));
                    item.setItemMeta(meta);
                    inv.setItem(slot++, item);
                }
                if (state.page > 1) {
                    inv.setItem(45, this.namedWithLore(Material.ARROW, "\u00a7aBack", "ah_tx_prev", List.of()));
                }
                if (tx.size() > state.page * 45) {
                    inv.setItem(53, this.namedWithLore(Material.ARROW, "\u00a7aNext", "ah_tx_next", List.of()));
                }
                inv.setItem(50, this.namedWithLore(Material.ARROW, "\u00a7aBack to Your Items", "ah_tx_back", List.of()));
                player.openInventory(inv);
            });
        });
    }

