    private void openAhSellConfirm(Player player) {
        AhSellState state = this.ahSellState.get(player.getUniqueId());
        if (state == null || state.item == null || state.price <= 0.0) {
            this.openAhSellInsert(player);
            return;
        }
        if (this.useDialogUi(player)) {
            this.openAhSellConfirmDialog(player, state);
            return;
        }
        double floor = this.worthFloorFor(state.item);
        Inventory inv = Bukkit.createInventory(null, (int)27, (String)TITLE_AH_CONFIRM);
        ItemStack preview = state.item.clone();
        ItemMeta meta = preview.getItemMeta();
        ArrayList<String> lore = meta.hasLore() ? new ArrayList<String>(meta.getLore()) : new ArrayList<String>();
        lore.add("\u00a7fPrice: \u00a7f$" + this.fmtMoney(state.price));
        lore.add("\u00a7fWorth floor: \u00a7f$" + this.fmtMoney(floor));
        meta.setLore(lore);
        preview.setItemMeta(meta);
        inv.setItem(13, preview);
        inv.setItem(12, this.namedWithLore(Material.RED_STAINED_GLASS_PANE, "\u00a7c\u00a7lCancel", "ah_sell_confirm_cancel", List.of()));
        inv.setItem(14, this.namedWithLore(Material.GREEN_STAINED_GLASS_PANE, "\u00a7a\u00a7lConfirm", "ah_sell_confirm_accept", List.of()));
        player.openInventory(inv);
    }

    /** "Review Listing" dialog (1.21.6+): item icon + price + worth floor, Change Price / Create Listing. */
    private void openAhSellConfirmDialog(Player player, AhSellState state) {
        double floor = this.worthFloorFor(state.item);
        double total = state.price;
        List<DialogBody> body = List.of(
            DialogBody.item(state.item.clone()).build(),
            DialogBody.plainMessage(Component.text("Item: " + this.humanName(state.item.getType()) + " x" + state.item.getAmount(), NamedTextColor.WHITE)),
            DialogBody.plainMessage(Component.text("Price: $" + this.fmtMoney(total), NamedTextColor.GREEN)),
            DialogBody.plainMessage(Component.text("Worth floor: $" + this.fmtMoney(floor), NamedTextColor.GRAY)));
        List<ActionButton> buttons = new ArrayList<>();
        buttons.add(this.dialogButton(Component.text("Change Price", NamedTextColor.WHITE), null, 150,
            pl -> this.requestTextInput(pl, TextInputMode.AH_SELL_PRICE, "Type listing price in chat (supports 1k/1m/1b).")));
        buttons.add(this.dialogButton(Component.text("Create Listing", NamedTextColor.GREEN), null, 150,
            pl -> { pl.closeDialog(); this.finalizeAhListing(pl); }));
        Dialog dialog = this.buildDialog(Component.text("Review Listing", DIALOG_BRAND), body, List.of(),
            DialogType.multiAction(buttons).columns(2)
                .exitAction(this.dialogButton(Component.text("Cancel", NamedTextColor.RED), null, 150,
                    pl -> this.openAhSellInsert(pl))).build());
        player.showDialog(dialog);
    }

    private void finalizeAhListing(Player player) {
        AhSellState state = this.ahSellState.get(player.getUniqueId());
        if (state == null || state.item == null || state.price <= 0.0) {
            this.openAhSellInsert(player);
            return;
        }
        double floor = this.worthFloorFor(state.item);
        if (state.price < floor) {
            player.sendMessage("\u00a7cListing price is below worth floor.");
            return;
        }
        ItemStack listingItem = state.item.clone();
        state.item = null;
        final int listingCap = this.marketSlotCap(player);
        this.runAsyncTask(() -> {
            final double ahPrice = state.price;
            // Tiered concurrent-listing cap: default 18, pizza+ 27, pizza++/staff 36.
            int activeCount = 0;
            try (Connection conn = this.openSyncConnection();
                 PreparedStatement cps = conn.prepareStatement("SELECT COUNT(*) FROM auction_listings WHERE seller_uuid=? AND status='ACTIVE'")) {
                cps.setString(1, player.getUniqueId().toString());
                try (ResultSet rs = cps.executeQuery()) {
                    if (rs.next()) activeCount = rs.getInt(1);
                }
            } catch (Exception ex) {
                this.getLogger().warning("Failed counting AH listings: " + ex.getMessage());
            }
            if (activeCount >= listingCap) {
                this.runOnPlayerThread(player, () -> {
                    java.util.HashMap<Integer, ItemStack> overflow = player.getInventory().addItem(listingItem);
                    for (ItemStack left : overflow.values()) {
                        this.dropForPlayer(player, left);
                    }
                    player.sendMessage("§cYou have reached your auction listing limit (§f" + listingCap + "§c). Item returned.");
                });
                return;
            }
            String sql = "INSERT INTO auction_listings (seller_uuid,item_blob,item_key,price,status,expires_at) VALUES (?,?,?,?, 'ACTIVE', DATE_ADD(NOW(), INTERVAL 7 DAY))";
            try (Connection conn = this.openSyncConnection();
                 PreparedStatement ps = conn.prepareStatement(sql);){
                ps.setString(1, player.getUniqueId().toString());
                ps.setBytes(2, this.serializeItem(listingItem));
                ps.setString(3, listingItem.getType().name());
                ps.setDouble(4, ahPrice);
                ps.executeUpdate();
            }
            catch (Exception ex) {
                this.runOnPlayerThread(player, () -> {
                    player.getInventory().addItem(new ItemStack[]{listingItem});
                    player.sendMessage("\u00a7cListing creation failed.");
                });
                return;
            }
            this.logTransactionAudit(player.getUniqueId().toString(), player.getName(), "AH_LIST", listingItem.getType().name(), listingItem.getAmount(), ahPrice, ahPrice, null);
            this.runOnPlayerThread(player, () -> {
                player.sendMessage("\u00a7aListing created.");
                this.openAuctionHouseMenu(player);
            });
        });
    }

    private void returnAhSellInsertItem(Player player, Inventory inventory) {
        if (player == null || inventory == null) {
            return;
        }
        ItemStack stack = inventory.getItem(4);
        if (stack == null || stack.getType() == Material.AIR) {
            return;
        }
        inventory.setItem(4, null);
        HashMap overflow = player.getInventory().addItem(new ItemStack[]{stack.clone()});
        for (Object extra : overflow.values()) {
            this.dropForPlayer(player, (ItemStack)extra);
        }
    }

    private void returnPendingAhSellState(Player player) {
        if (player == null) {
            return;
        }
        AhSellState state = this.ahSellState.get(player.getUniqueId());
        if (state == null || state.item == null || state.item.getType() == Material.AIR) {
            return;
        }
        ItemStack stack = state.item.clone();
        state.item = null;
        state.price = 0.0;
        HashMap overflow = player.getInventory().addItem(new ItemStack[]{stack});
        for (Object extra : overflow.values()) {
            this.dropForPlayer(player, (ItemStack)extra);
        }
    }

    private void handleAhSellInHandCommand(Player player, String rawPrice) {
        ItemStack inHand = player.getInventory().getItemInMainHand();
        if (inHand == null || inHand.getType() == Material.AIR) {
            player.sendMessage("\u00a7cHold an item in your hand.");
            return;
        }
        ParsedAmount parsed = this.parseCompactAmount(rawPrice);
        if (parsed == null || parsed.value < 1.0) {
            player.sendMessage("\u00a7cInvalid price.");
            return;
        }
        double floor = this.worthFloorFor(inHand);
        if (parsed.value < floor) {
            player.sendMessage("\u00a7cPrice is below worth floor.");
            return;
        }
        ItemStack listing = inHand.clone();
        player.getInventory().setItemInMainHand(null);
        AhSellState state = this.ahSellState.computeIfAbsent(player.getUniqueId(), k -> new AhSellState());
        state.item = listing;
        state.price = parsed.value;
        this.finalizeAhListing(player);
    }

    private double worthFloorFor(ItemStack stack) {
        if (stack == null || stack.getType() == Material.AIR) {
            return 1.0;
        }
        double value = this.sellUnitPrice(stack.getType());
        if (value > 0.0) {
            return value;
        }
        return 1.0;
    }

    private List<OrderEntry> queryOrders(OrdersViewState state) {
        ArrayList<OrderEntry> out = new ArrayList<OrderEntry>();
        StringBuilder sql = new StringBuilder("SELECT o.id,o.item_key,o.amount_total,o.amount_filled,o.unit_price,o.creator_uuid,o.created_at,p.username,o.expires_at FROM order_listings o LEFT JOIN players p ON p.uuid=o.creator_uuid WHERE o.status='ACTIVE' AND (o.expires_at IS NULL OR o.expires_at > CURRENT_TIMESTAMP) ");
        if (state.creatorFilter != null && !state.creatorFilter.isBlank()) {
            sql.append("AND o.creator_uuid=? ");
        }
        // Hide the viewer's own orders from the browse (you can't fulfill your own).
        if (state.viewerUuid != null) {
            sql.append("AND o.creator_uuid <> ? ");
        }
        if (state.search != null && !state.search.isBlank()) {
            sql.append("AND LOWER(o.item_key) LIKE ? ");
        }
        sql.append("ORDER BY ").append(this.orderSortSql(state.sort)).append(" LIMIT 450");
        try (Connection conn = this.openSyncConnection();
             PreparedStatement ps = conn.prepareStatement(sql.toString());){
            int idx = 1;
            if (state.creatorFilter != null && !state.creatorFilter.isBlank()) {
                ps.setString(idx++, state.creatorFilter);
            }
            if (state.viewerUuid != null) {
                ps.setString(idx++, state.viewerUuid);
            }
            if (state.search != null && !state.search.isBlank()) {
                ps.setString(idx++, "%" + state.search.toLowerCase(Locale.ROOT) + "%");
            }
            try (ResultSet rs = ps.executeQuery();){
                while (rs.next()) {
                    Material mat = Material.matchMaterial((String)rs.getString(2));
                    if (mat == null) {
                        mat = Material.STONE;
                    }
                    if (!this.matchesUiCategory(mat, state.filter)) continue;
                    out.add(new OrderEntry(rs.getLong(1), mat, rs.getInt(3), rs.getInt(4), rs.getDouble(5), rs.getString(6), this.safeName(rs.getString(8), rs.getString(6)), rs.getTimestamp(7) == null ? System.currentTimeMillis() : rs.getTimestamp(7).getTime(), rs.getTimestamp(9) == null ? 0L : rs.getTimestamp(9).getTime()));
                }
            }
        }
        catch (Exception ex) {
            this.getLogger().warning("Failed querying orders: " + ex.getMessage());
        }
        return out;
    }

    private List<OrderItemTypeEntry> queryOrderItemTypes(OrdersViewState state) {
        ArrayList<OrderItemTypeEntry> out = new ArrayList<OrderItemTypeEntry>();
        String sortSql = switch (state.sort) {
            case "Best price" -> "MAX(unit_price) DESC";
            case "Most orders" -> "COUNT(*) DESC";
            case "Most remaining" -> "SUM(GREATEST(0, amount_total-amount_filled)) DESC";
            default -> "MAX(created_at) DESC";
        };
        StringBuilder sql = new StringBuilder(
            "SELECT item_key, COUNT(*) AS cnt, SUM(GREATEST(0, amount_total-amount_filled)) AS rem, MAX(unit_price) AS best " +
            "FROM order_listings WHERE status='ACTIVE' AND amount_filled < amount_total " +
            "AND (expires_at IS NULL OR expires_at > CURRENT_TIMESTAMP) ");
        if (state.search != null && !state.search.isBlank()) {
            sql.append("AND LOWER(item_key) LIKE ? ");
        }
        sql.append("GROUP BY item_key ORDER BY ").append(sortSql).append(" LIMIT 450");
        try (Connection conn = this.openSyncConnection();
             PreparedStatement ps = conn.prepareStatement(sql.toString())) {
            if (state.search != null && !state.search.isBlank()) {
                ps.setString(1, "%" + state.search.toLowerCase(Locale.ROOT) + "%");
            }
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next()) {
                    Material mat = Material.matchMaterial(rs.getString(1));
                    if (mat == null) continue;
                    if (!this.matchesUiCategory(mat, state.filter)) continue;
                    out.add(new OrderItemTypeEntry(mat, rs.getInt(2), rs.getLong(3), rs.getDouble(4)));
                }
            }
        } catch (Exception ex) {
            this.getLogger().warning("Failed querying order item types: " + ex.getMessage());
        }
        return out;
    }

    private List<OrderEntry> queryOrdersForItem(String materialName, OrdersViewState state) {
        ArrayList<OrderEntry> out = new ArrayList<OrderEntry>();
        String sql = "SELECT o.id,o.item_key,o.amount_total,o.amount_filled,o.unit_price,o.creator_uuid,o.created_at,p.username,o.expires_at " +
            "FROM order_listings o LEFT JOIN players p ON p.uuid=o.creator_uuid " +
            "WHERE o.status='ACTIVE' AND o.amount_filled < o.amount_total AND UPPER(o.item_key)=? " +
            "AND (o.expires_at IS NULL OR o.expires_at > CURRENT_TIMESTAMP) " +
            (state.viewerUuid != null ? "AND o.creator_uuid <> ? " : "") +
            "ORDER BY o.unit_price DESC, o.created_at DESC LIMIT 450";
        try (Connection conn = this.openSyncConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setString(1, materialName.toUpperCase(Locale.ROOT));
            if (state.viewerUuid != null) ps.setString(2, state.viewerUuid);
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next()) {
                    Material mat = Material.matchMaterial(rs.getString(2));
                    if (mat == null) mat = Material.STONE;
                    out.add(new OrderEntry(rs.getLong(1), mat, rs.getInt(3), rs.getInt(4), rs.getDouble(5), rs.getString(6), this.safeName(rs.getString(8), rs.getString(6)), rs.getTimestamp(7) == null ? System.currentTimeMillis() : rs.getTimestamp(7).getTime(), rs.getTimestamp(9) == null ? 0L : rs.getTimestamp(9).getTime()));
                }
            }
        } catch (Exception ex) {
            this.getLogger().warning("Failed querying orders for item: " + ex.getMessage());
        }
        return out;
    }

    private List<OrderEntry> queryOrdersForCreator(UUID creator, OrdersViewState state) {
        ArrayList<OrderEntry> out = new ArrayList<OrderEntry>();
        // Show only ACTIVE orders; completed orders with unclaimed deliveries are accessible via the claim button
        String sql = "SELECT ol.id,ol.item_key,ol.amount_total,ol.amount_filled,ol.unit_price,ol.creator_uuid,ol.created_at,ol.expires_at " +
            "FROM order_listings ol " +
            "WHERE ol.creator_uuid=? AND ol.status='ACTIVE' " +
            "AND (ol.expires_at IS NULL OR ol.expires_at > CURRENT_TIMESTAMP) " +
            "ORDER BY ol.created_at DESC LIMIT 450";
        String myName = this.playerName(creator);
        try (Connection conn = this.openSyncConnection();
             PreparedStatement ps = conn.prepareStatement(sql);){
            ps.setString(1, creator.toString());
            try (ResultSet rs = ps.executeQuery();){
                while (rs.next()) {
                    Material mat = Material.matchMaterial((String)rs.getString(2));
                    if (mat == null) mat = Material.STONE;
                    out.add(new OrderEntry(rs.getLong(1), mat, rs.getInt(3), rs.getInt(4), rs.getDouble(5), creator.toString(), myName, rs.getTimestamp(7).getTime(), rs.getTimestamp(8) == null ? 0L : rs.getTimestamp(8).getTime()));
                }
            }
        }
        catch (Exception ex) {
            this.getLogger().warning("Failed querying my orders: " + ex.getMessage());
        }
        return out;
    }

    private List<OrderDeliveryEntry> queryPendingOrderDeliveries(UUID creator) {
        return this.queryPendingOrderDeliveries(creator, 0L);
    }

    private List<OrderDeliveryEntry> queryPendingOrderDeliveries(UUID creator, long orderId) {
        ArrayList<OrderDeliveryEntry> out = new ArrayList<OrderDeliveryEntry>();
        String sql = "SELECT d.id,d.item_blob,d.amount,d.payout,d.fulfiller_uuid,d.created_at,p.username FROM order_deliveries d JOIN order_listings o ON o.id=d.order_id LEFT JOIN players p ON p.uuid=d.fulfiller_uuid WHERE o.creator_uuid=? AND d.claimed=0" + (orderId > 0L ? " AND d.order_id=?" : "") + " ORDER BY d.created_at DESC LIMIT 450";
        try (Connection conn = this.openSyncConnection();
             PreparedStatement ps = conn.prepareStatement(sql);){
            ps.setString(1, creator.toString());
            if (orderId > 0L) {
                ps.setLong(2, orderId);
            }
            try (ResultSet rs = ps.executeQuery();){
                while (rs.next()) {
                    ItemStack item = this.deserializeItem(rs.getBytes(2));
                    if (item == null) {
                        item = new ItemStack(Material.STONE, Math.max(1, rs.getInt(3)));
                    }
                    out.add(new OrderDeliveryEntry(rs.getLong(1), item, rs.getInt(3), rs.getDouble(4), this.safeName(rs.getString(7), rs.getString(5)), rs.getTimestamp(6) == null ? System.currentTimeMillis() : rs.getTimestamp(6).getTime()));
                }
            }
        }
        catch (Exception ex) {
            this.getLogger().warning("Failed querying pending order deliveries: " + ex.getMessage());
        }
        return out;
    }

