    private OrderDeliveryApplyResult applyOrderDeliveryAsServer(long orderId, Material material, int requestedAmount) {
        ItemStack preview = new ItemStack(material, Math.min(requestedAmount, material.getMaxStackSize()));
        UUID serverFulfiller;
        try { serverFulfiller = UUID.fromString(SERVER_UUID); } catch (Exception e) { return null; }
        return this.applyOrderDelivery(orderId, serverFulfiller, material, requestedAmount, preview);
    }

    private OrderDeliveryApplyResult applyOrderDelivery(long orderId, UUID fulfiller, Material material, int requestedAmount, ItemStack previewItem) {
        try (Connection conn = this.openSyncConnection();){
            conn.setAutoCommit(false);
            try (PreparedStatement sel = conn.prepareStatement("SELECT amount_total,amount_filled,unit_price,creator_uuid FROM order_listings WHERE id=? AND status='ACTIVE' AND (expires_at IS NULL OR expires_at > CURRENT_TIMESTAMP) FOR UPDATE");
                 PreparedStatement upd = conn.prepareStatement("UPDATE order_listings SET amount_filled=amount_filled+?, status=CASE WHEN amount_filled+?=amount_total THEN 'FILLED' ELSE 'ACTIVE' END WHERE id=? AND status='ACTIVE'");
                 PreparedStatement checkDelivery = conn.prepareStatement("SELECT id, amount, payout FROM order_deliveries WHERE order_id=? AND fulfiller_uuid=?");
                 PreparedStatement updateDelivery = conn.prepareStatement("UPDATE order_deliveries SET amount=amount+?, payout=payout+? WHERE order_id=? AND fulfiller_uuid=?");
                 PreparedStatement insertDelivery = conn.prepareStatement("INSERT INTO order_deliveries (order_id,fulfiller_uuid,amount,payout,item_blob,claimed) VALUES (?,?,?,?,?,0)");){
                sel.setLong(1, orderId);
                int deliverable = 0;
                double unitPrice = 0.0;
                String creatorUuid = null;
                try (ResultSet rs = sel.executeQuery();){
                    if (!rs.next()) {
                        conn.rollback();
                        return null;
                    }
                    deliverable = Math.min(requestedAmount, Math.max(0, rs.getInt(1) - rs.getInt(2)));
                    unitPrice = rs.getDouble(3);
                    creatorUuid = rs.getString(4);
                }
                if (deliverable <= 0 || creatorUuid.equals(fulfiller.toString())) {
                    conn.rollback();
                    return null;
                }
                double payout = (double)deliverable * unitPrice;
                ItemStack storedItem = previewItem != null && previewItem.getType() == material ? previewItem.clone() : new ItemStack(material);
                storedItem.setAmount(Math.max(1, Math.min(deliverable, storedItem.getMaxStackSize())));
                upd.setInt(1, deliverable);
                upd.setInt(2, deliverable);
                upd.setLong(3, orderId);
                if (upd.executeUpdate() <= 0) {
                    conn.rollback();
                    return null;
                }
                checkDelivery.setLong(1, orderId);
                checkDelivery.setString(2, fulfiller.toString());
                boolean hasExistingDelivery = false;
                try (ResultSet rs = checkDelivery.executeQuery();){
                    if (rs.next()) {
                        hasExistingDelivery = true;
                        updateDelivery.setInt(1, deliverable);
                        updateDelivery.setDouble(2, payout);
                        updateDelivery.setLong(3, orderId);
                        updateDelivery.setString(4, fulfiller.toString());
                        updateDelivery.executeUpdate();
                    }
                }
                if (!hasExistingDelivery) {
                    insertDelivery.setLong(1, orderId);
                    insertDelivery.setString(2, fulfiller.toString());
                    insertDelivery.setInt(3, deliverable);
                    insertDelivery.setDouble(4, payout);
                    insertDelivery.setBytes(5, this.serializeItem(storedItem));
                    insertDelivery.executeUpdate();
                }
                conn.commit();
                UUID creatorId = null;
                try { creatorId = UUID.fromString(creatorUuid); } catch (Exception ignored) {}
                return new OrderDeliveryApplyResult(deliverable, payout, creatorId);
            }
            catch (Exception ex) {
                conn.rollback();
                throw ex;
            }
            finally {
                conn.setAutoCommit(true);
            }
        }
        catch (Exception ex) {
            this.getLogger().warning("Failed order delivery apply: " + ex.getMessage());
            return null;
        }
    }

    private List<AhListingEntry> queryAhListings(AhViewState state) {
        ArrayList<AhListingEntry> out = new ArrayList<AhListingEntry>();
        // Parse search into a material part + optional enchant keywords.
        // e.g. "diamond sword mending" -> material DIAMOND_SWORD + enchant ["mending"]
        String matLike = null;
        java.util.List<String> enchantTerms = new java.util.ArrayList<>();
        if (state.search != null && !state.search.isBlank()) {
            String[] words = state.search.trim().toLowerCase(Locale.ROOT).split("\\s+");
            // Find the longest leading word-run that resolves to a material.
            int matEnd = 0;
            for (int k = words.length; k >= 1; k--) {
                String candidate = String.join("_", java.util.Arrays.copyOfRange(words, 0, k));
                if (Material.matchMaterial(candidate) != null) { matEnd = k; break; }
            }
            if (matEnd > 0) {
                matLike = String.join("_", java.util.Arrays.copyOfRange(words, 0, matEnd));
                for (int i = matEnd; i < words.length; i++) enchantTerms.add(words[i]);
            } else {
                matLike = String.join("_", words); // fall back to fuzzy LIKE on the whole thing
            }
        }
        StringBuilder sql = new StringBuilder("SELECT a.id,a.item_blob,a.item_key,a.price,a.seller_uuid,a.created_at,p.username FROM auction_listings a LEFT JOIN players p ON p.uuid=a.seller_uuid WHERE a.status='ACTIVE' ");
        if (state.sellerFilter != null && !state.sellerFilter.isBlank()) {
            sql.append("AND a.seller_uuid=? ");
        }
        // Hide the viewer's own listings (you can't buy your own anyway).
        if (state.viewerUuid != null) {
            sql.append("AND a.seller_uuid <> ? ");
        }
        if (matLike != null) {
            sql.append("AND LOWER(a.item_key) LIKE ? ");
        }
        sql.append("ORDER BY ").append(this.ahSortSql(state.sort)).append(" LIMIT 450");
        try (Connection conn = this.openSyncConnection();
             PreparedStatement ps = conn.prepareStatement(sql.toString());){
            int param = 1;
            if (state.sellerFilter != null && !state.sellerFilter.isBlank()) {
                ps.setString(param++, state.sellerFilter);
            }
            if (state.viewerUuid != null) {
                ps.setString(param++, state.viewerUuid);
            }
            if (matLike != null) {
                ps.setString(param++, "%" + matLike + "%");
            }
            try (ResultSet rs = ps.executeQuery();){
                while (rs.next()) {
                    ItemStack item = this.deserializeItem(rs.getBytes(2));
                    if (item == null) {
                        Material m = Material.matchMaterial((String)rs.getString(3));
                        item = new ItemStack(m == null ? Material.STONE : m);
                    }
                    if (!this.matchesUiCategory(item.getType(), state.filter)) continue;
                    // Enchant filter: item must carry every named enchant keyword.
                    if (!enchantTerms.isEmpty() && !this.itemHasEnchantKeywords(item, enchantTerms)) continue;
                    out.add(new AhListingEntry(rs.getLong(1), item, rs.getDouble(4), rs.getString(5), this.safeName(rs.getString(7), rs.getString(5)), rs.getTimestamp(6).getTime()));
                }
            }
        }
        catch (Exception ex) {
            this.getLogger().warning("Failed querying AH listings: " + ex.getMessage());
        }
        return out;
    }

    private boolean itemHasEnchantKeywords(ItemStack item, java.util.List<String> keywords) {
        if (item == null || !item.hasItemMeta()) return false;
        java.util.Set<String> enchantNames = new java.util.HashSet<>();
        ItemMeta meta = item.getItemMeta();
        java.util.Map<Enchantment, Integer> ench = meta.hasEnchants() ? meta.getEnchants() : item.getEnchantments();
        if (meta instanceof org.bukkit.inventory.meta.EnchantmentStorageMeta esm) {
            ench = esm.getStoredEnchants();
        }
        for (Enchantment e : ench.keySet()) {
            enchantNames.add(e.getKey().getKey().toLowerCase(Locale.ROOT)); // e.g. "mending", "protection"
        }
        for (String kw : keywords) {
            boolean matched = false;
            for (String en : enchantNames) {
                if (en.contains(kw) || kw.contains(en)) { matched = true; break; }
            }
            if (!matched) return false;
        }
        return true;
    }

