    private List<AhTxEntry> queryAhTransactions(UUID uuid, int page) {
        ArrayList<AhTxEntry> out = new ArrayList<AhTxEntry>();
        String sql = "SELECT item_blob,price,seller_uuid,buyer_uuid,updated_at FROM auction_listings WHERE (seller_uuid=? OR buyer_uuid=?) AND status='SOLD' ORDER BY updated_at DESC LIMIT 450";
        try (Connection conn = this.openSyncConnection();
             PreparedStatement ps = conn.prepareStatement(sql);){
            ps.setString(1, uuid.toString());
            ps.setString(2, uuid.toString());
            try (ResultSet rs = ps.executeQuery();){
                while (rs.next()) {
                    ItemStack item = this.deserializeItem(rs.getBytes(1));
                    if (item == null) {
                        item = new ItemStack(Material.STONE);
                    }
                    String seller = rs.getString(3);
                    String buyer = rs.getString(4);
                    String other = uuid.toString().equalsIgnoreCase(seller) ? this.playerNameByUuid(buyer) : this.playerNameByUuid(seller);
                    out.add(new AhTxEntry(item, rs.getDouble(2), other, rs.getTimestamp(5).getTime()));
                }
            }
        }
        catch (Exception ex) {
            this.getLogger().warning("Failed querying AH transactions: " + ex.getMessage());
        }
        return out;
    }

    private void openAhBuyConfirm(Player player, long listingId) {
        this.runAsyncTask(() -> {
            try (Connection conn = this.openSyncConnection();
                 PreparedStatement sel = conn.prepareStatement("SELECT price, item_blob, item_key, seller_uuid FROM auction_listings WHERE id=? AND status='ACTIVE' LIMIT 1")) {
                sel.setLong(1, listingId);
                try (ResultSet rs = sel.executeQuery()) {
                    if (!rs.next()) {
                        this.runOnPlayerThread(player, () -> player.sendMessage("§cListing no longer available."));
                        return;
                    }
                    double price = rs.getDouble(1);
                    ItemStack item = this.deserializeItem(rs.getBytes(2));
                    if (item == null) {
                        Material m = Material.matchMaterial(rs.getString(3) != null ? rs.getString(3) : "");
                        item = new ItemStack(m == null ? Material.STONE : m);
                    }
                    String sellerUuid = rs.getString(4);
                    if (player.getUniqueId().toString().equalsIgnoreCase(sellerUuid)) {
                        this.runOnPlayerThread(player, () -> player.sendActionBar(Component.text("§cYou cannot buy your own listing.")));
                        return;
                    }
                    final ItemStack fItem = item;
                    final double fPrice = price;
                    final long fId = listingId;
                    this.runOnPlayerThread(player, () -> {
                        if (!player.isOnline()) return;
                        Inventory inv = Bukkit.createInventory(null, 27, TITLE_AH_BUY_CONFIRM);
                        ItemStack cancelBtn = this.namedWithLore(Material.RED_STAINED_GLASS_PANE, "§c§lCancel", "ah_buy_cancel", List.of());
                        ItemStack confirmBtn = this.namedWithLore(Material.GREEN_STAINED_GLASS_PANE, "§a§lConfirm Purchase", "ah_buy_confirm", List.of(
                            "§7Price: §a$" + this.fmtMoney(fPrice)
                        ));
                        ItemStack border = this.namedWithLore(Material.GRAY_STAINED_GLASS_PANE, "§8", "border", List.of());
                        for (int s = 0; s < 27; s++) inv.setItem(s, border);
                        inv.setItem(13, fItem.clone());
                        inv.setItem(11, cancelBtn);
                        inv.setItem(15, confirmBtn);
                        this.pendingAhBuyListingId.put(player.getUniqueId(), fId);
                        player.openInventory(inv);
                    });
                }
            } catch (Exception ex) {
                this.runOnPlayerThread(player, () -> player.sendMessage("§cCould not open purchase confirmation."));
            }
        });
    }

    private void handleAhBuyConfirmClick(Player player, int slot) {
        String id = this.uiActionId(player.getOpenInventory().getTopInventory().getItem(slot));
        if ("ah_buy_cancel".equals(id)) {
            this.pendingAhBuyListingId.remove(player.getUniqueId());
            player.closeInventory();
            this.openAuctionHouseMenu(player);
            return;
        }
        if ("ah_buy_confirm".equals(id)) {
            Long listingId = this.pendingAhBuyListingId.remove(player.getUniqueId());
            if (listingId != null) {
                // Close the confirm GUI and reopen the AH browse, THEN buy. The buy's in-place
                // refresh (which only fires for the AH title) now applies, and the player isn't
                // left staring at a frozen confirm screen after a silent buy.
                player.closeInventory();
                this.buyAhListing(player, listingId);
                this.openAuctionHouseMenu(player);
            }
        }
    }

    // Drop an item that belongs to a specific player (AH overflow / sell-return): it lands at their
    // feet, only THEY can pick it up (no theft), and there's no pickup delay or throw arc — i.e. it
    // does NOT behave like a normal item you dropped from your own inventory.
    private void dropForPlayer(Player player, ItemStack stack) {
        if (stack == null || stack.getType() == Material.AIR) return;
        org.bukkit.entity.Item it = player.getWorld().dropItem(player.getLocation(), stack);
        try {
            it.setOwner(player.getUniqueId());
            it.setPickupDelay(0);
            it.setVelocity(new org.bukkit.util.Vector(0.0, 0.0, 0.0));
        } catch (Throwable ignored) {}
    }

    private void buyAhListing(Player player, long listingId) {
        this.buyAhListing(player, listingId, -1);
    }

    private void buyAhListing(Player player, long listingId, int slot) {
        // Per-listing dedupe: if a buy for this listing is already running, ignore the click silently.
        if (!this.ahBuyInFlight.add(listingId)) {
            return;
        }
        // Auction overflow OFF (default): block the buy if there's no room. ON: buy anyway and
        // drop the item in front of the player.
        boolean overflow = this.isSettingEnabledCached(player.getUniqueId(), "auction_overflow");
        if (!overflow && player.getInventory().firstEmpty() == -1) {
            player.sendMessage("§cYour inventory is full. Please make space before buying (or enable Auction Overflow in /settings).");
            player.sendActionBar((Component)Component.text("§cInventory full"));
            this.ahBuyInFlight.remove(listingId);
            return;
        }
        this.runAsyncTask(() -> {
            try (Connection conn = this.openSyncConnection();){
                conn.setAutoCommit(false);
                try (PreparedStatement sel = conn.prepareStatement("SELECT seller_uuid,price,item_blob FROM auction_listings WHERE id=? AND status='ACTIVE' FOR UPDATE");
                     PreparedStatement upd = conn.prepareStatement("UPDATE auction_listings SET status='SOLD', buyer_uuid=?, updated_at=CURRENT_TIMESTAMP WHERE id=? AND status='ACTIVE'");
                     PreparedStatement payout = conn.prepareStatement("INSERT INTO auction_payouts (recipient_uuid,listing_id,amount,claimed) VALUES (?,?,?,1)");
                     PreparedStatement sellerCredit = conn.prepareStatement("INSERT INTO balances (uuid,pending_vault_credit) VALUES (?,?) ON DUPLICATE KEY UPDATE pending_vault_credit=pending_vault_credit+VALUES(pending_vault_credit)");){
                    sel.setLong(1, listingId);
                    try (ResultSet rs = sel.executeQuery();){
                        if (!rs.next()) {
                            conn.rollback();
                            this.ahBuyInFlight.remove(listingId);
                            return; // silent: benign race when rapid-buying a just-sold listing
                        }
                        String sellerUuid = rs.getString(1);
                        double price = rs.getDouble(2);
                        if (player.getUniqueId().toString().equalsIgnoreCase(sellerUuid)) {
                            conn.rollback();
                            this.ahBuyInFlight.remove(listingId);
                            this.runOnPlayerThread(player, () -> player.sendActionBar(Component.text("\u00a7cYou cannot buy your own listing.")));
                            return;
                        }
                        if (!this.withdrawMoney(player, price)) {
                            conn.rollback();
                            this.ahBuyInFlight.remove(listingId);
                            this.runOnPlayerThread(player, () -> player.sendActionBar(Component.text("\u00a7cNot enough money.")));
                            return;
                        }
                        upd.setString(1, player.getUniqueId().toString());
                        upd.setLong(2, listingId);
                        if (upd.executeUpdate() <= 0) {
                            this.depositMoney(player, price);
                            conn.rollback();
                            this.ahBuyInFlight.remove(listingId);
                            return; // silent: lost the race to another buyer
                        }
                        if (!SERVER_UUID.equals(sellerUuid)) {
                            payout.setString(1, sellerUuid);
                            payout.setLong(2, listingId);
                            payout.setDouble(3, price);
                            payout.executeUpdate();
                            sellerCredit.setString(1, sellerUuid);
                            sellerCredit.setDouble(2, price);
                            sellerCredit.executeUpdate();
                        }
                        conn.commit();
                        ItemStack bought = this.deserializeItem(rs.getBytes(3));
                        UUID sellerId = UUID.fromString(sellerUuid);
                        Player seller = Bukkit.getPlayer((UUID)sellerId);
                        this.runOnPlayerThread(player, () -> {
                            if (bought != null) {
                                java.util.HashMap<Integer, ItemStack> over = player.getInventory().addItem(new ItemStack[]{bought});
                                for (ItemStack left : over.values()) {
                                    this.dropForPlayer(player, left);
                                }
                            }
                            // Silent buy: no "Listing purchased" message; the item just lands in the inventory.
                            String boughtKey = bought != null ? bought.getType().name() : "UNKNOWN";
                            int boughtAmt = bought != null ? bought.getAmount() : 1;
                            // Follow broadcasts: buyer's followers see the buy; the seller's followers see the sale.
                            String itemLbl = bought != null ? (boughtAmt + "x " + this.humanName(bought.getType())) : "an item";
                            this.notifyFollowers(player.getUniqueId(), player.getName(), "bought §f" + itemLbl + " §7for §f$" + this.fmtMoney(price) + "§7.", true);
                            if (!SERVER_UUID.equals(sellerUuid)) {
                                String sellerName = this.playerNameForUuid(sellerUuid);
                                if (sellerName != null) {
                                    this.notifyFollowers(sellerId, sellerName, "sold §f" + itemLbl + " §7for §f$" + this.fmtMoney(price) + "§7.", true);
                                }
                            }
                            this.logTransactionAudit(player.getUniqueId().toString(), player.getName(), "AH_BUY", boughtKey, boughtAmt, price, price, "seller=" + sellerUuid);
                            if (seller != null && seller.isOnline()) {
                                this.applyPendingCreditNow(seller);
                                if (this.isSettingEnabledCached(sellerId, "auction_alerts")) {
                                    seller.sendActionBar(Component.text("\u00a7aYour auction listing sold for \u00a7f$" + this.fmtMoney(price) + "\u00a7a."));
                                }
                            } else {
                                this.queuePlayerNotification(sellerId, "\u00a7aYour auction listing sold for \u00a7f$" + this.fmtMoney(price) + "\u00a7a.", "", 180);
                            }
                            this.ahBuyInFlight.remove(listingId);
                            // Instant refresh: drop the bought listing from the cached list and re-render
                            // in-memory (NO DB re-query), so spam-buying has no gap/delay.
                            if (TITLE_AH.equals(player.getOpenInventory().getTitle())) {
                                AhViewState st = this.ahViewState.get(player.getUniqueId());
                                if (st != null && st.cachedListings != null) {
                                    st.cachedListings.removeIf(e -> e.id() == listingId);
                                    this.renderAhMain(player, st.cachedListings, st);
                                } else {
                                    this.openAuctionHouseMenu(player);
                                }
                            }
                            // Make the sold listing vanish instantly for every OTHER player browsing the AH.
                            this.broadcastAhListingSold(listingId, player.getUniqueId());
                        });
                        return;
                    }
                }
                catch (Exception ex) {
                    conn.rollback();
                    throw ex;
                }
                finally {
                    conn.setAutoCommit(true);
                }
            }
            catch (Exception ex) {
                this.ahBuyInFlight.remove(listingId);
                this.runOnPlayerThread(player, () -> player.sendActionBar(Component.text("\u00a7cPurchase failed.")));
            }
        });
    }

    // After a listing sells (or is cancelled), drop it from every other browsing player's cached
    // list and re-render their AH so the item disappears instantly for everyone, not just the buyer.
    private void broadcastAhListingSold(long listingId, UUID excludeUuid) {
        for (Map.Entry<UUID, AhViewState> en : this.ahViewState.entrySet()) {
            UUID uid = en.getKey();
            if (uid.equals(excludeUuid)) continue;
            Player viewer = Bukkit.getPlayer(uid);
            if (viewer == null || !viewer.isOnline()) continue;
            AhViewState st = en.getValue();
            // Mutate + render on the viewer's own thread (cachedListings is not thread-safe; safe on Folia too).
            this.runOnPlayerThread(viewer, () -> {
                if (st.cachedListings == null) return;
                boolean removed = st.cachedListings.removeIf(e -> e.id() == listingId);
                if (removed && TITLE_AH.equals(viewer.getOpenInventory().getTitle())) {
                    this.renderAhMain(viewer, st.cachedListings, st);
                }
            });
        }
    }

    private void cancelAhListing(Player player, long listingId) {
        if (player.getInventory().firstEmpty() == -1) {
            player.sendActionBar(Component.text("§cYour inventory is full. Please make space to take down a listing."));
            return;
        }
        this.runAsyncTask(() -> {
            String sql = "UPDATE auction_listings SET status='CANCELLED', updated_at=CURRENT_TIMESTAMP WHERE id=? AND seller_uuid=? AND status='ACTIVE'";
            byte[] blob = null;
            try (Connection conn = this.openSyncConnection();
                 PreparedStatement sel = conn.prepareStatement("SELECT item_blob FROM auction_listings WHERE id=? AND seller_uuid=? AND status='ACTIVE'");
                 PreparedStatement upd = conn.prepareStatement(sql);){
                sel.setLong(1, listingId);
                sel.setString(2, player.getUniqueId().toString());
                try (ResultSet rs = sel.executeQuery();){
                    if (rs.next()) {
                        blob = rs.getBytes(1);
                    }
                }
                upd.setLong(1, listingId);
                upd.setString(2, player.getUniqueId().toString());
                if (upd.executeUpdate() > 0) {
                    ItemStack back = this.deserializeItem(blob);
                    this.runOnPlayerThread(player, () -> {
                        if (back != null) {
                            player.getInventory().addItem(new ItemStack[]{back});
                        }
                        player.sendMessage("\u00a7aListing cancelled.");
                        this.openAhMyItems(player);
                        // Vanish it for everyone else browsing the AH, too.
                        this.broadcastAhListingSold(listingId, player.getUniqueId());
                    });
                }
            }
            catch (Exception ex) {
                this.runOnPlayerThread(player, () -> player.sendMessage("\u00a7cCancel failed."));
            }
        });
    }

    // D15: claim EVERY pending delivery across all the player's orders in one action.
    private void claimAllOrderDeliveries(Player player) {
        this.runAsyncTask(() -> {
            List<OrderDeliveryEntry> pending = this.queryPendingOrderDeliveries(player.getUniqueId());
            if (pending.isEmpty()) {
                this.runOnPlayerThread(player, () -> {
                    player.sendActionBar(Component.text("§7No deliveries to claim."));
                    this.openOrderDeliveriesMenu(player);
                });
                return;
            }
            List<Long> ids = new java.util.ArrayList<>();
            for (OrderDeliveryEntry d : pending) ids.add(d.id());
            List<OrderDeliveryEntry> claimed = this.claimOrderDeliveries(player.getUniqueId(), 0L, ids);
            this.runOnPlayerThread(player, () -> {
                int totalAmount = 0;
                int distinctTypes = 0;
                java.util.Set<Material> seen = new java.util.HashSet<>();
                for (OrderDeliveryEntry delivery : claimed) {
                    totalAmount += delivery.amount();
                    if (seen.add(delivery.item().getType())) distinctTypes++;
                    for (ItemStack stack : this.splitOrderDeliveryStacks(delivery)) {
                        this.giveItemStack(player, stack);
                    }
                }
                player.sendActionBar(this.legacyColorize("&#00BFFFClaimed §f" + totalAmount + " §7items across §f" + distinctTypes + " §7types."));
                player.playSound(player.getLocation(), Sound.ENTITY_EXPERIENCE_ORB_PICKUP, 0.7f, 1.3f);
                this.openOrderDeliveriesMenu(player);
            });
        });
    }

    private void claimOrderDelivery(Player player, long deliveryId) {
        this.runAsyncTask(() -> {
            OrdersViewState state = this.ordersViewState.computeIfAbsent(player.getUniqueId(), id -> new OrdersViewState());
            List<OrderDeliveryEntry> claimed = this.claimOrderDeliveries(player.getUniqueId(), state.selectedOrderId, List.of(deliveryId));
            this.runOnPlayerThread(player, () -> {
                if (claimed.isEmpty()) {
                    player.sendMessage("\u00a7cThat delivery is no longer available.");
                    this.openOrderDeliveriesMenu(player);
                    return;
                }
                int claimedAmount = 0;
                for (OrderDeliveryEntry delivery : claimed) {
                    claimedAmount += delivery.amount();
                    for (ItemStack stack : this.splitOrderDeliveryStacks(delivery)) {
                        this.giveItemStack(player, stack);
                    }
                }
                player.sendMessage("\u00a7aClaimed " + claimedAmount + "x " + this.humanName(claimed.get(0).item().getType()) + ".");
                this.openOrderDeliveriesMenu(player);
            });
        });
    }

    /*
     * Enabled aggressive exception aggregation
     */
    private byte[] serializeItem(ItemStack item) {
        if (item == null) return new byte[0];
        try {
            return item.serializeAsBytes();
        } catch (Exception ex) {
            return new byte[0];
        }
    }

    private ItemStack deserializeItem(byte[] data) {
        if (data == null || data.length == 0) return null;
        try {
            return ItemStack.deserializeBytes(data);
        } catch (Exception ex) {
            // Fallback for blobs written with old BukkitObjectOutputStream format
            try (ByteArrayInputStream bis = new ByteArrayInputStream(data);
                 BukkitObjectInputStream in = new BukkitObjectInputStream((InputStream)bis)) {
                Object obj = in.readObject();
                return obj instanceof ItemStack ? (ItemStack) obj : null;
            } catch (Exception ex2) {
                return null;
            }
        }
    }

    private String orderSortSql(String sort) {
        return switch (sort) {
            case "Most paid" -> "unit_price DESC, created_at DESC";
            case "Most delivered" -> "(amount_filled) DESC, created_at DESC";
            case "Most money per item" -> "unit_price DESC, created_at DESC";
            default -> "created_at DESC";
        };
    }

    private String ahSortSql(String sort) {
        return switch (sort) {
            case "Highest price" -> "price DESC, created_at DESC";
            case "Lowest price" -> "price ASC, created_at DESC";
            case "Last listed" -> "updated_at DESC";
            default -> "created_at DESC";
        };
    }

    private String shortAge(long epochMs) {
        long seconds = Math.max(0L, (System.currentTimeMillis() - epochMs) / 1000L);
        if (seconds < 60L) {
            return seconds + "s ago";
        }
        long minutes = seconds / 60L;
        if (minutes < 60L) {
            return minutes + "m ago";
        }
        long hours = minutes / 60L;
        if (hours < 24L) {
            return hours + "h ago";
        }
        long days = hours / 24L;
        return days + "d ago";
    }

    private String timeUntil(long epochMs) {
        if (epochMs <= 0L) {
            return "Unknown";
        }
        long seconds = Math.max(0L, (epochMs - System.currentTimeMillis()) / 1000L);
        if (seconds < 60L) {
            return seconds + "s";
        }
        long minutes = seconds / 60L;
        if (minutes < 60L) {
            return minutes + "m";
        }
        long hours = minutes / 60L;
        if (hours < 48L) {
            return hours + "h";
        }
        long days = hours / 24L;
        return days + "d";
    }

    private String humanName(Material material) {
        String[] words = material.name().toLowerCase(Locale.ROOT).split("_");
        StringBuilder sb = new StringBuilder();
        for (String word : words) {
            if (sb.length() > 0) sb.append(' ');
            if (!word.isEmpty()) sb.append(Character.toUpperCase(word.charAt(0))).append(word.substring(1));
        }
        return sb.toString();
    }

    private String categoryForMaterial(Material material) {
        String n = material.name();
        if (n.contains("SWORD") || n.contains("AXE") || n.contains("BOW") || n.contains("TRIDENT")) {
            return "Combat";
        }
        if (n.contains("POTION")) {
            return "Potions";
        }
        if (n.contains("BOOK")) {
            return "Books";
        }
        if (n.contains("INGOT") || n.contains("DUST") || n.contains("SHARD") || n.contains("BLAZE") || n.contains("WART")) {
            return "Ingredients";
        }
        if (n.contains("PICKAXE") || n.contains("SHOVEL") || n.contains("HOE")) {
            return "Tools";
        }
        if (n.contains("BEEF") || n.contains("CHICKEN") || n.contains("CARROT") || n.contains("APPLE") || n.contains("BERRIES")) {
            return "Food";
        }
        if (material.isBlock()) {
            return "Blocks";
        }
        return "Utilities";
    }

    private boolean matchesUiCategory(Material material, String filter) {
        if (filter == null || filter.isBlank() || "All".equalsIgnoreCase(filter)) {
            return true;
        }
        return this.categoryForMaterial(material).equalsIgnoreCase(filter);
    }

    private void notifyPendingOrderDeliveries(UUID uuid) {
        if (uuid == null) {
            return;
        }
        List<OrderDeliveryEntry> deliveries = this.queryPendingOrderDeliveries(uuid);
        if (deliveries.isEmpty()) {
            return;
        }
        Player player = Bukkit.getPlayer((UUID)uuid);
        if (player == null || !player.isOnline()) {
            return;
        }
        int count = deliveries.size();
        this.runOnPlayerThread(player, () -> {
            if (player.isOnline()) {
                player.sendActionBar(this.legacyColorize("&#00BFFFYou have \u00a7f" + count + " &#00BFFFitems waiting in /orders to claim."));
            }
        });
    }

    private List<Material> pickerMaterials(String search) {
        ArrayList<Material> list = new ArrayList<Material>();
        String needle = search == null ? "" : search.toLowerCase(Locale.ROOT);
        for (Material m : Material.values()) {
            if (!m.isItem() || m == Material.AIR || m.name().contains("LEGACY") || !needle.isEmpty() && !m.name().toLowerCase(Locale.ROOT).contains(needle)) continue;
            list.add(m);
        }
        list.sort((a, b) -> a.name().compareToIgnoreCase(b.name()));
        return list;
    }

    private long parseLongSafe(String raw, long fallback) {
        try {
            return Long.parseLong(raw);
        }
        catch (Exception ignored) {
            return fallback;
        }
    }

    private String safeName(String resolved, String fallbackUuid) {
        if (resolved != null && !resolved.isBlank()) {
            return resolved;
        }
        return fallbackUuid == null ? "Unknown" : fallbackUuid.substring(0, Math.min(8, fallbackUuid.length()));
    }

    private String playerName(UUID uuid) {
        return this.playerNameByUuid(uuid.toString());
    }

    /*
     * Enabled aggressive block sorting
     * Enabled unnecessary exception pruning
     * Enabled aggressive exception aggregation
     */
    private String playerNameByUuid(String uuid) {
        if (uuid == null) return "Unknown";
        if (uuid.isBlank()) {
            return "Unknown";
        }
        String sql = "SELECT username FROM players WHERE uuid=? LIMIT 1";
        try (Connection conn = this.openSyncConnection();
             PreparedStatement ps = conn.prepareStatement(sql);){
            ps.setString(1, uuid);
            try (ResultSet rs = ps.executeQuery();){
                if (!rs.next()) return uuid.substring(0, Math.min(8, uuid.length()));
                String name = rs.getString(1);
                if (name == null) return uuid.substring(0, Math.min(8, uuid.length()));
                if (name.isBlank()) return uuid.substring(0, Math.min(8, uuid.length()));
                String string = name;
                return string;
            }
        }
        catch (Exception exception) {
            // empty catch block
        }
        return uuid.substring(0, Math.min(8, uuid.length()));
    }

    private int countInventoryMaterial(Player player, Material material) {
        int total = 0;
        for (ItemStack stack : player.getInventory().getStorageContents()) {
            if (stack == null || stack.getType() != material) continue;
            total += stack.getAmount();
        }
        return total;
    }

    private void removeInventoryMaterial(Player player, Material material, int amount) {
        int remaining = amount;
        ItemStack[] contents = player.getInventory().getStorageContents();
        for (int i = 0; i < contents.length && remaining > 0; ++i) {
            ItemStack stack = contents[i];
            if (stack == null || stack.getType() != material) continue;
            int take = Math.min(remaining, stack.getAmount());
            stack.setAmount(stack.getAmount() - take);
            if (stack.getAmount() <= 0) {
                contents[i] = null;
            }
            remaining -= take;
        }
        player.getInventory().setStorageContents(contents);
    }

    private String capitalize(String s) {
        if (s == null || s.isEmpty()) {
            return s;
        }
        return Character.toUpperCase(s.charAt(0)) + s.substring(1);
    }

