    private ItemStack createSellMultiCategoryItem(String name, Material icon, String categoryKey, int level) {
        String description = this.getSellMultiDescription(categoryKey);
        int nextLevel = level + 1;
        double nextMulti = 1.0 + (nextLevel * 0.1);
        String progressBar = this.generateProgressBar(level);
        List<String> lore = new ArrayList<>();
        lore.add("§a" + description);
        lore.add("");
        lore.add("§aProgress to §f" + String.format("%.1f", nextMulti) + "x");
        lore.add(progressBar);
        ItemStack item = this.namedWithLore(icon, "§a" + name, "sellmulti_cat:" + categoryKey, lore);
        item.setAmount(Math.min(level + 1, 64));
        return item;
    }

    private String getSellMultiDescription(String categoryKey) {
        switch (categoryKey) {
            case "crops": return "Sell crops and farming materials";
            case "ores": return "Sell ores and mining materials";
            case "mob_drops": return "Sell drops from mobs";
            case "natural": return "Sell natural items";
            case "armor_tools": return "Sell armor and tools";
            case "fish": return "Sell fish and ocean items";
            case "books": return "Sell enchanted books";
            case "potions": return "Sell potions and ingredients";
            case "blocks": return "Sell blocks and building materials";
            default: return "Upgrade your sell multiplier";
        }
    }

    private String generateProgressBar(int level) {
        int maxLevel = 20;
        if (level >= maxLevel) {
            return "§a█████████████████████ §fMax";
        }
        int filled = (level * 22) / maxLevel;
        int empty = 22 - filled;
        StringBuilder bar = new StringBuilder("§a");
        for (int i = 0; i < filled; i++) bar.append("█");
        bar.append("§7");
        for (int i = 0; i < empty; i++) bar.append("█");
        bar.append(" §f").append((level * 100) / maxLevel).append("%");
        return bar.toString();
    }

    private void openSellMultiCategoryGui(Player player, String categoryKey) {
        this.runAsyncTask(() -> {
            int level = this.loadSellMultiLevel(player.getUniqueId(), categoryKey);
            double earned = this.loadSellMultiEarned(player.getUniqueId(), categoryKey);
            this.runOnPlayerThread(player, () -> {
                Inventory inv = Bukkit.createInventory(null, 54, "§f" + this.getCategoryDisplayName(categoryKey) + " Progress");
                int[] snakePath = this.generateSnakePath();
                for (int i = 0; i < 20 && i < snakePath.length; i++) {
                    inv.setItem(snakePath[i], this.createProgressionPane(i, level, earned));
                }
                inv.setItem(49, this.namedWithLore(Material.ARROW, "§fBack", "sellmulti_back", List.of()));
                player.openInventory(inv);
            });
        });
    }

    private int[] generateSnakePath() {
        int[] path = new int[36];
        int index = 0;
        for (int row = 0; row < 4; row++) {
            int rowStart = row * 9;
            if (row % 2 == 0) {
                for (int col = 0; col < 9; col++) {
                    path[index++] = rowStart + col;
                    if (index >= 20) break;
                }
            } else {
                for (int col = 8; col >= 0; col--) {
                    path[index++] = rowStart + col;
                    if (index >= 20) break;
                }
            }
            if (index >= 20) break;
        }
        return path;
    }

    private String extractCategoryFromTitle(String title) {
        for (String cat : new String[] { "crops", "ores", "mob_drops", "natural", "armor_tools", "fish", "books", "potions", "blocks" }) {
            if (title.contains(this.getCategoryDisplayName(cat))) {
                return cat;
            }
        }
        return null;
    }

    private void claimSellMultiLevel(UUID playerUuid, String categoryKey, int levelIndex) {
        String querySql = "SELECT level, earned FROM sell_multiplier_progress WHERE player_uuid=? AND category=?";
        try (Connection conn = this.openSyncConnection();
             PreparedStatement queryPs = conn.prepareStatement(querySql)) {
            queryPs.setString(1, playerUuid.toString());
            queryPs.setString(2, categoryKey);
            ResultSet rs = queryPs.executeQuery();
            int currentLevel = 0;
            double earned = 0.0;
            if (rs.next()) {
                currentLevel = rs.getInt("level");
                earned = rs.getDouble("earned");
            }

            double threshold = this.calculateSellMultiThreshold(levelIndex);
            if (levelIndex >= currentLevel || earned < threshold) {
                return;
            }

            String updateSql = "INSERT INTO sell_multiplier_progress (player_uuid, category, level, earned, claimed_up_to) VALUES (?, ?, ?, earned, ?) ON DUPLICATE KEY UPDATE level = VALUES(level), claimed_up_to = VALUES(claimed_up_to)";
            try (PreparedStatement updatePs = conn.prepareStatement(updateSql)) {
                updatePs.setString(1, playerUuid.toString());
                updatePs.setString(2, categoryKey);
                updatePs.setInt(3, levelIndex + 1);
                updatePs.setInt(4, levelIndex + 1);
                updatePs.executeUpdate();
            }
        } catch (Exception ex) {
            this.getLogger().warning("Failed claiming sellmulti level: " + ex.getMessage());
        }
    }

    private String getCategoryDisplayName(String categoryKey) {
        switch (categoryKey) {
            case "crops": return "Crops";
            case "ores": return "Ores";
            case "mob_drops": return "Mob Drops";
            case "natural": return "Natural Items";
            case "armor_tools": return "Armor & Tools";
            case "fish": return "Fish";
            case "books": return "Enchanted Books";
            case "potions": return "Potions";
            case "blocks": return "Blocks";
            default: return categoryKey;
        }
    }

    private ItemStack createProgressionPane(int levelIndex, int currentLevel, double earned) {
        double threshold = this.calculateSellMultiThreshold(levelIndex);
        double multiplier = 1.0 + (levelIndex * 0.1);

        if (levelIndex < currentLevel) {
            return this.namedWithLore(Material.GREEN_STAINED_GLASS_PANE, "§a✓ Level " + (levelIndex + 1) + " (" + String.format("%.1f", multiplier) + "x)", "sellmulti_progress_done", List.of("§a$" + this.fmtMoney(threshold) + " earned"));
        } else if (levelIndex == currentLevel) {
            return this.namedWithLore(Material.YELLOW_STAINED_GLASS_PANE, "§eLevel " + (levelIndex + 1) + " - Claimable", "sellmulti_claim:" + levelIndex, List.of("§eMultiplier: §f" + String.format("%.1f", multiplier) + "x", "§e$" + this.fmtMoney(earned) + " §7/ §f$" + this.fmtMoney(threshold), "§eClick to claim"));
        } else {
            return this.namedWithLore(Material.WHITE_STAINED_GLASS_PANE, "§fLevel " + (levelIndex + 1) + " (" + String.format("%.1f", multiplier) + "x)", "sellmulti_progress_incomplete", List.of("§7Progress to unlock", "§e$" + this.fmtMoney(earned) + " §7/ §f$" + this.fmtMoney(threshold)));
        }
    }

    private double calculateSellMultiThreshold(int levelIndex) {
        if (levelIndex < 0) return 0;
        if (levelIndex == 0) return 5000;
        if (levelIndex == 1) return 10000;
        if (levelIndex == 2) return 25000;
        if (levelIndex == 3) return 50000;
        if (levelIndex == 4) return 100000;
        if (levelIndex == 5) return 250000;
        if (levelIndex == 6) return 500000;
        if (levelIndex == 7) return 1000000;
        if (levelIndex == 8) return 2500000;
        if (levelIndex == 9) return 5000000;
        if (levelIndex == 10) return 10000000;
        if (levelIndex == 11) return 25000000;
        if (levelIndex == 12) return 50000000;
        if (levelIndex == 13) return 100000000;
        if (levelIndex == 14) return 250000000;
        if (levelIndex == 15) return 500000000;
        if (levelIndex == 16) return 1000000000.0;
        if (levelIndex == 17) return 2500000000.0;
        if (levelIndex == 18) return 5000000000.0;
        return 10000000000.0;
    }

    private Map<String, Integer> loadSellMultiProgress(UUID playerUuid) {
        Map<String, Integer> progress = new HashMap<>();
        String sql = "SELECT category, level FROM sell_multiplier_progress WHERE player_uuid = ?";
        try (Connection conn = this.openSyncConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setString(1, playerUuid.toString());
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next()) {
                    progress.put(rs.getString("category"), rs.getInt("level"));
                }
            }
        } catch (Exception ex) {
            this.getLogger().warning("Failed loading sellmulti progress: " + ex.getMessage());
        }
        return progress;
    }

    private int loadSellMultiLevel(UUID playerUuid, String category) {
        String sql = "SELECT level FROM sell_multiplier_progress WHERE player_uuid = ? AND category = ?";
        try (Connection conn = this.openSyncConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setString(1, playerUuid.toString());
            ps.setString(2, category);
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) {
                    return rs.getInt("level");
                }
            }
        } catch (Exception ex) {
            this.getLogger().warning("Failed loading sellmulti level: " + ex.getMessage());
        }
        return 0;
    }

    private double loadSellMultiEarned(UUID playerUuid, String category) {
        String sql = "SELECT earned FROM sell_multiplier_progress WHERE player_uuid = ? AND category = ?";
        try (Connection conn = this.openSyncConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setString(1, playerUuid.toString());
            ps.setString(2, category);
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) {
                    return rs.getDouble("earned");
                }
            }
        } catch (Exception ex) {
            this.getLogger().warning("Failed loading sellmulti earned: " + ex.getMessage());
        }
        return 0.0;
    }

