    // ── Teams member management ──────────────────────────────────────────────

    private String playerNameForUuid(String uuidStr) {
        try {
            org.bukkit.OfflinePlayer op = Bukkit.getOfflinePlayer(java.util.UUID.fromString(uuidStr));
            return op.getName() != null ? op.getName() : uuidStr;
        } catch (Exception e) { return uuidStr; }
    }

    private void openTeamMemberManageGui(Player viewer, String targetUuidStr) {
        this.runAsyncTask(() -> {
            try (Connection conn = this.openSyncConnection()) {
                long teamId = this.getTeamIdLong(conn, viewer.getUniqueId());
                if (teamId < 0) { this.runOnPlayerThread(viewer, () -> viewer.sendMessage("§cNot in a team.")); return; }
                String myRole = this.getTeamRole(conn, viewer.getUniqueId(), teamId);
                boolean isManager = "OWNER".equalsIgnoreCase(myRole) || "OFFICER".equalsIgnoreCase(myRole);
                String targetRole = this.getTeamRole(conn, java.util.UUID.fromString(targetUuidStr), teamId);
                String targetName = this.playerNameForUuid(targetUuidStr);
                this.runOnPlayerThread(viewer, () -> {
                    Inventory inv = Bukkit.createInventory(null, 27, "§bManage: " + targetName);
                    ItemStack head = this.createPlayerHead(targetUuidStr);
                    if (head == null) head = new ItemStack(Material.PLAYER_HEAD);
                    ItemMeta hm = head.getItemMeta();
                    hm.setDisplayName("§b" + targetName);
                    hm.setLore(List.of("§7Role: §f" + (targetRole != null ? targetRole : "Member")));
                    head.setItemMeta(hm);
                    inv.setItem(13, head);
                    if (isManager && !"OWNER".equalsIgnoreCase(targetRole)) {
                        inv.setItem(10, this.namedWithLore(Material.BARRIER, "§cKick", "team_kick:" + targetUuidStr, List.of("§7Remove from team")));
                        if ("MEMBER".equalsIgnoreCase(targetRole)) {
                            inv.setItem(11, this.namedWithLore(Material.ARROW, "§aPromote", "team_promote:" + targetUuidStr, List.of("§7→ Officer")));
                        }
                        if ("OFFICER".equalsIgnoreCase(targetRole) && "OWNER".equalsIgnoreCase(myRole)) {
                            inv.setItem(15, this.namedWithLore(Material.ARROW, "§eDemote", "team_demote:" + targetUuidStr, List.of("§7→ Member")));
                        }
                    }
                    viewer.openInventory(inv);
                });
            } catch (Exception ex) { this.getLogger().warning("openTeamMemberManageGui failed: " + ex.getMessage()); }
        });
    }

    private void handleTpaCommand(Player requester, String targetName, String tpaType) {
        Player target = this.fuzzyOnlinePlayer(requester, targetName);   // typo-tolerant name match
        if (target == null) {
            requester.sendActionBar(Component.text("§cPlayer not found: " + targetName));
            return;
        }
        if (target.equals(requester)) {
            requester.sendActionBar(Component.text("§cYou cannot send a TPA request to yourself."));
            return;
        }

        long now = System.currentTimeMillis();
        // Rank-based TPA cooldown: default 20s, pizza+ 15s, staff 5s.
        long tpaCd = this.getTpaCooldownMillis(requester);
        Long lastTpa = this.tpaCooldowns.get(requester.getUniqueId());
        if (lastTpa != null && (now - lastTpa) < tpaCd) {
            long remaining = Math.max(1L, (tpaCd - (now - lastTpa) + 999) / 1000);
            requester.sendActionBar(this.legacyColorize("§cYou can't tpa for another §f" + remaining + "s"));
            return;
        }

        TPARequest request = new TPARequest(requester.getUniqueId(), target.getUniqueId(), tpaType, now);
        this.pendingTpaRequests.put(target.getUniqueId(), request);
        this.tpaRequestExpiry.put(target.getUniqueId(), now + 60000);
        this.tpaCooldowns.put(requester.getUniqueId(), now);

        // TPA auto-accept (/tpauto or the /settings toggle): accept immediately through the normal
        // /tpaccept path so combat checks, countdown and sounds all still apply.
        if (this.isSettingEnabledCached(target.getUniqueId(), "tpa_auto_accept")) {
            this.hotbarWithSound(requester, "&#00BFFF" + target.getName() + " §7auto-accepts teleport requests",
                Sound.BLOCK_NOTE_BLOCK_PLING, 1.0f, 1.9f);
            this.runOnPlayerThread(target, () -> Bukkit.dispatchCommand(target, "tpaccept " + requester.getName()));
            return;
        }

        // If recipient has TPA confirm GUI enabled, open it; otherwise actionbar
        if (this.isSettingEnabledCached(target.getUniqueId(), "tpa_confirm_menus")) {
            this.runOnPlayerThread(target, () -> this.openTpaConfirmGui(target, request));
        } else {
            Component targetMessage = "tpa".equals(tpaType)
                ? this.legacyColorize("§7" + requester.getName() + " &#00BFFFWANTS TO TP TO YOU")
                : this.legacyColorize("§7" + requester.getName() + " &#00BFFFWANTS YOU TO TP TO THEM");
            target.sendActionBar(targetMessage);
            this.hotbarWithSound(target, "", Sound.BLOCK_NOTE_BLOCK_PLING, 1.0f, 2.0f);
        }

        this.hotbarWithSound(requester, "&#00BFFFYou sent a teleport request to §7" + target.getName(),
            Sound.BLOCK_NOTE_BLOCK_PLING, 1.0f, 1.9f);

        this.scheduleTask(() -> {
            if (this.pendingTpaRequests.get(target.getUniqueId()) == request) {
                this.pendingTpaRequests.remove(target.getUniqueId());
                this.tpaRequestExpiry.remove(target.getUniqueId());
                this.runOnPlayerThread(target, () -> {
                    target.sendActionBar(Component.text("§cTPA request from " + requester.getName() + " has expired"));
                    Map<String, Boolean> s = this.playerSettingsCache.getOrDefault(target.getUniqueId(), Map.of());
                    if (s.getOrDefault("music_sound_notifications", true)) {
                        target.playSound(target.getLocation(), Sound.BLOCK_NOTE_BLOCK_BASS, 0.5f, 0.8f);
                    }
                });
            }
        }, 60, TimeUnit.SECONDS);
    }

    private void handleTpaCancelCommand(Player requester) {
        boolean found = false;
        for (java.util.Iterator<Map.Entry<UUID, TPARequest>> it = this.pendingTpaRequests.entrySet().iterator(); it.hasNext(); ) {
            Map.Entry<UUID, TPARequest> entry = it.next();
            if (entry.getValue().requester().equals(requester.getUniqueId())) {
                it.remove();
                this.tpaRequestExpiry.remove(entry.getKey());
                found = true;
                break;
            }
        }
        if (found) {
            requester.sendActionBar(Component.text("§aTPA request cancelled"));
            Map<String, Boolean> cs = this.playerSettingsCache.getOrDefault(requester.getUniqueId(), Map.of());
            if (cs.getOrDefault("music_sound_notifications", true)) {
                requester.playSound(requester.getLocation(), Sound.UI_BUTTON_CLICK, 0.6f, 0.9f);
            }
        } else {
            requester.sendActionBar(Component.text("§cNo active TPA request"));
        }
    }

    // TPA cooldown by rank: staff 5s, pizza++ 8s, pizza+ 15s, everyone else 20s.
    private long getTpaCooldownMillis(Player p) {
        if (p == null) return 20000L;
        if (p.isOp() || p.hasPermission("pizzasmp.staff") || p.hasPermission("pizzasmp.staff.tpa")) return 5000L;
        if (this.isPizzaPlusPlus(p)) return 8000L;
        if (p.hasPermission("pizzasmp.rank.pizzaplus")) return 15000L;
        return 20000L;
    }

    private void handleTpaAcceptCommand(Player recipient, String requesterName) {
        UUID recipientId = recipient.getUniqueId();
        TPARequest request = this.pendingTpaRequests.get(recipientId);

        if (request == null) {
            recipient.sendActionBar(Component.text("§cNo pending TPA request"));
            return;
        }

        if (requesterName != null) {
            Player requester = Bukkit.getPlayer(request.requester());
            if (requester == null || !requester.getName().equalsIgnoreCase(requesterName)) {
                recipient.sendActionBar(Component.text("§cInvalid requester name"));
                return;
            }
        }

        Player requester = Bukkit.getPlayer(request.requester());
        if (requester == null) {
            this.pendingTpaRequests.remove(recipientId);
            this.tpaRequestExpiry.remove(recipientId);
            recipient.sendActionBar(Component.text("§cRequester is no longer online"));
            return;
        }

        if (this.combatTaggedUntil.containsKey(requester.getUniqueId())) {
            recipient.sendActionBar(Component.text("§cCannot accept: requester is in combat"));
            return;
        }

        this.pendingTpaRequests.remove(recipientId);
        this.tpaRequestExpiry.remove(recipientId);

        UUID requesterId = requester.getUniqueId();
        Map<String, Boolean> requesterSettings = this.playerSettingsCache.getOrDefault(requester.getUniqueId(), Map.of());
        boolean requesterSounds = requesterSettings.getOrDefault("music_sound_notifications", true);
        if ("tpa".equals(request.type())) {
            // requester wants to teleport TO recipient — requester is the mover
            Location destination = recipient.getLocation();
            this.cancelPendingTpaTeleport(requesterId);
            PendingTpaTeleport pending = new PendingTpaTeleport(destination);
            this.pendingTpaTeleports.put(requesterId, pending);
            this.tickTpaTeleportCountdown(requesterId);
            requester.sendActionBar(this.legacyColorize("§7" + recipient.getName() + " &#00BFFFaccepted your TPA request"));
        } else {
            // tpahere — recipient should teleport TO requester
            Location destination = requester.getLocation();
            this.cancelPendingTpaTeleport(recipientId);
            PendingTpaTeleport pending = new PendingTpaTeleport(destination);
            this.pendingTpaTeleports.put(recipientId, pending);
            this.tickTpaTeleportCountdown(recipientId);
            requester.sendActionBar(this.legacyColorize("§7" + recipient.getName() + " &#00BFFFaccepted your TPA here request"));
        }
        if (requesterSounds) {
            requester.playSound(requester.getLocation(), Sound.ENTITY_PLAYER_LEVELUP, 0.6f, 2.0f);
        }
        recipient.sendActionBar(this.legacyColorize("&#00BFFFYou accepted §7" + requester.getName() + "&#00BFFF's request"));
        Map<String, Boolean> rs = this.playerSettingsCache.getOrDefault(recipientId, Map.of());
        if (rs.getOrDefault("music_sound_notifications", true)) {
            recipient.playSound(recipient.getLocation(), Sound.BLOCK_NOTE_BLOCK_BELL, 0.8f, 1.6f);
        }
    }

    private void handleTpaDenyCommand(Player recipient, String requesterName) {
        UUID recipientId = recipient.getUniqueId();
        TPARequest request = this.pendingTpaRequests.get(recipientId);

        if (request == null) {
            recipient.sendActionBar(Component.text("§cNo pending TPA request"));
            return;
        }

        if (requesterName != null) {
            Player requester = Bukkit.getPlayer(request.requester());
            if (requester == null || !requester.getName().equalsIgnoreCase(requesterName)) {
                recipient.sendActionBar(Component.text("§cInvalid requester name"));
                return;
            }
        }

        this.pendingTpaRequests.remove(recipientId);
        this.tpaRequestExpiry.remove(recipientId);
        recipient.sendActionBar(Component.text("§aTPA request denied"));
        Map<String, Boolean> rcs = this.playerSettingsCache.getOrDefault(recipientId, Map.of());
        if (rcs.getOrDefault("music_sound_notifications", true)) {
            recipient.playSound(recipient.getLocation(), Sound.UI_BUTTON_CLICK, 0.6f, 0.9f);
        }

        Player requester = Bukkit.getPlayer(request.requester());
        if (requester != null) {
            requester.sendActionBar(Component.text("§cTPA request denied by " + recipient.getName()));
            Map<String, Boolean> rqs = this.playerSettingsCache.getOrDefault(requester.getUniqueId(), Map.of());
            if (rqs.getOrDefault("music_sound_notifications", true)) {
                requester.playSound(requester.getLocation(), Sound.BLOCK_NOTE_BLOCK_BASS, 0.7f, 0.7f);
            }
            Map<String, Boolean> requesterSettings = this.playerSettingsCache.getOrDefault(requester.getUniqueId(), Map.of());
            if (requesterSettings.getOrDefault("music_sound_notifications", true)) {
                requester.playSound(requester.getLocation(), Sound.BLOCK_NOTE_BLOCK_BASS, 0.8f, 0.5f);
            }
        }
    }

    private void tickTpaTeleportCountdown(UUID uuid) {
        // Instant TPA teleport — no warmup, no cooldown.
        PendingTpaTeleport pending = this.pendingTpaTeleports.get(uuid);
        Player player = Bukkit.getPlayer(uuid);
        if (pending == null || player == null || !player.isOnline()) {
            this.cancelPendingTpaTeleport(uuid);
            return;
        }
        if (this.isCombatTagged(player)) {
            this.cancelPendingTpaTeleport(uuid);
            player.sendActionBar(Component.text("§cCannot teleport: in combat"));
            return;
        }
        this.pendingTpaTeleports.remove(uuid);
        if (pending.task != null) {
            pending.task.cancel();
        }
        player.teleportAsync(pending.destination).thenAccept(success -> {
            if (success) {
                this.runOnPlayerThread(player, () -> {
                    this.resetFallAfterTeleport(player);
                    player.sendActionBar(Component.text("§aTeleported!"));
                    Map<String, Boolean> settings = this.playerSettingsCache.getOrDefault(player.getUniqueId(), Map.of());
                    if (settings.getOrDefault("music_sound_notifications", true)) {
                        player.playSound(player.getLocation(), Sound.ENTITY_ENDERMAN_TELEPORT, 0.8f, 1.2f);
                    }
                });
            }
        });
    }

    private void cancelPendingTpaTeleport(UUID uuid) {
        PendingTpaTeleport pending = this.pendingTpaTeleports.remove(uuid);
        if (pending != null && pending.task != null) {
            pending.task.cancel();
        }
    }

    // ---- TPA Confirm GUI (3×9) ----
    // Layout: slot 1=cancel(red glass), slot 3=location(iron block), slot 4=head, slot 5=type(feather), slot 7=accept(lime glass)
    private void openTpaConfirmGui(Player recipient, TPARequest request) {
        Player requester = Bukkit.getPlayer(request.requester());
        if (requester == null || !requester.isOnline()) {
            recipient.sendActionBar(Component.text("§cRequester is no longer online"));
            return;
        }
        Inventory inv = Bukkit.createInventory(null, 27, TITLE_TPA_CONFIRM);
        // Determine who will move and where
        boolean isTpa = "tpa".equals(request.type());
        Player mover = isTpa ? requester : recipient;
        Location dest = isTpa ? recipient.getLocation() : requester.getLocation();
        String worldDisplay = this.worldDisplayName(dest.getWorld());
        String coordsLore = "§7X: §f" + dest.getBlockX() + " §7Y: §f" + dest.getBlockY() + " §7Z: §f" + dest.getBlockZ();

        // Slot 10: Cancel (red stained glass)
        inv.setItem(10, this.namedWithLore(Material.RED_STAINED_GLASS_PANE, "§c§lDecline", "tpa_confirm_decline",
            List.of("§7Click to decline this request")));

        // Slot 12: Location (iron block → shows world + coords on hover)
        Material worldIcon = switch (worldDisplay) {
            case "Nether" -> Material.NETHERRACK;
            case "The End" -> Material.END_STONE;
            default -> Material.IRON_BLOCK;
        };
        inv.setItem(12, this.namedWithLore(worldIcon, "§f" + worldDisplay, "tpa_confirm_location",
            List.of(coordsLore, "", isTpa ? "§7They want to teleport to you" : "§7You will teleport to them")));

        // Slot 13: Player head
        ItemStack head = this.createPlayerHead(requester.getUniqueId().toString());
        if (head == null) head = new ItemStack(Material.PLAYER_HEAD);
        ItemMeta headMeta = head.getItemMeta();
        headMeta.setDisplayName("§b" + requester.getName());
        headMeta.setLore(List.of("§7Sent a TPA request"));
        if (this.uiActionKey != null) {
            headMeta.getPersistentDataContainer().set(this.uiActionKey, PersistentDataType.STRING, "tpa_confirm_head");
        }
        head.setItemMeta(headMeta);
        inv.setItem(13, head);

        // Slot 14: TP type (feather)
        String typeLabel = isTpa ? "§fTPA" : "§fTPA Here";
        String typeDesc = isTpa ? "§7" + requester.getName() + " wants to TP to you" : "§7" + requester.getName() + " wants you to TP to them";
        inv.setItem(14, this.namedWithLore(Material.FEATHER, typeLabel, "tpa_confirm_type", List.of(typeDesc)));

        // Slot 16: Accept (lime stained glass)
        inv.setItem(16, this.namedWithLore(Material.LIME_STAINED_GLASS_PANE, "§a§lAccept", "tpa_confirm_accept",
            List.of("§7Click to accept this request")));

        recipient.openInventory(inv);
        recipient.playSound(recipient.getLocation(), Sound.BLOCK_NOTE_BLOCK_PLING, 1.0f, 2.0f);
    }

    private String worldDisplayName(org.bukkit.World world) {
        if (world == null) return "Overworld";
        return switch (world.getEnvironment()) {
            case NETHER -> "Nether";
            case THE_END -> "The End";
            default -> "Overworld";
        };
    }

    private void handleTpaConfirmClick(Player recipient, int slot, ItemStack item) {
        if (item == null || !item.hasItemMeta()) return;
        String id = this.uiActionId(item);
        if (id == null) return;
        switch (id) {
            case "tpa_confirm_accept" -> {
                recipient.closeInventory();
                this.handleTpaAcceptCommand(recipient, null);
            }
            case "tpa_confirm_decline" -> {
                recipient.closeInventory();
                this.handleTpaDenyCommand(recipient, null);
            }
        }
    }

