    // ---- /bounty system ----
    private void handleBountyCommand(Player p, String[] args) {
        if (args.length == 0) {
            this.openBountyGui(p, 1);
            return;
        }
        switch (args[0].toLowerCase(Locale.ROOT)) {
            case "remove", "cancel" -> {
                this.removeBounty(p, args.length >= 2 ? args[1] : null);
            }
            default -> {
                if (args.length < 2) { p.sendActionBar(Component.text("§cUsage: /bounty <player> <amount>")); return; }
                this.placeBounty(p, args[0], args[1]);
            }
        }
    }

    private void placeBounty(Player placer, String targetName, String amountStr) {
        ParsedAmount parsed = this.parseCompactAmount(amountStr);
        if (parsed == null || parsed.value <= 0.0) {
            placer.sendActionBar(Component.text("§cInvalid amount.")); return;
        }
        double amount = parsed.value;
        if (amount < 100) { placer.sendActionBar(Component.text("§cMinimum bounty is $100.")); return; }
        UUID placerUuid = placer.getUniqueId();
        // Resolve target: online (exact) first, else offline via the players table.
        this.runAsyncTask(() -> {
            Player onlineTarget = Bukkit.getPlayerExact(targetName);
            UUID resolvedUuid = onlineTarget != null ? onlineTarget.getUniqueId() : this.lookupUuidByName(targetName);
            String resolvedName = onlineTarget != null ? onlineTarget.getName() : targetName;
            if (resolvedUuid == null) {
                this.runOnPlayerThread(placer, () -> placer.sendActionBar(Component.text("§cPlayer not found: " + targetName)));
                return;
            }
            // Self-bounties are allowed.
            final UUID targetUuid = resolvedUuid;
            final String targetDisplay = resolvedName;
            this.runOnPlayerThread(placer, () -> {
                if (!this.withdrawMoney(placer, amount)) {
                    placer.sendActionBar(Component.text("§cNot enough money."));
                    return;
                }
                this.runAsyncTask(() -> {
                    try (Connection conn = this.openSyncConnection();
                         PreparedStatement ps = conn.prepareStatement("INSERT INTO bounties (placer_uuid,target_uuid,amount) VALUES (?,?,?)")) {
                        ps.setString(1, placerUuid.toString());
                        ps.setString(2, targetUuid.toString());
                        ps.setDouble(3, amount);
                        ps.executeUpdate();
                    } catch (Exception ex) {
                        this.getLogger().warning("[Bounty] Failed to place bounty: " + ex.getMessage());
                        this.runOnPlayerThread(placer, () -> { this.depositMoney(placer, amount); placer.sendActionBar(Component.text("§cBounty failed, refunded.")); });
                        return;
                    }
                    this.logTransactionAudit(placerUuid.toString(), placer.getName(), "BOUNTY_PLACE", targetDisplay, 1, amount, amount, "target=" + targetUuid);
                    this.runOnPlayerThread(placer, () -> placer.sendActionBar(this.legacyColorize("&#00BFFFBounty of §a$" + this.fmtMoney(amount) + " &#00BFFFplaced on §f" + targetDisplay)));
                    for (Player online : Bukkit.getOnlinePlayers()) {
                        if (this.isSettingEnabledCached(online.getUniqueId(), "bounty_alerts")) {
                            this.runOnPlayerThread(online, () -> online.sendActionBar(this.legacyColorize("§c☠ §f" + placer.getName() + " §7placed a §a$" + this.fmtMoney(amount) + " §7bounty on §f" + targetDisplay)));
                        }
                    }
                });
            });
        });
    }

    private void removeBounty(Player placer, String targetName) {
        this.runAsyncTask(() -> {
            try (Connection conn = this.openSyncConnection();
                 PreparedStatement ps = conn.prepareStatement("SELECT id, amount, target_uuid FROM bounties WHERE placer_uuid=? AND status='ACTIVE' ORDER BY created_at DESC LIMIT 1")) {
                ps.setString(1, placer.getUniqueId().toString());
                try (ResultSet rs = ps.executeQuery()) {
                    if (!rs.next()) {
                        this.runOnPlayerThread(placer, () -> placer.sendActionBar(Component.text("§cYou have no active bounties.")));
                        return;
                    }
                    long id = rs.getLong(1);
                    double amount = rs.getDouble(2);
                    try (PreparedStatement upd = conn.prepareStatement("UPDATE bounties SET status='CANCELLED' WHERE id=?")) {
                        upd.setLong(1, id);
                        upd.executeUpdate();
                    }
                    this.runOnPlayerThread(placer, () -> {
                        this.depositMoney(placer, amount);
                        placer.sendActionBar(this.legacyColorize("&#00BFFFBounty cancelled. §a$" + this.fmtMoney(amount) + " &#00BFFFrefunded."));
                    });
                }
            } catch (Exception ex) {
                this.runOnPlayerThread(placer, () -> placer.sendActionBar(Component.text("§cFailed to cancel bounty.")));
            }
        });
    }

    private record BountyEntry(String uuid, String name, double total) {}

    private void openBountyGui(Player p, int page) {
        this.bountyGuiPage.put(p.getUniqueId(), page);
        String search = this.bountyGuiSearch.getOrDefault(p.getUniqueId(), "");
        String sort = this.bountyGuiSort.getOrDefault(p.getUniqueId(), "Highest");
        this.runAsyncTask(() -> {
            java.util.List<BountyEntry> entries = new java.util.ArrayList<>();
            String orderSql = switch (sort) {
                case "Lowest" -> "total ASC";
                case "Name" -> "p.username ASC";
                default -> "total DESC";
            };
            StringBuilder sql = new StringBuilder("SELECT b.target_uuid, p.username, SUM(b.amount) AS total FROM bounties b LEFT JOIN players p ON p.uuid=b.target_uuid WHERE b.status='ACTIVE' ");
            if (!search.isBlank()) sql.append("AND LOWER(p.username) LIKE ? ");
            sql.append("GROUP BY b.target_uuid ORDER BY ").append(orderSql).append(" LIMIT 450");
            try (Connection conn = this.openSyncConnection();
                 PreparedStatement ps = conn.prepareStatement(sql.toString())) {
                if (!search.isBlank()) ps.setString(1, "%" + search.toLowerCase(Locale.ROOT) + "%");
                try (ResultSet rs = ps.executeQuery()) {
                    while (rs.next()) {
                        String name = rs.getString(2) != null ? rs.getString(2) : "Unknown";
                        entries.add(new BountyEntry(rs.getString(1), name, rs.getDouble(3)));
                    }
                }
            } catch (Exception ex) {
                this.getLogger().warning("[Bounty] Failed GUI query: " + ex.getMessage());
            }
            this.runOnPlayerThread(p, () -> this.renderBountyGui(p, entries, page, sort, search));
        });
    }

    private void renderBountyGui(Player p, java.util.List<BountyEntry> entries, int page, String sort, String search) {
        if (!p.isOnline()) return;
        Inventory inv = Bukkit.createInventory(null, 54, TITLE_BOUNTY);
        int start = Math.max(0, (page - 1) * 45);
        int end = Math.min(entries.size(), start + 45);
        for (int i = start; i < end; ++i) {
            BountyEntry e = entries.get(i);
            ItemStack head = this.createPlayerHead(e.uuid());
            if (head == null) head = new ItemStack(Material.PLAYER_HEAD);
            ItemMeta meta = head.getItemMeta();
            meta.setDisplayName("§c☠ §f" + e.name());
            meta.setLore(List.of("§7Bounty: §a$" + this.fmtMoney(e.total()), "§7Kill them to claim the reward"));
            head.setItemMeta(meta);
            inv.setItem(i - start, head);
        }
        int maxPage = Math.max(1, (int)Math.ceil(entries.size() / 45.0));
        if (page > 1) inv.setItem(45, this.namedWithLore(Material.ARROW, "§aPrev", "bounty_prev", List.of("§7Page " + (page - 1))));
        inv.setItem(46, this.namedWithLore(Material.OAK_SIGN, "§aPage §f" + page + "§a/§f" + maxPage, "bounty_page", List.of()));
        inv.setItem(48, this.namedWithLore(Material.OAK_SIGN, "§aSearch", "bounty_search", List.of(search.isBlank() ? "§7Click to search a name" : "§7Current: §f" + search)));
        inv.setItem(49, this.namedWithLore(Material.HOPPER, "§aSort: §f" + sort, "bounty_sort", List.of("§7• Highest", "§7• Lowest", "§7• Name")));
        if (!search.isBlank()) inv.setItem(50, this.namedWithLore(Material.BARRIER, "§cClear search", "bounty_clear", List.of()));
        if (entries.size() > page * 45) inv.setItem(53, this.namedWithLore(Material.ARROW, "§aNext", "bounty_next", List.of("§7Page " + (page + 1))));
        if (entries.isEmpty()) {
            inv.setItem(22, this.namedWithLore(Material.GRAY_DYE, "§7No active bounties", "bounty_none", List.of("§7Use §f/bounty <player> <amount>")));
        }
        p.openInventory(inv);
    }

    private void handleBountyGuiClick(Player p, ItemStack item, ClickType click) {
        if (item == null || !item.hasItemMeta()) return;
        String id = this.uiActionId(item);
        if (id == null) return;
        int page = this.bountyGuiPage.getOrDefault(p.getUniqueId(), 1);
        switch (id) {
            case "bounty_prev" -> this.openBountyGui(p, Math.max(1, page - 1));
            case "bounty_next" -> this.openBountyGui(p, page + 1);
            case "bounty_sort" -> {
                String cur = this.bountyGuiSort.getOrDefault(p.getUniqueId(), "Highest");
                String next = switch (cur) { case "Highest" -> "Lowest"; case "Lowest" -> "Name"; default -> "Highest"; };
                this.bountyGuiSort.put(p.getUniqueId(), next);
                this.openBountyGui(p, 1);
            }
            case "bounty_search" -> this.requestTextInput(p, TextInputMode.BOUNTY_SEARCH, "Type a name to search in chat.");
            case "bounty_clear" -> { this.bountyGuiSearch.remove(p.getUniqueId()); this.openBountyGui(p, 1); }
        }
    }

    void claimBountiesOnKill(Player killer, Player victim) {
        UUID killerUuid = killer.getUniqueId();
        UUID victimUuid = victim.getUniqueId();
        this.runAsyncTask(() -> {
            double totalClaimed = 0;
            try (Connection conn = this.openSyncConnection()) {
                conn.setAutoCommit(false);
                try (PreparedStatement sel = conn.prepareStatement("SELECT id, amount FROM bounties WHERE target_uuid=? AND status='ACTIVE' FOR UPDATE");
                     PreparedStatement upd = conn.prepareStatement("UPDATE bounties SET status='CLAIMED', claimer_uuid=?, claimed_at=CURRENT_TIMESTAMP WHERE id=?")) {
                    sel.setString(1, victimUuid.toString());
                    try (ResultSet rs = sel.executeQuery()) {
                        while (rs.next()) {
                            long id = rs.getLong(1);
                            double amt = rs.getDouble(2);
                            upd.setString(1, killerUuid.toString());
                            upd.setLong(2, id);
                            upd.executeUpdate();
                            totalClaimed += amt;
                        }
                    }
                    conn.commit();
                } catch (Exception ex) {
                    conn.rollback();
                    throw ex;
                } finally {
                    conn.setAutoCommit(true);
                }
            } catch (Exception ex) {
                this.getLogger().warning("[Bounty] Failed to claim bounties: " + ex.getMessage());
                return;
            }
            if (totalClaimed > 0) {
                final double payout = totalClaimed;
                this.runOnPlayerThread(killer, () -> {
                    this.depositMoney(killer, payout);
                    killer.sendActionBar(this.legacyColorize("§c☠ §aBounty claimed! §f+$" + this.fmtMoney(payout)));
                    this.logTransactionAudit(killerUuid.toString(), killer.getName(), "BOUNTY_CLAIM", victim.getName(), 1, payout, payout, "victim=" + victimUuid);
                    killer.playSound(killer.getLocation(), Sound.ENTITY_PLAYER_LEVELUP, 1.0f, 0.8f);
                    for (Player online : Bukkit.getOnlinePlayers()) {
                        if (this.isSettingEnabledCached(online.getUniqueId(), "bounty_alerts")) {
                            online.sendActionBar(this.legacyColorize("§c☠ §f" + killer.getName() + " §7claimed the bounty on §f" + victim.getName() + " §7(§a$" + this.fmtMoney(payout) + "§7)"));
                        }
                    }
                });
            }
        });
    }

    private void scheduleTask(Runnable task, long delay, TimeUnit unit) {
        if (this.foliaRuntime) {
            Bukkit.getAsyncScheduler().runDelayed(this, scheduledTask -> task.run(), delay, unit);
        } else {
            long delayTicks = unit.toMillis(delay) / 50;
            Bukkit.getScheduler().scheduleSyncDelayedTask(this, task, delayTicks);
        }
    }

    private void openSuspiciousPlayersGui(Player viewer) {
        SuspiciousPlayersGuiState state = this.suspiciousPlayersGuiState.computeIfAbsent(viewer.getUniqueId(), k -> new SuspiciousPlayersGuiState());
        this.openSuspiciousPlayersGui(viewer, state.page);
    }

    private void openSuspiciousPlayersGui(Player viewer, int page) {
        if (this.useDialogUi(viewer)) {
            this.openSuspiciousPlayersDialog(viewer, page);
            return;
        }
        this.runAsyncTask(() -> {
            java.util.List<SuspiciousPlayerEntry> allSuspicious = this.loadSuspiciousPlayers(500);
            // Per-UUID breakdown of check types with counts, top-first.
            java.util.Map<String, java.util.List<String>> flagBreakdown = this.loadSuspiciousFlagBreakdown();
            final int itemsPerPage = 45;
            final int totalPages = allSuspicious.isEmpty() ? 1 : (int) Math.ceil((double) allSuspicious.size() / itemsPerPage);
            final int finalPage = Math.max(1, Math.min(page, totalPages));

            final int start = allSuspicious.isEmpty() ? 0 : (finalPage - 1) * itemsPerPage;
            final int end = allSuspicious.isEmpty() ? 0 : Math.min(start + itemsPerPage, allSuspicious.size());
            final java.util.List<SuspiciousPlayerEntry> pageEntries = allSuspicious.isEmpty() ? new java.util.ArrayList<>() : allSuspicious.subList(start, end);

            this.runOnPlayerThread(viewer, () -> {
                if (!viewer.isOnline()) return;

                Inventory inv = Bukkit.createInventory(null, 54, "§cSuspicious Players");

                if (!pageEntries.isEmpty()) {
                    int slot = 0;
                    for (SuspiciousPlayerEntry entry : pageEntries) {
                        if (slot >= 45) break;
                        ItemStack head = this.createPlayerHead(entry.uuid());
                        if (head == null) head = new ItemStack(Material.PLAYER_HEAD);
                        ItemMeta meta = head.getItemMeta();
                        meta.setDisplayName("§c" + entry.playerName() + " §7(§f" + entry.violationCount() + "§7)");
                        java.util.List<String> lore = new java.util.ArrayList<>();
                        lore.add("§7Severity: " + (entry.maxSeverity().equals("HIGH") ? "§c" : entry.maxSeverity().equals("MEDIUM") ? "§e" : "§a") + entry.maxSeverity()
                            + "  §7VL: §f" + String.format("%.1f", entry.totalVlPoints()));
                        // Flag breakdown: top 5 check types with counts (e.g. "KillauraA ×3").
                        java.util.List<String> bd = flagBreakdown.getOrDefault(entry.uuid(), java.util.List.of());
                        if (bd.isEmpty()) {
                            lore.add("§7Latest: §f" + entry.lastViolationType());
                        } else {
                            lore.add("§7Flagged for:");
                            int shown = 0;
                            for (String line : bd) {
                                lore.add("  §8• §f" + line);
                                if (++shown >= 5) break;
                            }
                        }
                        lore.add("");
                        lore.add("§7Click to view details");
                        meta.setLore(lore);
                        if (this.uiActionKey != null) {
                            meta.getPersistentDataContainer().set(this.uiActionKey, PersistentDataType.STRING, "sus_player:" + entry.uuid());
                        }
                        head.setItemMeta(meta);
                        inv.setItem(slot++, head);
                    }
                } else {
                    ItemStack noPlayers = this.named(Material.LIME_TERRACOTTA, "§aNo suspicious players", null);
                    inv.setItem(22, noPlayers);
                }

                // Navigation buttons
                if (finalPage > 1) {
                    inv.setItem(45, this.namedWithLore(Material.ARROW, "§aBack", "sus_prev", List.of()));
                }

                inv.setItem(49, this.namedWithLore(Material.REDSTONE_BLOCK, "§aReload", "sus_reload", List.of("§7Refresh suspicious player list")));

                if (!allSuspicious.isEmpty() && finalPage < totalPages) {
                    inv.setItem(53, this.namedWithLore(Material.ARROW, "§aNext", "sus_next", List.of()));
                }

                SuspiciousPlayersGuiState state = this.suspiciousPlayersGuiState.computeIfAbsent(viewer.getUniqueId(), k -> new SuspiciousPlayersGuiState());
                state.page = finalPage;

                viewer.openInventory(inv);
            });
        });
    }

    private void openSuspiciousPlayerDetailGui(Player viewer, String targetUuid) {
        this.runAsyncTask(() -> {
            String sql = "SELECT player_uuid, player_name FROM anticheat_violations WHERE player_uuid = ? LIMIT 1";
            try (Connection conn = this.openSyncConnection();
                 PreparedStatement ps = conn.prepareStatement(sql)) {
                ps.setString(1, targetUuid);
                try (ResultSet rs = ps.executeQuery()) {
                    if (!rs.next()) {
                        viewer.sendMessage("§cPlayer not found.");
                        return;
                    }
                    String playerName = rs.getString(2);

                    this.runOnPlayerThread(viewer, () -> {
                        if (!viewer.isOnline()) return;
                        Inventory inv = Bukkit.createInventory(null, 27, "§c" + playerName + " - Details");

                        // Teleport button
                        inv.setItem(11, this.namedWithLore(Material.ENDER_PEARL, "§aTeleport to Player", "sus_detail_tp:" + targetUuid, List.of("§7Click to teleport to this player")));

                        // Punish button
                        inv.setItem(13, this.namedWithLore(Material.REDSTONE_BLOCK, "§cPunish Player", "sus_detail_punish:" + targetUuid, List.of("§7Click to open punish menu")));

                        // Clear flags button (opens confirm)
                        inv.setItem(15, this.namedWithLore(Material.BARRIER, "§eClear All Flags", "sus_detail_clear:" + targetUuid,
                            List.of("§7Remove this player from the", "§7suspicious list (false-positive).", "§7Click to confirm.")));

                        // Back button
                        inv.setItem(22, this.namedWithLore(Material.ARROW, "§7Back", "sus_detail_back", List.of()));

                        viewer.openInventory(inv);
                    });
                }
            } catch (Exception ex) {
                this.getLogger().warning("Failed loading suspicious player details: " + ex.getMessage());
            }
        });
    }

    // For each suspicious UUID, returns a list of "<CheckName> ×<count>" strings
    // sorted by count desc — used to enrich the /sus list lore.
    private java.util.Map<String, java.util.List<String>> loadSuspiciousFlagBreakdown() {
        java.util.Map<String, java.util.List<String>> out = new java.util.HashMap<>();
        String sql = "SELECT player_uuid, violation_type, COUNT(*) c FROM anticheat_violations "
            + "WHERE reported_at > DATE_SUB(NOW(), INTERVAL 7 DAY) "
            + "GROUP BY player_uuid, violation_type ORDER BY player_uuid, c DESC";
        try (Connection conn = this.openSyncConnection();
             PreparedStatement ps = conn.prepareStatement(sql);
             ResultSet rs = ps.executeQuery()) {
            while (rs.next()) {
                String uuid = rs.getString(1);
                String type = rs.getString(2);
                int count = rs.getInt(3);
                out.computeIfAbsent(uuid, k -> new java.util.ArrayList<>())
                    .add(type + " §7×§f" + count);
            }
        } catch (Exception ex) {
            this.getLogger().warning("Failed loading suspicious flag breakdown: " + ex.getMessage());
        }
        return out;
    }

