    // ===================== Suspicious players dialog (Java / dialog clients) =====================

    private void openSuspiciousPlayersDialog(Player viewer, int page) {
        this.runAsyncTask(() -> {
            java.util.List<SuspiciousPlayerEntry> all = this.loadSuspiciousPlayers(500);
            java.util.Map<String, java.util.List<String>> breakdown = this.loadSuspiciousFlagBreakdown();
            final int per = 14;
            final int totalPages = all.isEmpty() ? 1 : (int) Math.ceil((double) all.size() / per);
            final int fp = Math.max(1, Math.min(page, totalPages));
            final int start = all.isEmpty() ? 0 : (fp - 1) * per;
            final int end = all.isEmpty() ? 0 : Math.min(start + per, all.size());
            final java.util.List<SuspiciousPlayerEntry> pageEntries = all.isEmpty()
                ? java.util.List.of() : new java.util.ArrayList<>(all.subList(start, end));
            this.runOnPlayerThread(viewer, () -> {
                if (!viewer.isOnline()) return;
                SuspiciousPlayersGuiState state = this.suspiciousPlayersGuiState.computeIfAbsent(viewer.getUniqueId(), k -> new SuspiciousPlayersGuiState());
                state.page = fp;
                java.util.List<DialogBody> body = List.of(DialogBody.plainMessage(Component.text(
                    all.isEmpty() ? "No suspicious players." : (all.size() + " flagged · page " + fp + "/" + totalPages),
                    NamedTextColor.GRAY)));
                java.util.List<ActionButton> buttons = new java.util.ArrayList<>();
                for (SuspiciousPlayerEntry entry : pageEntries) {
                    String sev = entry.maxSeverity();
                    NamedTextColor sc = "HIGH".equals(sev) ? NamedTextColor.RED : "MEDIUM".equals(sev) ? NamedTextColor.YELLOW : NamedTextColor.GREEN;
                    java.util.List<String> flags = breakdown.getOrDefault(entry.uuid(), java.util.List.of());
                    String tip = "Severity " + sev + " · VL " + String.format("%.1f", entry.totalVlPoints())
                        + (flags.isEmpty() ? "" : " · " + String.join(", ", flags.subList(0, Math.min(3, flags.size())))
                            .replaceAll("§[0-9a-fk-or]", ""));
                    final String uuid = entry.uuid();
                    final String nm = entry.playerName();
                    buttons.add(this.dialogButton(Component.text(nm + " (" + entry.violationCount() + ")", sc), tip, 150,
                        p -> this.openSuspiciousPlayerDetailDialog(p, uuid, nm)));
                }
                if (fp > 1) buttons.add(this.dialogButton(Component.text("← Prev"), null, 100, p -> this.openSuspiciousPlayersDialog(p, fp - 1)));
                buttons.add(this.dialogButton(Component.text("Reload"), null, 100, p -> this.openSuspiciousPlayersDialog(p, fp)));
                if (fp < totalPages) buttons.add(this.dialogButton(Component.text("Next →"), null, 100, p -> this.openSuspiciousPlayersDialog(p, fp + 1)));
                Dialog dialog = this.buildDialog(Component.text("Suspicious Players", DIALOG_BRAND), body, List.of(),
                    DialogType.multiAction(buttons).columns(2)
                        .exitAction(this.dialogButton(Component.text("Close"), null, 150, p -> p.closeDialog())).build());
                viewer.showDialog(dialog);
            });
        });
    }

    private void openSuspiciousPlayerDetailDialog(Player viewer, String targetUuid, String name) {
        java.util.List<DialogBody> body = List.of(DialogBody.plainMessage(Component.text("Anticheat actions for " + name, NamedTextColor.GRAY)));
        java.util.List<ActionButton> buttons = List.of(
            this.dialogButton(Component.text("Teleport", NamedTextColor.GREEN), "Teleport to this player", 150, p -> {
                try {
                    Player t = Bukkit.getPlayer(UUID.fromString(targetUuid));
                    if (t != null && t.isOnline()) {
                        p.closeDialog();
                        p.teleport(t);
                        p.sendActionBar(Component.text("§aTeleported to " + t.getName()));
                    } else {
                        p.sendActionBar(Component.text("§cPlayer is offline."));
                    }
                } catch (IllegalArgumentException ex) {
                    p.sendActionBar(Component.text("§cInvalid player UUID."));
                }
            }),
            this.dialogButton(Component.text("Punish", NamedTextColor.RED), "Open the punish menu", 150, p -> {
                p.closeDialog();
                p.performCommand("punish " + name);
            }),
            this.dialogButton(Component.text("Clear All Flags", NamedTextColor.YELLOW), "Remove from the suspicious list", 150,
                p -> this.openSuspiciousClearConfirmDialog(p, targetUuid, name)));
        Dialog dialog = this.buildDialog(Component.text(name + " · Details", DIALOG_BRAND), body, List.of(),
            DialogType.multiAction(buttons).columns(1)
                .exitAction(this.dialogButton(Component.text("Back"), null, 150,
                    p -> this.openSuspiciousPlayersDialog(p,
                        this.suspiciousPlayersGuiState.computeIfAbsent(p.getUniqueId(), k -> new SuspiciousPlayersGuiState()).page))).build());
        viewer.showDialog(dialog);
    }

    private void openSuspiciousClearConfirmDialog(Player viewer, String targetUuid, String name) {
        ActionButton confirm = this.dialogButton(Component.text("Confirm Clear", NamedTextColor.RED), null, 150, p -> {
            p.closeDialog();
            this.runAsyncTask(() -> {
                int deleted = this.clearSuspiciousFlags(targetUuid);
                this.runOnPlayerThread(p, () -> {
                    p.sendActionBar(Component.text(deleted < 0
                        ? "§cFailed to clear flags." : "§aCleared " + deleted + " flag(s)."));
                    this.openSuspiciousPlayersDialog(p, 1);
                });
            });
        });
        ActionButton cancel = this.dialogButton(Component.text("Cancel", NamedTextColor.GRAY), null, 150,
            p -> this.openSuspiciousPlayerDetailDialog(p, targetUuid, name));
        Dialog dialog = this.buildDialog(Component.text("Clear flags?", DIALOG_BRAND),
            List.of(DialogBody.plainMessage(Component.text("Delete ALL anticheat flags for " + name + "? This cannot be undone.", NamedTextColor.GRAY))),
            List.of(), DialogType.confirmation(confirm, cancel));
        viewer.showDialog(dialog);
    }

    // ======================================================================
    // ===================== /admin server console ==========================
    // In-game server management for admin/SRADMIN/owner/dev (perm
    // pizzasmp.admin.console). Dialog-based; the panels drive existing
    // hooks (maintenance, world access, view distance, shop).
    // ======================================================================

    private void loadWorldAccess() {
        this.disabledWorlds.clear();
        this.rtpDisabledWorlds.clear();
        this.disabledWorlds.addAll(this.settings.getStringList("world_access.disabled_worlds"));
        this.rtpDisabledWorlds.addAll(this.settings.getStringList("world_access.rtp_disabled_worlds"));
        this.evacTargetWorld = this.settings.getString("world_access.evac_target", "world");
        this.worldAccessAdminBypass = this.settings.getBoolean("world_access.admin_bypass", true);
        this.worldLockMessage = this.settings.getString("world_access.lock_message", "&cThis region is down for maintenance");
        this.endRtpClosed = this.settings.getBoolean("flags.end_closed", true);
    }

    private Component worldLockComponent() {
        return this.legacyColorize(this.worldLockMessage);
    }

    private void saveWorldAccess() {
        this.settings.set("world_access.disabled_worlds", new java.util.ArrayList<>(this.disabledWorlds));
        this.settings.set("world_access.rtp_disabled_worlds", new java.util.ArrayList<>(this.rtpDisabledWorlds));
        this.settings.set("world_access.evac_target", this.evacTargetWorld);
        this.settings.set("world_access.admin_bypass", this.worldAccessAdminBypass);
        this.settings.set("world_access.lock_message", this.worldLockMessage);
        this.settings.set("flags.end_closed", this.endRtpClosed);
        this.saveConfig();
        // Keep the limbo's closed-world view in sync no matter which UI toggled access (/region or /admin).
        this.publishClosedWorlds();
    }

    // True if player should be blocked from world wn (disabled and the player isn't a bypassing admin).
    private boolean worldBlockedFor(Player player, String wn) {
        if (!this.disabledWorlds.contains(wn)) return false;
        return !(this.worldAccessAdminBypass && player.hasPermission(PERM_ADMIN_CONSOLE));
    }

    private org.bukkit.World evacWorld() {
        org.bukkit.World w = Bukkit.getWorld(this.evacTargetWorld);
        if (w == null && !Bukkit.getWorlds().isEmpty()) w = Bukkit.getWorlds().getFirst();
        return w;
    }

    // /region — per-world (dimension) maintenance over the world-access engine: closing a region
    // evacuates everyone to the evac target and blocks re-entry (tp/portal/rtp/join) until reopened.
    // This is the in-process maintenance path: no restart, no limbo, other dimensions keep playing.
    // /region is disabled by default pending a per-world-instances-over-Velocity design. The
    // machinery (limbo hold, closed_worlds channel) stays intact; flip this to true to re-enable.


    /** Accepts dimension shorthand (east/overworld/nether/end) or an exact loaded-world name. */
    private String resolveRegionWorld(String in) {
        if (in == null) return null;
        String dim = this.normalizeRtpDimension(in.toLowerCase(Locale.ROOT));
        if (dim != null) {
            return switch (dim) { case "nether" -> "world_nether"; case "end" -> "world_the_end"; default -> "world"; };
        }
        org.bukkit.World w = Bukkit.getWorld(in);
        return w != null ? w.getName() : null;
    }

    // /region start: give the closed world's players the FULL limbo treatment (snapshot + region
    // copy + transfer) instead of dumping them at the evac spawn. Mirrors the /limbomaint prep flow
    // but scoped to one world and WITHOUT any SMP shutdown. The limbo holds them (closed_worlds
    // signal) until /region end, then returns them to their exact spot. Falls back to spawn-evac
    // if the limbo is unreachable.
    private int sendWorldToLimbo(String worldName) {
        org.bukkit.World from = Bukkit.getWorld(worldName);
        if (from == null) return 0;
        String limboHost = this.settings.getString("limbo.probe-host", "127.0.0.1");
        int limboPort = this.settings.getInt("limbo.probe-port", 25567);
        String limbo = this.settings.getString("limbo.server-name", "limbo");
        // Limbo down -> old behaviour (evac to spawn) instead of stranding transfers.
        boolean limboUp;
        try (java.net.Socket s = new java.net.Socket()) {
            s.connect(new java.net.InetSocketAddress(limboHost, limboPort), 1000);
            limboUp = true;
        } catch (Exception ex) { limboUp = false; }
        if (!limboUp) {
            this.getLogger().warning("[Region] limbo unreachable — falling back to spawn evacuation for " + worldName);
            return this.evacuateWorld(worldName);
        }
        java.util.List<Player> affected = new java.util.ArrayList<>();
        for (Player pl : from.getPlayers()) {
            if (this.worldAccessAdminBypass && pl.hasPermission(PERM_ADMIN_CONSOLE)) continue;   // admins may stay
            affected.add(pl);
        }
        if (affected.isEmpty()) return 0;
        try { from.save(); } catch (Exception ignored) {}
        int vd = Bukkit.getViewDistance() + 1;
        final java.io.File limboRegionDir = new java.io.File(this.settings.getString("limbo.region-dir",
            "../PizzaLimbo/limbo/region"));
        final java.io.File limboAdvDir = new java.io.File(this.settings.getString("limbo.advancements-dir",
            "../PizzaLimbo/limbo/advancements"));
        final java.io.File mainWorldFolder = Bukkit.getWorlds().isEmpty() ? null : Bukkit.getWorlds().get(0).getWorldFolder();
        final java.io.File regionDir = this.regionFolder(from);
        final java.util.List<int[]> copyJobs = new java.util.ArrayList<>();
        final java.util.List<java.io.File> advSrc = new java.util.ArrayList<>();
        final java.util.List<UUID> moveIds = new java.util.ArrayList<>();
        for (Player pl : affected) {
            try {
                pl.saveData();                     // authoritative data to disk FIRST
                this.captureLimboSnapshot(pl);     // visual copy for the limbo
                int cx = pl.getLocation().getBlockX() >> 4, cz = pl.getLocation().getBlockZ() >> 4;
                copyJobs.add(new int[]{(cx - vd) >> 5, (cx + vd) >> 5, (cz - vd) >> 5, (cz + vd) >> 5});
                if (mainWorldFolder != null) {
                    java.io.File af = new java.io.File(mainWorldFolder, "advancements/" + pl.getUniqueId() + ".json");
                    if (af.isFile()) advSrc.add(af);
                }
                moveIds.add(pl.getUniqueId());
            } catch (Exception ex) {
                this.getLogger().warning("[Region] prep failed for " + pl.getName() + ": " + ex.getMessage());
            }
        }
        this.runAsyncTask(() -> {
            try {
                if (!limboRegionDir.isDirectory()) limboRegionDir.mkdirs();
                if (!limboAdvDir.isDirectory()) limboAdvDir.mkdirs();
                for (java.io.File af : advSrc) {
                    try { java.nio.file.Files.copy(af.toPath(), new java.io.File(limboAdvDir, af.getName()).toPath(),
                        java.nio.file.StandardCopyOption.REPLACE_EXISTING); } catch (Exception ignored) {}
                }
                if (regionDir != null && regionDir.isDirectory()) {
                    for (int[] j : copyJobs) {
                        for (int rx = j[0]; rx <= j[1]; rx++) for (int rz = j[2]; rz <= j[3]; rz++) {
                            java.io.File src = new java.io.File(regionDir, "r." + rx + "." + rz + ".mca");
                            if (!src.isFile()) continue;
                            try { java.nio.file.Files.copy(src.toPath(), new java.io.File(limboRegionDir, src.getName()).toPath(),
                                java.nio.file.StandardCopyOption.REPLACE_EXISTING); } catch (Exception ignored) {}
                        }
                    }
                }
            } catch (Exception ex) { this.getLogger().warning("[Region] limbo copy failed: " + ex.getMessage()); }
            Bukkit.getScheduler().runTask((Plugin)this, () -> {
                for (UUID id : moveIds) {
                    Player pl = Bukkit.getPlayer(id);
                    if (pl != null && pl.isOnline() && pl.getWorld().getName().equals(worldName)) {
                        try { this.connectToServer(pl, limbo); } catch (Exception ignored) {}
                    }
                }
            });
        });
        return affected.size();
    }

    // Publish the closed-world set to the limbo's control channel so it HOLDS players whose snapshot
    // world is closed (SMP being up would otherwise return them) and releases them on reopen.
    private void publishClosedWorlds() {
        final String csv = String.join(",", this.disabledWorlds);
        this.runAsyncTask(() -> {
            try (Connection c = this.openSyncConnection(); PreparedStatement ps = c.prepareStatement(
                    "INSERT INTO limbo_control (id, closed_worlds) VALUES (1, ?) ON DUPLICATE KEY UPDATE closed_worlds=VALUES(closed_worlds)")) {
                ps.setString(1, csv);
                ps.executeUpdate();
            } catch (Exception ex) {
                this.getLogger().warning("[Region] closed-worlds publish failed: " + ex.getMessage());
            }
        });
    }

    // /tpauto — flips the SAME "tpa_auto_accept" setting the /settings GUI uses.
    private void handleTpAutoCommand(Player p) {
        this.togglePlayerSetting(p, "tpa_auto_accept", () -> {
            boolean on = this.isSettingEnabledCached(p.getUniqueId(), "tpa_auto_accept");
            p.sendActionBar(this.legacyColorize(on
                ? "&7TPA auto-accept &#00BFFFenabled&7. Incoming requests teleport instantly."
                : "&7TPA auto-accept &fdisabled&7."));
        });
    }

    // Teleport every non-admin player out of a disabled world to the evac target's spawn.
    private int evacuateWorld(String worldName) {
        org.bukkit.World from = Bukkit.getWorld(worldName);
        if (from == null) return 0;
        org.bukkit.World to = this.evacWorld();
        if (to == null || to.getName().equals(worldName)) return 0;
        int moved = 0;
        for (Player pl : new java.util.ArrayList<>(from.getPlayers())) {
            if (this.worldAccessAdminBypass && pl.hasPermission(PERM_ADMIN_CONSOLE)) continue; // admins may stay
            pl.teleport(to.getSpawnLocation());
            pl.sendActionBar(this.worldLockComponent());
            moved++;
        }
        return moved;
    }

    @EventHandler(ignoreCancelled = true)
    public void onWorldAccessTeleport(org.bukkit.event.player.PlayerTeleportEvent e) {
        if (e.getTo() == null || e.getTo().getWorld() == null) return;
        if (this.worldBlockedFor(e.getPlayer(), e.getTo().getWorld().getName())) {
            e.setCancelled(true);
            e.getPlayer().sendActionBar(this.worldLockComponent());
        }
    }

    @EventHandler(ignoreCancelled = true)
    public void onWorldAccessPortal(PlayerPortalEvent e) {
        if (e.getTo() == null || e.getTo().getWorld() == null) return;
        if (this.worldBlockedFor(e.getPlayer(), e.getTo().getWorld().getName())) {
            e.setCancelled(true);
            e.getPlayer().sendActionBar(this.worldLockComponent());
        }
    }

    @EventHandler
    public void onWorldAccessJoin(PlayerJoinEvent e) {
        Player pl = e.getPlayer();
        if (this.worldBlockedFor(pl, pl.getWorld().getName())) {
            // Rejoin into a CLOSED world: hold them in the limbo (position preserved) instead of
            // teleporting to spawn — teleporting would permanently lose their spot in the region.
            this.runPlayerTaskLater(pl, () -> {
                if (!pl.isOnline() || !this.worldBlockedFor(pl, pl.getWorld().getName())) return;
                try {
                    pl.saveData();
                    this.captureLimboSnapshot(pl);
                    this.connectToServer(pl, this.settings.getString("limbo.server-name", "limbo"));
                } catch (Exception ex) {
                    // Limbo transfer failed -> last resort: old spawn-evac (position lost but not stuck).
                    org.bukkit.World to = this.evacWorld();
                    if (to != null && !to.getName().equals(pl.getWorld().getName())) pl.teleport(to.getSpawnLocation());
                }
            }, 10L);
        }
    }

    private DialogBody kv(String label, String value, NamedTextColor valueColor) {
        return DialogBody.plainMessage(Component.text(label + " ", NamedTextColor.GRAY)
            .append(Component.text(value, valueColor)));
    }

    // /admin = STAFF tools only (moderation, player mod, chat). Backend management moved to /manage.
    private void openAdminConsole(Player p) {
        double tps = Bukkit.getTPS()[0];
        NamedTextColor tpsColor = tps >= 19.0 ? NamedTextColor.GREEN : tps >= 15.0 ? NamedTextColor.YELLOW : NamedTextColor.RED;
        java.util.List<DialogBody> body = List.of(
            DialogBody.plainMessage(Component.text("Staff console — moderation, players, chat.", NamedTextColor.GRAY)),
            this.kv("TPS:", String.format("%.1f", Math.min(20.0, tps)), tpsColor),
            this.kv("Online:", String.valueOf(Bukkit.getOnlinePlayers().size()), NamedTextColor.WHITE));
        java.util.List<ActionButton> buttons = new java.util.ArrayList<>(List.of(
            this.dialogButton(Component.text("Players", DIALOG_BRAND), "Kick / mute / freeze / history", 150, this::openAdminPlayers),
            this.dialogButton(Component.text("ChatGuard", DIALOG_BRAND), "Chat filter + strikes", 150, this::openAdminChatGuard),
            this.dialogButton(Component.text("Broadcast", DIALOG_BRAND), "Send a server broadcast", 150, this::openAdminBroadcast)));
        // Backend tier: only offered to those who hold /manage access (dev + granted admins).
        if (p.hasPermission("pizzasmp.manage")) {
            buttons.add(this.dialogButton(Component.text("Server Management →", NamedTextColor.LIGHT_PURPLE),
                "Backend: maintenance, world access, performance, economy, flags…", 150, this::openManageConsole));
        }
        Dialog dialog = this.buildDialog(Component.text("Staff Admin", DIALOG_BRAND), body, List.of(),
            DialogType.multiAction(buttons).columns(2)
                .exitAction(this.dialogButton(Component.text("Close"), null, 150, q -> q.closeDialog())).build());
        p.showDialog(dialog);
    }

    // Dev-only: grant/revoke pizzasmp.manage for online staff (the "dev grants access via UI" flow).
    private void openManageAccess(Player p) {
        if (!p.hasPermission("pizzasmp.manage.grant")) {
            p.sendActionBar(this.legacyColorize("&cOnly the dev can grant management access."));
            return;
        }
        java.util.List<ActionButton> buttons = new java.util.ArrayList<>();
        for (Player t : Bukkit.getOnlinePlayers()) {
            if (t.equals(p) || !t.hasPermission("pizzasmp.pluginadmin")) continue;   // staff only, not self
            boolean has = t.hasPermission("pizzasmp.manage");
            String tn = t.getName();
            buttons.add(this.dialogButton(
                Component.text((has ? "Revoke " : "Grant ") + tn, has ? NamedTextColor.RED : NamedTextColor.GREEN),
                has ? "Currently HAS /manage" : "Currently no /manage", 150, q -> {
                    Bukkit.dispatchCommand(Bukkit.getConsoleSender(),
                        "lp user " + tn + " permission set pizzasmp.manage " + (!has));
                    q.sendActionBar(this.legacyColorize((has ? "&cRevoked" : "&aGranted") + " /manage for &f" + tn));
                    this.openManageAccess(q);
                }));
        }
        java.util.List<DialogBody> body = List.of(DialogBody.plainMessage(buttons.isEmpty()
            ? Component.text("No other staff online to grant.", NamedTextColor.GRAY)
            : Component.text("Grant or revoke backend (/manage) access for online staff.", NamedTextColor.GRAY)));
        buttons.add(this.dialogButton(Component.text("Back"), null, 150, this::openManageConsole));
        p.showDialog(this.buildDialog(Component.text("Manage Access", NamedTextColor.LIGHT_PURPLE), body, List.of(),
            DialogType.multiAction(buttons).columns(2)
                .exitAction(this.dialogButton(Component.text("Back"), null, 150, this::openManageConsole)).build()));
    }

    // /manage = BACKEND management (the tier above /admin). Access: pizzasmp.manage (dev + admins the
    // dev grants). Everything here can affect server operation — deliberately separated from staff tools.
    private void openManageConsole(Player p) {
        if (!p.hasPermission("pizzasmp.manage")) {
            p.sendActionBar(this.legacyColorize("&cYou do not have backend management access."));
            return;
        }
        double tps = Bukkit.getTPS()[0];
        NamedTextColor tpsColor = tps >= 19.0 ? NamedTextColor.GREEN : tps >= 15.0 ? NamedTextColor.YELLOW : NamedTextColor.RED;
        java.util.List<DialogBody> body = List.of(
            DialogBody.plainMessage(Component.text("Backend management console.", NamedTextColor.GRAY)),
            this.kv("TPS:", String.format("%.1f", Math.min(20.0, tps)), tpsColor),
            this.kv("Online:", String.valueOf(Bukkit.getOnlinePlayers().size()), NamedTextColor.WHITE));
        java.util.List<ActionButton> buttons = List.of(
            this.dialogButton(Component.text("Maintenance", DIALOG_BRAND), null, 150, this::openAdminMaintenance),
            this.dialogButton(Component.text("World Access", DIALOG_BRAND), null, 150, this::openAdminWorldAccess),
            this.dialogButton(Component.text("Performance", DIALOG_BRAND), null, 150, this::openAdminPerformance),
            this.dialogButton(Component.text("Shop", DIALOG_BRAND), null, 150, this::openAdminEcoShop),
            this.dialogButton(Component.text("Economy & Ranks", DIALOG_BRAND), null, 150, this::openAdminEconomy),
            this.dialogButton(Component.text("Diagnostics", DIALOG_BRAND), null, 150, this::openAdminDiagnostics),
            this.dialogButton(Component.text("Feature Flags", DIALOG_BRAND), null, 150, this::openAdminFeatureFlags),
            this.dialogButton(Component.text("Server Settings", DIALOG_BRAND), null, 150, this::openAdminServerSettings),
            this.dialogButton(Component.text("Gameplay Tuning", DIALOG_BRAND), null, 150, this::openAdminTuning),
            this.dialogButton(Component.text("Manage Access", NamedTextColor.LIGHT_PURPLE), "Grant/revoke /manage for admins (dev only)", 150, this::openManageAccess),
            this.dialogButton(Component.text("Data & Logs", DIALOG_BRAND), null, 150, this::openAdminData));
        Dialog dialog = this.buildDialog(Component.text("Server Management", NamedTextColor.LIGHT_PURPLE), body, List.of(),
            DialogType.multiAction(buttons).columns(2)
                .exitAction(this.dialogButton(Component.text("Close"), null, 150, q -> q.closeDialog())).build());
        p.showDialog(dialog);
    }

