    // Capture the next chat line a legacy-admin player types (or "cancel") and run the action.
    private void promptAdminInput(Player p, String prompt, java.util.function.Consumer<String> consumer) {
        this.pendingAdminInput.put(p.getUniqueId(), text -> {
            if (text == null || text.equalsIgnoreCase("cancel")) { p.sendMessage("§7Cancelled."); this.openAdminLegacy(p); return; }
            consumer.accept(text.trim());
        });
        p.closeInventory();
        p.sendMessage("§b" + prompt + " §7(type 'cancel' to abort)");
    }

