    private void openAdminLegacyPlayers(Player p) {
        Inventory inv = Bukkit.createInventory(null, 54, TITLE_ADMIN);
        int slot = 0;
        for (Player t : Bukkit.getOnlinePlayers()) {
            if (slot >= 45) break;
            ItemStack head = this.createPlayerHead(t.getUniqueId().toString());
            if (head == null) head = new ItemStack(Material.PLAYER_HEAD);
            ItemMeta meta = head.getItemMeta();
            meta.setDisplayName("§f" + t.getName());
            meta.setLore(List.of("§7In " + t.getWorld().getName(), "§7Click for actions"));
            if (this.uiActionKey != null) meta.getPersistentDataContainer().set(this.uiActionKey, PersistentDataType.STRING, "adm_p:" + t.getUniqueId());
            head.setItemMeta(meta);
            inv.setItem(slot++, head);
        }
        inv.setItem(49, this.namedWithLore(Material.ARROW, "§7Back", "adm_back", List.of()));
        p.openInventory(inv);
    }

