    private void openAdminLegacyGamerules(Player p, String wn) {
        org.bukkit.World w = Bukkit.getWorld(wn);
        if (w == null) { this.openAdminLegacyWorlds(p); return; }
        java.util.List<org.bukkit.GameRule<Boolean>> rules = java.util.List.of(
            org.bukkit.GameRule.DO_FIRE_TICK, org.bukkit.GameRule.MOB_GRIEFING, org.bukkit.GameRule.DO_INSOMNIA,
            org.bukkit.GameRule.FALL_DAMAGE, org.bukkit.GameRule.FIRE_DAMAGE, org.bukkit.GameRule.DROWNING_DAMAGE,
            org.bukkit.GameRule.NATURAL_REGENERATION, org.bukkit.GameRule.DO_IMMEDIATE_RESPAWN, org.bukkit.GameRule.KEEP_INVENTORY,
            org.bukkit.GameRule.DO_TILE_DROPS, org.bukkit.GameRule.DISABLE_RAIDS, org.bukkit.GameRule.SHOW_DEATH_MESSAGES,
            org.bukkit.GameRule.DO_DAYLIGHT_CYCLE, org.bukkit.GameRule.DO_WEATHER_CYCLE);
        Inventory inv = Bukkit.createInventory(null, 54, TITLE_ADMIN);
        ItemStack filler = this.namedWithLore(Material.GRAY_STAINED_GLASS_PANE, " ", null, List.of());
        for (int i = 0; i < 54; i++) inv.setItem(i, filler);
        int slot = 0;
        for (org.bukkit.GameRule<Boolean> gr : rules) {
            boolean val = Boolean.TRUE.equals(w.getGameRuleValue(gr));
            inv.setItem(slot++, this.namedWithLore(val ? Material.LIME_DYE : Material.GRAY_DYE,
                (val ? "§a" : "§7") + gr.getName() + ": " + (val ? "ON" : "OFF"), "adm_gr:" + gr.getName() + ":" + wn, List.of("§7Click to toggle")));
        }
        inv.setItem(49, this.namedWithLore(Material.ARROW, "§7Back", "adm_world:" + wn, List.of()));
        p.openInventory(inv);
    }

    @SuppressWarnings("unchecked")
    private void toggleLegacyGamerule(Player p, String ruleName, String wn) {
        org.bukkit.World w = Bukkit.getWorld(wn);
        if (w == null) { this.openAdminLegacyWorlds(p); return; }
        org.bukkit.GameRule<?> gr = org.bukkit.GameRule.getByName(ruleName);
        if (gr != null && gr.getType() == Boolean.class) {
            org.bukkit.GameRule<Boolean> bgr = (org.bukkit.GameRule<Boolean>) gr;
            w.setGameRule(bgr, !Boolean.TRUE.equals(w.getGameRuleValue(bgr)));
        }
        this.openAdminLegacyGamerules(p, wn);
    }

    private void handleAdminLegacyClick(Player p, ItemStack item, ClickType click) {
        if (item == null || !item.hasItemMeta()) return;
        String id = this.uiActionId(item);
        if (id == null) return;
        switch (id) {
            case "adm_saveall" -> { Bukkit.dispatchCommand(Bukkit.getConsoleSender(), "save-all"); p.sendMessage("§7Saving all worlds."); }
            case "adm_restart" -> this.openAdminLegacyConfirm(p, true);
            case "adm_stop" -> this.openAdminLegacyConfirm(p, false);
            case "adm_do_restart" -> {
                p.closeInventory(); Bukkit.broadcast(Component.text("§e§lServer restarting in 5 seconds..."));
                this.spawnRelaunch(); Bukkit.dispatchCommand(Bukkit.getConsoleSender(), "save-all");
                Bukkit.getScheduler().runTaskLater((Plugin) this, () -> Bukkit.dispatchCommand(Bukkit.getConsoleSender(), "stop"), 100L);
            }
            case "adm_do_stop" -> {
                p.closeInventory(); Bukkit.broadcast(Component.text("§e§lServer stopping in 5 seconds..."));
                Bukkit.dispatchCommand(Bukkit.getConsoleSender(), "save-all");
                Bukkit.getScheduler().runTaskLater((Plugin) this, () -> Bukkit.dispatchCommand(Bukkit.getConsoleSender(), "stop"), 100L);
            }
            case "adm_back" -> this.openAdminLegacy(p);
            case "adm_maint_on" -> { Bukkit.dispatchCommand(Bukkit.getConsoleSender(), "maintenance on"); p.sendMessage("§7Maintenance ON."); }
            case "adm_maint_off" -> { Bukkit.dispatchCommand(Bukkit.getConsoleSender(), "maintenance off"); p.sendMessage("§7Maintenance OFF."); this.openAdminLegacy(p); }
            case "adm_queue" -> { this.settings.set("queue.enabled", !this.settings.getBoolean("queue.enabled", true)); this.saveConfig(); this.openAdminLegacy(p); }
            case "adm_end" -> { this.endRtpClosed = !this.endRtpClosed; this.saveWorldAccess(); this.openAdminLegacy(p); }
            case "adm_vd_up" -> { this.currentThrottledVd = Math.min(VD_MAX, this.currentThrottledVd + 1); this.applyServerVd(this.currentThrottledVd); this.openAdminLegacy(p); }
            case "adm_vd_down" -> { this.currentThrottledVd = Math.max(VD_MIN, this.currentThrottledVd - 1); this.applyServerVd(this.currentThrottledVd); this.openAdminLegacy(p); }
            case "adm_broadcast" -> this.promptAdminInput(p, "Type the broadcast message", t -> { Bukkit.dispatchCommand(Bukkit.getConsoleSender(), "broadcast " + t); p.sendMessage("§7Broadcast sent."); this.openAdminLegacy(p); });
            case "adm_lockmsg" -> this.promptAdminInput(p, "Type the region-down lock message (& / hex colors)", t -> { this.worldLockMessage = t; this.saveWorldAccess(); p.sendMessage("§7Lock message set: "); p.sendActionBar(this.worldLockComponent()); this.openAdminLegacy(p); });
            case "adm_maint_motd" -> this.promptAdminInput(p, "Type the maintenance MOTD (& / hex colors)", t -> { this.setMaintenanceMotd(p, t); this.openAdminLegacy(p); });
            case "adm_whitelist" -> { Bukkit.setWhitelist(!Bukkit.hasWhitelist()); p.sendMessage("§7Whitelist " + (Bukkit.hasWhitelist() ? "ON" : "OFF") + "."); this.openAdminLegacy(p); }
            case "adm_reload" -> { this.reloadConfig(); this.settings = this.getConfig(); this.loadBranding(); this.loadWorldAccess(); p.sendMessage("§7Reloaded PNC config."); this.openAdminLegacy(p); }
            case "adm_worlds" -> this.openAdminLegacyWorlds(p);
            case "adm_economy" -> this.openAdminLegacyEconomy(p);
            case "adm_players" -> this.openAdminLegacyPlayers(p);
            case "adm_tuning" -> this.openAdminLegacyTuning(p);
            case "adm_data" -> this.openAdminLegacyData(p);
            case "adm_d_invsee" -> this.promptAdminInput(p, "Inventory inspect — type: <player>", t -> { p.performCommand("invsee " + t.split("\\s+")[0]); });
            case "adm_d_history" -> this.promptAdminInput(p, "Player history — type: <player>", t -> { p.performCommand("history " + t.split("\\s+")[0]); });
            case "adm_d_txlog" -> { p.closeInventory(); p.performCommand("txlog"); }
            case "adm_d_bans" -> { p.closeInventory(); p.performCommand("listbans"); }
            case "adm_d_suspects" -> { p.closeInventory(); this.openSuspiciousPlayersGui(p); }
            case "adm_diag" -> { p.closeInventory(); p.sendMessage("§7TPS §f" + String.format("%.1f", Math.min(20.0, Bukkit.getTPS()[0])) + " §7| Online §f" + Bukkit.getOnlinePlayers().size() + " §7| Plugins §f" + Bukkit.getPluginManager().getPlugins().length); }
            case "adm_e_givemoney" -> this.promptAdminInput(p, "Give money — type: <player> <amount>", t -> { this.runAdminEco(p, "eco give", t); });
            case "adm_e_setmoney" -> this.promptAdminInput(p, "Set money — type: <player> <amount>", t -> { this.runAdminEco(p, "eco set", t); });
            case "adm_e_giveshards" -> this.promptAdminInput(p, "Give shards — type: <player> <amount>", t -> { this.runAdminEco(p, "shards give", t); });
            case "adm_e_plusgive" -> this.promptAdminInput(p, "Give " + this.brandTierPlus + " (30d) — type: <player>", t -> { Bukkit.dispatchCommand(Bukkit.getConsoleSender(), "pizzaplus give " + t.split("\\s+")[0] + " plus 30"); p.sendMessage("§7Done."); this.openAdminLegacyEconomy(p); });
            case "adm_e_plusplusgive" -> this.promptAdminInput(p, "Give " + this.brandTierPlusPlus + " (30d) — type: <player>", t -> { Bukkit.dispatchCommand(Bukkit.getConsoleSender(), "pizzaplus give " + t.split("\\s+")[0] + " plusplus 30"); p.sendMessage("§7Done."); this.openAdminLegacyEconomy(p); });
            case "adm_e_revoke" -> this.promptAdminInput(p, "Revoke " + this.brandTierPlus + "/++ — type: <player>", t -> { Bukkit.dispatchCommand(Bukkit.getConsoleSender(), "pizzaplus revoke " + t.split("\\s+")[0]); p.sendMessage("§7Done."); this.openAdminLegacyEconomy(p); });
            case "adm_close" -> p.closeInventory();
            default -> this.handleAdminLegacyParam(p, id);
        }
    }

    // Parameterized legacy admin actions (world:<wn>, w_*:<wn>, p:<uuid>, pa_*:<uuid>).
    private void handleAdminLegacyParam(Player p, String id) {
        if (id.startsWith("adm_world:")) { this.openAdminLegacyWorld(p, id.substring("adm_world:".length())); return; }
        if (id.startsWith("adm_tune:")) {
            String key = id.substring("adm_tune:".length());
            this.promptAdminInput(p, "New value for " + key, t -> {
                try { if (t.contains(".")) this.settings.set(key, Double.parseDouble(t)); else this.settings.set(key, Long.parseLong(t)); this.saveConfig(); p.sendMessage("§7" + key + " = " + t); }
                catch (NumberFormatException ex) { p.sendMessage("§cInvalid number."); }
                this.openAdminLegacyTuning(p);
            });
            return;
        }
        if (id.startsWith("adm_gr:")) {
            String rest = id.substring("adm_gr:".length());
            int lastColon = rest.lastIndexOf(':');
            if (lastColon > 0) this.toggleLegacyGamerule(p, rest.substring(0, lastColon), rest.substring(lastColon + 1));
            return;
        }
        if (id.startsWith("adm_w_gamerules:")) { this.openAdminLegacyGamerules(p, id.substring("adm_w_gamerules:".length())); return; }
        if (id.startsWith("adm_w_")) {
            int colon = id.indexOf(':');
            if (colon < 0) return;
            String act = id.substring("adm_w_".length(), colon);
            String wn = id.substring(colon + 1);
            org.bukkit.World w = Bukkit.getWorld(wn);
            if (w == null) { this.openAdminLegacyWorlds(p); return; }
            switch (act) {
                case "access" -> {
                    if (this.disabledWorlds.remove(wn)) { this.saveWorldAccess(); p.sendMessage("§a" + this.friendlyWorldName(wn) + " reopened."); }
                    else { this.disabledWorlds.add(wn); this.saveWorldAccess(); int moved = this.evacuateWorld(wn); p.sendMessage("§c" + this.friendlyWorldName(wn) + " disabled, evacuated " + moved + "."); }
                }
                case "rtp" -> { if (!this.rtpDisabledWorlds.remove(wn)) this.rtpDisabledWorlds.add(wn); this.saveWorldAccess(); }
                case "pvp" -> w.setPVP(!w.getPVP());
                case "mobs" -> w.setGameRule(org.bukkit.GameRule.DO_MOB_SPAWNING, !Boolean.TRUE.equals(w.getGameRuleValue(org.bukkit.GameRule.DO_MOB_SPAWNING)));
                case "diff" -> { org.bukkit.Difficulty[] d = org.bukkit.Difficulty.values(); w.setDifficulty(d[(w.getDifficulty().ordinal() + 1) % d.length]); }
                case "day" -> w.setTime(1000L);
                case "night" -> w.setTime(13000L);
                case "clear" -> { w.setStorm(false); w.setThundering(false); }
                case "rain" -> { w.setStorm(true); w.setThundering(false); }
                case "border" -> { this.promptAdminInput(p, "Border radius for " + this.friendlyWorldName(wn) + " (blocks)", t -> {
                        try { double r = Double.parseDouble(t.trim()); org.bukkit.World ww = Bukkit.getWorld(wn);
                            if (ww != null && r >= 16 && r <= 29999984) { ww.getWorldBorder().setSize(r * 2.0); p.sendMessage("§7Border set to " + (long) r + "."); }
                            else p.sendMessage("§cRadius must be 16-29999984."); }
                        catch (NumberFormatException ex) { p.sendMessage("§cInvalid number."); }
                        this.openAdminLegacyWorld(p, wn); }); return; }
            }
            this.openAdminLegacyWorld(p, wn);
            return;
        }
        if (id.startsWith("adm_p:")) {
            String uuid = id.substring("adm_p:".length());
            Player t = Bukkit.getPlayer(UUID.fromString(uuid));
            if (t != null) this.openAdminLegacyPlayerActions(p, uuid, t.getName()); else this.openAdminLegacyPlayers(p);
            return;
        }
        if (id.startsWith("adm_pa_")) {
            int colon = id.indexOf(':');
            if (colon < 0) return;
            String act = id.substring("adm_pa_".length(), colon);
            String uuid = id.substring(colon + 1);
            Player t = Bukkit.getPlayer(UUID.fromString(uuid));
            if (t == null) { p.sendMessage("§cThat player is offline."); this.openAdminLegacyPlayers(p); return; }
            String name = t.getName();
            switch (act) {
                case "tp" -> { p.closeInventory(); p.teleport(t); }
                case "bring" -> { t.teleport(p); p.sendMessage("§7Brought " + name + "."); this.openAdminLegacyPlayerActions(p, uuid, name); }
                case "gms" -> { t.setGameMode(org.bukkit.GameMode.SURVIVAL); p.sendMessage("§7" + name + " -> Survival."); this.openAdminLegacyPlayerActions(p, uuid, name); }
                case "gmsp" -> { t.setGameMode(org.bukkit.GameMode.SPECTATOR); p.sendMessage("§7" + name + " -> Spectator."); this.openAdminLegacyPlayerActions(p, uuid, name); }
                case "heal" -> { Bukkit.dispatchCommand(Bukkit.getConsoleSender(), "heal " + name); this.openAdminLegacyPlayerActions(p, uuid, name); }
                case "feed" -> { Bukkit.dispatchCommand(Bukkit.getConsoleSender(), "feed " + name); this.openAdminLegacyPlayerActions(p, uuid, name); }
                case "freeze" -> { Bukkit.dispatchCommand(Bukkit.getConsoleSender(), "freeze " + name); this.openAdminLegacyPlayerActions(p, uuid, name); }
                case "mute" -> { Bukkit.dispatchCommand(Bukkit.getConsoleSender(), "mute " + name + " 30m"); p.sendMessage("§7Muted " + name + " 30m."); this.openAdminLegacyPlayerActions(p, uuid, name); }
                case "kick" -> { Bukkit.dispatchCommand(Bukkit.getConsoleSender(), "kick " + name); p.sendMessage("§7Kicked " + name + "."); this.openAdminLegacyPlayers(p); }
                case "punish" -> { p.closeInventory(); p.performCommand("punish " + name); }
            }
        }
    }

    private void runAdminEco(Player p, String cmd, String input) {
        String[] a = input.trim().split("\\s+");
        if (a.length < 2) { p.sendMessage("§cNeed: <player> <amount>"); this.openAdminLegacyEconomy(p); return; }
        Bukkit.dispatchCommand(Bukkit.getConsoleSender(), cmd + " " + a[0] + " " + a[1]);
        p.sendMessage("§7Ran: /" + cmd + " " + a[0] + " " + a[1]);
        this.openAdminLegacyEconomy(p);
    }

    private void openAdminMaintenance(Player p) {
        boolean underMaint = this.maintenanceQueueManager != null && this.maintenanceQueueManager.isServerUnderMaintenance("survival");
        boolean queueOn = this.settings.getBoolean("queue.enabled", true);
        java.util.List<DialogBody> body = List.of(
            this.kv("Maintenance:", underMaint ? "ON" : "OFF", underMaint ? NamedTextColor.RED : NamedTextColor.GREEN),
            this.kv("Join queue:", queueOn ? "Enabled" : "Disabled", queueOn ? NamedTextColor.GREEN : NamedTextColor.GRAY));
        java.util.List<ActionButton> buttons = List.of(
            this.dialogButton(Component.text("Maintenance ON", NamedTextColor.RED), "Kick non-exempt players and close the server", 150, q -> {
                Bukkit.dispatchCommand(Bukkit.getConsoleSender(), "maintenance on");
                q.sendActionBar(Component.text("§7Maintenance turned ON."));
                this.openAdminMaintenance(q);
            }),
            this.dialogButton(Component.text("Maintenance OFF", NamedTextColor.GREEN), "Reopen the server", 150, q -> {
                Bukkit.dispatchCommand(Bukkit.getConsoleSender(), "maintenance off");
                q.sendActionBar(Component.text("§7Maintenance turned OFF."));
                this.openAdminMaintenance(q);
            }),
            this.dialogButton(Component.text(queueOn ? "Disable Queue" : "Enable Queue", DIALOG_BRAND), null, 150, q -> {
                this.settings.set("queue.enabled", !queueOn);
                this.saveConfig();
                this.openAdminMaintenance(q);
            }),
            this.dialogButton(Component.text("Frozen Maint: Start", NamedTextColor.YELLOW), "Freeze players in place (servermaint)", 150, q -> {
                Bukkit.dispatchCommand(Bukkit.getConsoleSender(), "servermaint start");
                q.sendActionBar(Component.text("§7Frozen maintenance started."));
            }),
            this.dialogButton(Component.text("Frozen Maint: End", NamedTextColor.GREEN), null, 150, q -> {
                Bukkit.dispatchCommand(Bukkit.getConsoleSender(), "servermaint end");
                q.sendActionBar(Component.text("§7Frozen maintenance ended."));
            }),
            this.dialogButton(Component.text("Set MOTD", DIALOG_BRAND), "The server-list message shown during maintenance", 150, this::openAdminMaintenanceMotdInput));
        Dialog dialog = this.buildDialog(Component.text("Maintenance", DIALOG_BRAND), body, List.of(),
            DialogType.multiAction(buttons).columns(2)
                .exitAction(this.dialogButton(Component.text("Back"), null, 150, this::openManageConsole)).build());
        p.showDialog(dialog);
    }

    private void openAdminWorldAccess(Player p) {
        java.util.List<DialogBody> body = new java.util.ArrayList<>();
        body.add(DialogBody.plainMessage(Component.text("Pick a world to manage. Disabling evacuates players to the evac target.", NamedTextColor.GRAY)));
        body.add(this.kv("Evac target:", this.evacTargetWorld, NamedTextColor.AQUA));
        body.add(this.kv("Admin bypass:", this.worldAccessAdminBypass ? "ON (admins ignore locks)" : "OFF (locks apply to admins)",
            this.worldAccessAdminBypass ? NamedTextColor.GREEN : NamedTextColor.RED));
        java.util.List<ActionButton> buttons = new java.util.ArrayList<>();
        for (org.bukkit.World w : Bukkit.getWorlds()) {
            final String wn = w.getName();
            boolean disabled = this.disabledWorlds.contains(wn);
            buttons.add(this.dialogButton(
                Component.text(this.friendlyWorldName(wn) + (disabled ? " [DISABLED]" : ""),
                    disabled ? NamedTextColor.RED : NamedTextColor.WHITE),
                w.getPlayers().size() + " player(s) here", 150, q -> this.openAdminWorldDetail(q, wn)));
        }
        buttons.add(this.dialogButton(Component.text("Cycle Evac Target", DIALOG_BRAND), "Where evacuated players are sent", 150, q -> {
            java.util.List<org.bukkit.World> worlds = Bukkit.getWorlds();
            int idx = 0;
            for (int i = 0; i < worlds.size(); i++) if (worlds.get(i).getName().equals(this.evacTargetWorld)) { idx = i; break; }
            this.evacTargetWorld = worlds.get((idx + 1) % worlds.size()).getName();
            this.saveWorldAccess();
            this.openAdminWorldAccess(q);
        }));
        buttons.add(this.dialogButton(
            Component.text(this.worldAccessAdminBypass ? "Bypass: ON" : "Bypass: OFF", this.worldAccessAdminBypass ? NamedTextColor.GREEN : NamedTextColor.RED),
            "Whether admins ignore world locks", 150, q -> {
                this.worldAccessAdminBypass = !this.worldAccessAdminBypass;
                this.saveWorldAccess();
                this.openAdminWorldAccess(q);
            }));
        buttons.add(this.dialogButton(Component.text("Set Lock Message", DIALOG_BRAND),
            "The message shown to blocked players (& and hex colors)", 150, this::openAdminLockMessageInput));
        Dialog dialog = this.buildDialog(Component.text("World Access", DIALOG_BRAND), body, List.of(),
            DialogType.multiAction(buttons).columns(2)
                .exitAction(this.dialogButton(Component.text("Back"), null, 150, this::openManageConsole)).build());
        p.showDialog(dialog);
    }

    private void openAdminWorldDetail(Player p, String wn) {
        org.bukkit.World w = Bukkit.getWorld(wn);
        if (w == null) { this.openAdminWorldAccess(p); return; }
        boolean disabled = this.disabledWorlds.contains(wn);
        boolean rtpOff = this.rtpDisabledWorlds.contains(wn);
        boolean pvp = w.getPVP();
        boolean mobs = Boolean.TRUE.equals(w.getGameRuleValue(org.bukkit.GameRule.DO_MOB_SPAWNING));
        boolean dayLock = Boolean.FALSE.equals(w.getGameRuleValue(org.bukkit.GameRule.DO_DAYLIGHT_CYCLE));
        boolean weatherLock = Boolean.FALSE.equals(w.getGameRuleValue(org.bukkit.GameRule.DO_WEATHER_CYCLE));
        boolean keepInv = Boolean.TRUE.equals(w.getGameRuleValue(org.bukkit.GameRule.KEEP_INVENTORY));
        String weather = w.isThundering() ? "Thunder" : w.hasStorm() ? "Rain" : "Clear";
        java.util.List<DialogBody> body = List.of(
            this.kv("Access:", disabled ? "DISABLED" : "OPEN", disabled ? NamedTextColor.RED : NamedTextColor.GREEN),
            this.kv("Difficulty:", w.getDifficulty().name(), NamedTextColor.WHITE),
            this.kv("Weather:", weather + (weatherLock ? " (locked)" : ""), NamedTextColor.AQUA),
            this.kv("Border radius:", String.valueOf((long) (w.getWorldBorder().getSize() / 2.0)), NamedTextColor.WHITE));
        java.util.List<ActionButton> buttons = new java.util.ArrayList<>();
        buttons.add(this.dialogButton(Component.text(disabled ? "Enable Access" : "Disable + Evacuate", disabled ? NamedTextColor.GREEN : NamedTextColor.RED),
            null, 150, q -> {
                if (this.disabledWorlds.remove(wn)) {
                    this.saveWorldAccess();
                    q.sendActionBar(Component.text("§a" + this.friendlyWorldName(wn) + " reopened."));
                } else {
                    this.disabledWorlds.add(wn);
                    this.saveWorldAccess();
                    int moved = this.evacuateWorld(wn);
                    q.sendActionBar(Component.text("§c" + this.friendlyWorldName(wn) + " disabled · evacuated " + moved + "."));
                }
                this.openAdminWorldDetail(q, wn);
            }));
        buttons.add(this.dialogButton(Component.text("RTP: " + (rtpOff ? "OFF" : "ON"), rtpOff ? NamedTextColor.RED : NamedTextColor.GREEN), null, 150, q -> {
            if (!this.rtpDisabledWorlds.remove(wn)) this.rtpDisabledWorlds.add(wn);
            this.saveWorldAccess();
            this.openAdminWorldDetail(q, wn);
        }));
        buttons.add(this.dialogButton(Component.text("PvP: " + (pvp ? "ON" : "OFF"), pvp ? NamedTextColor.GREEN : NamedTextColor.RED), null, 150, q -> {
            w.setPVP(!pvp); this.openAdminWorldDetail(q, wn);
        }));
        buttons.add(this.dialogButton(Component.text("Mob Spawning: " + (mobs ? "ON" : "OFF"), mobs ? NamedTextColor.GREEN : NamedTextColor.RED), null, 150, q -> {
            w.setGameRule(org.bukkit.GameRule.DO_MOB_SPAWNING, !mobs); this.openAdminWorldDetail(q, wn);
        }));
        buttons.add(this.dialogButton(Component.text("Difficulty: " + w.getDifficulty().name(), DIALOG_BRAND), "Cycle difficulty", 150, q -> {
            org.bukkit.Difficulty[] d = org.bukkit.Difficulty.values();
            w.setDifficulty(d[(w.getDifficulty().ordinal() + 1) % d.length]);
            this.openAdminWorldDetail(q, wn);
        }));
        buttons.add(this.dialogButton(Component.text("Set Day", DIALOG_BRAND), "Set time to day", 150, q -> { w.setTime(1000L); q.sendActionBar(Component.text("§7Time set to day.")); }));
        buttons.add(this.dialogButton(Component.text("Set Night", DIALOG_BRAND), "Set time to night", 150, q -> { w.setTime(13000L); q.sendActionBar(Component.text("§7Time set to night.")); }));
        buttons.add(this.dialogButton(Component.text("Daylight Lock: " + (dayLock ? "ON" : "OFF"), dayLock ? NamedTextColor.RED : NamedTextColor.GREEN), "Freeze time of day", 150, q -> {
            w.setGameRule(org.bukkit.GameRule.DO_DAYLIGHT_CYCLE, dayLock); this.openAdminWorldDetail(q, wn);
        }));
        buttons.add(this.dialogButton(Component.text("Weather: Clear", DIALOG_BRAND), null, 150, q -> { w.setStorm(false); w.setThundering(false); this.openAdminWorldDetail(q, wn); }));
        buttons.add(this.dialogButton(Component.text("Weather: Rain", DIALOG_BRAND), null, 150, q -> { w.setStorm(true); w.setThundering(false); this.openAdminWorldDetail(q, wn); }));
        buttons.add(this.dialogButton(Component.text("Weather Lock: " + (weatherLock ? "ON" : "OFF"), weatherLock ? NamedTextColor.RED : NamedTextColor.GREEN), null, 150, q -> {
            w.setGameRule(org.bukkit.GameRule.DO_WEATHER_CYCLE, weatherLock); this.openAdminWorldDetail(q, wn);
        }));
        buttons.add(this.dialogButton(Component.text("keepInventory: " + (keepInv ? "ON" : "OFF"), keepInv ? NamedTextColor.GREEN : NamedTextColor.RED), null, 150, q -> {
            w.setGameRule(org.bukkit.GameRule.KEEP_INVENTORY, !keepInv); this.openAdminWorldDetail(q, wn);
        }));
        buttons.add(this.dialogButton(Component.text("Set Border Radius", DIALOG_BRAND), "Set the world border (blocks from center)", 150,
            q -> this.openAdminBorderInput(q, wn)));
        buttons.add(this.dialogButton(Component.text("More Gamerules", DIALOG_BRAND), "Toggle all common gamerules", 150,
            q -> this.openAdminGamerules(q, wn)));
        buttons.add(this.dialogButton(Component.text("Set World Spawn Here", DIALOG_BRAND), "Set this world's spawn to your position", 150, q -> {
            if (q.getWorld().getName().equals(wn)) { q.getWorld().setSpawnLocation(q.getLocation()); q.sendActionBar(Component.text("§7World spawn set to your position.")); }
            else q.sendActionBar(Component.text("§cStand in " + this.friendlyWorldName(wn) + " to set its spawn."));
            this.openAdminWorldDetail(q, wn);
        }));
        Dialog dialog = this.buildDialog(Component.text(this.friendlyWorldName(wn) + " · World", DIALOG_BRAND), body, List.of(),
            DialogType.multiAction(buttons).columns(2)
                .exitAction(this.dialogButton(Component.text("Back"), null, 150, this::openAdminWorldAccess)).build());
        p.showDialog(dialog);
    }

    private void openAdminBorderInput(Player p, String wn) {
        java.util.List<DialogInput> inputs = List.of(
            DialogInput.text("radius", Component.text("Radius (blocks)", NamedTextColor.GRAY)).width(160).maxLength(8).build());
        ActionButton apply = ActionButton.builder(Component.text("Apply", NamedTextColor.GREEN)).width(140)
            .action(DialogAction.customClick((view, aud) -> {
                if (aud instanceof Player pl) {
                    String raw = view.getText("radius");
                    this.runOnPlayerThread(pl, () -> {
                        org.bukkit.World w = Bukkit.getWorld(wn);
                        try {
                            double r = Double.parseDouble(raw == null ? "" : raw.trim());
                            if (w != null && r >= 16 && r <= 29999984) {
                                w.getWorldBorder().setSize(r * 2.0);
                                pl.sendActionBar(Component.text("§7Border set to " + (long) r + " blocks."));
                            } else {
                                pl.sendActionBar(Component.text("§cRadius must be 16-29999984."));
                            }
                        } catch (NumberFormatException ex) {
                            pl.sendActionBar(Component.text("§cInvalid number."));
                        }
                        this.openAdminWorldDetail(pl, wn);
                    });
                }
            }, ClickCallback.Options.builder().build())).build();
        ActionButton back = this.dialogButton(Component.text("Cancel"), null, 140, q -> this.openAdminWorldDetail(q, wn));
        Dialog dialog = this.buildDialog(Component.text("World Border", DIALOG_BRAND), List.of(), inputs,
            DialogType.confirmation(apply, back));
        p.showDialog(dialog);
    }

    private String friendlyWorldName(String wn) {
        return switch (wn) {
            case "world" -> "Overworld";
            case "world_nether" -> "The Nether";
            case "world_the_end" -> "The End";
            default -> wn;
        };
    }

    private void openAdminPerformance(Player p) {
        double[] tps = Bukkit.getTPS();
        double mspt = Bukkit.getAverageTickTime();
        NamedTextColor tpsColor = tps[0] >= 19.0 ? NamedTextColor.GREEN : tps[0] >= 15.0 ? NamedTextColor.YELLOW : NamedTextColor.RED;
        java.util.List<DialogBody> body = List.of(
            this.kv("TPS (1m/5m/15m):", String.format("%.1f / %.1f / %.1f",
                Math.min(20.0, tps[0]), Math.min(20.0, tps[1]), Math.min(20.0, tps[2])), tpsColor),
            this.kv("MSPT:", String.format("%.1f ms", mspt), mspt <= 40.0 ? NamedTextColor.GREEN : NamedTextColor.YELLOW),
            this.kv("Server view distance:", String.valueOf(this.currentThrottledVd), NamedTextColor.WHITE),
            this.kv("Online:", String.valueOf(Bukkit.getOnlinePlayers().size()), NamedTextColor.WHITE));
        java.util.List<ActionButton> buttons = List.of(
            this.dialogButton(Component.text("View Distance +1", DIALOG_BRAND), "Raise server view distance (max " + VD_MAX + ")", 150, q -> {
                this.currentThrottledVd = Math.min(VD_MAX, this.currentThrottledVd + 1);
                this.applyServerVd(this.currentThrottledVd);
                this.openAdminPerformance(q);
            }),
            this.dialogButton(Component.text("View Distance -1", DIALOG_BRAND), "Lower server view distance (min " + VD_MIN + ")", 150, q -> {
                this.currentThrottledVd = Math.max(VD_MIN, this.currentThrottledVd - 1);
                this.applyServerVd(this.currentThrottledVd);
                this.openAdminPerformance(q);
            }),
            this.dialogButton(Component.text("Reset VD to " + VD_MAX, NamedTextColor.GREEN), "Resume auto view-distance throttle", 150, q -> {
                this.currentThrottledVd = VD_MAX;
                this.applyServerVd(VD_MAX);
                this.openAdminPerformance(q);
            }),
            this.dialogButton(Component.text("Refresh", NamedTextColor.WHITE), null, 150, this::openAdminPerformance));
        Dialog dialog = this.buildDialog(Component.text("Performance", DIALOG_BRAND), body, List.of(),
            DialogType.multiAction(buttons).columns(2)
                .exitAction(this.dialogButton(Component.text("Back"), null, 150, this::openManageConsole)).build());
        p.showDialog(dialog);
    }

