    // ----- Maintenance MOTD (D6) -----
    // The maintenance ping MOTD lives in the third-party Maintenance plugin's config.yml under
    // ping-message.messages (MiniMessage). We write index 0 and hot-reload the plugin.
    private java.io.File maintenanceConfigFile() {
        return new java.io.File(this.getDataFolder().getParentFile(), "Maintenance/config.yml");
    }

    private String getMaintenanceMotd() {
        java.io.File f = this.maintenanceConfigFile();
        if (!f.isFile()) return "(Maintenance plugin config not found)";
        org.bukkit.configuration.file.YamlConfiguration cfg = org.bukkit.configuration.file.YamlConfiguration.loadConfiguration(f);
        java.util.List<String> msgs = cfg.getStringList("ping-message.messages");
        if (msgs.isEmpty()) {
            String single = cfg.getString("ping-message.messages");
            return single == null ? "(none set)" : single;
        }
        return String.join(" ", msgs);
    }

    private void setMaintenanceMotd(Player feedbackTo, String legacyText) {
        java.io.File f = this.maintenanceConfigFile();
        if (!f.isFile()) {
            if (feedbackTo != null) feedbackTo.sendMessage("§cMaintenance plugin config not found; cannot set MOTD.");
            return;
        }
        String mini = this.legacyToMiniMessage(legacyText.trim());
        try {
            org.bukkit.configuration.file.YamlConfiguration cfg = org.bukkit.configuration.file.YamlConfiguration.loadConfiguration(f);
            cfg.set("ping-message.messages", java.util.List.of(mini));
            cfg.save(f);
        } catch (Exception ex) {
            this.getLogger().warning("Failed to write maintenance MOTD: " + ex.getMessage());
            if (feedbackTo != null) feedbackTo.sendMessage("§cFailed to save maintenance MOTD: " + ex.getMessage());
            return;
        }
        // Hot-reload the Maintenance plugin so the new MOTD takes effect immediately.
        Bukkit.dispatchCommand(Bukkit.getConsoleSender(), "maintenance reload");
        if (feedbackTo != null) {
            feedbackTo.sendMessage(this.legacyColorize("&#00BFFFMaintenance MOTD updated."));
            feedbackTo.sendMessage(this.legacyColorize(legacyText.trim()));
        }
    }

    // Convert our usual legacy color input (& codes + &#RRGGBB hex) into MiniMessage, since the
    // Maintenance plugin's config is MiniMessage. If the text already looks like MiniMessage
    // (contains a tag), it is passed through untouched.
    private String legacyToMiniMessage(String in) {
        if (in == null || in.isEmpty()) return "";
        if (in.indexOf('<') >= 0 && in.indexOf('>') >= 0) return in; // already MiniMessage
        // hex first: &#RRGGBB or §#RRGGBB -> <#RRGGBB>
        String s = in.replaceAll("(?i)[&§]#([0-9a-f]{6})", "<#$1>");
        StringBuilder out = new StringBuilder(s.length() + 16);
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if ((c == '&' || c == '§') && i + 1 < s.length()) {
                char code = Character.toLowerCase(s.charAt(++i));
                String tag = switch (code) {
                    case '0' -> "<black>";       case '1' -> "<dark_blue>";
                    case '2' -> "<dark_green>";  case '3' -> "<dark_aqua>";
                    case '4' -> "<dark_red>";    case '5' -> "<dark_purple>";
                    case '6' -> "<gold>";        case '7' -> "<gray>";
                    case '8' -> "<dark_gray>";   case '9' -> "<blue>";
                    case 'a' -> "<green>";       case 'b' -> "<aqua>";
                    case 'c' -> "<red>";         case 'd' -> "<light_purple>";
                    case 'e' -> "<yellow>";      case 'f' -> "<white>";
                    case 'l' -> "<bold>";        case 'm' -> "<strikethrough>";
                    case 'n' -> "<underlined>";  case 'o' -> "<italic>";
                    case 'k' -> "<obfuscated>";  case 'r' -> "<reset>";
                    default -> null;
                };
                if (tag != null) out.append(tag);
                else { out.append(c); out.append(s.charAt(i)); }
            } else {
                out.append(c);
            }
        }
        return out.toString();
    }

