    private void openAdminDataPlayerInput(Player p, String cmdTemplate) {
        java.util.List<DialogInput> inputs = List.of(
            DialogInput.text("player", Component.text("Player", NamedTextColor.GRAY)).width(200).maxLength(16).build());
        ActionButton go = ActionButton.builder(Component.text("Open", NamedTextColor.GREEN)).width(140)
            .action(DialogAction.customClick((view, aud) -> {
                if (aud instanceof Player pl) {
                    String who = view.getText("player");
                    this.runOnPlayerThread(pl, () -> {
                        if (who == null || who.isBlank()) { pl.sendActionBar(Component.text("§cEnter a player.")); this.openAdminData(pl); return; }
                        pl.closeDialog();
                        pl.performCommand(cmdTemplate.replace("%p%", who.trim()));
                    });
                }
            }, ClickCallback.Options.builder().build())).build();
        ActionButton back = this.dialogButton(Component.text("Cancel"), null, 140, this::openAdminData);
        Dialog dialog = this.buildDialog(Component.text("Player", DIALOG_BRAND), List.of(), inputs, DialogType.confirmation(go, back));
        p.showDialog(dialog);
    }

    // Bulk-delete all anticheat violations for a player (false-positive cleanup).
    private int clearSuspiciousFlags(String targetUuid) {
        String sql = "DELETE FROM anticheat_violations WHERE player_uuid = ?";
        try (Connection conn = this.openSyncConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setString(1, targetUuid);
            return ps.executeUpdate();
        } catch (Exception ex) {
            this.getLogger().warning("Failed clearing suspicious flags for " + targetUuid + ": " + ex.getMessage());
            return -1;
        }
    }

    private java.util.List<SuspiciousPlayerEntry> loadSuspiciousPlayers(int limit) {
        java.util.List<SuspiciousPlayerEntry> results = new java.util.ArrayList<>();
        String sql = "SELECT player_uuid, player_name, COUNT(*) as violation_count, violation_type, severity, SUM(vl_points) as total_vl, MAX(severity) as max_severity FROM anticheat_violations WHERE reported_at > DATE_SUB(NOW(), INTERVAL 7 DAY) GROUP BY player_uuid ORDER BY violation_count DESC, total_vl DESC LIMIT ?";
        try (Connection conn = this.openSyncConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setInt(1, limit);
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next()) {
                    results.add(new SuspiciousPlayerEntry(
                        rs.getString(1),
                        rs.getString(2),
                        rs.getInt(3),
                        rs.getString(4),
                        rs.getString(5),
                        rs.getDouble(6),
                        rs.getString(7)
                    ));
                }
            }
        } catch (Exception ex) {
            this.getLogger().warning("Failed loading suspicious players: " + ex.getMessage());
        }
        return results;
    }

    private record SuspiciousPlayerEntry(String uuid, String playerName, int violationCount, String lastViolationType, String lastSeverity, double totalVlPoints, String maxSeverity) {}

    private static final class SuspiciousPlayersGuiState {
        private int page = 1;

        private SuspiciousPlayersGuiState() {
        }
    }

    // Console variant of /shards give — no Player sender required (stipend grants from PizzaAdminTools).
    private void handleShardsGiveFromConsole(CommandSender sender, String targetName, String amountStr) {
        ParsedAmount parsed = this.parseCompactAmount(amountStr);
        if (parsed == null || parsed.value <= 0.0) {
            sender.sendMessage("Invalid amount: " + amountStr);
            return;
        }
        long amount = (long) Math.floor(parsed.value);
        if (amount <= 0L) {
            sender.sendMessage("Amount must be positive");
            return;
        }
        this.runAsyncTask(() -> {
            Player online = Bukkit.getPlayerExact(targetName);
            UUID tid = online != null ? online.getUniqueId() : this.lookupUuidByName(targetName);
            if (tid == null) {
                this.getLogger().warning("[shards] Console give failed — player not found: " + targetName);
                return;
            }
            try {
                this.grantShards(tid, amount);
                this.getLogger().info("[shards] Console gave " + amount + " shards to " + targetName);
                if (online != null) {
                    this.runOnPlayerThread(online, () -> online.sendMessage("§aYou received " + amount + " shards"));
                }
            } catch (Exception ex) {
                this.getLogger().warning("Failed to grant shards: " + ex.getMessage());
            }
        });
    }

    private void handleShardsGiveCommand(Player p, String targetName, String amountStr) {
        // Supports k/m/b/t amounts and offline targets.
        ParsedAmount parsed = this.parseCompactAmount(amountStr);
        if (parsed == null || parsed.value <= 0.0) {
            p.sendMessage("§cInvalid amount: " + amountStr);
            return;
        }
        long amount = (long) Math.floor(parsed.value);
        if (amount <= 0) { p.sendMessage("§cAmount must be positive"); return; }
        Player online = Bukkit.getPlayerExact(targetName);
        if (online != null) {
            UUID tid = online.getUniqueId();
            this.runAsyncTask(() -> {
                try {
                    this.grantShards(tid, amount);
                    this.runOnPlayerThread(p, () -> p.sendMessage("§aGave " + amount + " shards to " + online.getName()));
                    this.runOnPlayerThread(online, () -> online.sendMessage("§aYou received " + amount + " shards"));
                } catch (Exception ex) { this.getLogger().warning("Failed to grant shards: " + ex.getMessage()); }
            });
            return;
        }
        // Offline target.
        this.runAsyncTask(() -> {
            UUID tid = this.lookupUuidByName(targetName);
            if (tid == null) {
                this.runOnPlayerThread(p, () -> p.sendMessage("§cPlayer not found: " + targetName));
                return;
            }
            try {
                this.grantShards(tid, amount);
                this.runOnPlayerThread(p, () -> p.sendMessage("§aGave " + amount + " shards to " + targetName + " §7(offline)"));
            } catch (Exception ex) { this.getLogger().warning("Failed to grant shards: " + ex.getMessage()); }
        });
    }

    private void handleResetCommand(Player p, String type, String targetName) {
        Player target = Bukkit.getPlayer(targetName);
        if (target == null) {
            p.sendMessage("§cPlayer not found: " + targetName);
            return;
        }
        this.runAsyncTask(() -> {
            try {
                switch (type.toLowerCase()) {
                    case "deaths":
                        this.resetPlayerDeaths(target.getUniqueId());
                        this.runOnPlayerThread(p, () -> p.sendMessage("§aReset deaths for " + target.getName()));
                        this.runOnPlayerThread(target, () -> target.sendMessage("§aYour deaths have been reset"));
                        break;
                    case "kills":
                        this.resetPlayerKills(target.getUniqueId());
                        this.runOnPlayerThread(p, () -> p.sendMessage("§aReset kills for " + target.getName()));
                        this.runOnPlayerThread(target, () -> target.sendMessage("§aYour kills have been reset"));
                        break;
                    case "playtime":
                        this.resetPlayerPlaytime(target.getUniqueId());
                        this.runOnPlayerThread(p, () -> p.sendMessage("§aReset playtime for " + target.getName()));
                        this.runOnPlayerThread(target, () -> target.sendMessage("§aYour playtime has been reset"));
                        break;
                    case "money":
                        this.resetPlayerMoney(target.getUniqueId());
                        this.runOnPlayerThread(p, () -> p.sendMessage("§aReset money for " + target.getName()));
                        this.runOnPlayerThread(target, () -> target.sendMessage("§aYour money has been reset"));
                        break;
                    default:
                        this.runOnPlayerThread(p, () -> p.sendMessage("§cUnknown reset type: " + type));
                }
            } catch (Exception ex) {
                this.getLogger().warning("Failed to reset player stat: " + ex.getMessage());
            }
        });
    }

    private void grantShards(UUID uuid, long amount) {
        // Shards live in the `balances` table (not `players`). Upsert so it works for new rows too.
        String sql = "INSERT INTO balances (uuid, shards) VALUES (?, ?) ON DUPLICATE KEY UPDATE shards = shards + VALUES(shards)";
        try (Connection conn = this.openSyncConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setString(1, uuid.toString());
            ps.setLong(2, amount);
            ps.executeUpdate();
        } catch (Exception ex) {
            this.getLogger().warning("Failed to grant shards: " + ex.getMessage());
        }
    }

